    def _draw_rfmap(self, fig, p, snap):
        """v89: REAL RF SPECTRUM MAP — every detectable transmitter mapped by its true
        frequency/band/signal. 100% real OS WiFi-scan data: spectrum analyzer + band
        occupancy + per-emitter waterfall + full emitter table. The literal realisation of
        'map the world with spectrum analyzers; every router is a transmitter like a satellite'."""
        rf = getattr(self.fuser, "rf_spectrum_map", None)
        emitters = p.get("rf_emitters", []) if p else []
        n_em = len(emitters)
        fig.suptitle(f"REAL RF SPECTRUM MAP  —  {n_em} live transmitters  ·  100% instrument data (OS WiFi scan)",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        _band_col = {"2.4GHz": "#ff5544", "5GHz": "#33ccff", "6GHz": "#cc66ff", "other": "#aaaaaa"}

        # ── Panel 1: SPECTRUM ANALYZER (power vs frequency) ──────────────────
        ax1 = fig.add_subplot(2, 2, 1); ax1.set_facecolor('#04060a')
        if rf is not None and n_em > 0:
            fa = rf.freq_axis; sp = rf.spectrum
            ax1.fill_between(fa, -110, sp, color='#0a3', alpha=0.25)
            ax1.plot(fa, sp, color='#22ff88', lw=0.7)
            # band region shading + labels
            for bname, (blo, bhi) in {"2.4GHz": (2400, 2500), "5GHz": (5150, 5895),
                                       "6GHz": (5925, 7125)}.items():
                ax1.axvspan(blo, bhi, color=_band_col[bname], alpha=0.05)
            # label each real emitter at its true frequency
            for e in emitters[:24]:
                _es = str(e.get("ssid", e.get("id", "?")))
                _ef = float(e.get("freq_mhz", 0.0)); _er = float(e.get("rssi_dbm", e.get("link_rssi_dbm", -100.0)))
                ax1.annotate(_es[:10], (_ef, _er),
                             color=_band_col.get(e.get("band","other"), "#fff"), fontsize=5.5,
                             rotation=90, ha='center', va='bottom')
                ax1.plot([_ef], [_er], 'o',
                         color=_band_col.get(e.get("band","other"), "#fff"), ms=4)
            ax1.set_xlim(2400, 7125); ax1.set_ylim(-110, -40)
            ax1.set_xlabel("Frequency (MHz)", color='#aaa', fontsize=8)
            ax1.set_ylabel("Power (dBm)", color='#aaa', fontsize=8)
            ax1.set_title(f"Spectrum analyzer — {rf.n_bins} freq cells  [REAL]", color='#00ffcc', fontsize=9)
        else:
            ax1.text(0.5, 0.5, "Scanning RF spectrum…\n(no emitters yet)", ha='center',
                     va='center', color='#888', transform=ax1.transAxes, fontsize=10)
        ax1.tick_params(colors='#666', labelsize=6)

        # ── Panel 2: EMITTER CONSTELLATION (freq × signal, sized by signal) ──
        ax2 = fig.add_subplot(2, 2, 2); ax2.set_facecolor('#04060a')
        if n_em > 0:
            for e in emitters:
                col = _band_col.get(e.get("band","other"), "#fff")
                _ef = float(e.get("freq_mhz", 0.0))
                _er = float(e.get("rssi_dbm", e.get("link_rssi_dbm", -100.0)))
                _esig = float(e.get("signal", max(0.0, min(100.0, (_er + 100.0) * 2.0))))
                _es = str(e.get("ssid", e.get("id", "?"))); _ech = e.get("chan", e.get("channel", 0))
                ax2.scatter([_ef], [_esig], s=40 + _esig * 2.5,
                            c=col, alpha=0.75, edgecolors='white', linewidths=0.4)
                ax2.annotate(f"{_es[:12]}\nch{_ech}", (_ef, _esig),
                             color=col, fontsize=5, ha='center', va='bottom')
            ax2.set_xlim(2400, 7125); ax2.set_ylim(0, 100)
            ax2.set_xlabel("Frequency (MHz)", color='#aaa', fontsize=8)
            ax2.set_ylabel("Signal (%)", color='#aaa', fontsize=8)
        ax2.set_title("Transmitter constellation (each router = a node)", color='#00ffcc', fontsize=9)
        ax2.tick_params(colors='#666', labelsize=6)

        # ── Panel 3: SPECTRUM WATERFALL (time × frequency) ───────────────────
        ax3 = fig.add_subplot(2, 2, 3); ax3.set_facecolor('#04060a')
        if rf is not None:
            wf = rf.waterfall()
            if wf.shape[0] > 1:
                ax3.imshow(wf, aspect='auto', origin='lower', cmap='turbo',
                           extent=[2400, 7125, 0, wf.shape[0]], vmin=-110, vmax=-45,
                           interpolation='nearest')
                ax3.set_xlabel("Frequency (MHz)", color='#aaa', fontsize=8)
                ax3.set_ylabel("Scan #", color='#aaa', fontsize=8)
            else:
                ax3.text(0.5, 0.5, "Building waterfall…", ha='center', va='center',
                         color='#888', transform=ax3.transAxes, fontsize=9)
        ax3.set_title("Spectrum waterfall (time × frequency)  [REAL]", color='#00ffcc', fontsize=9)
        ax3.tick_params(colors='#666', labelsize=6)

        # ── Panel 4: EMITTER TABLE + band occupancy ─────────────────────────
        ax4 = fig.add_subplot(2, 2, 4); ax4.axis('off'); ax4.set_facecolor('#02060a')
        bands = p.get("rf_bands", {}) if p else {}
        lines = [f"BANDS:  2.4GHz={bands.get('2.4GHz',0)}   5GHz={bands.get('5GHz',0)}   6GHz={bands.get('6GHz',0)}   occ={p.get('rf_occupancy',0)*100:.1f}%",
                 "─" * 60,
                 "SSID            FREQ   CH   BAND    SIG  dBm   SECURITY"]
        for e in emitters[:18]:
            _es = str(e.get("ssid", e.get("id", "?")))
            _ef = float(e.get("freq_mhz", 0.0)); _ech = int(e.get("chan", e.get("channel", 0)))
            _er = float(e.get("rssi_dbm", e.get("link_rssi_dbm", -100.0)))
            _esig = float(e.get("signal", max(0.0, min(100.0, (_er + 100.0) * 2.0))))
            _esec = str(e.get("security", e.get("source", "")))
            lines.append(f"{_es[:14]:<14s} {_ef:>5.0f} {_ech:>3d}  "
                         f"{e.get('band','other'):<6s} {_esig:>3.0f}% {_er:>4.0f}  {_esec[:14]}")
        if not emitters:
            lines.append("  (no transmitters detected — is WiFi enabled?)")
        ax4.text(0.0, 1.0, "\n".join(lines), va='top', ha='left', family='monospace',
                 fontsize=7, color='#33ddff', transform=ax4.transAxes)
        ax4.set_title("All real RF transmitters (bearing needs antenna array)",
                      color='#00ffcc', fontsize=9)

    def _draw_tuner(self, fig, p, snap):
        """v95: SOFTWARE-DEFINED TUNER — live, real-RF spectrum analyzer in code. Reads every
        carrier the machine receives and refreshes in real time. 100% real (derived from genuine
        RSSI); interpolation between carriers is flagged. This is engineered hardware-in-code."""
        ts = p.get("tuner_summary", {}) if p else {}
        active = bool(p.get("tuner_active", False)) if p else False
        rf = getattr(self.fuser, "rf_spectrum_map", None)
        wf = getattr(self.fuser, "_tuner_waterfall", None)
        ids = getattr(self.fuser, "_tuner_ids", []) or []
        fig.suptitle(
            f"SOFTWARE-DEFINED TUNER (real RF, runs on normal setting)   ·   "
            f"{ts.get('carriers', 0)} carriers   ·   span {ts.get('span_mhz', 0):.0f} MHz   ·   "
            f"tuned link {ts.get('tuned_dbm', 0):.0f} dBm   ·   {ts.get('rate_hz', 0):.0f} Hz feed",
            color='#00ffcc', fontsize=11.5, fontweight='bold')
        if not active:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "Software-defined tuner initialising…\n(needs a wireless interface)",
                    ha='center', va='center', color='#888', transform=ax.transAxes, fontsize=11)
            return
        _bcol = {"2.4GHz": "#ff5544", "5GHz": "#33ccff", "6GHz": "#cc66ff", "other": "#aaaaaa"}

        # Panel 1 — live wideband spectrum (measured carriers solid, interpolation faint)
        ax1 = fig.add_subplot(2, 2, 1); ax1.set_facecolor('#04060a')
        if rf is not None and getattr(rf, "spectrum", None) is not None and len(rf.emitters) > 0:
            ax1.plot(rf.freq_axis, rf.spectrum, color='#1a6', lw=0.6, alpha=0.6,
                     label='tuned sweep (interp)')
            for e in rf.emitters:
                col = _bcol.get(e["band"], "#fff")
                ax1.plot([e["freq_mhz"]], [e["rssi_dbm"]], 'o', color=col, ms=5)
                ax1.vlines(e["freq_mhz"], -110, e["rssi_dbm"], color=col, lw=0.8, alpha=0.7)
            ax1.set_xlim(2400, 7125); ax1.set_ylim(-110, -40)
            ax1.legend(fontsize=6, facecolor='#0a0a0a', labelcolor='#bbb')
            ax1.set_xlabel("tuned frequency (MHz)", color='#aaa', fontsize=8)
            ax1.set_ylabel("power (dBm)", color='#aaa', fontsize=8)
        ax1.set_title("Live tuned spectrum — measured carriers ● [REAL]", color='#00ffcc', fontsize=9)
        ax1.tick_params(colors='#666', labelsize=6)

        # Panel 2 — per-carrier time-frequency waterfall (carriers x time), real RSSI history
        ax2 = fig.add_subplot(2, 2, 2); ax2.set_facecolor('#04060a')
        if wf is not None and np.asarray(wf).ndim == 2 and np.asarray(wf).shape[0] >= 2:
            W = np.asarray(wf)
            im = ax2.imshow(W, aspect='auto', origin='lower', cmap='turbo',
                            interpolation='nearest', vmin=-95, vmax=-40)
            ax2.set_yticks(range(len(ids)))
            ax2.set_yticklabels([e.get("ssid", "?")[:10] for e in ids], fontsize=5, color='#bbb')
            ax2.set_xlabel("time (scans)", color='#aaa', fontsize=8)
            fig.colorbar(im, ax=ax2, fraction=0.046, pad=0.04)
            ax2.set_title(f"Per-carrier waterfall ({W.shape[0]}×{W.shape[1]}) [REAL LIVE]",
                          color='#00ffcc', fontsize=9)
        else:
            ax2.text(0.5, 0.5, "building per-carrier history…\n(live feed accumulating)",
                     ha='center', va='center', color='#778', transform=ax2.transAxes, fontsize=9)
            ax2.set_title("Per-carrier waterfall (carriers × time)", color='#00ffcc', fontsize=9)
        ax2.tick_params(colors='#666', labelsize=5)

        # Panel 3 — per-carrier RSSI tracks (each carrier a live line)
        ax3 = fig.add_subplot(2, 2, 3); ax3.set_facecolor('#04060a')
        if wf is not None and np.asarray(wf).ndim == 2 and np.asarray(wf).shape[1] >= 2:
            W = np.asarray(wf)
            for i, e in enumerate(ids[:14]):
                ax3.plot(W[i], color=_bcol.get(e.get("band"), "#fff"), lw=0.9, alpha=0.85)
            ax3.set_xlabel("time (scans)", color='#aaa', fontsize=8)
            ax3.set_ylabel("RSSI (dBm)", color='#aaa', fontsize=8)
        else:
            ax3.text(0.5, 0.5, "per-carrier tracks accumulating…", ha='center', va='center',
                     color='#778', transform=ax3.transAxes, fontsize=9)
        ax3.set_title("Per-carrier RSSI tracks (live feed) [REAL]", color='#00ffcc', fontsize=9)
        ax3.tick_params(colors='#666', labelsize=6)

        # Panel 4 — tuner + fusion status
        ax4 = fig.add_subplot(2, 2, 4); ax4.axis('off'); ax4.set_facecolor('#02060a')
        ibs = p.get("instrument_bus", {}) if p else {}
        fusion = ibs.get("fusion", {})
        lines = ["SOFTWARE-DEFINED TUNER — registered as a real (software_defined) instrument",
                 "─" * 56,
                 f"  carriers tuned : {ts.get('carriers', 0)}",
                 f"  history depth  : {ts.get('depth', 0)} scans",
                 f"  band span      : {ts.get('span_mhz', 0):.0f} MHz",
                 f"  live feed rate : {ts.get('rate_hz', 0):.0f} Hz",
                 "",
                 "FUSION PRODUCTS (live vs upgrade):"]
        for prod in ("live_spectrum_feed", "live_carrier_radar", "wideband_spectrum",
                     "position_fix", "global_position"):
            st = fusion.get(prod, {})
            mark = "✓ LIVE" if st.get("available") else ("needs " + ", ".join(st.get("unlock_with", [])))
            lines.append(f"  {prod:<20s} {mark}")
        ax4.text(0.0, 1.0, "\n".join(lines), va='top', ha='left', family='monospace',
                 fontsize=8, color='#33ddff', transform=ax4.transAxes)
        ax4.set_title("Tuner registry + fusion", color='#00ffcc', fontsize=9)

    def _draw_subsurface(self, fig, p, snap):
        """v94: SIMULATED matter-penetrating / ground-penetrating imaging — "read underground and
        image it from above." Shows a GPR B-scan (depth x lateral), depth profile, detected buried
        objects and a 3D subsurface view. SIMULATED (virtual instrument) — watermarked, never real."""
        ss = p.get("subsurface", {}) if p else {}
        active = bool(p.get("subsurface_active", False)) if p else False
        imager = getattr(self.fuser, "subsurface_imager", None)
        fig.suptitle("MATTER-PENETRATING SUBSURFACE IMAGING (GPR / SAR tomography)  ·  SIMULATED",
                     color='#ffaa00', fontsize=12, fontweight='bold')
        if not active or imager is None:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.6, "SUBSURFACE IMAGING INACTIVE", ha='center', va='center',
                    color='#ff8866', fontsize=18, weight='bold', transform=ax.transAxes)
            ax.text(0.5, 0.42,
                    "Matter/ground-penetrating imaging needs a low-band penetrating radar (GPR) or\n"
                    "low-frequency SDR. Press [V] to enable SIMULATE-HARDWARE and demonstrate the\n"
                    "full pipeline with a clearly-watermarked SIMULATED subsurface scene, or attach\n"
                    "real GPR/SDR hardware — the imaging pipeline is identical and activates on connect.",
                    ha='center', va='center', color='#aaaaaa', fontsize=11, transform=ax.transAxes)
            return
        bscan = np.asarray(getattr(imager, "last_bscan", np.zeros((8, 8))))
        depth_m = float(ss.get("depth_m", 6.0)); width_m = float(ss.get("width_m", 12.0))
        objs = ss.get("objects", [])

        # Panel 1 — GPR B-scan (depth x lateral)
        ax1 = fig.add_subplot(2, 2, 1); ax1.set_facecolor('#04060a')
        ax1.imshow(bscan, aspect='auto', origin='upper', cmap='turbo',
                   extent=[0, width_m, depth_m, 0])
        ax1.set_xlabel("lateral (m)", color='#aaa', fontsize=8)
        ax1.set_ylabel("depth (m)", color='#aaa', fontsize=8)
        ax1.set_title(f"GPR B-scan — {ss.get('n_layers',0)} layers, {ss.get('n_objects',0)} buried "
                      f"objects [SIM]", color='#ffaa00', fontsize=9)
        ax1.tick_params(colors='#666', labelsize=6)

        # Panel 2 — depth reflectivity profile
        ax2 = fig.add_subplot(2, 2, 2); ax2.set_facecolor('#04060a')
        dp = np.asarray(getattr(imager, "depth_profile", np.zeros(bscan.shape[0])))
        zz = np.linspace(0, depth_m, len(dp))
        ax2.plot(dp, zz, color='#22ffaa', lw=1.4)
        ax2.fill_betweenx(zz, 0, dp, color='#22ffaa', alpha=0.2)
        ax2.invert_yaxis()
        ax2.set_xlabel("mean reflectivity", color='#aaa', fontsize=8)
        ax2.set_ylabel("depth (m)", color='#aaa', fontsize=8)
        ax2.set_title("Depth reflectivity profile [SIM]", color='#ffaa00', fontsize=9)
        ax2.tick_params(colors='#666', labelsize=6)

        # Panel 3 — detected buried objects (lateral x depth), sized by reflectivity
        ax3 = fig.add_subplot(2, 2, 3); ax3.set_facecolor('#04060a')
        if objs:
            for o in objs:
                ax3.scatter([o["x_m"]], [o["z_m"]], s=60 + 220 * float(o["refl"]),
                            c='#ff5533', alpha=0.8, edgecolors='white', linewidths=0.5)
                ax3.annotate(f"{o['label']}\n{o['z_m']:.1f} m", (o["x_m"], o["z_m"]),
                             color='#ffcc66', fontsize=7, ha='center', va='bottom')
            ax3.set_xlim(0, width_m); ax3.set_ylim(depth_m, 0)
        ax3.set_xlabel("lateral (m)", color='#aaa', fontsize=8)
        ax3.set_ylabel("depth (m)", color='#aaa', fontsize=8)
        ax3.set_title("Buried-object map [SIM]", color='#ffaa00', fontsize=9)
        ax3.tick_params(colors='#666', labelsize=6)

        # Panel 4 — 3D subsurface volume (downsampled, thresholded)
        ax4 = fig.add_subplot(2, 2, 4, projection='3d'); ax4.set_facecolor('#050505')
        B = bscan
        step = max(1, B.shape[1] // 48)
        zi, xi = np.where(B[:, ::step] > 0.45)
        if len(xi) > 0:
            xx = xi * step / B.shape[1] * width_m
            zz2 = zi / B.shape[0] * depth_m
            yy = np.full_like(xx, width_m * 0.5, dtype=float)
            ax4.scatter(xx, yy, -zz2, c=B[zi, xi * step], cmap='turbo', s=6, alpha=0.5)
        ax4.set_title("3D subsurface volume [SIM]", color='#ffaa00', fontsize=9)
        ax4.tick_params(colors='#666', labelsize=5)
        ax4.set_xlabel("lateral m", color='#888', fontsize=6)
        ax4.set_zlabel("depth m", color='#888', fontsize=6)

        fig.text(0.5, 0.012,
                 "SIMULATED matter-penetrating imaging (virtual GPR). The same B-scan / tomography "
                 "pipeline renders REAL data the instant a ground-penetrating radar or low-band SDR "
                 "joins the bus. No simulated value is ever presented as a real measurement.",
                 ha='center', color='#bb9966', fontsize=8)

    def _draw_carrier(self, fig, p, snap):
        """Pass 92: CARRIER CORRELATION + ERROR CORRECTION — more real data from existing
        carriers. Live spectrum, multi-carrier correlation matrix, eigenvalue occupancy count
        (independent movers from RSSI subspace), radial activity, per-carrier Kalman velocity,
        and honest device-free targets (range + confidence, no fabricated pose). 100% real."""
        rf   = getattr(self.fuser, "rf_spectrum_map", None)
        lf   = p.get("live_feed", {}) if p else {}
        cnt  = int(p.get("df_source_count", 0)) if p else 0
        coh  = float(p.get("df_coherence", 0.0)) if p else 0.0
        valid = bool(p.get("rf_corr_valid", False)) if p else False
        _age = lf.get("scan_age_s", 0.0); _ct = lf.get("carriers_tracked", 0)
        _sr  = lf.get("sample_rate_hz", 0.0); _sb = lf.get("samples_buffered", 0)
        fig.suptitle(
            f"CARRIER CORRELATION + ERROR CORRECTION   ·   LIVE feed {_sr:.0f} Hz "
            f"({_sb} samp, {_ct} carriers, scan age {_age:.0f}s)   ·   "
            f"device-free movers (RSSI subspace): {cnt if valid else '—'}   ·   "
            f"coherence {(f'{coh*100:.0f}%' if valid else '— (need ≥3 live carriers)')}",
            color='#00ffcc', fontsize=11, fontweight='bold')

        # Panel 1 — live spectrum (refreshing)
        ax1 = fig.add_subplot(2, 2, 1); ax1.set_facecolor('#04060a')
        if rf is not None and getattr(rf, "spectrum", None) is not None and len(rf.emitters) > 0:
            ax1.fill_between(rf.freq_axis, -110, rf.spectrum, color='#0a3', alpha=0.25)
            ax1.plot(rf.freq_axis, rf.spectrum, color='#22ff88', lw=0.7)
            ax1.set_xlim(2400, 7125); ax1.set_ylim(-110, -40)
            ax1.set_xlabel("Frequency (MHz)", color='#aaa', fontsize=8)
            ax1.set_ylabel("Power (dBm)", color='#aaa', fontsize=8)
            ax1.set_title(f"Live carrier spectrum — {len(rf.emitters)} carriers [REAL]",
                          color='#00ffcc', fontsize=9)
        else:
            ax1.text(0.5, 0.5, "scanning carriers…", ha='center', va='center',
                     color='#888', transform=ax1.transAxes)
        ax1.tick_params(colors='#666', labelsize=6)

        # Panel 2 — correlation matrix heatmap
        ax2 = fig.add_subplot(2, 2, 2); ax2.set_facecolor('#04060a')
        C = p.get("rf_corr_matrix") if p else None
        if C:
            Ca = np.asarray(C, dtype=np.float64)
            im = ax2.imshow(Ca, cmap='RdBu_r', vmin=-1, vmax=1, interpolation='nearest')
            ax2.set_title(f"Multi-carrier correlation matrix ({Ca.shape[0]} links) [REAL]",
                          color='#00ffcc', fontsize=9)
            fig.colorbar(im, ax=ax2, fraction=0.046, pad=0.04)
        else:
            ax2.text(0.5, 0.5, "need ≥3 live carriers with motion\n(correlation builds as RSSI varies)",
                     ha='center', va='center', color='#ff8866', transform=ax2.transAxes, fontsize=9)
            ax2.set_title("Multi-carrier correlation matrix", color='#00ffcc', fontsize=9)
        ax2.tick_params(colors='#666', labelsize=5)

        # Panel 3 — eigenvalue spectrum → occupancy count
        ax3 = fig.add_subplot(2, 2, 3); ax3.set_facecolor('#04060a')
        eig = p.get("rf_eigenvalues", []) if p else []
        nf  = float(p.get("rf_corr_noise_floor", 0.0)) if p else 0.0
        if eig:
            ev = np.asarray(eig, dtype=np.float64)
            thr = nf * 1.05
            cols = ['#ff4466' if v > thr else '#3a7' for v in ev]
            ax3.bar(range(len(ev)), ev, color=cols)
            ax3.axhline(thr, color='#ffcc33', lw=1.0, ls='--', label=f'mover threshold ({thr:.2f})')
            ax3.axhline(nf, color='#888', lw=0.8, ls=':', label=f'Marchenko-Pastur noise edge ({nf:.2f})')
            ax3.legend(fontsize=6, facecolor='#111', labelcolor='#ccc')
            ax3.set_xlabel("eigen-index", color='#aaa', fontsize=7)
            ax3.set_ylabel("eigenvalue", color='#aaa', fontsize=7)
            ax3.set_title(f"Carrier-covariance eigenspectrum → {cnt} independent mover(s) [REAL]",
                          color='#00ffcc', fontsize=9)
        else:
            ax3.text(0.5, 0.5, "eigenspectrum builds from real carrier covariance",
                     ha='center', va='center', color='#888', transform=ax3.transAxes, fontsize=9)
            ax3.set_title("Carrier-covariance eigenspectrum", color='#00ffcc', fontsize=9)
        ax3.tick_params(colors='#666', labelsize=6)

        # Panel 4 — radial activity + device-free targets + carrier velocities
        ax4 = fig.add_subplot(2, 2, 4); ax4.set_facecolor('#04060a')
        rad = p.get("radial_activity", []) if p else []
        rmax = float(p.get("radial_range_max", 30.0)) if p else 30.0
        if rad and np.sum(rad) > 0:
            ra = np.asarray(rad, dtype=np.float64)
            xr = np.linspace(0, rmax, len(ra))
            ax4.fill_between(xr, 0, ra, color='#ff8833', alpha=0.5, step='mid')
            ax4.plot(xr, ra, color='#ffaa33', lw=1.0, drawstyle='steps-mid')
            ax4.set_xlabel("range from receiver (m)", color='#aaa', fontsize=7)
            ax4.set_ylabel("device-free motion energy", color='#aaa', fontsize=7)
        else:
            ax4.text(0.5, 0.72, "no device-free motion on any carrier", ha='center', va='center',
                     color='#778', transform=ax4.transAxes, fontsize=9)
        # device-free targets overlaid as vertical markers
        dft = p.get("df_targets", []) if p else []
        for tgt in dft:
            ax4.axvline(tgt["range_m"], color='#00ffcc', lw=1.4, alpha=0.9)
            ax4.text(tgt["range_m"], ax4.get_ylim()[1]*0.92,
                     f"target\n{tgt['range_m']:.1f}m\nconf {tgt['confidence']*100:.0f}%",
                     color='#00ffcc', fontsize=6, ha='center', va='top')
        _tt = (f"Radial activity + {len(dft)} device-free target(s)  "
               f"(range only — bearing needs antenna array)")
        ax4.set_title(_tt, color='#00ffcc', fontsize=8.5)
        ax4.tick_params(colors='#666', labelsize=6)

        # v120/v122 Bottom row — 3 panels spanning full width
        ents_v = p.get("rf_link_entities", []) if p else []
        ents_real = [e for e in ents_v if e.get("source") != "interpolated"]

        # Panel 5a — Doppler velocity per carrier [REAL Kalman]
        try:
            ct = getattr(self.fuser, "rf_carrier_tracker", None)
            ax5a = fig.add_axes([0.07, 0.008, 0.27, 0.135])
            ax5a.set_facecolor('#04060a')
            vel_labels, vel_vals, vel_cols = [], [], []
            if ct is not None and ents_real:
                for e in ents_real[:16]:
                    cid = str(e.get("bssid", "?"))
                    rssi = float(e.get("rssi_dbm", -85.0))
                    v = ct.velocity_ms(cid, rssi)
                    if v == v:
                        vel_labels.append(str(e.get("id", "?"))[:8])
                        vel_vals.append(float(v))
                        c = '#4488ff' if v < -0.05 else '#ff4444' if v > 0.05 else '#aaaaaa'
                        vel_cols.append(c)
            if vel_vals:
                x5 = np.arange(len(vel_vals))
                ax5a.bar(x5, vel_vals, color=vel_cols, width=0.7)
                ax5a.axhline(0, color='#888', lw=0.5)
                ax5a.set_xticks(x5)
                ax5a.set_xticklabels(vel_labels, color='#888', fontsize=5.0, rotation=45, ha='right')
                ax5a.set_ylabel("m/s", color='#aaa', fontsize=6)
            else:
                ax5a.text(0.5, 0.5, "building Doppler…", ha='center', va='center',
                          color='#555', fontsize=7, transform=ax5a.transAxes)
            ax5a.tick_params(colors='#555', labelsize=5)
            ax5a.set_title("Doppler velocity [REAL Kalman]", color='#88ccaa', fontsize=6.5)
        except Exception:
            pass

        # Panel 5b — v122 HMM carrier state distribution
        try:
            _hmm_res = p.get("carrier_hmm_states", {}) if p else {}
            ax5b = fig.add_axes([0.38, 0.008, 0.27, 0.135])
            ax5b.set_facecolor('#04060a')
            _HMM_COLS = {"QUIET": "#33ddff", "RISING": "#22ff66", "FALLING": "#3399ff",
                         "OSCILLATING": "#ffaa22", "BURST": "#ff4444"}
            if _hmm_res and ents_real:
                hmm_labels, hmm_states, hmm_cols = [], [], []
                for e in ents_real[:16]:
                    bid = str(e.get("bssid", e.get("id", "?")))
                    hr = _hmm_res.get(bid, {})
                    st_name = hr.get("current_state", "QUIET")
                    hmm_labels.append(str(e.get("id", "?"))[:8])
                    hmm_states.append(st_name)
                    hmm_cols.append(_HMM_COLS.get(st_name, "#888888"))
                x5b = np.arange(len(hmm_labels))
                # Plot as colored vertical bars (height = dwell fraction in current state)
                for xi, (dw, c) in enumerate(zip(
                    [_hmm_res.get(str(ents_real[i].get("bssid","?")),{}).get("dwells",{}).get(s,0)
                     for i, s in enumerate(hmm_states) if i < len(ents_real)],
                    hmm_cols
                )):
                    ax5b.bar(xi, max(1, dw), color=c, width=0.7, alpha=0.85)
                ax5b.set_xticks(x5b)
                ax5b.set_xticklabels(hmm_labels, color='#888', fontsize=5.0, rotation=45, ha='right')
                ax5b.set_ylabel("state dwell", color='#aaa', fontsize=6)
                # Annotate state name on each bar
                for xi, (lbl, c) in enumerate(zip(hmm_states, hmm_cols)):
                    ax5b.text(xi, 0.5, lbl[:4], ha='center', va='bottom', color=c,
                              fontsize=4.5, rotation=90)
            else:
                ax5b.text(0.5, 0.5, "HMM: building carrier state sequences…",
                          ha='center', va='center', color='#555', fontsize=6.5, transform=ax5b.transAxes)
            ax5b.tick_params(colors='#555', labelsize=5)
            ax5b.set_title("HMM carrier states (QUIT/RISE/FALL/OSC/BURST) [v122 Viterbi]",
                           color='#ffaa33', fontsize=6.5)
        except Exception:
            pass

        # Panel 5c — v122 MSE complexity + modulation type per carrier
        try:
            _mse_res  = p.get("carrier_mse", {}) if p else {}
            _mod_res  = p.get("carrier_modulation", {}) if p else {}
            ax5c = fig.add_axes([0.70, 0.008, 0.27, 0.135])
            ax5c.set_facecolor('#04060a')
            _MOD_COLS = {"OFDM": "#22ffaa", "DSSS": "#ffaa22", "BLE_FHSS": "#44aaff",
                         "FM_BROADCAST": "#ff44cc", "AM_BROADCAST": "#ffff44", "NOISE": "#556677"}
            if ents_real and (_mse_res or _mod_res):
                labels5c, ci_vals, mod_cols = [], [], []
                for e in ents_real[:16]:
                    bid = str(e.get("bssid", e.get("id", "?")))
                    ci = float(_mse_res.get(bid, {}).get("complexity_index", 0.0))
                    mod = str(_mod_res.get(bid, {}).get("class", "?"))
                    labels5c.append(str(e.get("id", "?"))[:8])
                    ci_vals.append(ci)
                    mod_cols.append(_MOD_COLS.get(mod, "#aaaaaa"))
                x5c = np.arange(len(labels5c))
                ax5c.bar(x5c, ci_vals, color=mod_cols, width=0.7, alpha=0.88)
                ax5c.set_xticks(x5c)
                ax5c.set_xticklabels(labels5c, color='#888', fontsize=5.0, rotation=45, ha='right')
                ax5c.set_ylabel("MSE CI", color='#aaa', fontsize=6)
                # mod type legend (small colored patches)
                for xi, bid in enumerate([str(e.get("bssid",e.get("id","?"))) for e in ents_real[:16]]):
                    mod = str(_mod_res.get(bid, {}).get("class", "?")[:4])
                    mc = _MOD_COLS.get(_mod_res.get(bid, {}).get("class", "?"), "#888")
                    ax5c.text(xi, 0.05, mod, ha='center', va='bottom', color=mc,
                              fontsize=4.2, rotation=90)
            else:
                ax5c.text(0.5, 0.5, "MSE + modulation builds from RSSI histories…",
                          ha='center', va='center', color='#555', fontsize=6.5, transform=ax5c.transAxes)
            ax5c.tick_params(colors='#555', labelsize=5)
            ax5c.set_title("MSE complexity + modulation (OFDM/DSSS/BLE…) [v122]",
                           color='#44aaff', fontsize=6.5)
        except Exception:
            pass

        fig.text(0.5, 0.180,
                 "Kalman Doppler · Viterbi HMM states · Multi-Scale Entropy complexity · Modulation classification — "
                 "all real, derived from RSSI histories.  No fabricated positions.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_entities(self, fig, p, snap):
        """Pass 91: PER-ENTITY VIEW. Every real RF transmitter is an entity on its own link
        to this receiver, with genuine device-free link sensing — 100% instrument data.
        Each card: SSID/band/channel/freq, signal bar, RSSI, range estimate, REAL link-motion
        (a body crossing the TX→RX path perturbs that link's RSSI), and the real RSSI history
        sparkline. When CSI/mmWave hardware is attached, per-person body entities appear too."""
        ents  = p.get("rf_link_entities", []) if p else []
        n     = len(ents)
        _pres = bool(p.get("presence_detected", False)) if p else False
        _mm   = float(p.get("link_motion_max", 0.0)) if p else 0.0
        _bs   = bool(p.get("body_sensing_active", False)) if p else False
        fig.suptitle(
            f"PER-ENTITY VIEW — {n} real RF transmitters (each = one link to this RX)   ·   "
            f"presence: {'DETECTED' if _pres else 'none'}   ·   device-free movers: "
            f"{int(p.get('df_source_count', 0)) if p else 0}   ·   peak link-motion: {_mm*100:.0f}%   ·   "
            f"body-sensing: {'LIVE' if _bs else 'needs CSI/mmWave'}",
            color='#00ffcc', fontsize=11.5, fontweight='bold')
        _band_col = {"2.4GHz": "#ff5544", "5GHz": "#33ccff", "6GHz": "#cc66ff", "other": "#aaaaaa"}
        # v95: per-BODY cards render regardless of RF-transmitter count (each body its own view).
        persons = p.get("person_entities", []) if p else []
        _grid_top = 0.90
        if persons:
            _grid_top = 0.63
            np_show = persons[:4]
            pw = 0.92 / max(1, len(np_show))
            for pi, pe in enumerate(np_show):
                axp = fig.add_axes([0.04 + pi * pw, 0.66, pw * 0.94, 0.26])
                axp.set_xticks([]); axp.set_yticks([]); axp.set_xlim(0,1); axp.set_ylim(0,1)
                _pcol = '#ffaa00' if pe.get("provenance") == "SIMULATED" else '#00ffcc'
                for sp in axp.spines.values(): sp.set_color(_pcol); sp.set_linewidth(1.6)
                axp.text(0.05, 0.86, f"BODY {pe.get('id','?')}", color=_pcol, fontsize=12, weight='bold')
                axp.text(0.05, 0.70, f"HR {pe.get('hr',0):.0f} bpm", color='#ff5577', fontsize=10)
                axp.text(0.05, 0.57, f"BR {pe.get('br',0):.1f} /min", color='#55aaff', fontsize=10)
                axp.text(0.05, 0.44, f"range {pe.get('range_m',0):.1f} m", color='#88ccaa', fontsize=9)
                axp.text(0.05, 0.32, f"pos ({pe.get('x',0):.1f},{pe.get('y',0):.1f},{pe.get('z',0):.1f}) m",
                         color='#aabbcc', fontsize=8)
                _gait = pe.get('gait_hz', 0.0)
                axp.text(0.05, 0.20, f"gait {_gait:.1f} Hz  {'(walking)' if _gait>0.05 else '(still)'}",
                         color='#ccaa66', fontsize=8)
                axp.text(0.05, 0.07, f"[{pe.get('provenance','?')}]", color=_pcol, fontsize=7, weight='bold')
            fig.text(0.5, 0.945, f"PER-BODY VIEW — {len(persons)} bodies (each its own card)",
                     ha='center', color='#00ffcc', fontsize=9.5, weight='bold')
        if n == 0:
            if not persons:
                ax = fig.add_subplot(111); ax.axis('off')
                ax.text(0.5, 0.5, "No RF transmitters detected.\n(Is WiFi enabled? nmcli scan returned nothing.)",
                        ha='center', va='center', color='#ff8866', fontsize=12, transform=ax.transAxes)
            else:
                fig.text(0.5, 0.32, "(no RF transmitters — bodies above are from the active body sensor)",
                         ha='center', color='#778', fontsize=9)
            return
        cols = 4
        shown = ents[:12] if persons else ents[:16]
        rows = int(np.ceil(len(shown) / cols))
        gs = fig.add_gridspec(rows, cols, left=0.025, right=0.985, top=_grid_top, bottom=0.055,
                              hspace=0.30, wspace=0.14)
        # v121: temporal analysis results for motion tags + trends
        _temporal = p.get("carrier_temporal", {}) if p else {}
        _TAG_COL = {"STATIC": "#33ddff", "RISING": "#22ff66", "FALLING": "#3399ff",
                    "PERIODIC": "#ffaa22", "ERRATIC": "#ff4444"}
        # noise floor for SNR estimate (from iw station or iw survey)
        _noise_dbm = float(p.get("iw_station_noise_dbm", p.get("iw_noise_floor_dbm", -95.0)) if p else -95.0)
        # v133: DOA result for bearing display on entity cards
        _doa_card = (p.get("doa_result") or {}) if p else {}
        _doa_az = _doa_card.get("azimuth_deg")
        _tdoa_card = (p.get("tdoa_fix") or {}) if p else {}
        _mlat_card = (p.get("multilat_position") or {}) if p else {}
        for i, e in enumerate(shown):
            r, c = divmod(i, cols)
            ax = fig.add_subplot(gs[r, c]); ax.set_facecolor('#070b10')
            ax.set_xticks([]); ax.set_yticks([]); ax.set_xlim(0, 1); ax.set_ylim(0, 1)
            bc = _band_col.get(e.get("band", "other"), "#ffffff")
            # v132 hardening: rf_link_entities is a MIXED pool (WiFi+BLE+remote+ESP32+
            # multi-chan). Non-WiFi carriers lack chan/signal/security/rssi_dbm → use
            # .get() with derived fallbacks so the tab never crashes (was KeyError).
            _e_rssi = float(e.get("rssi_dbm", e.get("link_rssi_dbm", -100.0)))
            _e_chan = e.get("chan", e.get("channel", 0))
            _e_freq = float(e.get("freq_mhz", 0.0))
            _e_sec  = str(e.get("security", e.get("source", "")))
            _e_sig  = float(e.get("signal", max(0.0, min(100.0, (_e_rssi + 100.0) * 2.0))))
            _e_band = e.get("band", "other")
            _e_id   = str(e.get("id", e.get("ssid", e.get("bssid", "?"))))
            # v121: motion tag colours border
            _bid = str(e.get("bssid", e.get("id", "")))
            _tinfo = _temporal.get(_bid, {})
            _tag = _tinfo.get("tag", "STATIC")
            _tag_col = _TAG_COL.get(_tag, "#33ddff")
            for sp in ax.spines.values():
                sp.set_color(_tag_col); sp.set_linewidth(1.6 if _tag in ("PERIODIC", "ERRATIC") else 1.2)
            # v121: trend arrow + motion tag badge (top-right corner)
            _trd = float(_tinfo.get("trend", 0.0))
            _arr = "↑" if _trd > 0.3 else ("↓" if _trd < -0.3 else "→")
            ax.text(0.96, 0.90, f"{_arr}{_tag[:3]}", color=_tag_col, fontsize=7.5,
                    weight='bold', ha='right', va='top')
            ax.text(0.05, 0.90, _e_id[:16], color=bc, fontsize=10.0, weight='bold')
            _ch_s = f"ch{_e_chan}  " if _e_chan else ""
            _freq_s = f"{_e_freq:.0f} MHz" if _e_freq > 0 else ""
            ax.text(0.05, 0.795, f"{_e_band}  {_ch_s}{_freq_s}",
                    color='#99ffbb', fontsize=7.5)
            _rng = float(e.get('range_m', float('nan')))
            _rngs = f"{_rng:.1f} m" if _rng == _rng else "n/a"
            # v121: real SNR = RSSI − noise floor (only when noise floor is known)
            _rssi_v = _e_rssi
            _snr = _rssi_v - _noise_dbm if _noise_dbm > -94.9 else float("nan")
            _snr_s = f"  SNR {_snr:.0f} dB" if _snr == _snr else ""
            ax.text(0.05, 0.705, f"{_rssi_v:.0f} dBm  ~{_rngs}{_snr_s}  {_e_sec[:8]}",
                    color='#88aacc', fontsize=7.2)
            # signal strength bar (real, derived from RSSI when 'signal' absent)
            _sig = float(np.clip(_e_sig / 100.0, 0, 1))
            ax.add_patch(plt.Rectangle((0.05, 0.585), 0.90, 0.050, color='#11261d'))
            ax.add_patch(plt.Rectangle((0.05, 0.585), 0.90 * _sig, 0.050, color='#22ff88', alpha=0.9))
            ax.text(0.05, 0.643, f"signal {_e_sig:.0f}%", color='#22ff88', fontsize=6.8)
            # v121: RSSI trend bar — shows dB/s signed velocity
            _vol = float(_tinfo.get("volatility", 0.0))
            _per = float(_tinfo.get("period_s", 0.0))
            _trd_norm = float(np.clip(abs(_trd) / 1.5, 0, 1))
            _trd_bar_col = '#22ff66' if _trd > 0.1 else ('#3399ff' if _trd < -0.1 else '#557799')
            ax.add_patch(plt.Rectangle((0.05, 0.515), 0.90, 0.042, color='#101820'))
            ax.add_patch(plt.Rectangle((0.05, 0.515), 0.90 * _trd_norm, 0.042,
                                       color=_trd_bar_col, alpha=0.85))
            _per_s = f"  T={_per:.1f}s" if _per > 0 else ""
            ax.text(0.05, 0.564, f"trend {_trd:+.2f} dB/s  σ={_vol:.2f} dB{_per_s}",
                    color=_trd_bar_col, fontsize=6.5)
            # link-motion bar (REAL device-free sensing)
            lm = float(e.get('link_motion', 0.0))
            lmc = '#ff4466' if lm > 0.5 else ('#ffaa33' if lm > 0.15 else '#5588aa')
            ax.add_patch(plt.Rectangle((0.05, 0.44), 0.90, 0.048, color='#26111a'))
            ax.add_patch(plt.Rectangle((0.05, 0.44), 0.90 * lm, 0.048, color=lmc, alpha=0.95))
            ax.text(0.05, 0.495, f"link-motion {lm*100:.0f}%  var={e.get('link_var_db', 0.0):.2f} dB",
                    color=lmc, fontsize=6.5)
            # RSSI history sparkline (real) with trend overlay
            h = np.asarray(e.get("hist", []), dtype=np.float64)
            if h.size >= 2:
                hx = 0.05 + np.linspace(0, 0.90, h.size)
                rng = (h.max() - h.min())
                hn = (h - h.min()) / (rng + 1e-9)
                hy = 0.10 + hn * 0.22
                ax.plot(hx, hy, color=bc, lw=1.0, alpha=0.9)
                # v121: trend line overlay on sparkline
                if abs(_trd) > 0.05 and h.size >= 4:
                    try:
                        _tx = np.linspace(0, 1, h.size)
                        _tc = np.polyfit(_tx, h, 1)
                        _th = np.polyval(_tc, _tx)
                        _th_n = (_th - h.min()) / (rng + 1e-9)
                        _ty = 0.10 + np.clip(_th_n, 0, 1) * 0.22
                        ax.plot(hx, _ty, color=_trd_bar_col, lw=0.7, alpha=0.6, linestyle='--')
                    except Exception:
                        pass
                ax.text(0.05, 0.338, f"RSSI history  {h.size} real samples  [{_tag}]",
                        color='#667788', fontsize=6)
            else:
                ax.text(0.05, 0.22, "building RSSI history…", color='#556', fontsize=6.5)
            # v133: DOA/TDOA/MLAT position summary at card bottom
            _pos_parts = []
            if _doa_az is not None:
                _pos_parts.append(f"DOA {_doa_az}°")
            if _tdoa_card.get("x_m") is not None:
                _tx = float(_tdoa_card["x_m"]); _ty = float(_tdoa_card["y_m"])
                _dist = (_tx**2 + _ty**2)**0.5
                _pos_parts.append(f"TDOA {_dist:.0f}m")
            if _mlat_card.get("x_m") is not None:
                _mx = float(_mlat_card["x_m"]); _my = float(_mlat_card["y_m"])
                _md = (_mx**2 + _my**2)**0.5
                _uc = _mlat_card.get("uncertainty_m", 0)
                _pos_parts.append(f"MLAT {_md:.0f}±{_uc:.0f}m")
            _hist_len = len(e.get("rssi_history") or e.get("hist") or [])
            _pos_parts.append(f"hist={_hist_len}")
            ax.text(0.05, 0.058, "  ".join(_pos_parts),
                    color='#557799', fontsize=6.0)
        fig.text(0.5, 0.012,
                 "Each card = a genuine transmitter.  Border color = motion tag (STATIC/RISING/FALLING/PERIODIC/ERRATIC). "
                 "↑↓→ = RSSI trend.  SNR from iw noise floor.  Link-motion = REAL device-free sensing (RSSI variance).  "
                 "DOA/TDOA/MLAT from MUSIC estimator (needs ≥3 APs × 20+ history samples).",
                 ha='center', color='#778899', fontsize=8)

    def _draw_medical(self, fig, p, snap):
        """Pass 63 UI: Medical Vitals Dashboard."""
        import math as _mth
        # v86 DATA HONESTY: contactless vitals require CSI/radar hardware. If none is
        # present we show an explicit NO-SENSOR page rather than fabricated vital signs.
        _vm = p.get("vitals_mode", "none")
        if _vm == "none" or not p.get("vitals_valid", True):
            fig.suptitle("MEDICAL VITALS — NO CSI/RADAR SENSOR",
                         color='#ff6666', fontsize=13, fontweight='bold')
            axn = fig.add_subplot(111); axn.axis('off')
            axn.text(0.5, 0.62, "NO VITAL-SIGN SENSOR DETECTED", ha='center', va='center',
                     color='#ff6666', fontsize=20, weight='bold', transform=axn.transAxes)
            axn.text(0.5, 0.42,
                     "Contactless HR / BR / HRV / BP / EEG require Nexmon CSI, an SDR, or an\n"
                     "mmWave radar delivering a high-rate channel response. RSSI-only capture\n"
                     "(proc_wireless / iw / multi-AP) cannot sense vital signs.\n\n"
                     "No fabricated medical data is shown. Run with real CSI hardware, or\n"
                     "--sim-validate for a clearly-labelled SIMULATED demonstration.",
                     ha='center', va='center', color='#aaaaaa', fontsize=11,
                     transform=axn.transAxes)
            return
        _med_tag = "  [SIMULATED — demo, not real]" if _vm == "simulated" else "  [REAL CSI]"
        _med_col = '#ffaa00' if _vm == "simulated" else '#00ffcc'
        fig.suptitle("MEDICAL VITALS  (Passes 61-72)" + _med_tag,
                     color=_med_col, fontsize=12, fontweight='bold')
        # v98: PER-BODY vitals strip — each detected body shown with its OWN HR/BR, directly
        # addressing "vitals show for only 1 entity". The clinical panels below are the
        # whole-scene aggregate; full per-body cards live in the Entities tab [e].
        _pe = p.get("person_entities", []) if p else []
        if _pe:
            _prov = _pe[0].get("provenance", "?")
            _cells = "    ".join(
                f"{str(e.get('id','?'))[:6]}: HR {e.get('hr',0):.0f} · BR {e.get('br',0):.0f}"
                for e in _pe[:6])
            fig.text(0.5, 0.945, f"PER-BODY ({len(_pe)} detected): {_cells}    [{_prov}]",
                     ha='center', va='center',
                     color=('#ffaa00' if _prov == 'SIMULATED' else '#00ffcc'),
                     fontsize=9, fontweight='bold',
                     bbox=dict(boxstyle='round', facecolor='#0a0f14',
                               edgecolor=('#ffaa00' if _prov == 'SIMULATED' else '#0aa'), alpha=0.8))

        ax1 = fig.add_subplot(2, 3, 1); ax1.set_facecolor('#080808'); ax1.axis('off')
        _vr = [
            ("Heart Rate",   "%.0f bpm (sd %.1f)" % (float(p.get("p61_hr_mean",0)), float(p.get("p61_hr_std",0))), '#ff5577'),
            ("Breath Rate",  "%.1f bpm"   % float(p.get("p61_br_mean", 0)),   '#55aaff'),
            ("HRV SDNN",     "%.1f ms"    % float(p.get("p61_hrv_sdnn", 0)),  '#22ffaa'),
            ("HRV RMSSD",    "%.1f ms"    % float(p.get("p61_hrv_rmssd", 0)), '#22aaff'),
            ("HRV pNN50",    "%.1f %%"    % float(p.get("p61_hrv_pnn50", 0)), '#88aa22'),
            ("BP Systolic",  "%d mmHg"    % int(p.get("p61_bp_sys", 0)),      '#ff8844'),
            ("BP Diastolic", "%d mmHg"    % int(p.get("p61_bp_dia", 0)),      '#ffaa66'),
            ("BP Category",  str(p.get("p61_bp_category", "—")),              '#ffcc44'),
            ("BP Confidence","%d %%"      % int(p.get("p61_bp_conf", 0)),     '#88ffcc'),
            ("LF/HF Ratio",  "%.2f"       % float(p.get("p61_bp_lf_hf", 0)), '#aaccff'),
        ]
        for _i, (_n, _v, _c) in enumerate(_vr):
            ax1.text(0.03, 0.97 - _i * 0.097, "%-14s %s" % (_n, _v),
                     color=_c, fontsize=9.5, family='monospace', transform=ax1.transAxes)
        ax1.set_title("Vital Signs", color='#00ffcc', fontsize=10)

        ax2 = fig.add_subplot(2, 3, 2); ax2.set_facecolor('#080808'); ax2.axis('off')
        _sl  = str(p.get("p61_sleep_state", "Awake"))
        _act = str(p.get("p61_activity", "Unknown"))
        _md  = float(p.get("p61_meditation_score", 0.0))
        _apn = int(p.get("p61_apnea_count", 0))
        _cgh = int(p.get("p61_cough_count", 0))
        _mnd = float(p.get("p61_eeg_mindfulness", 0.0))
        _rst = float(p.get("p61_eeg_restfulness", 0.0))
        _slc = {"Awake": "#ffaa22", "Light Sleep": "#aaccff",
                "Deep Sleep": "#2255ff", "REM": "#ff55ff"}.get(_sl, "#888888")
        ax2.text(0.5, 0.93, _sl, color=_slc, fontsize=22, ha='center', va='top',
                 family='monospace', fontweight='bold', transform=ax2.transAxes)
        ax2.text(0.5, 0.75, "Activity: %s" % _act, color='#aaffcc',
                 fontsize=10, ha='center', transform=ax2.transAxes)
        ax2.text(0.05, 0.62, "Meditation:", color='#00ffcc', fontsize=9, transform=ax2.transAxes)
        _mdb = min(max(float(_md) / 100.0, 0.0), 1.0) * 0.88
        ax2.barh(0.53, _mdb, left=0.05, height=0.07, color='#22ffaa',
                 transform=ax2.transAxes, alpha=0.8)
        ax2.text(0.95, 0.55, "%.0f" % _md, color='#22ffaa', fontsize=9,
                 ha='right', transform=ax2.transAxes)
        for _i2, (_n2, _v2, _c2) in enumerate([
            ("EEG mindful", "%.3f" % _mnd, '#22aaff'),
            ("EEG restful", "%.3f" % _rst, '#aa66ff'),
            ("Apnea events", str(_apn),    '#ff3322'),
            ("Cough events", str(_cgh),    '#ffaa44'),
        ]):
            ax2.text(0.03, 0.41 - _i2 * 0.10, "%-14s %s" % (_n2, _v2),
                     color=_c2, fontsize=9, family='monospace', transform=ax2.transAxes)
        ax2.set_title("Sleep / Meditation / EEG", color='#00ffcc', fontsize=10)

        ax3 = fig.add_subplot(2, 3, 3); ax3.set_facecolor('#080808'); ax3.axis('off')
        _bps  = int(p.get("p61_bp_sys", 0))
        _bpd  = int(p.get("p61_bp_dia", 0))
        _bpct = str(p.get("p61_bp_category", "—"))
        _bpcn = int(p.get("p61_bp_conf", 0))
        _cc   = {"Normal": "#22ffaa", "Elevated": "#ffcc22",
                 "High BP Stage 1": "#ff8822", "High BP Stage 2": "#ff3322",
                 "Hypertensive Crisis": "#ff0000"}.get(_bpct, "#888888")
        ax3.text(0.5, 0.92, "%d / %d mmHg" % (_bps, _bpd), color=_cc,
                 fontsize=18, ha='center', va='top', family='monospace',
                 fontweight='bold', transform=ax3.transAxes)
        ax3.text(0.5, 0.74, _bpct, color=_cc, fontsize=13, ha='center',
                 transform=ax3.transAxes)
        ax3.text(0.5, 0.62, "Confidence: %d %%" % _bpcn,
                 color='#aaffcc', fontsize=10, ha='center', transform=ax3.transAxes)
        _sbf = min(max(float(_bps - 80) / 120.0, 0.0), 1.0) * 0.80
        ax3.barh(0.50, _sbf, left=0.10, height=0.07, color=_cc,
                 transform=ax3.transAxes, alpha=0.7)
        ax3.text(0.04, 0.52, "SBP", color='#888', fontsize=8, va='center', transform=ax3.transAxes)
        _dbf = min(max(float(_bpd - 50) / 80.0, 0.0), 1.0) * 0.80
        ax3.barh(0.40, _dbf, left=0.10, height=0.07, color=_cc,
                 transform=ax3.transAxes, alpha=0.6)
        ax3.text(0.04, 0.42, "DBP", color='#888', fontsize=8, va='center', transform=ax3.transAxes)
        for _bi, (_bn, _bcl) in enumerate([("alpha", "#22aaff"), ("beta", "#ffaa22"),
                                            ("theta", "#aa66ff"), ("gamma", "#ff5533")]):
            _bv = float(p.get("p59_band_%s" % _bn, 0.0))
            ax3.barh(0.20, min(_bv * 4.0, 0.18), left=0.05 + _bi * 0.22,
                     height=0.06, color=_bcl, transform=ax3.transAxes, alpha=0.8)
            ax3.text(0.06 + _bi * 0.22, 0.28, _bn[:3], color=_bcl,
                     fontsize=7, transform=ax3.transAxes)
        ax3.text(0.03, 0.31, "P59 EEG bands:", color='#aaffcc',
                 fontsize=7.5, transform=ax3.transAxes)
        ax3.set_title("Contactless BP  (PTT model)", color='#00ffcc', fontsize=10)

        ax4 = fig.add_subplot(2, 3, 4); ax4.set_facecolor('#080808')
        _dm = float(p.get("p61_dp_map_mean", 0.0))
        _dx = float(p.get("p61_dp_map_max", 0.0))
        _ps = float(p.get("p61_phase_clean_std", 0.0))
        try:
            _p61f = getattr(getattr(self, "fuser", None), "p61_fusion", None)
            if _p61f is None or not hasattr(_p61f, "dp_translator"):
                raise ValueError("no dp_translator")
            _rg4  = np.random.default_rng(int(p.get("frame_count", 0)) % 100 + 61)
            _a4   = _rg4.random((150, 3, 3)).astype(np.float32)
            _sp4  = _p61f.dp_translator.forward(_a4, _a4)
            ax4.imshow(_sp4[:, :, 0], cmap='plasma', origin='lower',
                       aspect='equal', vmin=0, vmax=1)
            ax4.set_title("WiFi DensePose map  mean=%.3f" % _dm, color='#00ffcc', fontsize=9)
        except Exception:
            ax4.text(0.5, 0.5, "DensePose: mean=%.3f max=%.3f phase_sd=%.3f" % (_dm, _dx, _ps),
                     ha='center', va='center', color='#aaaacc', fontsize=11, transform=ax4.transAxes)
            ax4.set_title("WiFi DensePose  (P61)", color='#00ffcc', fontsize=9)
        ax4.tick_params(colors='#666', labelsize=6)

        ax5 = fig.add_subplot(2, 3, 5, projection='3d'); ax5.set_facecolor('#050505')
        _mh  = float(p.get("p62_mm_body_height", 0.0))
        _mgx = float(p.get("p62_mm_g_loc_x", 0.0))
        _mgy = float(p.get("p62_mm_g_loc_y", 0.0))
        try:
            _p62f = getattr(getattr(self, "fuser", None), "p62_fusion", None)
            if _p62f is None or not hasattr(_p62f, "mm_model"):
                raise ValueError("no mm_model")
            _mr5 = _p62f.mm_model.synth_forward(B=1, T=1, N=32)
            _jt5 = _mr5['joints'][0, 0]
            ax5.scatter(_jt5[:, 0], _jt5[:, 1], _jt5[:, 2], c='#00ffcc', s=20, alpha=0.9)
            _sk_pairs = [(0,1),(0,2),(1,4),(2,5),(4,7),(5,8),(0,3),(3,6),
                         (6,9),(9,12),(12,15),(12,13),(12,14),(13,16),(14,17)]
            for _la5, _lb5 in _sk_pairs:
                if _la5 < 24 and _lb5 < 24:
                    ax5.plot([_jt5[_la5,0],_jt5[_lb5,0]], [_jt5[_la5,1],_jt5[_lb5,1]],
                             [_jt5[_la5,2],_jt5[_lb5,2]], color='#44ffaa', lw=1.0)
            ax5.set_title("mmMesh SMPL 24J  h=%.2fm" % _mh, color='#00ffcc', fontsize=9)
        except Exception:
            ax5.text2D(0.5, 0.5, "mmMesh 24J skeleton\nh=%.2fm  g=(%.2f,%.2f)" % (_mh,_mgx,_mgy),
                       ha='center', va='center', color='#aaffcc',
                       fontsize=11, transform=ax5.transAxes)
            ax5.set_title("mmMesh SMPL body  (P62)", color='#00ffcc', fontsize=9)
        ax5.tick_params(colors='#666', labelsize=5)

        ax6 = fig.add_subplot(2, 3, 6); ax6.set_facecolor('#080808'); ax6.axis('off')
        _p6r = [
            ("PR CFAR dets",  "%d peaks"  % int(p.get("p62_pr_n_detections", 0)),         '#00ffcc'),
            ("PR SNR peak",   "%.1f dB"   % float(p.get("p62_pr_snr_peak_db", 0)),        '#22ffaa'),
            ("PR RD mean",    "%.4f"      % float(p.get("p62_pr_rd_mean", 0)),             '#44aaff'),
            ("PR |w| norm",   "%.3f"      % float(p.get("p62_pr_w_norm", 0)),             '#88ccff'),
            ("SpecSens occ",  "%.0f%%"    % (float(p.get("p62_ss_occ_rate", 0))*100),     '#ffaa22'),
            ("Energy det",    "HIT" if p.get("p62_ss_energy_d") else "miss",              '#ffcc44'),
            ("Cyclostat det", "HIT" if p.get("p62_ss_cyclo_d")  else "miss",              '#ffee66'),
            ("SNR estimate",  "%.1f dB"   % float(p.get("p62_ss_snr_est_db", 0)),         '#ffcc88'),
            ("Body height",   "%.2f m"    % float(p.get("p62_mm_body_height", 0)),        '#ff88ff'),
            ("Joints mean Z", "%.2f m"    % float(p.get("p62_mm_joints_mean_z", 0)),      '#cc88ff'),
            ("Global loc X",  "%.2f m"    % float(p.get("p62_mm_g_loc_x", 0)),           '#aa66ff'),
            ("Global loc Y",  "%.2f m"    % float(p.get("p62_mm_g_loc_y", 0)),           '#8855ee'),
            ("Rot Frobenius", "%.3f"      % float(p.get("p62_mm_rot_frob", 0)),           '#7744dd'),
            ("ESP amp mean", "%.3f" % float(p.get("p64_esp_amp_mean", 0)), '#55ffee'),
            ("RootMUSIC 0",  "%.1fdeg" % float(p.get("p64_doa_root_music_0", 0)), '#55aaff'),
            ("PAPR",          "%.1fdB" % float(p.get("p64_doa_papr_db", 0)), '#88ffcc'),
            ("mmW+WiFi HR",   "%.0fbpm" % float(p.get("p64_fused_hr", 0)), '#ffaa55'),
            ("BCI-MI label",  str(p.get("p64_bci_mi_label", "rest")), '#ffcc88'),
        ]
        for _i6, (_n6, _v6, _c6) in enumerate(_p6r):
            ax6.text(0.03, 0.97 - _i6 * 0.073, "%-16s %s" % (_n6, _v6),
                     color=_c6, fontsize=9, family='monospace', transform=ax6.transAxes)
        ax6.set_title("P62: Passive Radar + SpecSens + mmMesh", color='#00ffcc', fontsize=9)
        # P65 physics data appended to ax6 lower region
        _p65_toa = float(p.get("p65_toa_range_m", 0.0))
        _p65_gdop = float(p.get("p65_gdop", 0.0))
        _p65_pc   = int(p.get("p65_pc_n_points", 0))
        _p65_pabs = float(p.get("p65_pabs", 0.0))
        _p65_sal  = float(p.get("p65_sal_concentration", 0.0))
        ax6.text(0.03, 0.30, "── P65 Physics ──────────────────",
                 color='#336633', fontsize=7, family='monospace', transform=ax6.transAxes)
        ax6.text(0.03, 0.24, "ToA err  %5.1f cm  GDOP %4.2f" % (_p65_toa*100, _p65_gdop),
                 color='#88ff88', fontsize=7, family='monospace', transform=ax6.transAxes)
        ax6.text(0.03, 0.17, "PC pts   %3d  range %4.2fm" % (_p65_pc, float(p.get("p65_pc_range_mean", 0.0))),
                 color='#88ccff', fontsize=7, family='monospace', transform=ax6.transAxes)
