    def _draw_medical_p65(self, ax, p):
        """P65 physics panel: ToA CRLB + Fresnel + point cloud + ReID."""
        ax.set_facecolor('#0a0a0a')
        for sp in ax.spines.values():
            sp.set_color('#1a3a1a')
        ax.set_xticks([]); ax.set_yticks([])
        _toa_m   = float(p.get("p65_toa_range_m", 0.0))
        _gdop    = float(p.get("p65_gdop", 0.0))
        _fr1     = float(p.get("p65_fresnel_r1_m", 0.0))
        _pabs    = float(p.get("p65_pabs", 0.0))
        _sal_c   = float(p.get("p65_sal_concentration", 0.0))
        _csik_snr = float(p.get("p65_csik_snr_db", 0.0))
        _pc_n    = int(p.get("p65_pc_n_points", 0))
        _pc_rng  = float(p.get("p65_pc_range_mean", 0.0))
        _reid    = str(p.get("p65_reid_label", "none"))
        _reid_c  = float(p.get("p65_reid_conf", 0.0))
        _rssi_l  = str(p.get("p65_rssi_loc", "none"))
        _rows = [
            ("ToA range err", f"{_toa_m*100:.1f} cm",   '#88ff88'),
            ("GDOP",          f"{_gdop:.2f}",            '#aaffaa'),
            ("Fresnel R1",    f"{_fr1:.2f} m",           '#88ccff'),
            ("PABS residual", f"{_pabs:.3f}",            '#ffaa44'),
            ("Sal. conc.",    f"{_sal_c:.1f}x",          '#ffff88'),
            ("CSIKit SNR",    f"{_csik_snr:.1f} dB",     '#88ffff'),
            ("PC points",     str(_pc_n),                '#ffffff'),
            ("PC range",      f"{_pc_rng:.2f} m",        '#aaffaa'),
            ("ReID label",    _reid[:12],                '#ffcc88'),
            ("ReID conf",     f"{_reid_c:.2f}",          '#ffcc88'),
            ("RSSI loc",      _rssi_l[:12],              '#cc88ff'),
        ]
        for _i, (_n, _v, _c) in enumerate(_rows):
            ax.text(0.03, 0.97 - _i * 0.087, "%-16s %s" % (_n, _v),
                    color=_c, fontsize=9, family='monospace', transform=ax.transAxes)
        ax.set_title("P65: RuView Physics + CSIKit + PC", color='#00ffcc', fontsize=9)

    def _draw_planetmap(self, fig, p, snap):
        """v97: PLANET MAP — navigable map built from REAL OpenStreetMap tiles for the node's
        real geolocation. The honest 'map the world at distance': millions of real pixels,
        zoom/pan, node pinned at its real position. No fabricated coordinates."""
        pm = getattr(self.fuser, "planet_map", None)
        fig.suptitle("PLANET MAP — REAL satellite imagery / cartography  (keys: [ ] zoom · j basemap)",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        ax = fig.add_subplot(111); ax.set_facecolor('#04121a')
        if pm is None:
            ax.axis('off')
            ax.text(0.5, 0.5, "PlanetMapEngine not initialised.", ha='center', va='center',
                    color='#ff8866', fontsize=12, transform=ax.transAxes)
            return
        st = pm.status()
        # kick a fetch if we have none yet
        if not st["have_map"] and not st["fetching"]:
            pm.build_map_async()
        with pm._lock:
            img = None if pm.map_img is None else np.array(pm.map_img)
            meta = dict(pm.map_meta)
        if img is None:
            ax.axis('off')
            if not st["online"] and st["geo_source"] == "none":
                ax.text(0.5, 0.5, "Locating node + fetching real OSM tiles…\n"
                        "(needs internet for live satellite/map data)",
                        ha='center', va='center', color='#88ccff', fontsize=12,
                        transform=ax.transAxes)
            else:
                ax.text(0.5, 0.5, "Fetching real OpenStreetMap tiles…",
                        ha='center', va='center', color='#88ccff', fontsize=12,
                        transform=ax.transAxes)
            return
        ax.imshow(img, origin='upper', interpolation='bilinear')
        # pin the node at its REAL location (centre of the stitched grid)
        try:
            px = pm.latlon_to_px(meta["lat"], meta["lon"]) or (img.shape[1] / 2, img.shape[0] / 2)
        except Exception:
            px = (img.shape[1] / 2, img.shape[0] / 2)
        ax.plot(px[0], px[1], marker='v', color='#ff3355', ms=15, mec='white', mew=1.4, zorder=10)
        ax.text(px[0] + 10, px[1] - 6, f"THIS NODE  ~{meta.get('city','')}",
                color='#ff6688', fontsize=10, fontweight='bold', zorder=11,
                bbox=dict(boxstyle='round', facecolor='#1a0008', edgecolor='#ff3355', alpha=0.8))
        # honest detected-emitter legend + to-scale range rings (real RSSI/range; NO bearing,
        # so each emitter is drawn as a RING around the node — it is somewhere on that circle,
        # never at a fabricated point). Rings use the map's true metres-per-pixel.
        # v121: all real carriers (exclude interpolated from map rings)
        ents_all = p.get("rf_link_entities", []) if p else []
        ents = [e for e in ents_all if e.get("source", "") != "interpolated"]
        # carrier temporal analysis for motion-colored rings
        _temporal = p.get("carrier_temporal", {}) if p else {}
        try:
            mpp = pm.meters_per_pixel()
        except Exception:
            mpp = 0.0
        # motion-tag → ring color: STATIC=cyan, RISING=green, FALLING=blue, PERIODIC=orange, ERRATIC=red
        _TAG_COL = {"STATIC": "#33ddff", "RISING": "#22ff66",
                    "FALLING": "#3399ff", "PERIODIC": "#ffaa22", "ERRATIC": "#ff4444"}
        if ents:
            lines = ["DETECTED RF (real RSSI · bearing unknown):"]
            ring_drawn = 0
            for e in ents[:12]:
                _r   = e.get("range_m", float("nan"))
                _rs  = f"~{_r:.0f}m" if _r == _r else "n/a"
                bid  = str(e.get("bssid", "?"))
                _ta  = _temporal.get(bid, {})
                _tag = _ta.get("tag", "STATIC")
                _trd = _ta.get("trend", 0.0)
                _arr = ("↑" if _trd > 0.3 else "↓" if _trd < -0.3 else "→")
                lines.append(f"  {str(e.get('id','?'))[:14]:14s} "
                              f"{e.get('rssi_dbm',0):.0f}dBm {_rs} {_arr}{_tag[:3]}")
                # color-coded to-scale range ring
                if mpp > 0 and _r == _r and 0 < _r < 8000:
                    rpx = _r / mpp
                    if 2 < rpx < max(img.shape[:2]) * 1.5:
                        col = _TAG_COL.get(_tag, "#33ddff")
                        lw  = 1.1 if _tag in ("PERIODIC", "ERRATIC") else 0.7
                        alpha = 0.65 if _tag != "STATIC" else 0.40
                        ax.add_patch(plt.Circle((px[0], px[1]), rpx, fill=False,
                                     edgecolor=col, lw=lw, alpha=alpha, zorder=8))
                        ring_drawn += 1
            # carrier density halo: radius proportional to carrier count
            n_real = len(ents)
            halo_r = max(20, min(80, n_real * 6))
            ax.add_patch(plt.Circle((px[0], px[1]), halo_r, fill=True,
                         facecolor='#22ff88', alpha=0.12, zorder=7))
            ax.text(px[0], px[1] + halo_r + 8, f"{n_real} carriers",
                    color='#88ffcc', fontsize=7, ha='center', zorder=11)
            # ring legend
            for tag, col in _TAG_COL.items():
                lines.append(f"  ■{col[:7]} = {tag}")
            ax.text(0.012, 0.985, "\n".join(lines[:18]), transform=ax.transAxes, va='top', ha='left',
                    color='#cfe', fontsize=7, family='monospace', zorder=11,
                    bbox=dict(boxstyle='round', facecolor='#031018', edgecolor='#0aa', alpha=0.7))
        # Remote node pins
        _rn = getattr(self.fuser, "remote_nodes", {}) or {}
        for _nid, _rec in list(_rn.items())[:8]:
            # remote nodes are on the LAN — same approximate location as this node
            # show them as small offset markers (no real geo available without GPS)
            _idx = list(_rn.keys()).index(_nid)
            _offx = 30 * ((_idx % 4) - 1.5)
            _offy = -40 - 20 * (_idx // 4)
            ax.plot(px[0] + _offx, px[1] + _offy, marker='o',
                    color='#ffcc33', ms=6, mec='#88aa00', mew=1, zorder=9, alpha=0.85)
            ax.text(px[0] + _offx, px[1] + _offy - 8,
                    str(_nid)[:8], color='#ffcc33', fontsize=5.5, ha='center', zorder=10)
        # v122: AIRCRAFT overlay — real ADS-B positions from OpenSky Network
        # Each aircraft is a real 1090 MHz ADS-B RF emitter at known lat/lon/alt.
        _aircraft = p.get("aircraft", []) if p else []
        _node_lat = float(meta.get("lat", 0.0)); _node_lon = float(meta.get("lon", 0.0))
        _ac_drawn = 0
        for _ac in _aircraft[:40]:
            try:
                _ac_lat = float(_ac.get("lat", 0.0)); _ac_lon = float(_ac.get("lon", 0.0))
                if mpp > 0 and (_ac_lat != 0 or _ac_lon != 0):
                    # Convert lat/lon offset to pixel offset using map's metres-per-pixel
                    _dlat_m = (_ac_lat - _node_lat) * 111320.0
                    _dlon_m = (_ac_lon - _node_lon) * 111320.0 * max(0.01, _m.cos(_m.radians(_node_lat)))
                    _dpx = _dlon_m / (mpp + 1e-9)
                    _dpy = -_dlat_m / (mpp + 1e-9)   # y-axis inverted
                    _apx = px[0] + _dpx; _apy = px[1] + _dpy
                    _alt = float(_ac.get("baro_alt_m", 0.0))
                    _alt_col = '#ff9900' if _alt > 8000 else ('#ffcc44' if _alt > 3000 else '#ffff88')
                    ax.plot(_apx, _apy, marker='^', color=_alt_col, ms=7,
                            mec='#ff6600', mew=0.8, zorder=12, alpha=0.85)
                    _cs = str(_ac.get("callsign", "")).strip() or str(_ac.get("icao24", ""))[:6]
                    ax.text(_apx + 5, _apy - 5, f"{_cs}\n{_alt:.0f}m",
                            color=_alt_col, fontsize=5.0, ha='left', va='bottom', zorder=13,
                            alpha=0.85)
                    _ac_drawn += 1
            except Exception:
                pass
        if _ac_drawn > 0:
            ax.text(0.012, 0.015, f"✈ {_ac_drawn} aircraft (ADS-B @1090 MHz · OpenSky)",
                    transform=ax.transAxes, va='bottom', ha='left', color='#ffaa33',
                    fontsize=7, zorder=11,
                    bbox=dict(boxstyle='round', facecolor='#0a0600', edgecolor='#ff9900', alpha=0.7))
        # v122: SATELLITE PASSES overlay — upcoming LEO passes from CelesTrak TLE
        _sat_passes = p.get("satellite_passes", []) if p else []
        _sp_drawn = 0
        for _sp_i, _sp in enumerate(_sat_passes[:6]):
            try:
                _t_s = float(_sp.get("t_pass_s", 9999))
                _urgency = '#ff4444' if _t_s < 300 else ('#ffaa33' if _t_s < 900 else '#aaffcc')
                _mins = int(_t_s // 60); _secs = int(_t_s % 60)
                _name = str(_sp.get("name", "?"))[:12]
                ax.text(0.988, 0.015 + _sp_i * 0.028,
                        f"↑SAT {_name} T-{_mins:02d}:{_secs:02d}  f={_sp.get('freq_mhz',137):.0f}MHz",
                        transform=ax.transAxes, va='bottom', ha='right', color=_urgency,
                        fontsize=6.5, zorder=11,
                        bbox=dict(boxstyle='round', facecolor='#0a060a', edgecolor=_urgency, alpha=0.65))
                _sp_drawn += 1
            except Exception:
                pass
        # LIVE local-sensing status (real device-free RSSI sensing + multi-carrier correlation)
        _pres = bool(p.get("rssi_presence", False)) if p else False
        _mot = float(p.get("rssi_motion", 0.0)) if p else 0.0
        _dfc = int(p.get("df_source_count", 0)) if p else 0
        _dfco = float(p.get("df_coherence", 0.0)) if p else 0.0
        _ncar = len(ents)
        _meth = str(p.get("capture_method", "?")) if p else "?"
        _band_nf = p.get("band_noise_floor", {}) if p else {}
        _ac_cnt = int(p.get("aircraft_count", 0)) if p else 0
        _sc_cnt = int(p.get("satellite_pass_count", 0)) if p else 0
        _sline = (f"LIVE SENSING (real)\n"
                  f" presence : {'YES' if _pres else 'none'}\n"
                  f" motion   : {_mot*100:4.0f}%\n"
                  f" WiFi carriers: {_ncar}\n"
                  f" aircraft ADS-B: {_ac_cnt}\n"
                  f" SAT passes/90m: {_sc_cnt}\n"
                  f" NF 2.4G:{_band_nf.get('2.4GHz',-95):.0f} 5G:{_band_nf.get('5GHz',-95):.0f} dBm\n"
                  f" RF-subspace movers: {_dfc} (coh {_dfco:.2f})\n"
                  f" capture  : {_meth}")
        ax.text(0.988, 0.985, _sline, transform=ax.transAxes, va='top', ha='right',
                color=('#ff8866' if _pres else '#9fb'), fontsize=7.5, family='monospace', zorder=11,
                bbox=dict(boxstyle='round', facecolor='#06121a',
                          edgecolor=('#ff5533' if _pres else '#0a8'), alpha=0.75))
        ax.set_title(f"{st.get('basemap_label','?')} · zoom {meta.get('zoom','?')} · "
                     f"{meta.get('tiles_ok',0)}/{meta.get('tiles_total',0)} real tiles · "
                     f"{meta.get('px',('?','?'))[0]}x{meta.get('px',('?','?'))[1]} px · "
                     f"loc {st['geo_source']} ({meta.get('lat',0):.4f}, {meta.get('lon',0):.4f})",
                     color='#88ccaa', fontsize=8.5)
        ax.set_xticks([]); ax.set_yticks([])
        fig.text(0.5, 0.015, "REAL cartographic data © OpenStreetMap contributors.  Node location is IP-approx "
                 "(city-level) unless a GNSS receiver is on the instrument bus.  RF emitters listed by real "
                 "RSSI/range only — one antenna gives no bearing, so none are placed at invented coordinates.",
                 ha='center', color='#6a8', fontsize=7.2)

    @staticmethod
    def _entity_list(p):
        """v101: ordered combined entity list for per-entity windows — every detected BODY
        (real or sim, with provenance) followed by every real RF transmitter (carrier). Each
        gets its own pop-up detail window. 100% from the live profile; nothing invented."""
        ents = []
        for b in (p.get("person_entities", []) or []):
            ents.append({"_t": "body", "_key": f"body:{b.get('id','?')}", **b})
        for e in (p.get("rf_link_entities", []) or []):
            ents.append({"_t": "rf", "_key": f"rf:{e.get('bssid', e.get('id','?'))}", **e})
        return ents

    def _draw_entitydetail(self, fig, p, snap):
        """v101: ONE entity, full detail, in its own window — directly answers 'each body/
        instrument in its own tab/pop-up'. Body → vitals/position/gait/skeleton (provenance
        watermarked). RF carrier → band/freq/RSSI/range + real link-motion + RSSI-history."""
        ents = self._entity_list(p)
        # v108: resolve by STABLE key so this window always tracks the SAME entity even as the
        # carrier list re-sorts every frame (fixes the per-window miscorrelation). Positional
        # index is only a fallback for windows opened before keys existed.
        e = None
        if self.entity_key is not None:
            e = next((x for x in ents if x.get("_key") == self.entity_key), None)
        if e is None and self.entity_idx is not None and self.entity_idx < len(ents):
            e = ents[self.entity_idx]
        if e is None:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, f"Entity '{self.entity_key or self.entity_idx}' no longer detected.\n"
                    f"({len(ents)} entities currently live)", ha='center', va='center',
                    color='#ff8866', fontsize=13, transform=ax.transAxes)
            return
        if e["_t"] == "body":
            _prov = e.get("provenance", "?")
            _col = '#ffaa00' if _prov == "SIMULATED" else '#00ffcc'
            fig.suptitle(f"BODY {e.get('id','?')} — full detail   [{_prov}]",
                         color=_col, fontsize=14, fontweight='bold')
            axl = fig.add_subplot(1, 2, 1); axl.axis('off')
            rows = [("ID", str(e.get("id", "?"))),
                    ("Heart Rate", f"{e.get('hr',0):.0f} bpm"),
                    ("Breath Rate", f"{e.get('br',0):.1f} /min"),
                    ("Position", f"({e.get('x',0):.1f}, {e.get('y',0):.1f}, {e.get('z',0):.1f}) m"),
                    ("Range", f"{e.get('range_m',0):.1f} m"),
                    ("Gait", f"{e.get('gait_hz',0):.2f} Hz  "
                             f"{'(walking)' if e.get('gait_hz',0) > 0.05 else '(stationary)'}"),
                    ("Provenance", _prov)]
            for i, (k, v) in enumerate(rows):
                axl.text(0.05, 0.92 - i * 0.12, k, color='#88aacc', fontsize=11, transform=axl.transAxes)
                axl.text(0.45, 0.92 - i * 0.12, v, color=_col, fontsize=12, fontweight='bold',
                         transform=axl.transAxes)
            # 3D skeleton from the body's joints if present
            axr = fig.add_subplot(1, 2, 2, projection='3d'); axr.set_facecolor('#050505')
            J = e.get("joints")
            if J is not None and len(np.asarray(J)) >= 3:
                J = np.asarray(J)
                axr.scatter(J[:, 0], J[:, 1], J[:, 2], c=_col, s=30)
            else:
                axr.text2D(0.5, 0.5, "skeleton needs CSI/mmWave joints", transform=axr.transAxes,
                           ha='center', color='#778', fontsize=10)
            axr.set_title("body skeleton", color=_col, fontsize=10)
        else:
            # v132f: include band so dual-band routers sharing one SSID (e.g. a 2.4 + 5 GHz
            # "NetgearNighthawk") are immediately distinguishable per-window. BSSID is the
            # truly-unique key — show it in the rows so no two windows look identical.
            _eband = str(e.get("band", "?"))
            fig.suptitle(f"RF CARRIER {str(e.get('id','?'))[:24]} [{_eband}] — full detail   [REAL]",
                         color='#00ffcc', fontsize=14, fontweight='bold')
            axl = fig.add_subplot(1, 2, 1); axl.axis('off')
            rows = [("SSID/ID", str(e.get("id", "?"))[:26]),
                    ("BSSID", str(e.get("bssid", e.get("_key","?")))[:24]),
                    ("Band", _eband),
                    ("Channel", str(e.get("chan", "?"))),
                    ("Frequency", f"{e.get('freq_mhz',0):.0f} MHz"),
                    ("RSSI", f"{e.get('rssi_dbm',0):.0f} dBm"),
                    ("Range est", f"~{e.get('range_m',float('nan')):.1f} m (bearing unknown)"),
                    ("Signal", f"{e.get('signal',0):.0f} %"),
                    ("Security", str(e.get("security", "?"))[:14]),
                    ("Link-motion", f"{e.get('link_motion',0)*100:.0f}%  (REAL device-free)")]
            for i, (k, v) in enumerate(rows):
                axl.text(0.05, 0.93 - i * 0.10, k, color='#88aacc', fontsize=10, transform=axl.transAxes)
                axl.text(0.42, 0.93 - i * 0.10, v, color='#00ffcc', fontsize=11, fontweight='bold',
                         transform=axl.transAxes)
            axr = fig.add_subplot(1, 2, 2); axr.set_facecolor('#070b10')
            h = np.asarray(e.get("hist", []), dtype=np.float64)
            if h.size >= 2:
                axr.plot(h, color='#22ff88', lw=1.4)
                axr.set_title(f"REAL RSSI history ({h.size} samples)", color='#00ffcc', fontsize=10)
                axr.set_ylabel("dBm", color='#789', fontsize=8)
                axr.tick_params(colors='#445', labelsize=7)
            else:
                axr.axis('off')
                axr.text(0.5, 0.5, "building RSSI history…", ha='center', va='center',
                         color='#556', transform=axr.transAxes)
        fig.text(0.5, 0.02, f"Entity '{e.get('_key','?')}' · {len(ents)} entities live.  "
                 f"This window tracks this exact entity (stable key — no re-sort drift).  "
                 f"Open all per-entity windows with key [P].",
                 ha='center', color='#678', fontsize=8)

    def _draw_netspectrum(self, fig, p, snap):
        """v134: PLANET-SCALE MULTISPECTRUM OVERLAY — HF through microwave.

        Full electromagnetic spectrum coverage from HF (1.8 MHz WSPR paths) through
        WiFi microwave (7.2 GHz). Real data only: WSPR spots from WSPR.live for HF,
        nmcli/iw for WiFi bands. Space weather (NOAA SWPC) shows ionospheric context.
        Layout: HF spectrum | WiFi spectrum | waterfall | band summary | modulation/HMM.
        """
        ents  = p.get("rf_link_entities", []) if p else []
        _nn   = int(p.get("remote_node_count", 0)) if p else 0
        _comb = int(p.get("combined_carrier_count", len(ents))) if p else len(ents)
        _mc   = int(p.get("mc_scan_total", 0)) if p else 0
        _interp_n = int(p.get("interp_carrier_count", 0)) if p else 0
        _wspr_spots = (p.get("wspr_spots") or snap.get("wspr_spots") or []) if p else []
        _wspr_n = int(p.get("wspr_n_spots", len(_wspr_spots))) if p else len(_wspr_spots)
        _kp   = float((p.get("kp_index") or snap.get("kp_index") or 0.0) if p else 0.0)
        _f107 = float((p.get("f107_flux") or snap.get("f107_flux") or 0.0) if p else 0.0)
        _sw_ok = bool((p.get("space_weather_ok") or snap.get("space_weather_ok") or False) if p else False)
        fig.suptitle(
            f"MULTISPECTRUM OVERLAY: HF-to-microwave — {_comb} WiFi carriers · "
            f"{_wspr_n} WSPR HF paths · {_nn} remote nodes"
            + (f" · Kp={_kp:.0f} F10.7={_f107:.0f}" if _sw_ok else ""),
            color='#00ffcc', fontsize=11, fontweight='bold')

        FMIN, FMAX, NB = 2400.0, 7200.0, 1920          # ~2.5 MHz bins
        freqs = np.linspace(FMIN, FMAX, NB)
        # Separate real vs interpolated
        power_real = np.full(NB, -110.0)
        power_interp = np.full(NB, -110.0)
        occ   = np.zeros(NB); nper = np.zeros(NB)
        chan_w = 20.0
        for e in ents:
            try:
                f = float(e.get("freq_mhz", 0.0)); rssi = float(e.get("rssi_dbm", -100.0))
            except Exception:
                continue
            if f < FMIN or f > FMAX:
                continue
            mask = np.abs(freqs - f) < chan_w
            src = str(e.get("source", ""))
            if src == "interpolated":
                power_interp[mask] = np.maximum(power_interp[mask], rssi)
            else:
                power_real[mask] = np.maximum(power_real[mask], rssi)
                occ[mask] = 1.0; nper[mask] += 1

        # ── iw survey noise floor (real kernel driver data) ──────────────────
        survey = p.get("iw_survey", {}) if p else {}
        noise_freqs, noise_vals = [], []
        busy_freqs, busy_vals   = [], []
        for fmhz, sd in sorted(survey.items()):
            if FMIN <= fmhz <= FMAX:
                noise_freqs.append(fmhz)
                noise_vals.append(sd.get("noise_dbm", -95.0))
                busy_freqs.append(fmhz)
                busy_vals.append(sd.get("busy_pct", 0.0))

        cols = ['#ff5544', '#33ccff', '#cc66ff', '#888888']

        # ── 5-row layout: HF spectrum | WiFi spectrum | waterfall | band summary | mod/HMM ──
        _gs = fig.add_gridspec(5, 1, top=0.92, bottom=0.05,
                               left=0.07, right=0.97,
                               hspace=0.50,
                               height_ratios=[1.0, 1.8, 1.1, 0.85, 0.85])

        # ── Panel 0: HF WSPR spectrum (1.8–30 MHz) ─────────────────────────
        ax_hf = fig.add_subplot(_gs[0]); ax_hf.set_facecolor('#040a06')
        _HF_BANDS = [(1.838,0.002,"160m"),(3.594,0.002,"80m"),(5.366,0.002,"60m"),
                     (7.040,0.003,"40m"),(10.140,0.003,"30m"),(14.097,0.003,"20m"),
                     (18.106,0.003,"17m"),(21.096,0.004,"15m"),(24.926,0.004,"12m"),
                     (28.126,0.005,"10m")]
        _HF_COL = {"160m":"#ff6633","80m":"#ff9922","60m":"#ffcc33","40m":"#ccff33",
                   "30m":"#33ff66","20m":"#33ffcc","17m":"#33ccff","15m":"#3388ff",
                   "12m":"#8833ff","10m":"#ff33cc"}
        _band_snr: dict = {}
        _band_cnt: dict = {}
        _band_dist: dict = {}
        for sp in _wspr_spots:
            bl = str(sp.get("band_label", "?"))
            snr = float(sp.get("snr_db", -30) or -30)
            dist = float(sp.get("distance_km", 0) or 0)
            _band_snr.setdefault(bl, []).append(snr)
            _band_cnt[bl] = _band_cnt.get(bl, 0) + 1
            _band_dist.setdefault(bl, []).append(dist)
        _wspr_freqs, _wspr_snr_peak, _wspr_cols = [], [], []
        for fc, bw, lbl in _HF_BANDS:
            _snr_list = _band_snr.get(lbl, [])
            _peak = max(_snr_list) if _snr_list else None
            _wspr_freqs.append(fc)
            _wspr_snr_peak.append(_peak if _peak is not None else -99)
            _wspr_cols.append(_HF_COL.get(lbl, "#888888"))
            col_v = _HF_COL.get(lbl, "#888888")
            ax_hf.axvspan(fc - bw * 3, fc + bw * 3, color=col_v, alpha=0.12)
            if _band_cnt.get(lbl, 0) > 0:
                _snr_peak_v = max(_snr_list) if _snr_list else -30
                _dist_avg = sum(_band_dist.get(lbl, [0])) / max(len(_band_dist.get(lbl, [1])), 1)
                ax_hf.text(fc, -5, f"{lbl}\n{_band_cnt[lbl]}sp\n{_dist_avg:.0f}km",
                           ha='center', va='top', color=col_v, fontsize=5.5)
        _hf_active = [f for f, s in zip(_wspr_freqs, _wspr_snr_peak) if s > -90]
        _hf_snr_a  = [s for s in _wspr_snr_peak if s > -90]
        if _hf_active:
            ax_hf.vlines(_hf_active, -35, _hf_snr_a, colors=[_wspr_cols[_wspr_freqs.index(f)]
                                                               for f in _hf_active],
                         lw=3, alpha=0.85, zorder=5)
        ax_hf.set_xlim(1.5, 30); ax_hf.set_ylim(-35, 5)
        ax_hf.set_xlabel("frequency (MHz)", color='#789', fontsize=6.5)
        ax_hf.set_ylabel("peak SNR (dB)", color='#789', fontsize=6.5)
        ax_hf.tick_params(colors='#456', labelsize=5.5)
        _sw_str = (f"  Kp={_kp:.0f} F10.7={_f107:.0f}" if _sw_ok else " (space weather pending)")
        ax_hf.set_title(f"HF WSPR SPECTRUM — {_wspr_n} real propagation paths from WSPR.live{_sw_str}",
                        color='#66ff88', fontsize=7.5)
        for sp2 in ax_hf.spines.values(): sp2.set_color('#0a2a0a')

        # ── Panel 1: WiFi/microwave spectrum analyzer ───────────────────────
        ax1 = fig.add_subplot(_gs[1]); ax1.set_facecolor('#04080e')
        # interpolated carriers (faded, dashed outline)
        interp_on = power_interp > -109
        if interp_on.any():
            ax1.fill_between(freqs, -110, power_interp, where=interp_on,
                             color='#886622', alpha=0.2, step='mid')
            ax1.plot(freqs[interp_on], power_interp[interp_on],
                     color='#ffaa44', lw=0.5, ls='--', alpha=0.7, label='[INTERPOLATED]')
        # real carriers (solid, bright)
        real_on = power_real > -109
        ax1.fill_between(freqs, -110, power_real, where=real_on,
                         color='#22ff88', alpha=0.45, step='mid')
        ax1.plot(freqs, power_real, color='#22ff88', lw=0.7, label='REAL measured')
        # iw-survey noise floor
        if noise_freqs:
            ax1.step(noise_freqs, noise_vals, where='mid', color='#ff4466',
                     lw=0.8, alpha=0.8, label=f'noise floor [iw survey {len(noise_freqs)} ch]')
        # band shading
        for bi, (lo, hi, nm) in enumerate([(2400,2500,"2.4G"),(5150,5925,"5G"),(5925,7125,"6G")]):
            ax1.axvspan(lo, hi, color=cols[bi], alpha=0.05)
            ax1.text((lo + hi) / 2, -41, nm, color=cols[bi], fontsize=7.5, ha='center')
        ax1.set_xlim(FMIN, FMAX); ax1.set_ylim(-110, -35)
        ax1.set_xlabel("frequency (MHz)", color='#789', fontsize=7)
        ax1.set_ylabel("peak RSSI (dBm)", color='#789', fontsize=7)
        ax1.tick_params(colors='#456', labelsize=6)
        _real_occ = 100.0 * occ.mean()
        ax1.set_title(f"{NB} bins · {int(occ.sum())} real-occupied ({_real_occ:.1f}%) · "
                      f"{_interp_n} interpolated [physics fill] · noise from iw-survey",
                      color='#88ccaa', fontsize=8)
        if noise_freqs or interp_on.any():
            ax1.legend(fontsize=6, facecolor='#111', labelcolor='#ccc', loc='upper right')

        # ── Panel 2: time-frequency waterfall (v123 SpectrumWaterfallBuffer) ─
        ax_wf = fig.add_subplot(_gs[2]); ax_wf.set_facecolor('#03060a')
        _wfb = getattr(self.fuser, "spectrum_waterfall", None)
        _wf_drawn = False
        if _wfb is not None:
            try:
                _wf_arr = _wfb.get()
                if _wf_arr is not None and _wf_arr.shape[0] > 1:
                    ax_wf.imshow(_wf_arr, aspect='auto', origin='lower',
                                 cmap='inferno', vmin=-105, vmax=-50,
                                 extent=[_wfb._fmin, _wfb._fmax, 0, _wf_arr.shape[0]],
                                 interpolation='bilinear')
                    ax_wf.set_xlim(FMIN, FMAX)
                    ax_wf.set_xlabel("frequency (MHz)", color='#789', fontsize=6.5)
                    ax_wf.set_ylabel("time (old→new)", color='#789', fontsize=6.5)
                    ax_wf.set_title(
                        f"RSSI time-frequency waterfall — {_wf_arr.shape[0]} time steps × "
                        f"{_wf_arr.shape[1]} freq bins  [real carrier histories · inferno colormap]",
                        color='#88ccaa', fontsize=7.5)
                    ax_wf.tick_params(colors='#456', labelsize=5.5)
                    _wf_drawn = True
            except Exception:
                pass
        if not _wf_drawn:
            ax_wf.text(0.5, 0.5,
                       "Waterfall: RSSI carrier histories accumulating… (fills after first scan cycle)",
                       ha='center', va='center', color='#446',
                       transform=ax_wf.transAxes, fontsize=9)
            ax_wf.set_xticks([]); ax_wf.set_yticks([])
            ax_wf.set_title("RSSI Time-Frequency Waterfall (v123) — building…",
                            color='#88ccaa', fontsize=7.5)

        # ── Panel 3: channel utilization (busy%) from iw survey ─────────────
        ax2 = fig.add_subplot(_gs[3]); ax2.set_facecolor('#04080e')
        bands = [("2.4 GHz", 2400, 2500), ("5 GHz", 5150, 5925), ("6 GHz", 5925, 7125)]
        names = []; occs_b = []; cnts_b = []
        for nm, lo, hi in bands:
            m = (freqs >= lo) & (freqs < hi)
            names.append(nm)
            occs_b.append(100.0 * occ[m].mean() if m.any() else 0.0)
            cnts_b.append(int(sum(1 for e in ents
                               if lo <= float(e.get("freq_mhz", 0)) < hi
                               and e.get("source") != "interpolated")))
        x = np.arange(len(names))
        ax2.bar(x - 0.18, occs_b, 0.36, color='#33ccff', alpha=0.8, label='carrier occ%')
        ax2b = ax2.twinx()
        ax2b.bar(x + 0.18, cnts_b, 0.36, color='#ffaa33', alpha=0.8, label='real carriers')
        # overlay iw-survey busy% as scatter per channel
        if busy_freqs:
            for fmhz, bpct in zip(busy_freqs, busy_vals):
                band_idx = (0 if fmhz < 2500 else 1 if fmhz < 5925 else 2)
                ax2.scatter(band_idx, bpct, c='#ff5544', s=12, alpha=0.7, zorder=5)
        ax2.set_xticks(x); ax2.set_xticklabels(names, color='#ccc', fontsize=8)
        ax2.set_ylabel("carrier occupancy %", color='#33ccff', fontsize=7)
        ax2b.set_ylabel("real carrier count", color='#ffaa33', fontsize=7)
        ax2.tick_params(colors='#456', labelsize=6)
        ax2b.tick_params(colors='#456', labelsize=6)
        ax2.set_title("per-band: carrier occupancy (bar) + iw-survey busy % (red dots) + carrier count",
                      color='#88ccaa', fontsize=8)

        # ── Panel 4: modulation + HMM state breakdown (v123) ────────────────
        ax3 = fig.add_subplot(_gs[4]); ax3.set_facecolor('#04060a')
        ax3.set_xlim(0, 1); ax3.set_ylim(0, 1)
        ax3.set_xticks([]); ax3.set_yticks([])
        _modp = p.get("carrier_modulation", {}) if p else {}
        _hmmp = p.get("carrier_hmm_states", {}) if p else {}
        _MOD_COL = {"OFDM": "#22ffaa", "DSSS": "#ffaa22", "BLE_FHSS": "#44aaff",
                    "FM_BROADCAST": "#ff44cc", "AM_BROADCAST": "#ffff44", "NOISE": "#445566"}
        _HMM_COL = {"QUIET": "#33ddff", "RISING": "#22ff66", "FALLING": "#3399ff",
                    "OSCILLATING": "#ffaa22", "BURST": "#ff4444"}
        # modulation bar
        _mods = {}
        for v in _modp.values():
            c = v.get("class", "NOISE"); _mods[c] = _mods.get(c, 0) + 1
        _total_m = max(sum(_mods.values()), 1)
        x_off = 0.0
        for c, n in sorted(_mods.items(), key=lambda kv: -kv[1]):
            w = n / _total_m * 0.48
            ax3.add_patch(plt.Rectangle((x_off, 0.56), w, 0.30,
                          facecolor=_MOD_COL.get(c, "#888"), alpha=0.8))
            if w > 0.04:
                ax3.text(x_off + w / 2, 0.71, f"{c[:4]}\n{n}", ha='center', va='center',
                         color='white', fontsize=5.0, weight='bold')
            x_off += w
        ax3.text(0.24, 0.92, "Modulation", ha='center', va='top', color='#22ffaa',
                 fontsize=7.5, weight='bold')
        # HMM state bar (right half)
        _hmm_cts = {}
        for v in _hmmp.values():
            s = v.get("current_state", "QUIET"); _hmm_cts[s] = _hmm_cts.get(s, 0) + 1
        _total_h = max(sum(_hmm_cts.values()), 1)
        x_off2 = 0.52
        for s in ["QUIET", "RISING", "FALLING", "OSCILLATING", "BURST"]:
            n = _hmm_cts.get(s, 0)
            w = n / _total_h * 0.46
            ax3.add_patch(plt.Rectangle((x_off2, 0.56), w, 0.30,
                          facecolor=_HMM_COL.get(s, "#888"), alpha=0.8))
            if w > 0.04:
                ax3.text(x_off2 + w / 2, 0.71, f"{s[:3]}\n{n}", ha='center', va='center',
                         color='white', fontsize=5.0, weight='bold')
            x_off2 += w
        ax3.text(0.75, 0.92, "HMM carrier states", ha='center', va='top', color='#ffaa22',
                 fontsize=7.5, weight='bold')
        ax3.axvline(0.50, color='#225', lw=1.0)
        # noise floor line
        _bnf = p.get("band_noise_floor", {}) if p else {}
        _nf_s = (f"NF: 2.4G={_bnf.get('2.4GHz',-110):.0f}  5G={_bnf.get('5GHz',-110):.0f}  "
                 f"6G={_bnf.get('6GHz',-110):.0f} dBm  |  "
                 f"Acoustic={int(float((p.get('acoustic_sensor',{}) or {}).get('motion',0))*100)}%  "
                 f"Thermal={float((p.get('thermal_sensor',{}) or {}).get('max_temp_c',0)):.1f}°C")
        ax3.text(0.5, 0.24, _nf_s, ha='center', va='center', color='#778899',
                 fontsize=6.5, transform=ax3.transAxes)
        for sp in ax3.spines.values():
            sp.set_color('#0a2a3a'); sp.set_linewidth(0.8)
        ax3.set_title("v123: modulation classes  |  HMM carrier states  |  band noise floors + sensor fusion",
                      color='#88ccaa', fontsize=7.5)

        fig.text(0.5, 0.012,
                 "HF=WSPR spots (WSPR.live real RX paths) · WiFi=measured RSSI · "
                 "[INTERPOLATED]=physics-extrapolated (path-loss RBF, labeled) · "
                 "Space weather=NOAA SWPC. No fabrication.",
                 ha='center', color='#6a8', fontsize=7)

    def _draw_globalview(self, fig, p, snap):
        """v123: GLOBAL OVERVIEW — ALL SENSORS UNIFIED in one navigable view.

        Shows every real data source simultaneously: planet map + aircraft + carrier
        spectrum + presence sensors + waterfall timeline + satellite passes + thermal +
        acoustic + MQTT IoT sensors + modulation + HMM states + multipath structure.
        No fabricated data — every panel is gated on real instrument input.
        """
        import math as _m
        ents_all = p.get("rf_link_entities", []) if p else []
        ents = [e for e in ents_all if e.get("source") != "interpolated"]
        aircraft = p.get("aircraft", []) if p else []
        sat_passes = p.get("satellite_passes", []) if p else []
        _acoustic = p.get("acoustic_sensor", {}) if p else {}
        _thermal = p.get("thermal_sensor", {}) if p else {}
        _mqtt_hints = p.get("mqtt_presence_hints", []) if p else []
        _mqtt_devs = int(p.get("mqtt_device_count", 0)) if p else 0
        _gps = p.get("gps_fix", {}) if p else {}
        _n_real = len(ents)
        _n_ac = len(aircraft)
        _n_sat = len(sat_passes)
        _pres = bool(p.get("rssi_presence", False)) if p else False
        _mot = float(p.get("rssi_motion", 0.0)) if p else 0.0
        _dfc = int(p.get("df_source_count", 0)) if p else 0
        _hmm_pool = p.get("carrier_hmm_states", {}) if p else {}
        _mod_pool = p.get("carrier_modulation", {}) if p else {}
        _cfp = p.get("carrier_fingerprint", {}) if p else {}
        _acoustic_mot = float(_acoustic.get("motion", 0.0))
        _thermal_warm = bool(_thermal.get("warming", False))
        _n_mqtt_pres = len(_mqtt_hints)
        _bnf = p.get("band_noise_floor", {}) if p else {}

        fig.suptitle(
            f"GLOBAL OVERVIEW — {_n_real} WiFi carriers · {_n_ac} aircraft (ADS-B) · "
            f"{_n_sat} sat-passes · presence={int(_mot*100)}% · acoustic={int(_acoustic_mot*100)}% · "
            f"IoT={_n_mqtt_pres} hints · thermal={'WARM' if _thermal_warm else 'nominal'}",
            color='#00ffcc', fontsize=10, fontweight='bold')

        gs = fig.add_gridspec(3, 4,
                              top=0.91, bottom=0.06,
                              left=0.04, right=0.97,
                              hspace=0.40, wspace=0.28,
                              height_ratios=[2.2, 1.3, 1.0])

        # ── Row 0, Col 0-1: Mini planet map (thumbnail with range rings + aircraft) ──
        ax_map = fig.add_subplot(gs[0, 0:2])
        ax_map.set_facecolor('#04121a')
        pm = getattr(self.fuser, "planet_map", None)
        _map_drawn = False
        _node_lat = 0.0; _node_lon = 0.0
        if pm is not None:
            try:
                with pm._lock:
                    img = None if pm.map_img is None else np.array(pm.map_img)
                    meta = dict(pm.map_meta)
                if img is not None:
                    ax_map.imshow(img, origin='upper', interpolation='bilinear')
                    _node_lat = float(meta.get("lat", 0.0))
                    _node_lon = float(meta.get("lon", 0.0))
                    px = pm.latlon_to_px(_node_lat, _node_lon) or (img.shape[1]/2, img.shape[0]/2)
                    ax_map.plot(px[0], px[1], 'v', color='#ff3355', ms=9,
                                mec='white', mew=1.2, zorder=10)
                    _TAG_COL = {"STATIC": "#33ddff", "RISING": "#22ff66",
                                "FALLING": "#3399ff", "PERIODIC": "#ffaa22", "ERRATIC": "#ff4444"}
                    _temporal = p.get("carrier_temporal", {}) if p else {}
                    try:
                        mpp = pm.meters_per_pixel()
                    except Exception:
                        mpp = 0.0
                    for e in ents[:10]:
                        _r = e.get("range_m", float("nan"))
                        _bid = str(e.get("bssid", "?"))
                        _tag = _temporal.get(_bid, {}).get("tag", "STATIC")
                        if mpp > 0 and _r == _r and 0 < _r < 8000:
                            rpx = _r / mpp
                            if 2 < rpx < max(img.shape[:2]) * 1.5:
                                ax_map.add_patch(plt.Circle((px[0], px[1]), rpx, fill=False,
                                                 edgecolor=_TAG_COL.get(_tag, "#33ddff"),
                                                 lw=0.6, alpha=0.5, zorder=8))
                    for _ac in aircraft[:12]:
                        try:
                            _dlat_m = (float(_ac.get("lat", 0)) - _node_lat) * 111320.0
                            _dlon_m = (float(_ac.get("lon", 0)) - _node_lon) * 111320.0 * max(0.01, _m.cos(_m.radians(_node_lat)))
                            if mpp > 0:
                                _apx = px[0] + _dlon_m / mpp
                                _apy = px[1] - _dlat_m / mpp
                                ax_map.plot(_apx, _apy, '^', color='#ffaa33', ms=4,
                                            mec='#ff6600', mew=0.5, zorder=12, alpha=0.85)
                        except Exception:
                            pass
                    _map_drawn = True
            except Exception:
                pass
        if not _map_drawn:
            ax_map.text(0.5, 0.5, "Planet map loading…\n(internet required for tiles)",
                        ha='center', va='center', color='#88ccff', fontsize=10,
                        transform=ax_map.transAxes)
        ax_map.set_xticks([]); ax_map.set_yticks([])
        _gps_s = f" GPS±{_gps.get('epx_m', 99):.0f}m" if _gps.get("ok") else " (IP-geo)"
        ax_map.set_title(f"Planet Map{_gps_s} · {_n_real} carriers · {_n_ac} aircraft",
                         color='#88ccaa', fontsize=8)

        # ── Row 0, Col 2: Live wideband spectrum strip ────────────────────────
        ax_spec = fig.add_subplot(gs[0, 2])
        ax_spec.set_facecolor('#04080e')
        FMIN, FMAX, NB = 2400.0, 7200.0, 384
        freqs = np.linspace(FMIN, FMAX, NB)
        power_real = np.full(NB, -110.0)
        for e in ents:
            try:
                f = float(e.get("freq_mhz", 0.0))
                rssi = float(e.get("rssi_dbm", -100.0))
                if FMIN <= f <= FMAX:
                    mask = np.abs(freqs - f) < 20.0
                    power_real[mask] = np.maximum(power_real[mask], rssi)
            except Exception:
                continue
        real_on = power_real > -109
        ax_spec.fill_between(freqs, -110, power_real, where=real_on,
                             color='#22ff88', alpha=0.4, step='mid')
        ax_spec.plot(freqs, power_real, color='#22ff88', lw=0.6)
        for _lo, _hi, _nm, _c in [(2400, 2500, "2.4G", "#ff5544"),
                                   (5150, 5925, "5G",  "#33ccff"),
                                   (5925, 7125, "6G",  "#cc66ff")]:
            ax_spec.axvspan(_lo, _hi, color=_c, alpha=0.04)
            ax_spec.text((_lo + _hi) / 2, -40, _nm, color=_c, fontsize=6, ha='center')
        ax_spec.set_xlim(FMIN, FMAX); ax_spec.set_ylim(-110, -35)
        ax_spec.set_title(f"Live spectrum — {_n_real} real carriers", color='#00ffcc', fontsize=8)
        ax_spec.tick_params(colors='#446', labelsize=5)
        ax_spec.set_xticks([2450, 5500, 6500])
        ax_spec.set_ylabel("dBm", color='#667', fontsize=6)
        _nf_all = float(_bnf.get("all", -110.0))
        if _nf_all > -109:
            ax_spec.axhline(_nf_all, color='#ff8800', lw=0.7, ls='--', alpha=0.7)
            ax_spec.text(FMAX - 50, _nf_all + 1.5, f"NF {_nf_all:.0f}dBm", color='#ff8800', fontsize=5.5, ha='right')

        # ── Row 0, Col 3: Sensor fusion summary panel ─────────────────────────
        ax_fusion = fig.add_subplot(gs[0, 3])
        ax_fusion.set_facecolor('#04080e')
        ax_fusion.set_xticks([]); ax_fusion.set_yticks([])
        ax_fusion.set_xlim(0, 1); ax_fusion.set_ylim(0, 1)
        _pres_col = '#ff4444' if _pres else '#33ddff'
        ax_fusion.add_patch(plt.Rectangle((0.08, 0.83), 0.84, 0.09,
                            facecolor='#0a1a2a', edgecolor=_pres_col, lw=1.5))
        ax_fusion.add_patch(plt.Rectangle((0.08, 0.83), 0.84 * _mot, 0.09,
                            facecolor=_pres_col, alpha=0.82))
        ax_fusion.text(0.5, 0.945, f"WiFi RSSI motion {int(_mot*100)}%  "
                       f"{'DETECTED' if _pres else 'none'}",
                       ha='center', va='bottom', color=_pres_col, fontsize=8, weight='bold')
        _ac_col = '#ff9900' if _acoustic_mot > 0.2 else '#668'
        ax_fusion.add_patch(plt.Rectangle((0.08, 0.70), 0.84, 0.08,
                            facecolor='#0a0a1a', edgecolor=_ac_col, lw=1.0))
        ax_fusion.add_patch(plt.Rectangle((0.08, 0.70), 0.84 * _acoustic_mot, 0.08,
                            facecolor=_ac_col, alpha=0.80))
        ax_fusion.text(0.5, 0.81, f"Acoustic Doppler {int(_acoustic_mot*100)}%"
                       + ("  [live]" if _acoustic.get("ok") else "  [no mic]"),
                       ha='center', va='bottom', color=_ac_col, fontsize=7)
        _th_col = '#ff6633' if _thermal_warm else '#449966'
        _max_t = float(_thermal.get("max_temp_c", 0.0))
        _trd_t = float(_thermal.get("max_trend_dC_min", 0.0))
        ax_fusion.text(0.5, 0.64, f"Thermal: {_max_t:.1f}°C  {_trd_t:+.3f}°C/min  "
                       f"{'WARMING' if _thermal_warm else 'stable'}",
                       ha='center', va='bottom', color=_th_col, fontsize=7)
        _mqtt_col = '#ffff44' if _n_mqtt_pres > 0 else '#556'
        ax_fusion.text(0.5, 0.57, f"MQTT IoT: {_mqtt_devs} devices · {_n_mqtt_pres} presence hints",
                       ha='center', va='bottom', color=_mqtt_col, fontsize=7)
        if _gps.get("ok"):
            ax_fusion.text(0.5, 0.50, f"GPS: {_gps.get('lat', 0):.5f},{_gps.get('lon', 0):.5f}  "
                           f"alt {_gps.get('alt_m', 0):.1f}m ±{_gps.get('epx_m', 99):.1f}m",
                           ha='center', va='bottom', color='#22ff88', fontsize=6.5)
        else:
            ax_fusion.text(0.5, 0.50, "GPS: no gpsd receiver → using IP-geolocation",
                           ha='center', va='bottom', color='#446', fontsize=6.5)
        _n_chg = sum(1 for v in _cfp.values() if v.get("changed"))
        _chg_col = '#ff4444' if _n_chg > 0 else '#446'
        ax_fusion.text(0.5, 0.43, f"Carrier change detect: {_n_chg}/{_n_real} changed (KS-test)",
                       ha='center', va='bottom', color=_chg_col, fontsize=7)
        ax_fusion.text(0.5, 0.36, f"RF movers: {_dfc}  (Marchenko-Pastur noise floor)",
                       ha='center', va='bottom', color='#88ffcc', fontsize=7)
        _nf_2g = float(_bnf.get("2.4GHz", -110.0)); _nf_5g = float(_bnf.get("5GHz", -110.0))
        _nf_6g = float(_bnf.get("6GHz", -110.0))
        ax_fusion.text(0.5, 0.29, f"Noise floor: 2.4G={_nf_2g:.0f}  5G={_nf_5g:.0f}  6G={_nf_6g:.0f} dBm",
                       ha='center', va='bottom', color='#778899', fontsize=6.5)
        for sp in ax_fusion.spines.values():
            sp.set_color('#0a3a4a'); sp.set_linewidth(1.0)
        ax_fusion.set_title("Sensor Fusion — ALL REAL SOURCES", color='#00ffcc', fontsize=8)

        # ── Row 1 (full width): RSSI time-frequency waterfall ─────────────────
        ax_wf = fig.add_subplot(gs[1, :])
        ax_wf.set_facecolor('#03060a')
        wf_buf = getattr(self.fuser, "spectrum_waterfall", None)
        _wf_drawn = False
        if wf_buf is not None:
            try:
                wf_arr = wf_buf.get()
                if wf_arr is not None and wf_arr.shape[0] > 1:
                    ax_wf.imshow(wf_arr, aspect='auto', origin='lower',
                                 cmap='inferno', vmin=-105, vmax=-50,
                                 extent=[wf_buf._fmin, wf_buf._fmax, 0, wf_arr.shape[0]],
                                 interpolation='bilinear')
                    ax_wf.set_xlabel("Frequency (MHz)", color='#789', fontsize=7)
                    ax_wf.set_ylabel("Time steps (oldest→newest)", color='#789', fontsize=7)
                    ax_wf.set_title(
                        f"RSSI Time-Frequency Waterfall — {wf_arr.shape[1]} freq bins × {wf_arr.shape[0]} time steps"
                        f"  [real carrier histories — inferno: dark=quiet, bright=active]",
                        color='#88ccaa', fontsize=8)
                    ax_wf.set_xlim(wf_buf._fmin, wf_buf._fmax)
                    ax_wf.tick_params(colors='#456', labelsize=6)
                    _wf_drawn = True
            except Exception:
                pass
        if not _wf_drawn:
            ax_wf.text(0.5, 0.5,
                       "Waterfall: carrier RSSI history accumulating… (updates each fuse cycle)",
                       ha='center', va='center', color='#446', transform=ax_wf.transAxes, fontsize=9)
            ax_wf.set_xticks([]); ax_wf.set_yticks([])
        ax_wf.tick_params(colors='#456', labelsize=6)

        # ── Row 2, Col 0: HMM carrier state distribution (bar) ───────────────
        ax_hmm = fig.add_subplot(gs[2, 0])
        ax_hmm.set_facecolor('#04060a')
        _HMM_COLS = {"QUIET": "#33ddff", "RISING": "#22ff66", "FALLING": "#3399ff",
                     "OSCILLATING": "#ffaa22", "BURST": "#ff4444"}
        _HMM_STATES = ["QUIET", "RISING", "FALLING", "OSCILLATING", "BURST"]
        _state_counts = {s: 0 for s in _HMM_STATES}
        for v in _hmm_pool.values():
            s = v.get("current_state", "QUIET")
            if s in _state_counts:
                _state_counts[s] += 1
        if any(_state_counts.values()):
            _sc_vals = [_state_counts[s] for s in _HMM_STATES]
            _sc_cols = [_HMM_COLS[s] for s in _HMM_STATES]
            ax_hmm.bar(range(len(_sc_vals)), _sc_vals, color=_sc_cols, width=0.65)
            ax_hmm.set_xticks(range(len(_HMM_STATES)))
            ax_hmm.set_xticklabels([s[:4] for s in _HMM_STATES], color='#aaa', fontsize=6.5)
        else:
            ax_hmm.text(0.5, 0.5, "HMM: building histories…",
                        ha='center', va='center', color='#445', transform=ax_hmm.transAxes, fontsize=8)
        ax_hmm.tick_params(colors='#556', labelsize=5)
        ax_hmm.set_title("HMM carrier states", color='#ffaa22', fontsize=7.5)

        # ── Row 2, Col 1: Modulation classification pie ───────────────────────
        ax_mod = fig.add_subplot(gs[2, 1])
        ax_mod.set_facecolor('#04060a')
        _MOD_COLS = {"OFDM": "#22ffaa", "DSSS": "#ffaa22", "BLE_FHSS": "#44aaff",
                     "FM_BROADCAST": "#ff44cc", "AM_BROADCAST": "#ffff44", "NOISE": "#445566"}
        _mod_counts = {}
        for v in _mod_pool.values():
            cls = v.get("class", "NOISE")
            _mod_counts[cls] = _mod_counts.get(cls, 0) + 1
        if _mod_counts:
            _mc_labels = list(_mod_counts.keys())
            _mc_vals = [_mod_counts[k] for k in _mc_labels]
            _mc_cols = [_MOD_COLS.get(k, "#888") for k in _mc_labels]
            try:
                ax_mod.pie(_mc_vals, labels=_mc_labels, colors=_mc_cols,
                           autopct='%1.0f%%',
                           textprops={'color': '#ccc', 'fontsize': 5.5},
                           pctdistance=0.78, startangle=90)
            except Exception:
                ax_mod.bar(range(len(_mc_vals)), _mc_vals, color=_mc_cols)
                ax_mod.set_xticks(range(len(_mc_labels)))
                ax_mod.set_xticklabels(_mc_labels, fontsize=5.5, color='#ccc')
        else:
            ax_mod.text(0.5, 0.5, "Classifying modulation…",
                        ha='center', va='center', color='#445', transform=ax_mod.transAxes, fontsize=8)
        ax_mod.set_title("Signal modulation types", color='#22ffaa', fontsize=7.5)

        # ── Row 2, Col 2: Aircraft radar (polar-style relative positions) ──────
        ax_radar = fig.add_subplot(gs[2, 2])
        ax_radar.set_facecolor('#020c04')
        ax_radar.set_aspect('equal', adjustable='box')
        ax_radar.set_xticks([]); ax_radar.set_yticks([])
        ax_radar.set_xlim(-200, 200); ax_radar.set_ylim(-200, 200)
        for r_km in [50, 100, 150, 200]:
            ax_radar.add_patch(plt.Circle((0, 0), r_km, fill=False,
                                          edgecolor='#224422', lw=0.5, alpha=0.6))
            ax_radar.text(r_km, 2, f"{r_km}km", color='#335533', fontsize=4.5)
        ax_radar.axhline(0, color='#224422', lw=0.4); ax_radar.axvline(0, color='#224422', lw=0.4)
        ax_radar.plot(0, 0, 'v', color='#ff3355', ms=7, mec='white', mew=1.0, zorder=10)
        for _ac in aircraft[:40]:
            try:
                _dlat_km = (float(_ac.get("lat", 0)) - _node_lat) * 111.32
                _dlon_km = (float(_ac.get("lon", 0)) - _node_lon) * 111.32 * max(0.01, _m.cos(_m.radians(_node_lat)))
                _alt = float(_ac.get("baro_alt_m", _ac.get("geo_alt_m", 0)) or 0)
                _alt_col = '#ff9900' if _alt > 8000 else ('#ffcc44' if _alt > 3000 else '#88ff88')
                ax_radar.plot(_dlon_km, _dlat_km, '^', color=_alt_col, ms=4,
                              mec='#ff6600', mew=0.4, zorder=8, alpha=0.85)
            except Exception:
                pass
        ax_radar.set_title(f"Aircraft radar — {_n_ac} ADS-B", color='#ffaa33', fontsize=7.5)

        # ── Row 2, Col 3: Satellite passes + thermal + MQTT summary ───────────
        ax_sat = fig.add_subplot(gs[2, 3])
        ax_sat.set_facecolor('#04080e')
        ax_sat.set_xticks([]); ax_sat.set_yticks([])
        ax_sat.set_xlim(0, 1); ax_sat.set_ylim(0, 1)
        yc = 0.96
        ax_sat.text(0.5, yc, "SATELLITE PASSES (next 90 min)", ha='center', va='top',
                    color='#aaffcc', fontsize=7.0, weight='bold'); yc -= 0.10
        for _sp in sat_passes[:4]:
            _t_s = float(_sp.get("t_pass_s", 9999))
            _mins = int(_t_s // 60); _secs = int(_t_s % 60)
            _urg = '#ff4444' if _t_s < 300 else ('#ffaa33' if _t_s < 900 else '#88ffcc')
            _sname = str(_sp.get("name", "?"))[:14]
            ax_sat.text(0.05, yc, f"↑ {_sname:14s} T-{_mins:02d}:{_secs:02d}",
                        va='top', color=_urg, fontsize=6.5); yc -= 0.09
        if not sat_passes:
            ax_sat.text(0.5, yc, "(fetching CelesTrak TLEs…)", ha='center', va='top',
                        color='#446', fontsize=7); yc -= 0.09
        ax_sat.axhline(yc + 0.04, color='#225', lw=0.6); yc -= 0.02
        ax_sat.text(0.5, yc, "THERMAL SENSORS", ha='center', va='top',
                    color='#ff9944', fontsize=7.0, weight='bold'); yc -= 0.09
        for _zn, _zd in list(_thermal.get("zones", {}).items())[:3]:
            _zt = float(_zd.get("temp_c", 0.0)); _ztr = float(_zd.get("trend_dC_min", 0.0))
            ax_sat.text(0.05, yc, f"{str(_zd.get('type','?'))[:10]:10s} {_zt:.1f}°C  {_ztr:+.3f}°C/min",
                        va='top', color='#ffbb77', fontsize=5.5); yc -= 0.07
        if not _thermal.get("zones"):
            ax_sat.text(0.5, yc, "(no thermal zones found in /sys)", ha='center', va='top',
                        color='#446', fontsize=6.5); yc -= 0.07
        ax_sat.axhline(yc + 0.04, color='#225', lw=0.6); yc -= 0.02
        ax_sat.text(0.5, yc, f"MQTT IoT: {_mqtt_devs} devices · {_n_mqtt_pres} presence hints",
                    ha='center', va='top', color='#ffff44', fontsize=7.0); yc -= 0.08
        for sp in ax_sat.spines.values():
            sp.set_color('#0a2a3a'); sp.set_linewidth(0.8)
        ax_sat.set_title("Satellites · Thermal · MQTT", color='#aaffcc', fontsize=7.5)

        fig.text(0.5, 0.016,
                 "GLOBAL OVERVIEW: WiFi RSSI · ADS-B aircraft · CelesTrak LEO satellites · "
                 "acoustic Doppler · system thermal · MQTT IoT · GPS/IP-geo — ALL REAL DATA, NO FABRICATION.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_multispec(self, fig, p, snap):
        """v124: UNIVERSAL MULTISPECTRUM — 0 to 30 GHz panoramic view.

        Shows ALL known RF emission sources across the full useful RF spectrum:
        FM broadcast · cellular · GPS · ADS-B · WiFi · satellite.
        Real measurements marked REAL in solid green; known-frequency physics
        estimates in dashed amber; never fabricated RSSI values.
        Two panels: 0-3 GHz (terrestrial) and 3-30 GHz (satellite/microwave).
        """
        _bs = p.get("broadband_spectrum", []) if p else []
        _n_real = sum(1 for s in _bs if s.get("source", "").startswith("REAL"))
        _n_known = sum(1 for s in _bs if "KNOWN" in s.get("source", ""))
        _n_phys = sum(1 for s in _bs if s.get("source", "") == "PHYSICS_EST")
        _rtlsdr_ok = bool(p.get("rtlsdr_ok")) if p else False
        _cell_ok = bool((p.get("cellular_signal") or {}).get("ok")) if p else False
        _ac_n = int(p.get("aircraft_count", 0)) if p else 0
        _sat_sigs = p.get("satellite_signals", []) if p else []
        _xbc = p.get("cross_band_coherence", {}) if p else {}

        fig.suptitle(
            f"UNIVERSAL MULTISPECTRUM 0–30 GHz — {_n_real} REAL · {_n_known} known-freq · "
            f"{_n_phys} physics-est · RTL-SDR={'LIVE' if _rtlsdr_ok else 'no dongle'} · "
            f"Cellular={'LIVE' if _cell_ok else 'no modem'} · {_ac_n} ADS-B aircraft",
            color='#00ffcc', fontsize=10, fontweight='bold')

        gs = fig.add_gridspec(3, 1, top=0.91, bottom=0.06,
                              left=0.07, right=0.97, hspace=0.45,
                              height_ratios=[1.8, 1.8, 0.9])

        # ── Source colour coding ──────────────────────────────────────────────
        _SRC_COLS = {
            "REAL_WIFI":    ("#22ff88", "-",  2.0),
            "REAL_ADSB":    ("#ffaa33", "-",  2.5),
            "REAL_CELLULAR":("#ff88ff", "-",  2.5),
            "REAL_SDR":     ("#00ccff", "-",  1.0),
            "KNOWN_FREQ":   ("#ffdd44", "--", 1.2),
            "KNOWN_FREQ_OVERHEAD": ("#ff6600", "--", 1.5),
            "PHYSICS_EST":  ("#558866", ":",  1.0),
        }

        def _plot_spectrum(ax, flo_mhz, fhi_mhz, title_col, title):
            ax.set_facecolor('#03060a')
            ax.set_xlim(flo_mhz, fhi_mhz)
            ax.set_ylim(-140, -20)
            ax.set_ylabel("Power (dBm est)", color='#789', fontsize=6.5)
            ax.tick_params(colors='#456', labelsize=6)
            ax.set_title(title, color=title_col, fontsize=8)
            # Plot known band backgrounds
            _BANDS = [
                (88, 108, "#55aa33", "FM"),
                (700, 900, "#2244aa", "Cell-A"),
                (1710, 2170, "#2266cc", "Cell-B1"),
                (2400, 2500, "#ff5544", "WiFi 2.4"),
                (5150, 5925, "#33ccff", "WiFi 5"),
                (5925, 7125, "#cc66ff", "WiFi 6"),
                (1575, 1576, "#88ff44", "GPS L1"),
                (1090, 1091, "#ffaa33", "ADS-B"),
                (10700, 12750, "#aa33ff", "Ku-sat"),
                (17800, 20200, "#ff33aa", "Ka-sat"),
            ]
            for blo, bhi, bc, bn in _BANDS:
                if bhi >= flo_mhz and blo <= fhi_mhz:
                    ax.axvspan(max(blo, flo_mhz), min(bhi, fhi_mhz), color=bc, alpha=0.06)
                    mid = (max(blo, flo_mhz) + min(bhi, fhi_mhz)) / 2
                    if flo_mhz <= mid <= fhi_mhz:
                        ax.text(mid, -25, bn, color=bc, fontsize=5.5,
                                ha='center', va='top', alpha=0.9)
            # Plot each source
            plotted_labels = set()
            for entry in _bs:
                try:
                    f = float(entry["freq_mhz"])
                    pw = float(entry["power_dbm"])
                    src = str(entry.get("source", "PHYSICS_EST"))
                    lbl = str(entry.get("label", "?"))[:14]
                except Exception:
                    continue
                if not (flo_mhz <= f <= fhi_mhz):
                    continue
                col, ls, lw = _SRC_COLS.get(src, ("#668", ":", 0.8))
                ax.axvline(f, color=col, ls=ls, lw=lw, alpha=0.85)
                ax.scatter([f], [pw], c=col, s=18, zorder=5, alpha=0.9)
                if lbl not in plotted_labels:
                    ax.text(f, pw + 3, lbl, color=col, fontsize=4.5,
                            ha='center', va='bottom', rotation=70, alpha=0.85)
                    plotted_labels.add(lbl)

        # ── Panel 0: 0-3 GHz (terrestrial: FM, GPS, ADS-B, cellular, WiFi 2.4G) ──
        ax0 = fig.add_subplot(gs[0])
        _plot_spectrum(ax0, 80.0, 3000.0,
                       "#ffaa33", "0.08 – 3 GHz  [FM · GPS · ADS-B · Cellular · WiFi 2.4G]")
        ax0.set_xlabel("MHz", color='#789', fontsize=6)

        # ── Panel 1: 3-30 GHz (microwave: WiFi 5/6G, satellite Ku/Ka) ───────
        ax1 = fig.add_subplot(gs[1])
        _plot_spectrum(ax1, 3000.0, 30000.0,
                       "#cc66ff", "3 – 30 GHz  [WiFi 5G/6G · Satellite Ku/Ka · ISM 5.8G]")
        ax1.set_xlabel("MHz", color='#789', fontsize=6)

        # ── Panel 2: Cross-band coherence + legend + stats ───────────────────
        ax2 = fig.add_subplot(gs[2])
        ax2.set_facecolor('#04060a')
        ax2.set_xticks([]); ax2.set_yticks([])
        ax2.set_xlim(0, 1); ax2.set_ylim(0, 1)
        # Legend
        y = 0.95
        for src, (col, ls, lw) in _SRC_COLS.items():
            ax2.plot([0.02, 0.08], [y, y], color=col, ls=ls, lw=max(lw, 1.0))
            ax2.text(0.10, y, f"{src:<22s}", color=col, fontsize=6.0,
                     va='center', family='monospace')
            y -= 0.14
        # Cross-band coherence summary (right side)
        ax2.text(0.55, 0.95, "CROSS-BAND COHERENCE", color='#88ccff',
                 fontsize=7.0, weight='bold', va='top')
        y2 = 0.80
        for pair, d in _xbc.items():
            c = float(d.get("coherence", 0))
            col = '#22ff88' if abs(c) > 0.7 else ('#ffaa33' if abs(c) > 0.4 else '#446')
            ax2.text(0.55, y2, f"{pair}: ρ={c:+.3f}  n={d.get('n',0)}",
                     color=col, fontsize=6.5, va='top'); y2 -= 0.13
        if not _xbc:
            ax2.text(0.55, 0.70, "cross-band: building histories…",
                     color='#446', fontsize=6.5, va='top')
        # Satellite signals overhead
        if _sat_sigs:
            ax2.text(0.55, 0.30, f"Overhead sats: {len(_sat_sigs)} freq lines emitting",
                     color='#ff6600', fontsize=6.5, va='top')
        for sp in ax2.spines.values():
            sp.set_color('#0a2a3a')
        ax2.set_title("Signal source legend · Cross-band coherence · Overhead satellite emitters",
                      color='#88ccaa', fontsize=7.5)

        fig.text(0.5, 0.015,
                 "REAL=direct measurement · KNOWN_FREQ=orbital/physics truth · "
                 "PHYSICS_EST=location-estimated · ALL labels honest — no fabricated RSSI values.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_tomoview(self, fig, p, snap):
        """v124: MULTI-CARRIER ART TOMOGRAPHY — 2D RF scatter image.

        Algebraic Reconstruction Technique (ART) using RSSI excess attenuation
        along AP→RX rays at multiple frequencies. Each AP-frequency pair acts
        as a projection. The 32×32 image shows where scatterers (walls, bodies,
        furniture) are densest relative to the RX position.
        Real-data only — image is flat when insufficient APs are visible.
        """
        _img = p.get("tomo_image", None) if p else None
        _ents = [e for e in (p.get("rf_link_entities", []) if p else [])
                 if e.get("source") != "interpolated"]
        _n_ents = len(_ents)
        _fzb = p.get("fresnel_body", {}) if p else {}
        _xbc = p.get("cross_band_coherence", {}) if p else {}

        fig.suptitle(
            f"MULTI-CARRIER TOMOGRAPHY — {_n_ents} real AP rays · "
            f"Fresnel body prob={_fzb.get('fresnel_body_prob', 0)*100:.0f}% · "
            f"ART 32×32 grid",
            color='#00ffcc', fontsize=11, fontweight='bold')

        gs = fig.add_gridspec(2, 2, top=0.91, bottom=0.06,
                              left=0.06, right=0.97,
                              hspace=0.40, wspace=0.30)

        # ── Tomo image (top-left, big) — ART + optional NeRF2 density overlay ──
        ax_img = fig.add_subplot(gs[0, 0:2])
        ax_img.set_facecolor('#03060a')
        # NeRF2 volumetric XY underlay (from v132 RFNeRFVolumetricEngine)
        _nerf_xy_tomo = (p.get("nerf_density_xy") if p else None)
        if _nerf_xy_tomo is not None and np.max(_nerf_xy_tomo) > 0.01:
            ax_img.imshow(_nerf_xy_tomo.T, origin='lower', aspect='equal',
                          extent=[0, 10, 0, 10], cmap='Blues_r',
                          vmin=0, vmax=float(np.max(_nerf_xy_tomo)),
                          alpha=0.30, interpolation='bilinear')
        if _img is not None and isinstance(_img, np.ndarray) and _img.max() > 0.001:
            im = ax_img.imshow(_img, origin='lower', cmap='hot', aspect='equal',
                                interpolation='gaussian',
                                extent=[0, 10, 0, 10])
            fig.colorbar(im, ax=ax_img, fraction=0.04, pad=0.01,
                         label="scatter density (excess dB/m)")
            # Mark RX at centre
            ax_img.plot(5, 5, 'v', color='#00ffcc', ms=10,
                        mec='white', mew=1.0, zorder=10)
            ax_img.text(5.2, 5.2, "RX (you)", color='#00ffcc', fontsize=7)
            # Mark each AP at estimated position
            import math as _m124
            for i, e in enumerate(_ents[:12]):
                rng = float(e.get("range_m", 5.0) or 5.0)
                ang = (hash(str(e.get("bssid", i))) % 360) * 3.14159 / 180
                apx = 5.0 + min(rng, 8.0) * _m124.cos(ang)
                apy = 5.0 + min(rng, 8.0) * _m124.sin(ang)
                apx = max(0.5, min(9.5, apx)); apy = max(0.5, min(9.5, apy))
                ax_img.plot(apx, apy, 's', color='#22aaff', ms=6,
                            mec='white', mew=0.6, zorder=9)
                ax_img.text(apx, apy + 0.3,
                             str(e.get("ssid", "?"))[:8],
                             color='#22aaff', fontsize=4.5, ha='center')
            ax_img.set_xlim(0, 10); ax_img.set_ylim(0, 10)
            ax_img.set_xlabel("X (m)", color='#789', fontsize=7)
            ax_img.set_ylabel("Y (m)", color='#789', fontsize=7)
            ax_img.set_title(
                f"RF scatter density — {_n_ents} APs · ART 32×32 · hot=high scatter",
                color='#ff8844', fontsize=8)
        else:
            ax_img.text(0.5, 0.5,
                        "Tomography: need ≥2 real APs in view to reconstruct scene.\n"
                        "Image builds over multiple fuse cycles.\n"
                        f"Current APs visible: {_n_ents}",
                        ha='center', va='center', color='#446',
                        transform=ax_img.transAxes, fontsize=10)
            ax_img.set_xticks([]); ax_img.set_yticks([])
            ax_img.set_title("RF Scatter Tomography (ART) — building…",
                             color='#88ccaa', fontsize=8)
        ax_img.tick_params(colors='#456', labelsize=6)

        # ── Fresnel zone analysis (bottom-left) ───────────────────────────────
        ax_fz = fig.add_subplot(gs[1, 0])
        ax_fz.set_facecolor('#04060a')
        ax_fz.set_xticks([]); ax_fz.set_yticks([])
        ax_fz.set_xlim(0, 1); ax_fz.set_ylim(0, 1)
        _fb_prob = float(_fzb.get("fresnel_body_prob", 0))
        _fb_col = '#ff4444' if _fb_prob > 0.5 else ('#ffaa33' if _fb_prob > 0.25 else '#33ddff')
        ax_fz.add_patch(plt.Rectangle((0.05, 0.65), 0.90, 0.18,
                         facecolor='#0a1a2a', edgecolor=_fb_col, lw=1.5))
        ax_fz.add_patch(plt.Rectangle((0.05, 0.65), 0.90 * _fb_prob, 0.18,
                         facecolor=_fb_col, alpha=0.85))
        ax_fz.text(0.5, 0.88, f"Fresnel body probability: {_fb_prob*100:.0f}%",
                   ha='center', va='bottom', color=_fb_col, fontsize=9, weight='bold')
        # Per-band Fresnel radii
        _frad = _fzb.get("fresnel_radii", {})
        _fbrssi = _fzb.get("fresnel_band_rssi", {})
        y = 0.58
        for b in ["2.4G", "5G", "6G"]:
            if b in _frad:
                r1 = _frad[b]; rssi = _fbrssi.get(b, 0)
                bc = '#ff4444' if r1 <= 0.25 else ('#ffaa33' if r1 <= 0.4 else '#446')
                ax_fz.text(0.05, y, f"{b}: r₁={r1:.3f}m  RSSI={rssi:.0f}dBm  "
                           f"{'← body fills zone!' if r1 <= 0.25 else ''}",
                           color=bc, fontsize=7.5, va='top'); y -= 0.12
        ax_fz.text(0.5, 0.12, f"Link range: ~{_fzb.get('fresnel_range_m', 0):.1f}m  "
                   f"Body radius ~0.25m  [Fresnel zone physics]",
                   ha='center', va='bottom', color='#778899', fontsize=6.5)
        for sp in ax_fz.spines.values():
            sp.set_color('#0a2a3a')
        ax_fz.set_title("Fresnel Zone Body Detection", color='#ffaa33', fontsize=8)

        # ── Cross-band coherence (bottom-right) ───────────────────────────────
        ax_xb = fig.add_subplot(gs[1, 1])
        ax_xb.set_facecolor('#04060a')
        if _xbc:
            pairs = list(_xbc.keys())
            cohs = [abs(float(_xbc[k].get("coherence", 0))) for k in pairs]
            cols = ['#22ff88' if c > 0.7 else ('#ffaa33' if c > 0.4 else '#334455')
                    for c in cohs]
            ax_xb.barh(range(len(pairs)), cohs, color=cols, height=0.6)
            ax_xb.set_yticks(range(len(pairs)))
            ax_xb.set_yticklabels(pairs, fontsize=7, color='#ccc')
            ax_xb.set_xlim(0, 1.0)
            ax_xb.axvline(0.7, color='#22ff88', lw=0.8, ls='--', alpha=0.7)
            ax_xb.axvline(0.4, color='#ffaa33', lw=0.8, ls='--', alpha=0.7)
            ax_xb.text(0.72, len(pairs) - 0.5, ">0.7: same reflector",
                       color='#22ff88', fontsize=5.5)
        else:
            ax_xb.text(0.5, 0.5, "Cross-band: building\nRSSI histories…",
                       ha='center', va='center', color='#446',
                       transform=ax_xb.transAxes, fontsize=9)
        ax_xb.tick_params(colors='#456', labelsize=6)
        ax_xb.set_xlabel("|correlation coefficient|", color='#789', fontsize=6.5)
        ax_xb.set_title("Cross-Band Coherence (shared reflectors)", color='#88ccff', fontsize=8)

        fig.text(0.5, 0.015,
                 "ART=Algebraic Reconstruction Technique · Fresnel zone = body detection physics · "
                 "Cross-band ρ > 0.7 indicates shared real physical reflector · All real RSSI data.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_rfsplat(self, fig, p, snap):
        """v125: RF GAUSSIAN SPLATTING — 2D power map from real path-loss estimates.
        Each AP is an isotropic Gaussian ring at estimated RSSI range. Based on RF-GS paper.
        Network topology from /proc/net/arp. Doppler velocity from multi-AP RSSI rates."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _ents = snap.get("rf_link_entities") or []
        _net_devs = snap.get("network_devices") or []
        _occ = snap.get("cyclo_occupancy") or {}
        _doppler = snap.get("doppler_velocity") or {}
        _splat_img = snap.get("rf_splat_image")
        _n_aps = len(snap.get("all_channel_aps") or [])

        gs = GridSpec(2, 2, figure=fig, left=0.04, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.34, wspace=0.22)

        # ── Panel 0 (left, full height): 2D RF Gaussian Splat power map ──
        ax0 = fig.add_subplot(gs[:, 0])
        ax0.set_facecolor("#04101a")
        _ext = 50.0
        if _splat_img is not None and np.max(_splat_img) > 0:
            im = ax0.imshow(_splat_img, origin='lower',
                            extent=[-_ext, _ext, -_ext, _ext],
                            cmap='inferno', vmin=0.0, vmax=1.0,
                            interpolation='bilinear', aspect='equal')
            # Overlay RSSI range rings per carrier
            _RSSI_REF = -40.0; _PL_N = 2.7
            for ent in _ents[:24]:
                rssi = float(ent.get("rssi", ent.get("link_rssi_db", -100)))
                if rssi < -96:
                    continue
                freq = float(ent.get("center_mhz", ent.get("freq_mhz", 2440)))
                d = 10.0 ** ((_RSSI_REF - rssi) / (10.0 * _PL_N))
                d = min(d, 48.0)
                col = ("#22ff88" if freq < 3000 else
                       "#ff88ff" if freq > 5900 else "#00ccff")
                circ = plt.Circle((0, 0), d, color=col, fill=False,
                                  lw=0.7, alpha=0.55, zorder=4)
                ax0.add_patch(circ)
            ax0.plot(0, 0, 'w^', ms=11, zorder=6, label="RX node")
            cb = fig.colorbar(im, ax=ax0, shrink=0.55, pad=0.02)
            cb.set_label("Rel. Power", color="#aaccbb", fontsize=8)
            cb.ax.yaxis.set_tick_params(labelcolor="#aaccbb", labelsize=7)
        else:
            ax0.text(0.5, 0.5, f"Building splat…\n{len(_ents)} carriers",
                     ha='center', va='center', color='#446655', fontsize=13,
                     transform=ax0.transAxes)
            ax0.set_xlim(-_ext, _ext); ax0.set_ylim(-_ext, _ext)
        ax0.set_title(f"RF GAUSSIAN SPLAT — {len(_ents)} real carriers / {_n_aps} APs",
                      color='#00ffcc', fontsize=11, fontweight='bold', pad=6)
        ax0.set_xlabel("East (m)", color='#aaccbb', fontsize=9)
        ax0.set_ylabel("North (m)", color='#aaccbb', fontsize=9)
        ax0.tick_params(colors='#aaccbb', labelsize=8)
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')
        _leg_txt = "  ■ 2.4GHz   ■ 5GHz   ■ 6GHz   △ RX"
        ax0.text(0.01, 0.99, _leg_txt, transform=ax0.transAxes, color='#aaccbb',
                 fontsize=7.5, va='top')

        # ── Panel 1 (top right): Network topology — real ARP devices ──
        ax1 = fig.add_subplot(gs[0, 1])
        ax1.set_facecolor("#04101a")
        ax1.set_title("REAL NETWORK TOPOLOGY — /proc/net/arp", color='#00ffcc', fontsize=10)
        if _net_devs:
            vendors = {}
            for dev in _net_devs:
                v = dev.get("vendor", "Unknown")
                vendors[v] = vendors.get(v, 0) + 1
            vlist = sorted(vendors.items(), key=lambda x: x[1], reverse=True)[:8]
            names = [v[0][:16] for v in vlist]
            counts = [v[1] for v in vlist]
            bar_colors = ["#22ff88", "#00ccff", "#ff88ff", "#ffdd44",
                          "#ff9933", "#44aaff", "#ff4455", "#aaffcc"][:len(names)]
            ax1.barh(range(len(names)), counts, color=bar_colors, alpha=0.82)
            ax1.set_yticks(range(len(names)))
            ax1.set_yticklabels(names, fontsize=8, color='#aaccbb')
            ax1.set_xlabel("Device Count", color='#aaccbb', fontsize=8)
            ax1.tick_params(colors='#aaccbb', labelsize=8)
            ax1.text(0.99, 0.99, f"Total: {len(_net_devs)} LAN devices",
                     transform=ax1.transAxes, ha='right', va='top',
                     color='#00ffcc', fontsize=8.5)
            # List IPs
            _ip_lines = [f"  {str(d.get('ip', d.get('addr','?'))):<15} "
                         f"{str(d.get('vendor', d.get('hostname','')))[:12]}"
                         for d in _net_devs[:6]]
            ax1.text(0.01, 0.01, "\n".join(_ip_lines), transform=ax1.transAxes,
                     va='bottom', ha='left', color='#557766', fontsize=7,
                     fontfamily='monospace')
        else:
            ax1.text(0.5, 0.5, "Scanning LAN…\n(/proc/net/arp)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax1.transAxes)
        for sp in ax1.spines.values():
            sp.set_color('#1a3a4a')
        ax1.tick_params(colors='#aaccbb', labelsize=8)

        # ── Panel 2 (bottom right): Channel occupancy + Doppler velocity ──
        ax2 = fig.add_subplot(gs[1, 1])
        ax2.set_facecolor("#04101a")
        ax2.set_title("CYCLOSTATIONARY OCCUPANCY + DOPPLER VELOCITY",
                      color='#00ffcc', fontsize=10)
        if _occ:
            bands = list(_occ.keys())
            occs = [_occ[b].get("occupancy", 0.0) * 100.0 for b in bands]
            n_carr = [_occ[b].get("n_carriers", 0) for b in bands]
            xpos = np.arange(len(bands))
            bcols = ["#22ff88", "#00ccff", "#ff88ff"][:len(bands)]
            ax2.bar(xpos, occs, color=bcols, alpha=0.82, width=0.55)
            ax2.set_xticks(xpos)
            ax2.set_xticklabels(
                [f"{b}\n({nc} carriers)" for b, nc in zip(bands, n_carr)],
                fontsize=8, color='#aaccbb')
            ax2.set_ylabel("Occupancy %", color='#aaccbb', fontsize=9)
            ax2.set_ylim(0, 108)
            ax2.axhline(50.0, color='#ff4444', lw=0.7, ls='--', alpha=0.5)
            ax2.tick_params(colors='#aaccbb', labelsize=8)
            # Period annotations
            for i, b in enumerate(bands):
                pms = _occ[b].get("period_ms")
                if pms:
                    ax2.text(i, occs[i] + 3, f"{pms:.0f}ms", ha='center',
                             color='#ffdd44', fontsize=7)
        else:
            ax2.text(0.5, 0.6, "Accumulating RSSI history…",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax2.transAxes)
            ax2.set_ylim(0, 108)
        if _doppler:
            spd = _doppler.get("speed_ms", 0.0)
            ang = _doppler.get("direction_deg", 0.0)
            vx = _doppler.get("vx_ms", 0.0)
            vy = _doppler.get("vy_ms", 0.0)
            nap = _doppler.get("n_aps", 0)
            ax2.text(0.99, 0.99,
                     f"Doppler  {spd:.3f} m/s @ {ang:.0f}°\n"
                     f"vx={vx:+.3f}  vy={vy:+.3f}  ({nap} APs)",
                     transform=ax2.transAxes, ha='right', va='top',
                     color='#ffdd44', fontsize=8.5,
                     bbox=dict(facecolor='#0a1e2a', alpha=0.75,
                               boxstyle='round,pad=0.3'))
        for sp in ax2.spines.values():
            sp.set_color('#1a3a4a')

        fig.suptitle(
            "RF GAUSSIAN SPLATTING — 2D POWER MAP · NETWORK TOPOLOGY · DOPPLER VELOCITY",
            color='#00ffcc', fontsize=12, fontweight='bold', y=0.98)
        fig.text(0.5, 0.015,
                 "Gaussian ring = path-loss range estimate per carrier (bearing unknown → ring). "
                 "ARP = kernel /proc/net/arp. Occupancy = cyclostationary RSSI analysis. "
                 "Doppler = multi-AP dRSSI/dt lstsq. All real data.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_scanner(self, fig, p, snap):
        """v125: REAL-TIME MULTI-CHANNEL RF SCANNER — all bands live from ContinuousChannelHopper.
        Rescans every 2.5s via nmcli --rescan, displays all visible APs and RF kernel events."""
        import numpy as np
        import time as _t
        fig.patch.set_facecolor("#050d14")
        _all_aps = snap.get("all_channel_aps") or []
        _rf_events = snap.get("rf_events") or []
        _scan_count = snap.get("channel_scan_count", 0)
        _ev_ok = snap.get("rf_event_monitor_ok", False)

        gs = GridSpec(3, 1, figure=fig, left=0.06, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.42)

        # ── Panel 0: Per-channel RSSI bars across all visible channels ──
        ax0 = fig.add_subplot(gs[0])
        ax0.set_facecolor("#04101a")
        if _all_aps:
            _24 = {}; _5 = {}; _6 = {}
            for ap in _all_aps:
                ch = ap.get("channel", 0); r = ap.get("rssi", -100)
                freq = ap.get("freq_mhz", 0)
                if ch <= 0:
                    continue
                if freq < 3000:
                    _24[ch] = max(_24.get(ch, -100), r)
                elif freq >= 5925:
                    _6[ch] = max(_6.get(ch, -100), r)
                else:
                    _5[ch] = max(_5.get(ch, -100), r)
            items = ([(ch, r, "#22ff88") for ch, r in sorted(_24.items())] +
                     [(ch, r, "#00ccff") for ch, r in sorted(_5.items())] +
                     [(ch, r, "#ff88ff") for ch, r in sorted(_6.items())])
            if items:
                xs_lbl = [str(i[0]) for i in items]
                ys = [max(-100, i[1]) for i in items]
                cs = [i[2] for i in items]
                ax0.bar(range(len(xs_lbl)), ys, color=cs, alpha=0.85, width=0.75)
                ax0.set_xticks(range(len(xs_lbl)))
                ax0.set_xticklabels(xs_lbl, fontsize=6, color='#aaccbb', rotation=90)
                ax0.axhline(-80, color='#ff4444', lw=0.7, ls='--', alpha=0.6)
                ax0.axhline(-65, color='#ffaa33', lw=0.7, ls='--', alpha=0.5)
                ax0.axhline(-50, color='#22ff88', lw=0.7, ls='--', alpha=0.5)
        else:
            ax0.text(0.5, 0.5, "Scanning all channels…",
                     ha='center', va='center', color='#446655', fontsize=13,
                     transform=ax0.transAxes)
        ax0.set_ylim(-100, -20)
        ax0.set_ylabel("RSSI (dBm)", color='#aaccbb', fontsize=9)
        ax0.set_title(
            f"ALL CHANNELS — {len(_all_aps)} APs detected  |  Scan #{_scan_count}  "
            f"|  ■ 2.4GHz  ■ 5GHz  ■ 6GHz",
            color='#00ffcc', fontsize=10, fontweight='bold')
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 1: AP table (top 32 by RSSI) ──
        ax1 = fig.add_subplot(gs[1])
        ax1.set_facecolor("#04101a")
        ax1.axis('off')
        ax1.set_title("ALL VISIBLE ACCESS POINTS", color='#00ffcc', fontsize=10)
        if _all_aps:
            top_aps = _all_aps[:32]
            rows = []
            for ap in top_aps:
                ssid = str(ap.get("ssid", ""))[:22]
                ch = ap.get("channel", 0)
                freq = ap.get("freq_mhz", 0)
                rssi = ap.get("rssi", -100)
                sec = str(ap.get("security", ""))[:10]
                band = "2.4G" if freq < 3000 else "6G" if freq >= 5925 else "5G"
                bssid = str(ap.get("bssid", ""))[:17]
                rows.append([ssid, bssid, f"Ch{ch}", band,
                              f"{rssi:.0f}dBm", sec])
            col_labels = ["SSID", "BSSID", "Chan", "Band", "RSSI", "Security"]
            tbl = ax1.table(cellText=rows, colLabels=col_labels,
                            cellLoc='left', loc='center',
                            colWidths=[0.28, 0.20, 0.08, 0.08, 0.12, 0.14])
            tbl.auto_set_font_size(False)
            tbl.set_fontsize(7.0)
            for (r, c), cell in tbl.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(
                    color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax1.text(0.5, 0.5, "No APs found — rescanning…",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax1.transAxes)

        # ── Panel 2: Real-time RF kernel events from iw event monitor ──
        ax2 = fig.add_subplot(gs[2])
        ax2.set_facecolor("#04101a")
        ax2.axis('off')
        _ev_status = "LIVE" if _ev_ok else "fallback (iw not in PATH)"
        ax2.set_title(f"REAL-TIME RF KERNEL EVENTS — iw event [{_ev_status}]",
                      color='#00ffcc', fontsize=10)
        if _rf_events:
            _now = _t.time()
            ev_lines = []
            for ev in reversed(_rf_events[-20:]):
                age = _now - ev.get("ts", _now)
                bssid = ev.get("bssid", "??:??:??:??:??:??")
                rssi_v = ev.get("rssi")
                freq_v = ev.get("freq_mhz")
                ssid = ev.get("ssid", "")[:18]
                rs = f"{rssi_v:.0f}dBm" if rssi_v is not None else "?dBm"
                fs = f"{freq_v:.0f}MHz" if freq_v is not None else "?MHz"
                ev_lines.append(
                    f"  [{age:5.1f}s]  {bssid}  {rs:8s}  {fs:8s}  {ssid}")
            ax2.text(0.01, 0.98, "\n".join(ev_lines[:18]),
                     transform=ax2.transAxes, va='top', ha='left',
                     color='#aaccbb', fontsize=8, fontfamily='monospace')
        else:
            ax2.text(0.5, 0.5,
                     "RF kernel event monitor starting…\n"
                     "(requires 'iw' in PATH for real-time kernel-push events)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax2.transAxes)

        fig.suptitle(
            "REAL-TIME MULTI-CHANNEL RF SCANNER — ALL BANDS CONTINUOUS (nmcli + iw event)",
            color='#00ffcc', fontsize=12, fontweight='bold', y=0.98)
        fig.text(0.5, 0.015,
                 "ContinuousChannelHopper: nmcli --rescan every 2.5s across all visible channels. "
                 "iw event: kernel-push RSSI events. All data from real RF hardware only.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_rangedoppler(self, fig, p, snap):
        """v126: WIFI RANGE-DOPPLER — 2D image from multi-AP RSSI time series.
        Range axis = path-loss distance per AP (0-80m). Doppler axis = dRSSI/dt velocity.
        Multi-lateration position fix overlay. Planetary link budget table.
        All real WiFi RSSI — no simulation."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _ents = snap.get("rf_link_entities") or []
        _rd = snap.get("rd_matrix")
        _mlat = snap.get("multilat_position") or {}
        _doppler = snap.get("doppler_velocity") or {}
        _link_budget = snap.get("planet_link_budget") or []
        _tri = snap.get("triangulated_aps") or {}
        _ebus_counts = snap.get("event_bus_counts") or {}
        _ebus_recent = snap.get("event_bus_recent", 0)

        gs = GridSpec(2, 3, figure=fig, left=0.05, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.38, wspace=0.28)

        # ── Panel 0 (top-left, span 2 cols): Range-Doppler image ──
        ax0 = fig.add_subplot(gs[0, :2])
        ax0.set_facecolor("#04101a")
        _MAX_R = 80.0; _MAX_V = 3.0
        if _rd is not None and np.max(_rd) > 0:
            ax0.imshow(_rd, origin='lower', aspect='auto',
                       extent=[-_MAX_V, _MAX_V, 0, _MAX_R],
                       cmap='hot', vmin=0.0, vmax=1.0, interpolation='bilinear')
            ax0.axvline(0, color='#00ffcc', lw=0.8, ls='--', alpha=0.6, label='Static')
            if _mlat:
                r_pos = float(np.sqrt(_mlat.get("x_m", 0)**2 + _mlat.get("y_m", 0)**2))
                v_pos = _doppler.get("speed_ms", 0.0)
                ax0.plot(v_pos, min(r_pos, _MAX_R - 1), 'c*', ms=14, zorder=6,
                         label=f"RX (mlat ±{_mlat.get('uncertainty_m', 99):.1f}m)")
                ax0.axhline(r_pos, color='#00ccff', lw=0.7, ls=':', alpha=0.5)
            ax0.legend(fontsize=7.5, facecolor='#0a1e2a', labelcolor='#aaccbb',
                       edgecolor='#1a3a4a', loc='upper right')
        else:
            ax0.text(0.5, 0.5, f"Accumulating RSSI history…\n{len(_ents)} real carriers",
                     ha='center', va='center', color='#446655', fontsize=13,
                     transform=ax0.transAxes)
            ax0.set_xlim(-_MAX_V, _MAX_V); ax0.set_ylim(0, _MAX_R)
        ax0.set_xlabel("Doppler velocity (m/s)", color='#aaccbb', fontsize=9)
        ax0.set_ylabel("Range (m)", color='#aaccbb', fontsize=9)
        _mlat_str = (f"Mlat: ({_mlat.get('x_m',0):.1f},{_mlat.get('y_m',0):.1f})m "
                     f"±{_mlat.get('uncertainty_m',99):.1f}m") if _mlat else "No mlat fix"
        ax0.set_title(f"WIFI RANGE-DOPPLER  |  {len(_ents)} AP carriers  |  {_mlat_str}",
                      color='#00ffcc', fontsize=11, fontweight='bold')
        ax0.tick_params(colors='#aaccbb', labelsize=8)
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 1 (top-right): Multi-lateration plan view ──
        ax1 = fig.add_subplot(gs[0, 2])
        ax1.set_facecolor("#04101a")
        ax1.set_aspect('equal')
        ax1.set_title("MULTI-LATERATION\nPOSITION FIX", color='#00ffcc', fontsize=9)
        _R_RSSI = -40.0; _PL = 2.7
        for ent in _ents[:16]:
            rssi = float(ent.get("rssi", ent.get("link_rssi_db", -100)))
            if rssi < -94:
                continue
            d = 10.0 ** ((_R_RSSI - rssi) / (10.0 * _PL))
            d = min(d, 70.0)
            freq = float(ent.get("center_mhz", ent.get("freq_mhz", 2440)))
            col = "#22ff88" if freq < 3000 else "#ff88ff" if freq > 5900 else "#00ccff"
            c = plt.Circle((0, 0), d, fill=False, color=col, lw=0.7, alpha=0.4)
            ax1.add_patch(c)
        ax1.plot(0, 0, 'w^', ms=11, zorder=6)
        if _mlat:
            mx = _mlat.get("x_m", 0); my = _mlat.get("y_m", 0)
            uc = _mlat.get("uncertainty_m", 5)
            ax1.plot(mx, my, 'c*', ms=14, zorder=7)
            c2 = plt.Circle((mx, my), uc, fill=False, color='#00ccff',
                             lw=1.2, ls='--', alpha=0.8)
            ax1.add_patch(c2)
            ax1.text(mx + 1, my + 1, f"({mx:.1f},{my:.1f})\n±{uc:.1f}m",
                     color='#00ccff', fontsize=7.5)
        for bssid, tri in list(_tri.items())[:5]:
            ax1.plot(tri["x_m"], tri["y_m"], 'y+', ms=10, zorder=5)
            ax1.text(tri["x_m"]+1, tri["y_m"]+1, bssid[-5:],
                     color='#ffdd44', fontsize=6.5)
        ax1.set_xlim(-75, 75); ax1.set_ylim(-75, 75)
        ax1.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax1.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        ax1.grid(True, color='#1a3a4a', lw=0.4, alpha=0.5)
        for sp in ax1.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 2 (bottom-left span 2): Planetary link budget table ──
        ax2 = fig.add_subplot(gs[1, :2])
        ax2.set_facecolor("#04101a")
        ax2.axis('off')
        ax2.set_title("PLANETARY LINK BUDGET — ALL ILLUMINATOR TYPES",
                      color='#00ffcc', fontsize=10)
        if _link_budget:
            top12 = _link_budget[:12]
            rows = [[b["name"][:18], f"{b['freq_mhz']:.1f}",
                     f"{b['range_km']:.0f}", f"{b['pr_dbm']:.1f}",
                     f"{b['snr_db']:.1f}", "YES" if b["detectable"] else "NO"]
                    for b in top12]
            col_labels = ["Illuminator", "MHz", "Range km", "Pr dBm", "SNR dB", "Det?"]
            tbl = ax2.table(cellText=rows, colLabels=col_labels,
                            cellLoc='center', loc='center',
                            colWidths=[0.28, 0.10, 0.13, 0.13, 0.13, 0.08])
            tbl.auto_set_font_size(False); tbl.set_fontsize(8.0)
            for (r, c), cell in tbl.get_celld().items():
                is_hdr = r == 0
                cell.set_facecolor('#0a2030' if is_hdr else '#04101a')
                cell.set_text_props(color='#00ffcc' if is_hdr else '#aaccbb')
                cell.set_edgecolor('#1a3a4a')
                if not is_hdr and rows[r-1][5] == "YES":
                    cell.set_text_props(color='#22ff88' if c == 5 else '#aaccbb')
        else:
            ax2.text(0.5, 0.5, "Computing link budget…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax2.transAxes)

        # ── Panel 3 (bottom-right): Live event bus stats ──
        ax3 = fig.add_subplot(gs[1, 2])
        ax3.set_facecolor("#04101a")
        ax3.axis('off')
        ax3.set_title("LIVE SENSOR EVENT BUS", color='#00ffcc', fontsize=9)
        lines = [f"  Events/5s: {_ebus_recent}",
                 f"  Total/120s: {sum(_ebus_counts.values())}"]
        for src in ["WIFI", "ADSB", "SATELLITE", "CELLULAR", "GPS",
                    "RFEVENT", "REMOTE", "ARP"]:
            cnt = _ebus_counts.get(src, 0)
            lines.append(f"  {src:<12} {cnt:>5}")
        if _doppler:
            spd = _doppler.get("speed_ms", 0)
            ang = _doppler.get("direction_deg", 0)
            lines.append(f"\n  Doppler: {spd:.3f}m/s @ {ang:.0f}°")
        ax3.text(0.04, 0.96, "\n".join(lines), transform=ax3.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.5,
                 fontfamily='monospace')

        fig.suptitle(
            "WIFI RANGE-DOPPLER  ·  MULTI-LATERATION  ·  PLANETARY LINK BUDGET  ·  LIVE EVENT BUS",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "Range-Doppler: RSSI path-loss range + dRSSI/dt Doppler per AP, 64×64 real image. "
                 "Mlat: WLS from N≥3 range circles. Link budget: free-space ITU, 1MHz BW, NF=5dB.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_worldfeed(self, fig, p, snap):
        """v126: LIVE WORLD SENSOR FEED — unified real-time timeline of ALL data sources.
        120s rolling window. WiFi/ADS-B/satellite/cellular/GPS/RF-events. All real data only."""
        import numpy as np
        import time as _t
        fig.patch.set_facecolor("#050d14")
        _ebus_counts = snap.get("event_bus_counts") or {}
        _ebus_recent = snap.get("event_bus_recent", 0)
        _all_aps = snap.get("all_channel_aps") or []
        _aircraft = snap.get("aircraft") or snap.get("adsb_aircraft") or []
        # v132e: real key is "satellite_passes" (set at ~67700); "sat_passes" was never
        # written → the satellite panel was always empty. Read both for safety.
        _sat_passes = snap.get("satellite_passes") or snap.get("sat_passes") or []
        _cell = snap.get("cellular_signal") or {}
        _gps = snap.get("gps_fix") or {}
        _ents = snap.get("rf_link_entities") or []
        _mlat = snap.get("multilat_position") or {}
        _rd = snap.get("rd_matrix")

        gs = GridSpec(3, 2, figure=fig, left=0.07, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.42, wspace=0.26)

        # ── Panel 0 (top-left): WiFi RSSI all-channel bars ──
        ax0 = fig.add_subplot(gs[0, 0])
        ax0.set_facecolor("#04101a")
        ax0.set_title(f"WIFI ALL CHANNELS ({len(_all_aps)} APs live)",
                      color='#00ffcc', fontsize=10)
        if _all_aps:
            top = sorted(_all_aps, key=lambda x: x.get("rssi", -100), reverse=True)[:20]
            rssis = [a.get("rssi", -100) for a in top]
            labels = [f"Ch{a.get('channel',0)}/{a.get('freq_mhz',0):.0f}" for a in top]
            cmap_v = [(r - (-100)) / 50.0 for r in rssis]
            bar_cols = [plt.cm.RdYlGn(min(max(v, 0), 1)) for v in cmap_v]
            ax0.barh(range(len(top)), rssis, color=bar_cols, alpha=0.85)
            ax0.set_yticks(range(len(top)))
            ax0.set_yticklabels(labels, fontsize=6.5, color='#aaccbb')
            ax0.set_xlim(-100, -20)
            ax0.axvline(-80, color='#ff4444', lw=0.6, ls='--', alpha=0.5)
            ax0.axvline(-50, color='#22ff88', lw=0.6, ls='--', alpha=0.4)
        else:
            ax0.text(0.5, 0.5, f"Scanning…\n{len(_ents)} carriers",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax0.transAxes)
        ax0.set_xlabel("RSSI (dBm)", color='#aaccbb', fontsize=8)
        ax0.tick_params(colors='#aaccbb', labelsize=6)
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 1 (top-right): ADS-B aircraft live ──
        ax1 = fig.add_subplot(gs[0, 1])
        ax1.set_facecolor("#04101a")
        ax1.set_title(f"ADS-B REAL AIRCRAFT ({len(_aircraft)})",
                      color='#00ffcc', fontsize=10)
        if _aircraft:
            ac_list = sorted(_aircraft, key=lambda x: x.get("altitude", 0), reverse=True)[:12]
            labels = [(a.get("callsign") or "?")[:8] for a in ac_list]
            alts = [a.get("altitude", 0) for a in ac_list]
            bar_cols = plt.cm.cool(np.linspace(0.2, 0.9, len(alts)))
            ax1.barh(range(len(alts)), alts, color=bar_cols, alpha=0.85)
            ax1.set_yticks(range(len(alts)))
            ax1.set_yticklabels(labels, fontsize=7.5, color='#aaccbb')
            ax1.set_xlabel("Altitude (ft)", color='#aaccbb', fontsize=8)
            for i, (a, ac) in enumerate(zip(alts, ac_list)):
                spd = ac.get("velocity", 0)
                ax1.text(a + 200, i, f"{spd:.0f}kt", va='center',
                         color='#ffdd44', fontsize=6)
        else:
            ax1.text(0.5, 0.5, "No aircraft\n(OpenSky polling every 60s)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax1.transAxes)
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax1.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 2 (middle-left): Range-Doppler mini view ──
        ax2 = fig.add_subplot(gs[1, 0])
        ax2.set_facecolor("#04101a")
        ax2.set_title("RANGE-DOPPLER (WiFi multi-AP RSSI)", color='#00ffcc', fontsize=10)
        if _rd is not None and np.max(_rd) > 0:
            ax2.imshow(_rd, origin='lower', aspect='auto',
                       extent=[-3.0, 3.0, 0, 80.0],
                       cmap='hot', vmin=0.0, vmax=1.0, interpolation='bilinear')
            ax2.axvline(0, color='#00ffcc', lw=0.7, ls='--', alpha=0.5)
            if _mlat:
                r_pos = float(np.sqrt(_mlat.get("x_m", 0)**2 + _mlat.get("y_m", 0)**2))
                ax2.axhline(min(r_pos, 79), color='#00ccff', lw=0.8, ls=':', alpha=0.7)
        else:
            ax2.text(0.5, 0.5, "Building…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax2.transAxes)
            ax2.set_xlim(-3, 3); ax2.set_ylim(0, 80)
        ax2.set_xlabel("Velocity (m/s)", color='#aaccbb', fontsize=8)
        ax2.set_ylabel("Range (m)", color='#aaccbb', fontsize=8)
        ax2.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax2.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 3 (middle-right): GPS + satellite passes ──
        ax3 = fig.add_subplot(gs[1, 1])
        ax3.set_facecolor("#04101a")
        ax3.axis('off')
        ax3.set_title("GPS FIX + SATELLITE PASSES", color='#00ffcc', fontsize=10)
        lines = []
        if _gps and _gps.get("lat") is not None:
            lines.append(f"  GPS: {_gps['lat']:.5f}°N {_gps.get('lon',0):.5f}°E")
            lines.append(f"       Alt:{_gps.get('alt',0):.0f}m")
        else:
            lines.append("  GPS: No fix (connect GPSD on port 2947)")
        lines.append("")
        lines.append("  Satellites overhead (passes):")
        for s in _sat_passes[:6]:
            nm = s.get("name", "?")[:10]
            el = s.get("elevation", 0)
            az = s.get("azimuth", 0)
            lines.append(f"   {nm:<10} El={el:.1f}° Az={az:.1f}°")
        if not _sat_passes:
            lines.append("   (none overhead right now)")
        # v134: real-time tracked fleet (CelesTrak TLE + Kepler/J2 sub-satellite point)
        _tracked = snap.get("tracked_satellites") or []
        if _tracked:
            lines.append("")
            lines.append(f"  Tracked fleet (TLE+Kepler/J2, {len(_tracked)} live):")
            for s in _tracked[:8]:
                nm = str(s.get("name", "?"))[:8]
                slat = float(s.get("lat", 0)); slon = float(s.get("lon", 0))
                alt = float(s.get("alt_km", 0)); age = float(s.get("tle_age_hr", 0))
                lines.append(f"   {nm:<8} {slat:+6.1f},{slon:+7.1f} {alt:5.0f}km {age:.0f}h")
        ax3.text(0.04, 0.96, "\n".join(lines), transform=ax3.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=7.5,
                 fontfamily='monospace')

        # ── Panel 4 (bottom-left): Event bus bar chart ──
        ax4 = fig.add_subplot(gs[2, 0])
        ax4.set_facecolor("#04101a")
        sources = ["WIFI", "ADSB", "SAT", "CELL", "GPS", "RF", "REMOTE", "SDR"]
        counts = [_ebus_counts.get(s, _ebus_counts.get(s.lower(), 0)) for s in sources]
        src_cols = ["#22ff88", "#ffaa33", "#00ccff", "#ff88ff", "#ffdd44",
                    "#aaffcc", "#ff6644", "#ff9933"]
        x_pos = np.arange(len(sources))
        if any(c > 0 for c in counts):
            ax4.bar(x_pos, counts, color=src_cols, alpha=0.85, width=0.7)
        ax4.set_xticks(x_pos)
        ax4.set_xticklabels(sources, fontsize=7.5, color='#aaccbb')
        ax4.set_ylabel("Events/120s", color='#aaccbb', fontsize=8)
        ax4.set_title(f"EVENT BUS — {_ebus_recent}/5s total:{sum(counts)}",
                      color='#00ffcc', fontsize=9)
        ax4.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax4.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 5 (bottom-right): Planetary coverage map ──
        ax5 = fig.add_subplot(gs[2, 1])
        ax5.set_facecolor("#030a12")
        _pcov_grid = snap.get("planet_coverage_grid")
        _pcov_pct  = snap.get("planet_coverage_pct", 0.0)
        _pcov_nnd  = snap.get("planet_n_nodes", 0)
        _pcov_nac  = snap.get("planet_n_aircraft", 0)
        _pcov_nsat = snap.get("planet_n_satellites", 0)
        _pcov_nwsp = snap.get("planet_n_wspr", 0)
        _pcov_napr = snap.get("planet_n_aprs", 0)
        _nstamps   = snap.get("planet_node_stamps") or {}
        _wspr_spots = (snap.get("wspr_spots") or [])[:80]
        _kp         = float(snap.get("kp_index", 0.0) or 0.0)
        _f107       = float(snap.get("f107_flux", 0.0) or 0.0)
        _bz         = float(snap.get("imf_bz", 0.0) or 0.0)
        _flare      = str(snap.get("flare_class", "?"))
        _sw_ok      = bool(snap.get("space_weather_ok", False))
        if _pcov_grid is not None and np.max(_pcov_grid) > 0.001:
            ax5.imshow(_pcov_grid, origin='lower', aspect='auto',
                       extent=[-180, 180, -90, 90], cmap='YlGn',
                       vmin=0, vmax=1, interpolation='bilinear', alpha=0.9)
            # v134: WSPR HF propagation paths — real radio arcs crossing the globe
            for spot in _wspr_spots:
                _tx_lon = float(spot.get("tx_lon", 0))
                _tx_lat = float(spot.get("tx_lat", 0))
                _rx_lon = float(spot.get("rx_lon", 0))
                _rx_lat = float(spot.get("rx_lat", 0))
                if _tx_lat == 0 or _rx_lat == 0:
                    continue
                _snr = float(spot.get("snr_db", -20) or -20)
                _alpha = min(0.55, max(0.08, (_snr + 30) / 40.0))
                ax5.plot([_tx_lon, _rx_lon], [_tx_lat, _rx_lat],
                         '-', color='#ffcc44', lw=0.35, alpha=_alpha, zorder=4)
            # Plot node positions by type (cap high so APRS/WSPR/sat all render)
            for nid, vstamp in list(_nstamps.items())[:900]:
                nlat, nlon = float(vstamp[0]), float(vstamp[1])
                if nid == 'local':
                    col, mk, ms = '#00ffcc', 'v', 7
                elif nid.startswith('ac:'):
                    col, mk, ms = '#ffaa33', '^', 4
                elif nid.startswith('sat:') or nid.startswith('tk:'):
                    col, mk, ms = '#aa88ff', '*', 6
                elif nid.startswith('wx:') or nid.startswith('wr:'):
                    col, mk, ms = '#ffcc44', '.', 3   # WSPR node (tiny dot)
                elif nid.startswith('ap:'):
                    col, mk, ms = '#44ddaa', '.', 3   # APRS VHF station (tiny dot)
                elif nid.startswith('r:'):
                    col, mk, ms = '#ff8844', 'o', 5
                else:
                    col, mk, ms = '#88ccff', 'o', 4
                ax5.plot(nlon, nlat, mk, color=col, ms=ms, zorder=5,
                         markeredgecolor='#ffffff', markeredgewidth=0.3)
        else:
            ax5.text(0.5, 0.5,
                     f"Planetary coverage building…\n{_pcov_nnd} nodes\nNeed geolocation",
                     ha='center', va='center', color='#446655', fontsize=9,
                     transform=ax5.transAxes)
            ax5.set_xlim(-180, 180); ax5.set_ylim(-90, 90)
        # v134/v135: space weather readout in corner (Kp/F10.7/Bz + solar flare class)
        if _sw_ok:
            _kp_col = '#ff3333' if _kp >= 5 else '#ffaa22' if _kp >= 3 else '#22ff88'
            _fl_txt = f"  Flare={_flare}" if _flare not in ("?", "") else ""
            ax5.text(0.01, 0.03,
                     f"SPACE WX  Kp={_kp:.0f}  F10.7={_f107:.0f}  Bz={_bz:+.1f}nT{_fl_txt}",
                     transform=ax5.transAxes, color=_kp_col, fontsize=5.5, va='bottom',
                     bbox=dict(facecolor='#030a12', alpha=0.85, pad=1.5))
        ax5.set_xlabel("Longitude", color='#aaccbb', fontsize=7)
        ax5.set_ylabel("Latitude", color='#aaccbb', fontsize=7)
        ax5.set_title(
            f"PLANETARY COVERAGE — {_pcov_nnd} nodes "
            f"({_pcov_nac} ADS-B · {_pcov_nsat} sat · {_pcov_nwsp} WSPR · {_pcov_napr} APRS) "
            f"— {_pcov_pct:.3f}% Earth",
            color='#00ffcc', fontsize=8.5)
        ax5.tick_params(colors='#aaccbb', labelsize=6)
        for sp in ax5.spines.values(): sp.set_color('#1a3a4a')

        fig.suptitle(
            f"LIVE WORLD SENSOR FEED — ALL REAL DATA SOURCES — "
            f"{_pcov_nnd} nodes ({_pcov_nac} ADS-B · {_pcov_nsat} sat · {_pcov_nwsp} WSPR · "
            f"{_pcov_napr} APRS) covering {_pcov_pct:.3f}% Earth",
            color='#00ffcc', fontsize=10.5, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "WiFi (nmcli) · ADS-B @1090MHz (OpenSky) · LEO sats (TLE+Kepler) · "
                 "WSPR HF (WSPR.live) · APRS VHF @144.39MHz (APRS-IS) · Space wx (NOAA SWPC) — all real.",
                 ha='center', color='#778899', fontsize=6.8)

    def _draw_acoustic(self, fig, p, snap):
        """v127: ACOUSTIC SENSING — ultrasonic sonar echo ranging + full 20Hz-20kHz
        sound spectrum from mic. Acoustic echo gives wall/obstacle range in metres.
        All real: recorded by laptop mic/speakers via arecord/aplay. OFDM sensing overlay."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _ranges = snap.get("acoustic_ranges") or []
        _latest = snap.get("acoustic_latest") or {}
        _echo_ok = snap.get("acoustic_echo_ok", False)
        _snd_spec = snap.get("sound_spectrum")
        _snd_bands = snap.get("sound_bands") or {}
        _vad = snap.get("voice_active", False)
        _snd_ok = snap.get("sound_ok", False)
        _ofdm = snap.get("ofdm_sensing_image")
        _mlat = snap.get("multilat_position") or {}
        _ents = snap.get("rf_link_entities") or []

        gs = GridSpec(2, 3, figure=fig, left=0.06, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.38, wspace=0.28)

        # ── Panel 0 (top-left): Acoustic echo range history ──
        ax0 = fig.add_subplot(gs[0, 0])
        ax0.set_facecolor("#04101a")
        ax0.set_title(f"ULTRASONIC ECHO RANGING ({'LIVE' if _echo_ok else 'Starting…'})",
                      color='#00ffcc', fontsize=10)
        if _ranges:
            rs = [r["range_m"] for r in _ranges[-20:]]
            snrs = [r.get("snr", 1.0) for r in _ranges[-20:]]
            xs = range(len(rs))
            cols = plt.cm.plasma(np.array(snrs) / max(max(snrs), 1.0))
            ax0.bar(list(xs), rs, color=cols, alpha=0.85, width=0.8)
            if _latest:
                ax0.axhline(_latest["range_m"], color='#00ffcc', lw=1.5, ls='--',
                            label=f"Latest: {_latest['range_m']:.2f}m")
                ax0.legend(fontsize=8, facecolor='#0a1e2a', labelcolor='#aaccbb',
                           edgecolor='#1a3a4a')
            ax0.set_ylim(0, 12)
            ax0.set_ylabel("Range (m)", color='#aaccbb', fontsize=9)
            ax0.set_xlabel("Ping #", color='#aaccbb', fontsize=8)
        else:
            ax0.text(0.5, 0.5, "Playing 18-22kHz chirp…\n(needs speaker + mic)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax0.transAxes)
            ax0.set_ylim(0, 12)
        if _latest:
            ax0.text(0.99, 0.99, f"Range: {_latest.get('range_m',0):.2f}m\n"
                                  f"ToF: {_latest.get('tof_ms',0):.1f}ms\n"
                                  f"SNR: {_latest.get('snr',0):.1f}",
                     transform=ax0.transAxes, ha='right', va='top',
                     color='#22ff88', fontsize=8.5,
                     bbox=dict(facecolor='#0a1e2a', alpha=0.75,
                               boxstyle='round,pad=0.3'))
        ax0.tick_params(colors='#aaccbb', labelsize=8)
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 1 (top-centre): Sound card spectrum 20Hz-20kHz ──
        ax1 = fig.add_subplot(gs[0, 1])
        ax1.set_facecolor("#04101a")
        vad_str = "VOICE ACTIVE" if _vad else "Quiet"
        ax1.set_title(f"ACOUSTIC SPECTRUM 20Hz-20kHz [{vad_str}]",
                      color='#00ffcc' if not _vad else '#ffdd44', fontsize=10)
        if _snd_spec is not None and len(_snd_spec) > 0:
            _FS = 44100; _NFFT = 8192
            freqs = np.fft.rfftfreq(_NFFT, d=1.0/_FS)[:_NFFT//2]
            # Only plot 20Hz-20kHz
            mask = (freqs >= 20) & (freqs <= 20000)
            ax1.plot(freqs[mask], _snd_spec[mask], color='#22ff88', lw=0.8, alpha=0.85)
            # Shade voice band
            vmask = (freqs >= 300) & (freqs <= 3400)
            if vmask.any():
                ax1.fill_between(freqs[vmask], -90, _snd_spec[vmask],
                                 color='#ffdd44', alpha=0.25, label='Voice 300-3400Hz')
            ax1.set_xscale('log')
            ax1.set_xlim(20, 20000)
            ax1.set_ylim(-90, 0)
            ax1.set_xlabel("Frequency (Hz)", color='#aaccbb', fontsize=8)
            ax1.set_ylabel("Power (dB)", color='#aaccbb', fontsize=8)
            ax1.axhline(-60, color='#ff4444', lw=0.6, ls='--', alpha=0.5)
            if vmask.any():
                ax1.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb',
                           edgecolor='#1a3a4a')
        else:
            ax1.text(0.5, 0.5, "Capturing audio…\n(arecord -f S16_LE)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax1.transAxes)
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax1.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 2 (top-right): Acoustic band powers ──
        ax2 = fig.add_subplot(gs[0, 2])
        ax2.set_facecolor("#04101a")
        ax2.set_title("ACOUSTIC BAND POWERS", color='#00ffcc', fontsize=10)
        if _snd_bands:
            bnames = list(_snd_bands.keys())
            bvals = [max(-90.0, _snd_bands[b]) + 90.0 for b in bnames]  # offset for bar
            bcols = ["#22ff88", "#00ccff", "#ffdd44", "#ff88ff", "#ff9933"][:len(bnames)]
            ax2.barh(range(len(bnames)), bvals, color=bcols, alpha=0.85)
            ax2.set_yticks(range(len(bnames)))
            ax2.set_yticklabels([f"{b}\n({_snd_bands[b]:.1f}dB)" for b in bnames],
                                 fontsize=8, color='#aaccbb')
            ax2.set_xlabel("Relative Power (dB + 90)", color='#aaccbb', fontsize=8)
        else:
            ax2.text(0.5, 0.5, "Waiting…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax2.transAxes)
        ax2.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax2.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 3 (bottom-left): OFDM multi-freq spatial coherence map ──
        ax3 = fig.add_subplot(gs[1, 0])
        ax3.set_facecolor("#04101a")
        ax3.set_title("OFDM MULTI-FREQ SPATIAL COHERENCE (32×32)",
                      color='#00ffcc', fontsize=9)
        if _ofdm is not None and np.max(_ofdm) > 0:
            ax3.imshow(_ofdm, origin='lower', aspect='equal',
                       extent=[-7.5, 7.5, -7.5, 7.5],
                       cmap='plasma', vmin=0.0, vmax=1.0, interpolation='bilinear')
            ax3.plot(0, 0, 'w^', ms=10, zorder=5)
            if _mlat:
                mx = _mlat.get("x_m", 0) * 0.5; my = _mlat.get("y_m", 0) * 0.5
                ax3.plot(np.clip(mx, -7, 7), np.clip(my, -7, 7), 'c*', ms=12, zorder=6)
        else:
            ax3.text(0.5, 0.5, f"Building spatial map…\n{len(_ents)} freqs",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax3.transAxes)
            ax3.set_xlim(-7.5, 7.5); ax3.set_ylim(-7.5, 7.5)
        ax3.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax3.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax3.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax3.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 4 (bottom-centre + right): Echo map plan view + sensor status ──
        ax4 = fig.add_subplot(gs[1, 1:])
        ax4.set_facecolor("#04101a")
        ax4.axis('off')
        ax4.set_title("ACOUSTIC SENSOR STATUS + ECHO MAP", color='#00ffcc', fontsize=10)
        lines = ["  ACOUSTIC SENSING SUMMARY",
                 "  " + "─" * 38]
        if _echo_ok and _latest:
            lines.append(f"  Echo OK:    {_latest.get('range_m', 0):.2f}m to nearest reflector")
            lines.append(f"  ToF:        {_latest.get('tof_ms', 0):.1f}ms")
            lines.append(f"  Ping SNR:   {_latest.get('snr', 0):.1f}x")
            lines.append(f"  Pings kept: {len(_ranges)}")
        else:
            lines.append("  Echo: Starting aplay/arecord pipeline…")
            lines.append("  (requires working ALSA audio + speaker + mic)")
        lines.append("")
        lines.append(f"  Audio spectrum: {'OK' if _snd_ok else 'Starting…'}")
        lines.append(f"  Voice active:   {'YES — detected voice/activity' if _vad else 'No'}")
        if _snd_bands:
            for b, v in _snd_bands.items():
                lines.append(f"  Band {b:<8} {v:+.1f} dB")
        lines.append("")
        lines.append(f"  Chirp: 18-22kHz FM sweep, 50ms")
        lines.append(f"  Speed of sound: 343 m/s (20°C)")
        lines.append(f"  Range resolution: ~0.17m (at 44100Hz)")
        ax4.text(0.04, 0.96, "\n".join(lines), transform=ax4.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.5,
                 fontfamily='monospace')

        fig.suptitle(
            "ACOUSTIC SENSING — ULTRASONIC ECHO SONAR + SOUND SPECTRUM + OFDM COHERENCE MAP",
            color='#00ffcc', fontsize=12, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "Acoustic echo: FM chirp 18-22kHz via aplay, capture via arecord, "
                 "cross-correlation ToF → range. Sound spectrum: FFT of mic audio. "
                 "OFDM coherence: Bartlett spatial map from multi-freq WiFi RSSI.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_bleview(self, fig, p, snap):
        """v127: BLE + SUBNET SCANNER — all nearby Bluetooth LE devices and LAN hosts.
        BLE: real advertising packets via bluetoothctl/hcitool lescan. RSSI from kernel.
        Subnet: full ARP sweep of local network. Planetary RF atlas — all emitter types."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _ble_devs = snap.get("ble_devices") or []
        _subnet = snap.get("subnet_devices") or []
        _ble_count = snap.get("ble_count", 0)
        _subnet_count = snap.get("subnet_count", 0)
        _rf_atlas = snap.get("rf_atlas") or []
        _total_emitters = snap.get("rf_atlas_total_emitters", 0)
        _ents = snap.get("rf_link_entities") or []

        gs = GridSpec(2, 2, figure=fig, left=0.04, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.36, wspace=0.24)

        # ── Panel 0 (top-left): BLE device proximity map ──
        ax0 = fig.add_subplot(gs[0, 0])
        ax0.set_facecolor("#04101a")
        ax0.set_aspect('equal')
        ax0.set_title(f"BLE PROXIMITY MAP — {_ble_count} devices",
                      color='#00ffcc', fontsize=10)
        _RSSI_REF = -40.0; _PL = 2.7
        for dev in _ble_devs[:20]:
            rssi = dev.get("rssi", -100)
            if rssi < -98:
                continue
            d = 10.0 ** ((_RSSI_REF - rssi) / (10.0 * _PL))
            d = min(d, 30.0)
            c = plt.Circle((0, 0), d, fill=False, color='#22ff88', lw=0.7, alpha=0.45)
            ax0.add_patch(c)
            # Place label at distance angle
        ax0.plot(0, 0, 'w^', ms=11, zorder=6, label="This node")
        ax0.set_xlim(-32, 32); ax0.set_ylim(-32, 32)
        ax0.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax0.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        ax0.grid(True, color='#1a3a4a', lw=0.4, alpha=0.4)
        ax0.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb',
                   edgecolor='#1a3a4a', loc='upper right')
        for sp in ax0.spines.values():
            sp.set_color('#1a3a4a')

        # ── Panel 1 (top-right): BLE device list ──
        ax1 = fig.add_subplot(gs[0, 1])
        ax1.set_facecolor("#04101a")
        ax1.axis('off')
        ax1.set_title("NEARBY BLE DEVICES (bluetoothctl + lescan)",
                      color='#00ffcc', fontsize=10)
        if _ble_devs:
            rows = [[dev.get("name", "?")[:18], dev["mac"][:17],
                     f"{dev.get('rssi',-100):.0f}",
                     dev.get("source", "BLE")[:10]]
                    for dev in _ble_devs[:16]]
            col_labels = ["Name", "MAC", "RSSI", "Source"]
            tbl = ax1.table(cellText=rows, colLabels=col_labels,
                            cellLoc='left', loc='center',
                            colWidths=[0.32, 0.34, 0.12, 0.18])
            tbl.auto_set_font_size(False); tbl.set_fontsize(7.5)
            for (r, c), cell in tbl.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax1.text(0.5, 0.5, "Scanning BLE…\n(bluetoothctl scan on / hcitool lescan)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax1.transAxes)

        # ── Panel 2 (bottom-left): Subnet LAN device list ──
        ax2 = fig.add_subplot(gs[1, 0])
        ax2.set_facecolor("#04101a")
        ax2.axis('off')
        ax2.set_title(f"LAN SUBNET MAP — {_subnet_count} devices (/proc/net/arp + arp-scan)",
                      color='#00ffcc', fontsize=10)
        if _subnet:
            rows2 = [[d.get("ip", "?")[:15], d.get("mac", "?")[:17],
                      d.get("vendor", "?")[:14], d.get("source", "ARP")[:8]]
                     for d in _subnet[:16]]
            col_labels2 = ["IP", "MAC", "Vendor", "Source"]
            tbl2 = ax2.table(cellText=rows2, colLabels=col_labels2,
                             cellLoc='left', loc='center',
                             colWidths=[0.24, 0.32, 0.26, 0.14])
            tbl2.auto_set_font_size(False); tbl2.set_fontsize(7.5)
            for (r, c), cell in tbl2.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax2.text(0.5, 0.5, "Sweeping subnet…\n(/proc/net/arp + arp-scan)",
                     ha='center', va='center', color='#446655', fontsize=11,
                     transform=ax2.transAxes)

        # ── Panel 3 (bottom-right): Planetary RF Atlas ──
        ax3 = fig.add_subplot(gs[1, 1])
        ax3.set_facecolor("#04101a")
        ax3.axis('off')
        ax3.set_title(f"PLANETARY RF ATLAS — {_total_emitters:,} total emitters",
                      color='#00ffcc', fontsize=10)
        lines = [f"  {'Type':<14} {'Name':<15} {'Count':>8} {'Freq MHz':>10}"]
        lines.append("  " + "─" * 52)
        type_cols = {"SATELLITE": "#00ccff", "TERRESTRIAL": "#22ff88",
                     "LOCAL_WIFI": "#ffdd44", "AIRCRAFT_ADSB": "#ffaa33",
                     "OVERHEAD_SAT": "#ff88ff"}
        for entry in _rf_atlas[:16]:
            nm = entry.get("name", "?")[:14]
            tp = entry.get("type", "?")[:8]
            cnt = entry.get("count", 1)
            freq = entry.get("freq_mhz", 0)
            lines.append(f"  {tp:<14} {nm:<15} {cnt:>8,} {freq:>10.1f}")
        if not _rf_atlas:
            lines.append("  Building atlas…")
        ax3.text(0.02, 0.97, "\n".join(lines[:18]), transform=ax3.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=7.5,
                 fontfamily='monospace')
        ax3.text(0.99, 0.02, f"Total: {_total_emitters:,} emitters worldwide",
                 transform=ax3.transAxes, ha='right', va='bottom',
                 color='#00ffcc', fontsize=9, fontweight='bold')

        fig.suptitle(
            f"BLE SCANNER · SUBNET ARP · PLANETARY RF ATLAS — {_ble_count} BLE + "
            f"{_subnet_count} LAN + {_total_emitters:,} global emitters",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "BLE: bluetoothctl devices + hcitool lescan (all nearby beacons real RSSI). "
                 "LAN: /proc/net/arp + arp-scan full subnet. Atlas: all known planetary emitter types.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_radar(self, fig, p, snap):
        """v128: PASSIVE RADAR + ENERGY DETECTION + MUSIC DOA.
        Real bistatic passive radar using WiFi APs as illuminators.
        CAF cross-ambiguity function between RSSI pairs → range-Doppler image.
        CA-CFAR detection. MUSIC DOA pseudospectrum from RSSI covariance matrix.
        Energy detector (chi-squared NP) per channel. All REAL data, no simulation."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _prad_pairs = snap.get("passive_radar_pairs") or []
        _caf_img = snap.get("passive_radar_caf")
        _edet = snap.get("energy_detect") or {}
        _doa = snap.get("doa_result") or {}
        _mvs = snap.get("mvs_motion") or {}
        _xcorr = snap.get("wideband_xcorr") or {}
        _rtlsdr_ok = snap.get("rtlsdr_ok", False)
        _rtl_spec = snap.get("rtlsdr_spectrum")
        _rtl_fc = snap.get("rtlsdr_fc_mhz", 100.0)
        _rtl_method = snap.get("rtlsdr_method", "none")
        _ents = snap.get("rf_link_entities") or []
        _n_pairs = len(_prad_pairs)

        gs = GridSpec(2, 3, figure=fig, left=0.06, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.40, wspace=0.30)

        # ── Panel 0 (top-left): CAF bistatic radar image ──
        ax0 = fig.add_subplot(gs[0, 0])
        ax0.set_facecolor("#04101a")
        ax0.set_title(f"PASSIVE RADAR CAF — {_n_pairs} AP pairs", color='#00ffcc', fontsize=10)
        if _caf_img is not None and np.max(_caf_img) > 0:
            ax0.imshow(10.0 * np.log10(_caf_img + 1e-12), aspect='auto', origin='lower',
                       cmap='inferno', interpolation='bilinear',
                       extent=[0, _caf_img.shape[1], 0, _caf_img.shape[0]])
            ax0.set_xlabel("Doppler bin", color='#aaccbb', fontsize=8)
            ax0.set_ylabel("Range delay (samples)", color='#aaccbb', fontsize=8)
            # Mark detected peaks
            for pr in _prad_pairs[:3]:
                if pr.get("detected"):
                    ax0.axhline(min(pr.get("delay_lag", 0), _caf_img.shape[0] - 1),
                                color='#22ff88', lw=1.0, ls='--', alpha=0.8)
        else:
            ax0.text(0.5, 0.5,
                     f"Cross-ambiguity function\nbuilding ({_n_pairs} AP pairs found)\n"
                     f"Need ≥2 APs with ≥16 RSSI history samples",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax0.transAxes)
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax0.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 1 (top-centre): MUSIC DOA pseudospectrum polar plot ──
        ax1 = fig.add_subplot(gs[0, 1], projection='polar')
        ax1.set_facecolor("#04101a")
        _ps = _doa.get("pseudospectrum")
        _az = _doa.get("azimuth_deg")
        if _ps is not None and len(_ps) > 0:
            angles_rad = np.linspace(0, 2 * np.pi, len(_ps), endpoint=False)
            ax1.plot(angles_rad, _ps, color='#22ff88', lw=1.0)
            ax1.fill(angles_rad, _ps, alpha=0.25, color='#22ff88')
            if _az is not None:
                az_rad = np.radians(_az)
                ax1.annotate('', xy=(az_rad, 1.05), xytext=(0, 0),
                             arrowprops=dict(arrowstyle='->', color='#ffdd44', lw=2.5))
                ax1.set_title(f"MUSIC DOA: {_az}°\n{_doa.get('n_aps', 0)} APs",
                              color='#00ffcc', fontsize=9, pad=12)
        else:
            ax1.set_title(f"MUSIC DOA\nBuilding ({len(_ents)} APs)…",
                          color='#00ffcc', fontsize=9, pad=12)
        ax1.set_theta_zero_location('N')
        ax1.set_theta_direction(-1)
        ax1.tick_params(colors='#aaccbb', labelsize=6)
        ax1.grid(color='#1a3a4a', lw=0.5)

        # ── Panel 2 (top-right): Energy detector per channel ──
        ax2 = fig.add_subplot(gs[0, 2])
        ax2.set_facecolor("#04101a")
        ax2.set_title("ENERGY DETECTOR (chi² NP, P_FA=5%)", color='#00ffcc', fontsize=9)
        if _edet:
            chs = sorted(_edet.keys())[:20]
            snrs = [_edet[c]["snr_db"] for c in chs]
            detected = [_edet[c]["detected"] for c in chs]
            cols = ['#22ff88' if d else '#336655' for d in detected]
            ax2.barh(range(len(chs)), snrs, color=cols, alpha=0.85, height=0.75)
            ax2.set_yticks(range(len(chs)))
            ax2.set_yticklabels([f"Ch{c}" for c in chs], fontsize=7, color='#aaccbb')
            ax2.axvline(0, color='#ff4444', lw=0.8, ls='--')
            ax2.set_xlabel("SNR (dB)", color='#aaccbb', fontsize=8)
            n_det = sum(1 for d in detected if d)
            ax2.set_title(f"ENERGY DETECTOR — {n_det}/{len(chs)} channels signal",
                          color='#00ffcc', fontsize=9)
        else:
            ax2.text(0.5, 0.5, "Collecting channel RSSI histories…",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax2.transAxes)
        ax2.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax2.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 3 (bottom-left): Bistatic pair table ──
        ax3 = fig.add_subplot(gs[1, 0])
        ax3.set_facecolor("#04101a")
        ax3.axis('off')
        ax3.set_title("BISTATIC PAIR DETECTIONS (CA-CFAR)", color='#00ffcc', fontsize=9)
        if _prad_pairs:
            rows = [[pr["ref"][:8], pr["surv"][:8],
                     f"{pr['bistatic_range_m']:.0f}m",
                     f"{pr['doppler_hz']:.3f}",
                     f"{pr['snr_db']:.1f}",
                     "YES" if pr["detected"] else "no"]
                    for pr in _prad_pairs[:10]]
            tbl = ax3.table(cellText=rows,
                            colLabels=["Ref AP", "Surv AP", "Range", "Dopp Hz", "SNR", "Det"],
                            cellLoc='center', loc='center',
                            colWidths=[0.18, 0.18, 0.14, 0.14, 0.12, 0.12])
            tbl.auto_set_font_size(False); tbl.set_fontsize(7)
            for (r, c), cell in tbl.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#22ff88' if r > 0 and rows[r-1][5]=="YES"
                                    else '#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax3.text(0.5, 0.5,
                     "Need ≥2 APs with 16+ RSSI\nhistory samples for bistatic pairs",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax3.transAxes)

        # ── Panel 4 (bottom-centre): Wideband cross-correlation matrix ──
        ax4 = fig.add_subplot(gs[1, 1])
        ax4.set_facecolor("#04101a")
        ax4.set_title("WIDEBAND CROSS-CORRELATION MATRIX", color='#00ffcc', fontsize=9)
        _xmat = _xcorr.get("xcorr_matrix")
        if _xmat is not None:
            im = ax4.imshow(_xmat, cmap='RdBu_r', vmin=-1, vmax=1,
                            aspect='auto', interpolation='nearest')
            _bands = _xcorr.get("bands", [])
            ax4.set_xticks(range(len(_bands))); ax4.set_xticklabels(_bands, fontsize=7, color='#aaccbb')
            ax4.set_yticks(range(len(_bands))); ax4.set_yticklabels(_bands, fontsize=7, color='#aaccbb')
            for i in range(len(_bands)):
                for j in range(len(_bands)):
                    ax4.text(j, i, f"{_xmat[i,j]:.2f}", ha='center', va='center',
                             color='k' if abs(_xmat[i,j]) > 0.5 else '#aaccbb', fontsize=8)
            lag_s = _xcorr.get("dominant_lag_s", 0)
            ax4.set_xlabel(f"Dominant inter-band lag: {lag_s:.1f}s", color='#aaccbb', fontsize=8)
        else:
            ax4.text(0.5, 0.5, "Building cross-band correlation…\n(need RSSI in 2+ bands)",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax4.transAxes)
        ax4.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax4.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 5 (bottom-right): RTL-SDR spectrum OR motion status ──
        ax5 = fig.add_subplot(gs[1, 2])
        ax5.set_facecolor("#04101a")
        if _rtlsdr_ok and _rtl_spec is not None:
            ax5.set_title(f"RTL-SDR SPECTRUM @ {_rtl_fc:.1f}MHz [{_rtl_method}]",
                          color='#00ffcc', fontsize=9)
            freqs = np.linspace(_rtl_fc - 1.2, _rtl_fc + 1.2, len(_rtl_spec))
            ax5.plot(freqs, _rtl_spec, color='#22ff88', lw=0.8)
            ax5.set_xlabel("Frequency (MHz)", color='#aaccbb', fontsize=8)
            ax5.set_ylabel("Power (dBFS)", color='#aaccbb', fontsize=8)
            ax5.set_ylim(-100, 0)
            ax5.fill_between(freqs, -100, _rtl_spec, alpha=0.25, color='#22ff88')
        else:
            ax5.set_title("MVS MOTION DETECTOR (ESPectre) + RTL-SDR",
                          color='#00ffcc', fontsize=9)
            ax5.axis('off')
            mvs_lines = [
                "  RTL-SDR: NOT CONNECTED",
                "  (plug in RTL-SDR dongle for real SDR spectrum)",
                "",
                f"  ESPectre MVS Motion Detector:",
                f"  Motion detected:  {'YES' if _mvs.get('motion') else 'No'}",
                f"  Turbulence score: {_mvs.get('score', 0.0):.3f} dB²",
                f"  Spatial turb (σ): {_mvs.get('turbulence', 0.0):.2f} dB",
                f"  N APs sampled:    {_mvs.get('n_aps', 0)}",
                f"  Threshold:        {_mvs.get('threshold', 0.8):.2f} dB²",
                "",
                "  Source: MVS_MOTION_REAL (real RSSI σ across APs)",
            ]
            ax5.text(0.04, 0.96, "\n".join(mvs_lines), transform=ax5.transAxes,
                     va='top', ha='left', color='#aaccbb', fontsize=8.5,
                     fontfamily='monospace')
        ax5.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax5.spines.values(): sp.set_color('#1a3a4a')

        n_det_total = sum(1 for pr in _prad_pairs if pr.get("detected"))
        mvs_str = "MOTION" if _mvs.get("motion") else "Quiet"
        fig.suptitle(
            f"PASSIVE RADAR · MUSIC DOA · ENERGY DETECTOR · CAF+CFAR — "
            f"{_n_pairs} pairs, {n_det_total} detections, MVS: {mvs_str}",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "Passive radar: WiFi APs as bistatic illuminators, RSSI cross-ambiguity + CA-CFAR. "
                 "DOA: MUSIC pseudospectrum from RSSI covariance matrix. "
                 "Energy detect: Neyman-Pearson chi² test on per-channel RSSI. All real data.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_scene3d(self, fig, p, snap):
        """v128: RF 3D GAUSSIAN SCENE — 3D Gaussian splatting of the RF environment.
        Each detected emitter → Gaussian splat at estimated position (path-loss range).
        Volume render: 32×32×8 voxel grid. 3 orthogonal cross-section slices (XY/XZ/YZ).
        Inspired by RF-GS (CrucialUseExampleCode12). Pure numpy, real RSSI only."""
        import numpy as np
        from mpl_toolkits.mplot3d import Axes3D  # noqa
        fig.patch.set_facecolor("#050d14")
        _xy = snap.get("rf3d_xy")
        _xz = snap.get("rf3d_xz")
        _yz = snap.get("rf3d_yz")
        _n_splats = snap.get("rf3d_splat_count", 0)
        _mlat = snap.get("multilat_position") or {}
        _doa = snap.get("doa_result") or {}
        _mdns_peers = snap.get("mdns_peers") or []
        _ents = snap.get("rf_link_entities") or []
        _prad_pairs = snap.get("passive_radar_pairs") or []

        gs = GridSpec(2, 3, figure=fig, left=0.05, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.40, wspace=0.30)

        # ── Panel 0 (top-left): XY top-down slice (floor plan view) ──
        ax0 = fig.add_subplot(gs[0, 0])
        ax0.set_facecolor("#04101a")
        ax0.set_title(f"RF 3D GAUSSIAN — XY (top-down) {_n_splats} splats",
                      color='#00ffcc', fontsize=9)
        G = 32; EXT = 25.0
        if _xy is not None and np.max(_xy) > 0:
            ax0.imshow(_xy.T, origin='lower', aspect='equal',
                       extent=[-EXT, EXT, -EXT, EXT],
                       cmap='hot', vmin=0, vmax=1, interpolation='bilinear')
        else:
            _blank = np.zeros((G, G))
            ax0.imshow(_blank, origin='lower', aspect='equal',
                       extent=[-EXT, EXT, -EXT, EXT], cmap='hot', vmin=0, vmax=1)
            ax0.text(0.5, 0.5, f"Building 3D Gaussian scene…\n{len(_ents)} emitters",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax0.transAxes)
        # Node at origin
        ax0.plot(0, 0, 'w^', ms=12, zorder=6, label="This node")
        # Multi-lat fix
        if _mlat.get("x_m") is not None:
            mx = np.clip(_mlat["x_m"], -EXT * 0.9, EXT * 0.9)
            my = np.clip(_mlat["y_m"], -EXT * 0.9, EXT * 0.9)
            uc = _mlat.get("uncertainty_m", 5)
            circ = plt.Circle((mx, my), uc, fill=False, color='#00ccff', lw=1.5, ls='--')
            ax0.add_patch(circ)
            ax0.plot(mx, my, 'c*', ms=10, zorder=7)
        # DOA arrow
        if _doa.get("azimuth_deg") is not None:
            az = np.radians(_doa["azimuth_deg"])
            ax0.annotate('', xy=(12 * np.sin(az), 12 * np.cos(az)), xytext=(0, 0),
                         arrowprops=dict(arrowstyle='->', color='#ffdd44', lw=2.0))
        ax0.set_xlim(-EXT, EXT); ax0.set_ylim(-EXT, EXT)
        ax0.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax0.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax0.grid(color='#1a3a4a', lw=0.4, alpha=0.5)
        ax0.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb',
                   edgecolor='#1a3a4a', loc='upper right')
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax0.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 1 (top-centre): XZ elevation slice ──
        ax1 = fig.add_subplot(gs[0, 1])
        ax1.set_facecolor("#04101a")
        ax1.set_title("RF 3D GAUSSIAN — XZ (elevation, front)", color='#00ffcc', fontsize=9)
        if _xz is not None and np.max(_xz) > 0:
            ax1.imshow(_xz.T, origin='lower', aspect='auto',
                       extent=[-EXT, EXT, 0, 5.0],
                       cmap='plasma', vmin=0, vmax=1, interpolation='bilinear')
        else:
            ax1.text(0.5, 0.5, "XZ slice…", ha='center', va='center',
                     color='#446655', fontsize=10, transform=ax1.transAxes)
            ax1.set_xlim(-EXT, EXT); ax1.set_ylim(0, 5)
        ax1.axhline(1.5, color='#aaccbb', lw=0.8, ls='--', alpha=0.5, label='AP height 1.5m')
        ax1.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax1.set_ylabel("Height (m)", color='#aaccbb', fontsize=8)
        ax1.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb', edgecolor='#1a3a4a')
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax1.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 2 (top-right): YZ side slice ──
        ax2 = fig.add_subplot(gs[0, 2])
        ax2.set_facecolor("#04101a")
        ax2.set_title("RF 3D GAUSSIAN — YZ (side elevation)", color='#00ffcc', fontsize=9)
        if _yz is not None and np.max(_yz) > 0:
            ax2.imshow(_yz.T, origin='lower', aspect='auto',
                       extent=[-EXT, EXT, 0, 5.0],
                       cmap='viridis', vmin=0, vmax=1, interpolation='bilinear')
        else:
            ax2.text(0.5, 0.5, "YZ slice…", ha='center', va='center',
                     color='#446655', fontsize=10, transform=ax2.transAxes)
            ax2.set_xlim(-EXT, EXT); ax2.set_ylim(0, 5)
        ax2.set_xlabel("North (m)", color='#aaccbb', fontsize=8)
        ax2.set_ylabel("Height (m)", color='#aaccbb', fontsize=8)
        ax2.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax2.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 3 (bottom-left): mDNS peer map ──
        ax3 = fig.add_subplot(gs[1, 0])
        ax3.set_facecolor("#04101a")
        ax3.axis('off')
        ax3.set_title(f"mDNS N.E.P.A. PEER NETWORK — {len(_mdns_peers)} peers",
                      color='#00ffcc', fontsize=9)
        peer_lines = ["  mDNS PEER DISCOVERY (_nepa._tcp.local.)", "  " + "─" * 38]
        if _mdns_peers:
            for peer in _mdns_peers[:12]:
                age = time.time() - peer.get("ts", time.time())
                peer_lines.append(f"  {peer['ip']:<18} port {peer['port']}  {age:.0f}s ago")
        else:
            peer_lines.append("  No N.E.P.A. peers found on LAN.")
            peer_lines.append("  (querying 224.0.0.251:5353 every 15s)")
        peer_lines.append("")
        peer_lines.append(f"  Bistatic radar pairs: {len(_prad_pairs)}")
        det = sum(1 for pr in _prad_pairs if pr.get("detected"))
        peer_lines.append(f"  CFAR detections:      {det}")
        if _mlat:
            peer_lines.append(f"  Multilat fix: {_mlat.get('x_m',0):.1f}m E, "
                               f"{_mlat.get('y_m',0):.1f}m N "
                               f"± {_mlat.get('uncertainty_m',0):.1f}m")
        ax3.text(0.04, 0.96, "\n".join(peer_lines), transform=ax3.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.5, fontfamily='monospace')

        # ── Panel 4 (bottom-centre): RF emitter list with estimated positions ──
        ax4 = fig.add_subplot(gs[1, 1])
        ax4.set_facecolor("#04101a")
        ax4.axis('off')
        ax4.set_title("EMITTER SPLAT TABLE (real RSSI → range → Gaussian)", color='#00ffcc', fontsize=8.5)
        _RSSI_REF = -40.0; _PL = 2.7
        rows4 = []
        for e in _ents[:14]:
            rssi = e.get("link_rssi_dbm", -100)
            if rssi < -95:
                continue
            d = 10.0 ** ((_RSSI_REF - rssi) / (10.0 * _PL))
            rows4.append([e.get("id", "?")[:12], e.get("band", "?")[:8],
                          f"{rssi:.0f}", f"{min(d,999):.1f}"])
        if rows4:
            tbl4 = ax4.table(cellText=rows4,
                             colLabels=["BSSID/ID", "Band", "RSSI", "Range(m)"],
                             cellLoc='left', loc='center',
                             colWidths=[0.34, 0.22, 0.18, 0.20])
            tbl4.auto_set_font_size(False); tbl4.set_fontsize(7.5)
            for (r, c), cell in tbl4.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax4.text(0.5, 0.5, "No emitters with RSSI > -95dBm", ha='center', va='center',
                     color='#446655', fontsize=10, transform=ax4.transAxes)

        # ── Panel 5 (bottom-right): Scene status ──
        ax5 = fig.add_subplot(gs[1, 2])
        ax5.set_facecolor("#04101a")
        ax5.axis('off')
        ax5.set_title("RF 3D SCENE STATUS", color='#00ffcc', fontsize=9)
        status_lines = [
            "  RF 3D GAUSSIAN SCENE RECONSTRUCTION",
            "  " + "─" * 40,
            f"  Gaussian splats placed: {_n_splats}",
            f"  Voxel grid:             32 × 32 × 8",
            f"  Spatial extent:         ±25m × ±25m × 5m",
            f"  Splat amplitude:        real RSSI → linear mW",
            f"  Splat sigma:            path-loss range × 0.45",
            "",
            f"  MUSIC DOA:  {_doa.get('azimuth_deg', 'Building…')}°"
            if _doa.get('azimuth_deg') is not None else "  MUSIC DOA:  Building…",
            f"  n_aps used: {_doa.get('n_aps', 0)} (need ≥3 with 32+ history)",
            "",
            "  Source: RF_3DGS_REAL (real RSSI path-loss → range)",
            "  Ref: RF-GS paper (CrucialUseExampleCode12)",
        ]
        ax5.text(0.04, 0.96, "\n".join(status_lines), transform=ax5.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.5,
                 fontfamily='monospace')

        fig.suptitle(
            f"RF 3D GAUSSIAN SCENE — {_n_splats} splats · MUSIC DOA · mDNS peers: {len(_mdns_peers)}",
            color='#00ffcc', fontsize=12, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "RF 3D Gaussian splatting: real RSSI → path-loss range → 3D Gaussian volume render. "
                 "Orthogonal slices XY/XZ/YZ show true RF power distribution in space. "
                 "MUSIC DOA from RSSI covariance matrix. No fabricated geometry.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_tomography(self, fig, p, snap):
        """v129: RF TOMOGRAPHY — SAR backprojection + attenuation map + NeRF2 + ITU-R."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _sar = snap.get("sar_image"); _sar_n = snap.get("sar_n_elements", 0)
        _tomo = snap.get("rf_tomo_image"); _tomo_n = snap.get("rf_tomo_n_views", 0)
        _nerf = snap.get("nerf2_slice_xy"); _nerf_loss = snap.get("nerf2_loss", 0.0)
        _nerf_iter = snap.get("nerf2_iter", 0)
        _itu = snap.get("itu_propagation") or []
        _tdoa = snap.get("tdoa_fix") or {}
        _mlat = snap.get("multilat_position") or {}
        _doa = snap.get("doa_result") or {}
        gs = GridSpec(2, 3, figure=fig, left=0.06, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.42, wspace=0.28)
        EXT = 30.0; EXT_T = 20.0
        # ── SAR image ──
        ax0 = fig.add_subplot(gs[0, 0]); ax0.set_facecolor("#04101a")
        ax0.set_title(f"SAR BACKPROJECTION ({_sar_n} elements)", color='#00ffcc', fontsize=9)
        if _sar is not None and np.max(_sar) > 0:
            ax0.imshow(_sar.T, origin='lower', aspect='equal',
                       extent=[-EXT, EXT, -EXT, EXT], cmap='hot', vmin=0, vmax=1,
                       interpolation='bilinear')
        else:
            ax0.text(0.5, 0.5, f"Building SAR…\n≥2 APs with ≥8 samples",
                     ha='center', va='center', color='#446655', fontsize=9,
                     transform=ax0.transAxes); ax0.set_xlim(-EXT, EXT); ax0.set_ylim(-EXT, EXT)
        ax0.plot(0, 0, 'w^', ms=11, zorder=6)
        ax0.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax0.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax0.grid(color='#1a3a4a', lw=0.4, alpha=0.4)
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax0.spines.values(): sp.set_color('#1a3a4a')
        # ── RF tomo ──
        ax1 = fig.add_subplot(gs[0, 1]); ax1.set_facecolor("#04101a")
        ax1.set_title(f"RF TOMO ({_tomo_n} views{'|FBP' if _tomo_n>=8 else '|BP'})",
                      color='#00ffcc', fontsize=9)
        if _tomo is not None and np.max(_tomo) > 0:
            im1 = ax1.imshow(_tomo.T, origin='lower', aspect='equal',
                             extent=[-EXT_T, EXT_T, -EXT_T, EXT_T],
                             cmap='RdYlGn_r', vmin=0, vmax=1, interpolation='bilinear')
            fig.colorbar(im1, ax=ax1, fraction=0.046, pad=0.04).ax.tick_params(
                colors='#aaccbb', labelsize=6)
        else:
            ax1.text(0.5, 0.5, "Backprojecting…\nRed=high atten / Green=clear",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax1.transAxes); ax1.set_xlim(-EXT_T, EXT_T); ax1.set_ylim(-EXT_T, EXT_T)
        ax1.plot(0, 0, 'w^', ms=11, zorder=6)
        ax1.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax1.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax1.spines.values(): sp.set_color('#1a3a4a')
        # ── NeRF2 ──
        ax2 = fig.add_subplot(gs[0, 2]); ax2.set_facecolor("#04101a")
        ax2.set_title(f"NERF2 RF FIELD (iter={_nerf_iter}, loss={_nerf_loss:.3f})",
                      color='#00ffcc', fontsize=9)
        if _nerf is not None and np.max(_nerf) > 0:
            ax2.imshow(_nerf.T, origin='lower', aspect='equal',
                       extent=[-20, 20, -20, 20], cmap='plasma', vmin=0, interpolation='bilinear')
        else:
            ax2.text(0.5, 0.5, "Ray marching…\nFitting to real RSSI",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax2.transAxes); ax2.set_xlim(-20, 20); ax2.set_ylim(-20, 20)
        ax2.plot(0, 0, 'w^', ms=11, zorder=6)
        ax2.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax2.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax2.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax2.spines.values(): sp.set_color('#1a3a4a')
        # ── Positioning comparison ──
        ax3 = fig.add_subplot(gs[1, 0]); ax3.set_facecolor("#04101a"); ax3.axis('off')
        ax3.set_title("POSITIONING METHODS", color='#00ffcc', fontsize=9)
        plines = ["  TDOA: " + (f"{_tdoa.get('x_m',0):+.1f}m E, {_tdoa.get('y_m',0):+.1f}m N"
                                if _tdoa else "Building…"),
                  "  MLAT: " + (f"{_mlat.get('x_m',0):+.1f}m E, {_mlat.get('y_m',0):+.1f}m N ±{_mlat.get('uncertainty_m',0):.1f}m"
                                if _mlat.get("x_m") is not None else "Building…"),
                  "  DOA:  " + (f"{_doa.get('azimuth_deg')}° ({_doa.get('n_aps',0)} APs)"
                                if _doa.get("azimuth_deg") is not None else "Building…"),
                  "", "  All real RSSI history — no fabricated positions.",
                  "  TDOA: gradient xcorr timing + Chan WLS",
                  "  MLAT: WLS circle intersection from path-loss ranges",
                  "  DOA:  MUSIC spatial covariance matrix eigenvectors"]
        ax3.text(0.04, 0.96, "\n".join(plines), transform=ax3.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.5, fontfamily='monospace')
        # ── ITU-R table ──
        ax4 = fig.add_subplot(gs[1, 1]); ax4.set_facecolor("#04101a"); ax4.axis('off')
        ax4.set_title("ITU-R P.525/676 ATMOSPHERIC (1km)", color='#00ffcc', fontsize=9)
        if _itu:
            rows4 = [[f"{i['freq_mhz']:>7.0f}", f"{i['fspl_db']:>5.1f}",
                      f"{i['o2_abs_db']:>5.2f}", f"{i['h2o_abs_db']:>5.2f}",
                      f"{i['total_loss_db']:>6.1f}",
                      "BLK" if i.get("iono_blocked") else "OK"] for i in _itu]
            tbl = ax4.table(cellText=rows4,
                            colLabels=["Freq MHz","FSPL","O₂","H₂O","Total","Iono"],
                            cellLoc='center', loc='center',
                            colWidths=[0.17,0.13,0.12,0.12,0.14,0.10])
            tbl.auto_set_font_size(False); tbl.set_fontsize(7)
            for (r, c), cell in tbl.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#ff4444' if r > 0 and rows4[r-1][5]=="BLK"
                                    else '#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax4.text(0.5, 0.5, "Fetching open-meteo weather…",
                     ha='center', va='center', color='#446655', fontsize=10,
                     transform=ax4.transAxes)
        # ── Method legend ──
        ax5 = fig.add_subplot(gs[1, 2]); ax5.set_facecolor("#04101a"); ax5.axis('off')
        ax5.set_title("ALGORITHM REFERENCE", color='#00ffcc', fontsize=9)
        legend = ["  SAR: RSSI history → range series → sinc backproject",
                  "       Ref: MIMO-SAR (CrucialUseExampleCode5/8)",
                  "  TOMO: AP RSSI → Radon backproject → attenuation map",
                  "        FBP (ramp filter) when ≥8 views available",
                  "  NERF2: 32×32×8 voxel field fitted by gradient descent",
                  "         to real RSSI — numpy port (CrucialUseExampleCode11)",
                  "  ITU-R P.525-4: FSPL = 20log(d) + 20log(f) + 92.4",
                  "  ITU-R P.676-12: O₂ + H₂O molecular absorption",
                  "  Weather: open-meteo.com (T, RH, P_atm)"]
        ax5.text(0.04, 0.96, "\n".join(legend), transform=ax5.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=8.0, fontfamily='monospace')
        fig.suptitle(
            f"RF TOMOGRAPHY — SAR ({_sar_n} elem) · Tomo ({_tomo_n} views) · "
            f"NeRF2 (i={_nerf_iter} L={_nerf_loss:.3f}) · ITU-R ({len(_itu)} bands)",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "SAR RSSI backprojection · RF Radon tomography · numpy NeRF2 ray marching · "
                 "ITU-R atmospheric propagation · TDOA+MLAT+MUSIC positioning. All real data.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_planetview(self, fig, p, snap):
        """v129: PLANETARY SCAN VIEW — unified instrument coverage + local RF scene."""
        import numpy as np
        fig.patch.set_facecolor("#050d14")
        _scan = snap.get("planet_scan") or {}
        _instruments = _scan.get("instruments") or []
        _total_cov = _scan.get("total_coverage_pct", 0.0)
        _n_det = _scan.get("total_detections", 0)
        _n_for_planet = _scan.get("n_nodes_for_full_planet", 0)
        _itu = snap.get("itu_propagation") or []
        _ents = snap.get("rf_link_entities") or []
        _mlat = snap.get("multilat_position") or {}
        _doa = snap.get("doa_result") or {}
        _tdoa = snap.get("tdoa_fix") or {}
        _sar = snap.get("sar_image"); _tomo = snap.get("rf_tomo_image")
        _atlas = snap.get("rf_atlas") or []
        gs = GridSpec(2, 3, figure=fig, left=0.05, right=0.98, top=0.93, bottom=0.07,
                      hspace=0.40, wspace=0.26)
        # ── Coverage gauge ──
        ax0 = fig.add_subplot(gs[0, 0]); ax0.set_facecolor("#04101a")
        ax0.set_title("INSTRUMENT COVERAGE", color='#00ffcc', fontsize=10)
        if _instruments:
            names = [i["name"][:22] for i in _instruments]
            covs = [max(i["coverage_pct"], 1e-12) for i in _instruments]
            dets = [i["detections"] for i in _instruments]
            cols = ['#22ff88' if d > 0 else '#1a3a4a' for d in dets]
            ax0.barh(range(len(names)), covs, color=cols, alpha=0.85, height=0.7)
            ax0.set_yticks(range(len(names)))
            ax0.set_yticklabels([f"{n} ({d})" for n, d in zip(names, dets)],
                                 fontsize=7, color='#aaccbb')
            ax0.set_xlabel("Coverage % (log)", color='#aaccbb', fontsize=8)
            ax0.set_xscale('log'); ax0.set_xlim(1e-12, 110)
        else:
            ax0.text(0.5, 0.5, "Computing…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax0.transAxes)
        ax0.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax0.spines.values(): sp.set_color('#1a3a4a')
        # ── Local RF scene ──
        EXT = 25.0; _RSSI_REF = -40.0; _PL = 2.7
        ax1 = fig.add_subplot(gs[0, 1]); ax1.set_facecolor("#04101a")
        ax1.set_title("LOCAL RF SCENE — ALL FIXES", color='#00ffcc', fontsize=10)
        if _sar is not None and np.max(_sar) > 0:
            ax1.imshow(_sar.T, origin='lower', aspect='equal',
                       extent=[-EXT, EXT, -EXT, EXT], cmap='hot', vmin=0, vmax=1,
                       alpha=0.4, interpolation='bilinear')
        elif _tomo is not None and np.max(_tomo) > 0:
            ax1.imshow(_tomo.T, origin='lower', aspect='equal',
                       extent=[-EXT, EXT, -EXT, EXT], cmap='RdYlGn_r', vmin=0, vmax=1,
                       alpha=0.35, interpolation='bilinear')
        for e in _ents[:20]:
            rssi = e.get("link_rssi_dbm", -100)
            if rssi < -95: continue
            d = min(10.0 ** ((_RSSI_REF - rssi) / (10.0 * _PL)), EXT)
            c = plt.Circle((0, 0), d, fill=False,
                            color={'2.4GHz':'#22ff88','5GHz':'#00ccff','6GHz':'#ff88ff'}.get(e.get("band",""), '#888888'),
                            lw=0.7, alpha=0.45)
            ax1.add_patch(c)
        ax1.plot(0, 0, 'w^', ms=14, zorder=9, label="Node")
        if _mlat.get("x_m") is not None:
            mx = np.clip(_mlat["x_m"], -EXT*.9, EXT*.9)
            my = np.clip(_mlat["y_m"], -EXT*.9, EXT*.9)
            uc = _mlat.get("uncertainty_m", 5)
            ax1.add_patch(plt.Circle((mx, my), uc, fill=False, color='#00ccff', lw=2, ls='--'))
            ax1.plot(mx, my, 'c*', ms=12, zorder=8, label=f"MLAT ±{uc:.0f}m")
        if _tdoa.get("x_m") is not None:
            ax1.plot(np.clip(_tdoa["x_m"], -EXT*.9, EXT*.9),
                     np.clip(_tdoa["y_m"], -EXT*.9, EXT*.9),
                     'm+', ms=14, mew=2.5, zorder=8, label=f"TDOA")
        if _doa.get("azimuth_deg") is not None:
            az = np.radians(_doa["azimuth_deg"])
            ax1.annotate('', xy=(15*np.sin(az), 15*np.cos(az)), xytext=(0, 0),
                         arrowprops=dict(arrowstyle='->', color='#ffdd44', lw=2.5))
        ax1.set_xlim(-EXT, EXT); ax1.set_ylim(-EXT, EXT)
        ax1.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb',
                   edgecolor='#1a3a4a', loc='upper right')
        ax1.grid(color='#1a3a4a', lw=0.4, alpha=0.5)
        ax1.set_xlabel("East (m)", color='#aaccbb', fontsize=8)
        ax1.set_ylabel("North (m)", color='#aaccbb', fontsize=8)
        ax1.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax1.spines.values(): sp.set_color('#1a3a4a')
        # ── Atlas ──
        ax2 = fig.add_subplot(gs[0, 2]); ax2.set_facecolor("#04101a"); ax2.axis('off')
        ax2.set_title("PLANETARY EMITTER ATLAS", color='#00ffcc', fontsize=10)
        if _atlas:
            rows2 = [[e.get("name","?")[:15], e.get("type","?")[:10],
                      f"{e.get('count',1):,}", f"{e.get('freq_mhz',0):.0f}"]
                     for e in _atlas[:14]]
            tbl2 = ax2.table(cellText=rows2, colLabels=["Name","Type","Count","MHz"],
                             cellLoc='left', loc='center', colWidths=[0.32,0.24,0.20,0.20])
            tbl2.auto_set_font_size(False); tbl2.set_fontsize(7.5)
            for (r, c), cell in tbl2.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax2.text(0.5, 0.5, "Building atlas…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax2.transAxes)
        # ── ITU-R link budget vs range ──
        ax3 = fig.add_subplot(gs[1, 0]); ax3.set_facecolor("#04101a")
        ax3.set_title("ITU-R LINK BUDGET vs RANGE", color='#00ffcc', fontsize=9)
        if _itu:
            ranges = np.logspace(-3, 5, 80)
            _cols4 = ['#22ff88','#00ccff','#ffdd44','#ff88ff']
            ax3.set_xscale('log')
            for idx, ituf in enumerate(_itu[:4]):
                f_hz = ituf["freq_mhz"] * 1e6
                fspl = 20*np.log10(ranges*1e3+1) + 20*np.log10(f_hz) - 147.55
                atm = (ituf["o2_abs_db"]+ituf["h2o_abs_db"])*ranges
                ax3.plot(ranges, fspl+atm, color=_cols4[idx], lw=1.2,
                         label=f"{ituf['freq_mhz']:.0f}MHz")
            ax3.axvline(1e-1, color='#ffffff', lw=0.6, ls=':', alpha=0.4)
            ax3.axvline(1e3, color='#ffffff', lw=0.6, ls=':', alpha=0.4)
            ax3.set_xlabel("Range (km)", color='#aaccbb', fontsize=8)
            ax3.set_ylabel("Loss (dB)", color='#aaccbb', fontsize=8)
            ax3.set_ylim(0, 280)
            ax3.legend(fontsize=7, facecolor='#0a1e2a', labelcolor='#aaccbb', edgecolor='#1a3a4a')
        else:
            ax3.text(0.5, 0.5, "Fetching weather…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax3.transAxes)
        ax3.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax3.spines.values(): sp.set_color('#1a3a4a')
        # ── Scan model table ──
        ax4 = fig.add_subplot(gs[1, 1]); ax4.set_facecolor("#04101a"); ax4.axis('off')
        ax4.set_title(f"SCAN MODEL — {_total_cov:.6f}% / {_n_det} det",
                      color='#00ffcc', fontsize=8.5)
        if _instruments:
            rows4 = [[i["name"][:18], f"{i['scan_radius_km']:.2f}",
                      f"{i['coverage_pct']:.4f}%", str(i["detections"])]
                     for i in _instruments]
            tbl4 = ax4.table(cellText=rows4, colLabels=["Instrument","Rad km","Cov%","Det"],
                             cellLoc='left', loc='center', colWidths=[0.42,0.18,0.22,0.12])
            tbl4.auto_set_font_size(False); tbl4.set_fontsize(7)
            for (r, c), cell in tbl4.get_celld().items():
                cell.set_facecolor('#04101a' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax4.text(0.5, 0.5, "Computing…", ha='center', va='center',
                     color='#446655', fontsize=11, transform=ax4.transAxes)
        # ── How-to-scale summary ──
        ax5 = fig.add_subplot(gs[1, 2]); ax5.set_facecolor("#04101a"); ax5.axis('off')
        ax5.set_title("SCALE-UP ROADMAP", color='#00ffcc', fontsize=10)
        summary = [
            f"  Total coverage: {_total_cov:.8f}%",
            f"  Detections:     {_n_det}  (all real instruments)",
            f"  Local RF ents:  {len(_ents)}",
            "",
            "  TO REACH 100% PLANET COVERAGE:",
            f"  • {_n_for_planet:,.0f} WiFi nodes OR",
            "  • ADS-B on roof (500km, ~2000 nodes)",
            "  • RTL-SDR + yagi antenna (200km range)",
            "  • LEO satellite link (100% at 550km alt)",
            "",
            "  SCALE UP RIGHT NOW:",
            "  • nix-shell --run 'python3 N.E.P.A.py --ingest-port 8770'",
            "  • POST your phones WiFi scan to /ingest",
            "  • mDNS auto-finds other N.E.P.A. nodes",
            "  • RTL-SDR dongle: plug in + auto-detected",
        ]
        ax5.text(0.04, 0.96, "\n".join(summary), transform=ax5.transAxes,
                 va='top', ha='left', color='#aaccbb', fontsize=7.5, fontfamily='monospace')
        fig.suptitle(
            f"PLANETARY SCAN VIEW — {_total_cov:.6f}% Earth covered · "
            f"{_n_det} instruments · {len(_ents)} local entities",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "Honest planetary scan model: real physics determines coverage per instrument. "
                 "ITU-R propagation, SAR+tomo background, multi-method positioning. "
                 "Coverage grows with more nodes, RTL-SDR, ADS-B, satellite APIs.",
                 ha='center', color='#778899', fontsize=7.0)

    def _draw_pointcloud3d(self, fig, p, snap):
        """v131: RF 3D POINT CLOUD — all RF emitters in 3D space.
        WiFi at RSSI path-loss range, ADS-B at real altitude, BT at short range.
        Inspired by mmBody P4Transformer 4D point cloud token structure.
        All positions from real measured data — no synthetic geometry."""
        import numpy as np
        from mpl_toolkits.mplot3d import Axes3D
        fig.patch.set_facecolor("#030a12")
        _cloud = snap.get("rf_point_cloud") or []
        _mlat   = snap.get("multilat_position") or {}
        _tdoa   = snap.get("tdoa_fix") or {}
        _doa    = snap.get("doa_result") or {}
        _bt_devs = snap.get("bt_devices") or []
        _bt_cnt = snap.get("bt_count", 0)
        _pc_cnt = snap.get("rf_pc_count", 0)
        _sem    = snap.get("semantic_presence") or {}
        _COLS = {"WiFi": "#22ff88", "ADS-B": "#ffdd44", "BT": "#ff6622",
                 "BLE": "#ff8844", "FIX": "#00ccff", "SAT": "#cc88ff"}
        gs = GridSpec(2, 3, figure=fig, left=0.03, right=0.98, top=0.93, bottom=0.06,
                      hspace=0.35, wspace=0.22)
        ax3d = fig.add_subplot(gs[0:2, 0:2], projection='3d')
        ax3d.set_facecolor("#030a12")
        ax3d.xaxis.pane.fill = False; ax3d.yaxis.pane.fill = False; ax3d.zaxis.pane.fill = False
        for pane in (ax3d.xaxis.pane, ax3d.yaxis.pane, ax3d.zaxis.pane):
            pane.set_edgecolor('#1a3a4a')
        if _cloud:
            for typ, col in _COLS.items():
                pts = [pt for pt in _cloud if pt.get("type") == typ]
                if not pts: continue
                xs = [pt["x"] for pt in pts]; ys = [pt["y"] for pt in pts]
                zs = [pt["z"] for pt in pts]
                sz = [max(20.0, pt["intensity"] * 80.0) for pt in pts]
                ax3d.scatter(xs, ys, zs, s=sz, c=col, alpha=0.75, label=f"{typ} ({len(pts)})",
                             edgecolors='none', depthshade=True, zorder=5)
                for pt in pts[:3]:
                    ax3d.text(pt["x"], pt["y"], pt["z"], pt["label"][:12],
                              fontsize=6, color=col, alpha=0.8)
        else:
            ax3d.text2D(0.5, 0.5, "Scanning…\nNo RF emitters positioned yet",
                        ha='center', va='center', color='#446655', fontsize=11,
                        transform=ax3d.transAxes)
        ax3d.scatter([0], [0], [0], s=200, c='#ffffff', marker='^', zorder=10, label="YOU")
        if _mlat.get("x_m"):
            ax3d.scatter([_mlat["x_m"]], [_mlat["y_m"]], [0], s=120, c='#00ccff',
                         marker='*', zorder=9, label="MLAT")
        if _tdoa.get("x_m"):
            ax3d.scatter([_tdoa["x_m"]], [_tdoa["y_m"]], [0], s=120, c='#ff44ff',
                         marker='+', zorder=9, label="TDOA")
        if _doa.get("azimuth_deg") is not None:
            az = np.radians(_doa["azimuth_deg"])
            ax3d.quiver(0, 0, 0, 20*np.sin(az), 20*np.cos(az), 0,
                        color='#ffdd44', arrow_length_ratio=0.15, linewidth=2.0)
        ax3d.set_xlabel("East (m)", color='#aaccbb', fontsize=7)
        ax3d.set_ylabel("North (m)", color='#aaccbb', fontsize=7)
        ax3d.set_zlabel("Alt (m)", color='#aaccbb', fontsize=7)
        ax3d.tick_params(colors='#aaccbb', labelsize=6)
        ax3d.legend(fontsize=7, facecolor='#081820', labelcolor='#aaccbb',
                    edgecolor='#1a3a4a', loc='upper left')
        try:
            ax3d.view_init(elev=25, azim=(getattr(self, '_pc3d_azim', 30) + 0.5) % 360)
            self._pc3d_azim = ax3d.azim
        except Exception:
            pass
        ax3d.set_title(f"RF 3D POINT CLOUD — {_pc_cnt} points", color='#00ffcc', fontsize=10)
        ax_tbl = fig.add_subplot(gs[0, 2]); ax_tbl.set_facecolor("#030a12"); ax_tbl.axis('off')
        ax_tbl.set_title("CLOUD BREAKDOWN", color='#00ffcc', fontsize=9)
        by_type = {}
        for pt in _cloud:
            t = pt.get("type", "?")
            by_type[t] = by_type.get(t, 0) + 1
        rows = [[t, str(n)] for t, n in sorted(by_type.items(), key=lambda x: -x[1])]
        rows += [["BT devices", str(_bt_cnt)],
                 ["MLAT fix", "YES" if _mlat.get("x_m") else "NO"],
                 ["TDOA fix", "YES" if _tdoa.get("x_m") else "NO"],
                 ["DOA az", f"{_doa.get('azimuth_deg',0.0):.1f}°" if _doa.get('azimuth_deg') else "—"]]
        if rows:
            tbl = ax_tbl.table(cellText=rows, colLabels=["Type","Count"],
                               cellLoc='left', loc='center', colWidths=[0.65, 0.35])
            tbl.auto_set_font_size(False); tbl.set_fontsize(8.5)
            for (r, c), cell in tbl.get_celld().items():
                cell.set_facecolor('#030a12' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        ax_bt = fig.add_subplot(gs[1, 2]); ax_bt.set_facecolor("#030a12"); ax_bt.axis('off')
        ax_bt.set_title(f"BLUETOOTH DEVICES — {_bt_cnt}", color='#00ffcc', fontsize=9)
        if _bt_devs:
            rows_bt = [[d.get("addr","?")[:17], d.get("name","?")[:14],
                        d.get("type","BT"), d.get("source","?")[:14]]
                       for d in _bt_devs[:8]]
            tbl_bt = ax_bt.table(cellText=rows_bt, colLabels=["Address","Name","Type","Source"],
                                 cellLoc='left', loc='center',
                                 colWidths=[0.32,0.26,0.14,0.26])
            tbl_bt.auto_set_font_size(False); tbl_bt.set_fontsize(7.5)
            for (r, c), cell in tbl_bt.get_celld().items():
                cell.set_facecolor('#030a12' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax_bt.text(0.5, 0.5,
                       "No BT devices seen\n(hcitool/bluetoothctl scanning…)\n\n"
                       "Requires bluetooth adapter\nand discoverable devices",
                       ha='center', va='center', color='#446655', fontsize=8.5,
                       transform=ax_bt.transAxes)
        fig.suptitle(
            f"RF 3D POINT CLOUD — {_pc_cnt} points  |  WiFi+ADS-B+BT+FIX  |  "
            f"state: {_sem.get('state','?')}",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "RF point cloud: WiFi at RSSI path-loss range, ADS-B at real altitude, BT at short range. "
                 "All positions from real measured data. Inspired by mmBody P4Transformer 4D point tokens.",
                 ha='center', color='#445566', fontsize=7.0)

    def _draw_multispectral(self, fig, p, snap):
        """v131: MULTI-SPECTRAL FUSION MAP — freq-bearing power grid over all sources.
        Fuses WiFi RSSI + RTL-SDR spectrum + ADS-B into (frequency × azimuth) heatmap.
        Inspired by mmMesh range/Doppler/angle FFT pipeline. All real sensor data."""
        import numpy as np
        fig.patch.set_facecolor("#030a12")
        _grid = snap.get("multispec_grid")
        _ents = snap.get("rf_link_entities") or []
        _sdr_spec = snap.get("rtlsdr_spectrum")
        # v132d: key exists with value None when no RTL-SDR dongle → .get(k, default)
        # returns None, not the default → f"{None:.1f}" crashed the whole tab. Coerce.
        _sdr_fc = snap.get("rtlsdr_fc_mhz") or 100.0
        _fdiv = snap.get("freq_diversity") or {}
        _doa  = snap.get("doa_result") or {}
        _aircraft = snap.get("aircraft") or []
        _csi_motion = snap.get("csi_phase_motion")
        gs = GridSpec(2, 2, figure=fig, left=0.06, right=0.98, top=0.93, bottom=0.06,
                      hspace=0.38, wspace=0.28)
        ax_heat = fig.add_subplot(gs[0, 0:2]); ax_heat.set_facecolor("#030a12")
        ax_heat.set_title("MULTI-SPECTRAL POWER MAP  (log-frequency × bearing)", color='#00ffcc', fontsize=10)
        if _grid is not None and np.max(_grid) > 0:
            im = ax_heat.imshow(_grid.T, aspect='auto', origin='lower', cmap='plasma',
                                interpolation='bilinear', extent=[0.1, 7000.0, 0, 360])
            fig.colorbar(im, ax=ax_heat, fraction=0.015, pad=0.02,
                         label="Power (a.u.)").ax.tick_params(labelcolor='#aaccbb')
            ax_heat.set_xlabel("Frequency (MHz)", color='#aaccbb', fontsize=8)
            ax_heat.set_ylabel("Bearing (deg)", color='#aaccbb', fontsize=8)
            ax_heat.set_xscale('log')
            if _doa.get("azimuth_deg"):
                ax_heat.axhline(_doa["azimuth_deg"], color='#ffdd44', lw=1.5, ls='--', alpha=0.7,
                                label=f"DOA {_doa['azimuth_deg']:.0f}°")
            for f_mhz, label, col in [(2450,"2.4G","#22ff88"),(5500,"5G","#00ccff"),
                                       (6000,"6G","#ff88ff"),(1090,"ADS-B","#ffdd44"),
                                       (433,"ISM433","#ff6622")]:
                ax_heat.axvline(f_mhz, color=col, lw=0.8, ls=':', alpha=0.6, label=label)
            ax_heat.legend(fontsize=7, facecolor='#081820', labelcolor='#aaccbb',
                           edgecolor='#1a3a4a', loc='upper right')
        else:
            ax_heat.text(0.5, 0.5, "Building multi-spectral map…\nData accumulating from all sources",
                         ha='center', va='center', color='#446655', fontsize=11,
                         transform=ax_heat.transAxes)
        ax_heat.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_heat.spines.values(): sp.set_color('#1a3a4a')
        ax_sdr = fig.add_subplot(gs[1, 0]); ax_sdr.set_facecolor("#030a12")
        ax_sdr.set_title(f"RTL-SDR SPECTRUM @ {_sdr_fc:.1f} MHz", color='#00ffcc', fontsize=9)
        if _sdr_spec is not None and len(_sdr_spec) > 0:
            freqs = np.linspace(_sdr_fc - 1.2, _sdr_fc + 1.2, len(_sdr_spec))
            ax_sdr.plot(freqs, _sdr_spec, color='#22ff88', lw=0.9, alpha=0.85)
            ax_sdr.fill_between(freqs, _sdr_spec, min(_sdr_spec), alpha=0.25, color='#22ff88')
            ax_sdr.set_xlabel("Freq (MHz)", color='#aaccbb', fontsize=8)
            ax_sdr.set_ylabel("dBFS", color='#aaccbb', fontsize=8)
        else:
            ax_sdr.text(0.5, 0.5,
                        "RTL-SDR not connected\n\nPlug in RTL-SDR dongle\nauto-detected on USB",
                        ha='center', va='center', color='#446655', fontsize=9,
                        transform=ax_sdr.transAxes)
        ax_sdr.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_sdr.spines.values(): sp.set_color('#1a3a4a')
        ax_div = fig.add_subplot(gs[1, 1]); ax_div.set_facecolor("#030a12"); ax_div.axis('off')
        ax_div.set_title("SPECTRAL SUMMARY", color='#00ffcc', fontsize=9)
        _band_rssi = _fdiv.get("band_rssi_mean") or {}
        _coh_mat   = _fdiv.get("coherence_matrix") or {}
        _coh_bw    = _fdiv.get("coherence_bw_mhz")
        _div_gain  = _fdiv.get("diversity_gain_db") or 0.0
        _n_act     = _fdiv.get("n_bands_active", 0)
        lines = [f"Active RF bands: {_n_act}"]
        for b, v in _band_rssi.items():
            lines.append(f"  {b}: {v:.1f} dBm")
        lines.append("")
        for pair, corr in _coh_mat.items():
            lines.append(f"  {pair}: rho={corr:.3f}")
        if _coh_bw: lines.append(f"Coherence BW: {_coh_bw:.1f} MHz")
        lines.append(f"MRC diversity gain: {_div_gain:.1f} dB")
        lines.append("")
        lines.append(f"ADS-B aircraft: {len(_aircraft)}")
        lines.append(f"WiFi emitters: {len(_ents)}")
        if _csi_motion is not None:
            lines.append(f"CSI phase motion: {_csi_motion:.5f}")
        lines.append("")
        lines.append("Active sources:")
        lines.append(f"  WiFi RSSI ({len(_ents)} APs)")
        if _sdr_spec is not None: lines.append("  RTL-SDR spectrum")
        if _aircraft: lines.append(f"  ADS-B ({len(_aircraft)} aircraft)")
        ax_div.text(0.05, 0.95, "\n".join(lines), transform=ax_div.transAxes,
                    va='top', ha='left', color='#aaccbb', fontsize=8, fontfamily='monospace')
        fig.suptitle(
            f"MULTI-SPECTRAL FUSION MAP — {len(_ents)} WiFi + "
            f"{len(_aircraft)} aircraft + {_n_act} bands + "
            f"{'SDR' if _sdr_spec is not None else 'noSDR'}",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "Frequency x bearing power map fused from all real RF sources. "
                 "EMA-smoothed 80/20. Add RTL-SDR for wideband spectrum coverage.",
                 ha='center', color='#445566', fontsize=7.0)

    def _draw_liveworld(self, fig, p, snap):
        """v132: LIVE RF WALK-AROUND MAP — auto-zoom, NeRF overlay, full compass, sparklines.
        Node always at origin. APs at RSSI path-loss range. Auto-zoom fits all emitters.
        NeRF2 volumetric density underlay. Per-AP sparklines on map. Motion arcs.
        All data from real measurements only — no fabricated positions."""
        import numpy as np
        fig.patch.set_facecolor("#030a12")
        _ents   = snap.get("rf_link_entities") or []
        _mlat   = snap.get("multilat_position") or {}
        _doa    = snap.get("doa_result") or {}
        _tdoa   = snap.get("tdoa_fix") or {}
        _sar    = snap.get("sar_image")
        _tomo   = snap.get("rf_tomo_image")
        _nerf_xy= snap.get("nerf_density_xy")
        _sem    = snap.get("semantic_presence") or {}
        _fdiv   = snap.get("freq_diversity") or {}
        _mvs    = snap.get("mvs_motion") or {}
        _rxs    = snap.get("connected_receivers") or []
        _RSSI_REF = -40.0; _PL = 2.7
        _BAND_COL = {"2.4GHz": "#22ff88", "5GHz": "#00ccff", "6GHz": "#ff88ff",
                     "ADS-B": "#ffdd44", "BLE": "#ff6622", "SDR": "#aa88ff", "": "#888888"}

        # ── Auto-compute scene extent from real AP distances ──
        _valid_dists = []
        for e in _ents[:40]:
            rssi = float(e.get("link_rssi_dbm", -100))
            if rssi > -95:
                _valid_dists.append(min(10.0**((_RSSI_REF - rssi)/(10.0*_PL)), 80.0))
        if _mlat.get("x_m"):
            _valid_dists.append((float(_mlat["x_m"])**2 + float(_mlat["y_m"])**2)**0.5)
        EXT = max(20.0, min(80.0, (max(_valid_dists) * 1.25) if _valid_dists else 30.0))

        gs = GridSpec(3, 3, figure=fig, left=0.04, right=0.98, top=0.93, bottom=0.06,
                      hspace=0.38, wspace=0.28)

        # ── Panel 0 (large, 2×2): overhead RF walk-around map — auto-zoom + NeRF overlay ──
        ax_map = fig.add_subplot(gs[0:2, 0:2]); ax_map.set_facecolor("#030a12")
        ax_map.set_title(
            f"LIVE RF MAP — YOU AT ORIGIN — {len(_ents)} emitters — "
            f"auto-zoom ±{EXT:.0f}m",
            color='#00ffcc', fontsize=11)
        # Layer 1: NeRF2 volumetric density underlay (real RSSI ray-marching)
        if _nerf_xy is not None and np.max(_nerf_xy) > 0.01:
            ax_map.imshow(_nerf_xy.T, origin='lower', aspect='equal',
                          extent=[-EXT, EXT, -EXT, EXT], cmap='inferno',
                          vmin=0, vmax=float(np.max(_nerf_xy)), alpha=0.28, interpolation='bilinear')
        # Layer 2: SAR or tomo reconstruction overlay
        elif _sar is not None and np.max(_sar) > 0:
            ax_map.imshow(_sar.T, origin='lower', aspect='equal',
                          extent=[-EXT, EXT, -EXT, EXT], cmap='hot', vmin=0, vmax=1,
                          alpha=0.32, interpolation='bilinear')
        elif _tomo is not None and np.max(_tomo) > 0:
            ax_map.imshow(_tomo.T, origin='lower', aspect='equal',
                          extent=[-EXT, EXT, -EXT, EXT], cmap='RdYlGn_r', vmin=0, vmax=1,
                          alpha=0.28, interpolation='bilinear')
        # Draw range rings at fixed distances for spatial reference
        for ring_m in [5, 10, 20, 30, 50, 70]:
            if ring_m < EXT:
                ax_map.add_patch(plt.Circle((0, 0), ring_m, fill=False,
                                             color='#1a3a4a', lw=0.5, alpha=0.5, ls=':'))
                ax_map.text(0, ring_m, f"{ring_m}m", fontsize=6, color='#2a4a5a',
                            ha='center', va='bottom', zorder=2)
        # Draw APs as positioned dots + range ring + sparkline minibar
        _doa_az = _doa.get("azimuth_deg")
        _motion_any = False
        for idx, e in enumerate(_ents[:40]):
            rssi = float(e.get("link_rssi_dbm", -100))
            if rssi < -95: continue
            dist = min(10.0 ** ((_RSSI_REF - rssi) / (10.0 * _PL)), EXT * 0.90)
            band = e.get("band", ""); col = _BAND_COL.get(band, "#888888")
            ssid = str(e.get("ssid", e.get("id", f"AP{idx}")))[:12]
            var_db = float(e.get("link_var_db", 0.0))
            motion = float(e.get("link_motion", 0.0))
            if motion > 0.3: _motion_any = True
            # AP spread by DOA-estimated or evenly distributed angle
            angle_deg = ((_doa_az or 0) + idx * (360.0 / max(len(_ents), 1)))
            angle_rad = np.radians(angle_deg)
            lx = dist * np.sin(angle_rad); ly = dist * np.cos(angle_rad)
            # Range ring (thin, band-colored)
            ring_alpha = 0.25 + min(0.40, motion)
            ax_map.add_patch(plt.Circle((0, 0), dist, fill=False,
                                         color=col, lw=0.8, alpha=ring_alpha))
            # AP dot — size proportional to RSSI strength, pulsing glow if motion
            dot_size = max(30.0, min(120.0, (rssi + 100) * 2.0))
            ax_map.scatter([lx], [ly], s=dot_size, c=col, alpha=0.85, zorder=6,
                           edgecolors='#ffffff' if motion > 0.3 else 'none',
                           linewidths=1.5 if motion > 0.3 else 0)
            # SSID label
            if dist < EXT * 0.88:
                ax_map.annotate(ssid, (lx, ly), fontsize=6.0, color=col,
                                ha='center', va='bottom', zorder=7,
                                xytext=(0, 5), textcoords='offset points')
                # Variance indicator bar (mini sparkline near the dot)
                if var_db > 0.1 and dist < EXT * 0.75:
                    bar_h = min(var_db / 5.0, 1.0) * 4.0
                    ax_map.annotate(f"σ{var_db:.1f}dB", (lx, ly),
                                    fontsize=5.0, color='#ffdd44', alpha=0.7,
                                    ha='center', va='top', zorder=7,
                                    xytext=(0, -7), textcoords='offset points')
            # Line from origin to AP (signal path)
            ax_map.plot([0, lx], [0, ly], color=col, lw=0.5, alpha=0.18, zorder=3)
        # Motion glow on node if any AP detected motion
        if _motion_any:
            ax_map.add_patch(plt.Circle((0, 0), 1.8, fill=True, color='#ff4400',
                                         alpha=0.20, zorder=8))
        # Node marker — YOU ARE HERE (prominent)
        ax_map.plot(0, 0, 'w^', ms=18, zorder=12, label="YOU (node)", markeredgecolor='#00ffcc',
                    markeredgewidth=1.5)
        ax_map.add_patch(plt.Circle((0, 0), 0.5, color='#00ffcc', alpha=0.18, zorder=11))
        ax_map.plot(0, 0, 'w^', ms=4, zorder=13)  # inner dot
        # MLAT fix
        if _mlat.get("x_m") is not None:
            mx = np.clip(float(_mlat["x_m"]), -EXT*.88, EXT*.88)
            my = np.clip(float(_mlat["y_m"]), -EXT*.88, EXT*.88)
            uc = float(_mlat.get("uncertainty_m", 5))
            ax_map.add_patch(plt.Circle((mx, my), uc, fill=False, color='#00ccff',
                                         lw=2.0, ls='--', zorder=9))
            ax_map.plot(mx, my, 'c*', ms=14, zorder=10, label=f"MLAT ±{uc:.0f}m")
        # TDOA fix
        if _tdoa.get("x_m") is not None:
            tdx = np.clip(float(_tdoa["x_m"]), -EXT*.88, EXT*.88)
            tdy = np.clip(float(_tdoa["y_m"]), -EXT*.88, EXT*.88)
            ax_map.plot(tdx, tdy, 'm+', ms=16, mew=2.5, zorder=10, label="TDOA fix")
        # DOA arrow
        if _doa_az is not None:
            az = np.radians(_doa_az)
            arr_len = min(EXT * 0.60, 18.0)
            ax_map.annotate('', xy=(arr_len*np.sin(az), arr_len*np.cos(az)), xytext=(0, 0),
                            arrowprops=dict(arrowstyle='->', color='#ffdd44', lw=2.5), zorder=9)
            ax_map.text(arr_len*1.08*np.sin(az), arr_len*1.08*np.cos(az),
                        f"DOA {_doa_az:.0f}°", color='#ffdd44', fontsize=8,
                        ha='center', zorder=9, fontweight='bold')
        # Compass rose (full 16-point)
        for deg, lbl, fsize in [(0,"N",10),(45,"NE",7),(90,"E",10),(135,"SE",7),
                                  (180,"S",10),(225,"SW",7),(270,"W",10),(315,"NW",7)]:
            r = np.radians(deg)
            ax_map.text(EXT*0.90*np.sin(r), EXT*0.90*np.cos(r),
                        lbl, color='#3a5a6a', fontsize=fsize,
                        ha='center', va='center', alpha=0.75, fontweight='bold')
        # Cardinal bearing lines
        for deg in [0, 90, 180, 270]:
            r = np.radians(deg)
            ax_map.plot([0, EXT*np.sin(r)], [0, EXT*np.cos(r)],
                        color='#1a3a4a', lw=0.4, alpha=0.35, ls='--', zorder=1)
        ax_map.set_xlim(-EXT, EXT); ax_map.set_ylim(-EXT, EXT)
        ax_map.set_aspect('equal')
        ax_map.legend(fontsize=7.5, facecolor='#081820', labelcolor='#aaccbb',
                      edgecolor='#1a3a4a', loc='upper right',
                      markerscale=0.85, framealpha=0.85)
        ax_map.grid(color='#0d2030', lw=0.4, alpha=0.5, linestyle='--')
        ax_map.set_xlabel("East / metres (RSSI path-loss estimate)", color='#aaccbb', fontsize=8)
        ax_map.set_ylabel("North / metres", color='#aaccbb', fontsize=8)
        ax_map.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_map.spines.values(): sp.set_color('#1a3a4a')
        # Band legend inline
        for b, c in _BAND_COL.items():
            if b: ax_map.plot([], [], 'o', color=c, ms=5, label=b)

        # ── Panel 1 (top-right): RSSI history for top 5 APs ──
        ax_rssi = fig.add_subplot(gs[0, 2]); ax_rssi.set_facecolor("#030a12")
        ax_rssi.set_title("AP RSSI HISTORY (TOP 5)", color='#00ffcc', fontsize=9)
        _cols5 = ['#22ff88','#00ccff','#ff88ff','#ffdd44','#ff6622']
        shown = 0
        for idx, e in enumerate(_ents[:5]):
            # v132: canonical entity history key is "hist" (link_rssi_hist was never set)
            hist = e.get("hist") or e.get("link_rssi_hist") or []
            if hist and shown < 5:
                ax_rssi.plot(hist[-60:], color=_cols5[shown], lw=1.2,
                             label=str(e.get("ssid", e.get("id", f"AP{idx}")))[:12])
                shown += 1
        if shown == 0:
            ax_rssi.text(0.5, 0.5, "No RSSI history yet\n(scanning…)",
                         ha='center', va='center', color='#446655', fontsize=9,
                         transform=ax_rssi.transAxes)
        else:
            ax_rssi.legend(fontsize=6.5, facecolor='#081820', labelcolor='#aaccbb',
                           edgecolor='#1a3a4a')
        ax_rssi.set_xlabel("Samples (newest→right)", color='#aaccbb', fontsize=7)
        ax_rssi.set_ylabel("RSSI (dBm)", color='#aaccbb', fontsize=7)
        ax_rssi.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_rssi.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 2 (mid-right): Semantic presence state ──
        ax_sem = fig.add_subplot(gs[1, 2]); ax_sem.set_facecolor("#030a12"); ax_sem.axis('off')
        ax_sem.set_title("SEMANTIC PRESENCE STATE", color='#00ffcc', fontsize=9)
        _state     = _sem.get("state", "unknown")
        _conf      = _sem.get("confidence", 0.0)
        _dur       = _sem.get("duration_s", 0.0)
        _motion    = _sem.get("motion", 0.0)
        _turb      = _sem.get("turbulence", 0.0)
        _n_aps_s   = _sem.get("n_aps", 0)
        _src_s     = _sem.get("source", "—")
        _STATE_COL = {
            "room-empty": "#446655", "room-active": "#22ff88",
            "someone-sleeping": "#4488cc", "possible-distress": "#ff4444",
            "fall-risk-elevated": "#ff8800", "bed-exit": "#ffdd44",
            "multi-room-transition": "#aa88ff", "bathroom-occupied": "#00ccff",
            "meeting-in-progress": "#88ffcc", "elderly-inactivity-anomaly": "#ff6622",
        }
        sc = _STATE_COL.get(_state, "#888888")
        ax_sem.text(0.5, 0.80, _state.upper().replace("-", " "),
                    transform=ax_sem.transAxes, ha='center', va='top',
                    fontsize=13, fontweight='bold', color=sc, wrap=True)
        ax_sem.text(0.5, 0.58, f"confidence: {_conf*100:.0f}%  |  held: {_dur:.0f}s",
                    transform=ax_sem.transAxes, ha='center', va='top',
                    fontsize=8.5, color='#aaccbb')
        ax_sem.text(0.5, 0.42, f"motion={_motion:.4f}  turb={_turb:.3f}  n_aps={_n_aps_s}",
                    transform=ax_sem.transAxes, ha='center', va='top',
                    fontsize=8, color='#aaccbb', fontfamily='monospace')
        ax_sem.text(0.5, 0.26, f"source: {_src_s}",
                    transform=ax_sem.transAxes, ha='center', va='top',
                    fontsize=7.5, color='#557788')
        ax_sem.text(0.5, 0.10, "Derived from real RSSI variance only — no body sensor",
                    transform=ax_sem.transAxes, ha='center', va='top',
                    fontsize=7, color='#334455', style='italic')
        ax_sem.add_patch(plt.Rectangle((0.02, 0.02), 0.96, 0.96, fill=False,
                                        edgecolor=sc, lw=2, transform=ax_sem.transAxes))

        # ── Panel 3 (bottom-left): RF NeRF volumetric density XZ slice ──
        ax_nerf = fig.add_subplot(gs[2, 0]); ax_nerf.set_facecolor("#030a12")
        _nerf_xz = snap.get("nerf_density_xz")
        _n_rays  = snap.get("nerf_n_rays", 0)
        if _nerf_xz is not None and np.max(_nerf_xz) > 0.01:
            ax_nerf.imshow(_nerf_xz.T, origin='lower', aspect='auto',
                           extent=[-EXT, EXT, 0, 5.0], cmap='inferno',
                           vmin=0, vmax=float(np.max(_nerf_xz)), interpolation='bilinear')
            ax_nerf.axhline(1.5, color='#aaccbb', lw=0.8, ls='--', alpha=0.5,
                             label='AP height 1.5m')
            ax_nerf.axvline(0, color='#ffffff', lw=0.6, ls=':', alpha=0.4)
            ax_nerf.set_xlabel("East (m)", color='#aaccbb', fontsize=7)
            ax_nerf.set_ylabel("Height (m)", color='#aaccbb', fontsize=7)
            ax_nerf.legend(fontsize=6.5, facecolor='#081820', labelcolor='#aaccbb',
                           edgecolor='#1a3a4a')
        else:
            ax_nerf.text(0.5, 0.5, f"NeRF2 volumetric building…\n{_n_rays} rays cast",
                         ha='center', va='center', color='#446655', fontsize=9,
                         transform=ax_nerf.transAxes)
        ax_nerf.set_title(f"NeRF RF DENSITY (XZ elevation) — {_n_rays} rays",
                           color='#00ffcc', fontsize=9)
        ax_nerf.tick_params(colors='#aaccbb', labelsize=6)
        for sp in ax_nerf.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 4 (bottom-mid): motion score + RSSI variance time series ──
        ax_mot = fig.add_subplot(gs[2, 1]); ax_mot.set_facecolor("#030a12")
        ax_mot.set_title("MOTION SCORE + RSSI VARIANCE TIMELINE", color='#00ffcc', fontsize=9)
        _sem_eng = getattr(getattr(self, "fuser", None), "semantic_presence", None)
        if _sem_eng is not None and hasattr(_sem_eng, "_motion_hist"):
            _mh = list(_sem_eng._motion_hist[-120:])
            _th = list(getattr(_sem_eng, "_turb_hist", [])[-120:])
            if _mh:
                xs = list(range(len(_mh)))
                ax_mot.fill_between(xs, _mh, color='#22ff88', alpha=0.30, label="motion")
                ax_mot.plot(xs, _mh, color='#22ff88', lw=1.2)
                if _th:
                    tmax = max(max(_th), 1e-9)
                    tnorm = [v / tmax for v in _th[:len(xs)]]
                    ax_mot.plot(xs[:len(tnorm)], tnorm, color='#ffdd44', lw=1.0,
                                ls='--', label="turbulence(norm)")
                ax_mot.set_ylabel("Score", color='#aaccbb', fontsize=7)
                ax_mot.set_xlabel("Samples (1Hz)", color='#aaccbb', fontsize=7)
                ax_mot.legend(fontsize=7, facecolor='#081820', labelcolor='#aaccbb',
                              edgecolor='#1a3a4a')
        else:
            _mvs_score = float(_mvs.get("score", 0.0))
            ax_mot.bar(["RSSI var", "motion"], [_mvs_score, _mvs_score],
                       color=['#22ff88','#ffdd44'], alpha=0.8)
            ax_mot.set_ylim(0, max(_mvs_score * 1.4, 0.01))
            ax_mot.text(0.5, 0.5, f"motion={_mvs_score:.4f}",
                        ha='center', va='center', color='#aaccbb', fontsize=9,
                        transform=ax_mot.transAxes)
        ax_mot.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_mot.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 5 (bottom-right): Connected receivers + fix summary ──
        ax_coh = fig.add_subplot(gs[2, 2]); ax_coh.set_facecolor("#030a12"); ax_coh.axis('off')
        ax_coh.set_title("RECEIVERS + POSITIONING SUMMARY", color='#00ffcc', fontsize=9)
        _fdiv = snap.get("freq_diversity") or {}
        _coh_bw = _fdiv.get("coherence_bw_mhz"); _ds_ns = _fdiv.get("delay_spread_ns")
        _div_gain = _fdiv.get("diversity_gain_db", 0.0); _n_act = _fdiv.get("n_bands_active", 0)
        lines = [f"── RECEIVERS ({len(_rxs)}) ──"]
        for rx in _rxs[:6]:
            lines.append(f"  [{rx['type']}] {rx['id']}")
        lines += ["", f"── POSITIONING ──"]
        if _mlat.get("x_m"): lines.append(f"  MLAT ({_mlat['x_m']:.1f},{_mlat['y_m']:.1f})m")
        if _tdoa.get("x_m"): lines.append(f"  TDOA ({_tdoa['x_m']:.1f},{_tdoa['y_m']:.1f})m")
        if _doa_az: lines.append(f"  DOA  {_doa_az:.1f}° azimuth")
        lines += [f"  RF emitters: {len(_ents)}", f"  Bands active: {_n_act}",
                  f"  MRC gain: {_div_gain:.1f}dB"]
        if _coh_bw: lines.append(f"  Coh.BW: {_coh_bw:.0f}MHz")
        if _ds_ns:  lines.append(f"  DelaySpread: {_ds_ns:.0f}ns")
        lines += ["", f"── SEMANTIC STATE ──"]
        _state = _sem.get("state", "unknown")
        _conf  = _sem.get("confidence", 0.0)
        lines.append(f"  {_state.upper()} ({_conf*100:.0f}%)")
        ax_coh.text(0.05, 0.97, "\n".join(lines), transform=ax_coh.transAxes,
                    va='top', ha='left', color='#aaccbb', fontsize=7.5,
                    fontfamily='monospace')
        fig.suptitle(
            f"LIVE RF WALK-AROUND — {len(_ents)} emitters | state: {_state.upper()} | "
            f"zoom: ±{EXT:.0f}m | receivers: {len(_rxs)}",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "YOU are always at origin (white triangle). APs at RSSI path-loss range. "
                 "NeRF2 ray-march underlay shows signal density. Auto-zoom fits all detected emitters. "
                 "Motion glow = RSSI variance > threshold. All data real sensor measurements.",
                 ha='center', color='#445566', fontsize=7.0)

    def _draw_sigint(self, fig, p, snap):
        """v130: SIGNAL INTELLIGENCE — ESP32 CSI subcarrier heatmap, WiFi hardware adapters,
        semantic presence states, network device table. All real sensor data only."""
        import numpy as np
        fig.patch.set_facecolor("#030a12")
        _csi_ok   = snap.get("esp32_csi_ok", False)
        _csi_meth = snap.get("esp32_csi_method", "none")
        _csi_n    = snap.get("esp32_csi_n_subcarriers", 0)
        _amp_hist = snap.get("esp32_csi_amp_hist")
        _phase_hist = snap.get("esp32_csi_phase_hist")
        _adapters = snap.get("wifi_adapters") or []
        _net_devs = snap.get("network_devices") or []
        _net_meth = snap.get("network_sniffer_method", "none")
        _sem      = snap.get("semantic_presence") or {}
        _fdiv     = snap.get("freq_diversity") or {}
        _ents     = snap.get("rf_link_entities") or []
        gs = GridSpec(2, 3, figure=fig, left=0.04, right=0.98, top=0.93, bottom=0.06,
                      hspace=0.40, wspace=0.26)

        # ── Panel 0: ESP32 CSI amplitude heatmap (subcarrier × time) ──
        ax_csi = fig.add_subplot(gs[0, 0:2]); ax_csi.set_facecolor("#030a12")
        if _csi_ok and _amp_hist is not None and _amp_hist.size > 0:
            im = ax_csi.imshow(_amp_hist.T, aspect='auto', origin='lower',
                               cmap='inferno', interpolation='nearest')
            fig.colorbar(im, ax=ax_csi, fraction=0.025, pad=0.02,
                         label="Amplitude").ax.tick_params(labelcolor='#aaccbb')
            ax_csi.set_xlabel("Frame (newest→right)", color='#aaccbb', fontsize=8)
            ax_csi.set_ylabel("Subcarrier index", color='#aaccbb', fontsize=8)
            ax_csi.set_title(
                f"ESP32 CSI AMPLITUDE — {_csi_n} subcarriers  [{_csi_meth}]  "
                f"source: ESP32_CSI_UDP_REAL",
                color='#00ffcc', fontsize=9)
        else:
            ax_csi.set_title("ESP32 CSI — WAITING FOR DEVICE", color='#ffdd44', fontsize=10)
            ax_csi.text(0.5, 0.58,
                        "No ESP32 CSI device connected",
                        ha='center', va='center', color='#888888', fontsize=11,
                        transform=ax_csi.transAxes)
            ax_csi.text(0.5, 0.40,
                        f"Listening on UDP port {ESP32CSILiveStream._UDP_PORT}  [{_csi_meth}]",
                        ha='center', va='center', color='#557788', fontsize=9,
                        transform=ax_csi.transAxes)
            ax_csi.text(0.5, 0.25,
                        "Flash ESP32 with ESP32-CSI-Tool firmware, connect to same LAN,\n"
                        "it will stream CSI CSV packets to this port automatically.",
                        ha='center', va='center', color='#445566', fontsize=8,
                        transform=ax_csi.transAxes, style='italic')
        ax_csi.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_csi.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 1: ESP32 CSI phase heatmap ──
        ax_phase = fig.add_subplot(gs[0, 2]); ax_phase.set_facecolor("#030a12")
        if _csi_ok and _phase_hist is not None and _phase_hist.size > 0:
            im2 = ax_phase.imshow(_phase_hist.T, aspect='auto', origin='lower',
                                  cmap='bwr', vmin=-np.pi, vmax=np.pi, interpolation='nearest')
            fig.colorbar(im2, ax=ax_phase, fraction=0.040, pad=0.02,
                         label="Phase (rad)").ax.tick_params(labelcolor='#aaccbb')
            ax_phase.set_title("CSI PHASE (rad)", color='#00ffcc', fontsize=9)
            ax_phase.set_xlabel("Frame", color='#aaccbb', fontsize=8)
            ax_phase.set_ylabel("Subcarrier", color='#aaccbb', fontsize=8)
        else:
            ax_phase.set_title("CSI PHASE — NO DEVICE", color='#ffdd44', fontsize=9)
            ax_phase.text(0.5, 0.5, "—", ha='center', va='center',
                          color='#446655', fontsize=20, transform=ax_phase.transAxes)
        ax_phase.tick_params(colors='#aaccbb', labelsize=7)
        for sp in ax_phase.spines.values(): sp.set_color('#1a3a4a')

        # ── Panel 2: WiFi hardware adapter table ──
        ax_hw = fig.add_subplot(gs[1, 0]); ax_hw.set_facecolor("#030a12"); ax_hw.axis('off')
        ax_hw.set_title(f"WIFI HARDWARE ADAPTERS — {len(_adapters)} detected", color='#00ffcc', fontsize=9)
        if _adapters:
            rows_hw = [[a.get("iface","?"), a.get("driver","?")[:12],
                        " ".join(a.get("bands",[])), a.get("wifi_gen","?"),
                        "yes" if a.get("monitor") else "no",
                        a.get("source","?")[:14]]
                       for a in _adapters[:8]]
            tbl_hw = ax_hw.table(cellText=rows_hw,
                                 colLabels=["iface","driver","bands","gen","mon","source"],
                                 cellLoc='left', loc='center',
                                 colWidths=[0.14,0.18,0.22,0.14,0.10,0.18])
            tbl_hw.auto_set_font_size(False); tbl_hw.set_fontsize(8)
            for (r, c), cell in tbl_hw.get_celld().items():
                cell.set_facecolor('#030a12' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax_hw.text(0.5, 0.5, "No wireless adapters detected\n(/sys/class/net scan running…)",
                       ha='center', va='center', color='#446655', fontsize=9,
                       transform=ax_hw.transAxes)

        # ── Panel 3: Semantic presence detail ──
        ax_sem = fig.add_subplot(gs[1, 1]); ax_sem.set_facecolor("#030a12"); ax_sem.axis('off')
        ax_sem.set_title("SEMANTIC PRESENCE — ALL 10 STATES", color='#00ffcc', fontsize=9)
        _STATES_ALL = [
            ("room-empty",               "#446655"),
            ("room-active",              "#22ff88"),
            ("someone-sleeping",         "#4488cc"),
            ("possible-distress",        "#ff4444"),
            ("fall-risk-elevated",       "#ff8800"),
            ("bed-exit",                 "#ffdd44"),
            ("multi-room-transition",    "#aa88ff"),
            ("bathroom-occupied",        "#00ccff"),
            ("meeting-in-progress",      "#88ffcc"),
            ("elderly-inactivity-anomaly","#ff6622"),
        ]
        current_state = _sem.get("state", "room-empty")
        for idx, (sname, scol) in enumerate(_STATES_ALL):
            y = 0.92 - idx * 0.09
            is_cur = sname == current_state
            ax_sem.text(0.03, y, ("▶ " if is_cur else "  ") + sname,
                        transform=ax_sem.transAxes, va='center',
                        fontsize=8.5 if is_cur else 7.5, color=scol if is_cur else '#445566',
                        fontweight='bold' if is_cur else 'normal')
            if is_cur:
                conf = _sem.get("confidence", 0.0)
                ax_sem.text(0.72, y, f"{conf*100:.0f}%",
                            transform=ax_sem.transAxes, va='center',
                            fontsize=8, color=scol)

        # ── Panel 4: Network device table (scapy / proc/arp) ──
        ax_net = fig.add_subplot(gs[1, 2]); ax_net.set_facecolor("#030a12"); ax_net.axis('off')
        ax_net.set_title(
            f"NETWORK DEVICES — {len(_net_devs)}  [{_net_meth}]",
            color='#00ffcc', fontsize=9)
        if _net_devs:
            rows_net = [[d.get("mac","?")[:17], d.get("ip","?") or "?",
                         d.get("hostname","?") or "?",
                         str(d.get("packets", 0)),
                         d.get("source","?")[:14]]
                        for d in sorted(_net_devs, key=lambda x: x.get("last_seen",0), reverse=True)[:8]]
            tbl_net = ax_net.table(cellText=rows_net,
                                   colLabels=["MAC","IP","hostname","pkts","source"],
                                   cellLoc='left', loc='center',
                                   colWidths=[0.28,0.18,0.22,0.08,0.20])
            tbl_net.auto_set_font_size(False); tbl_net.set_fontsize(7.5)
            for (r, c), cell in tbl_net.get_celld().items():
                cell.set_facecolor('#030a12' if r > 0 else '#0a2030')
                cell.set_text_props(color='#aaccbb' if r > 0 else '#00ffcc')
                cell.set_edgecolor('#1a3a4a')
        else:
            ax_net.text(0.5, 0.5,
                        f"No devices seen yet\n({_net_meth})\n\nDevices will appear as\nARP/DNS/DHCP traffic is observed",
                        ha='center', va='center', color='#446655', fontsize=8.5,
                        transform=ax_net.transAxes)
        fig.suptitle(
            f"SIGNAL INTELLIGENCE — ESP32 CSI: {'LIVE' if _csi_ok else 'NO DEVICE'}  |  "
            f"Adapters: {len(_adapters)}  |  Net devices: {len(_net_devs)}  |  "
            f"RF entities: {len(_ents)}",
            color='#00ffcc', fontsize=11, fontweight='bold', y=0.98)
        fig.text(0.5, 0.012,
                 "ESP32-CSI-Tool: flash firmware → UDP port 6969. WiFi adapters from /sys/class/net. "
                 "Network devices from ARP/DNS (scapy) or /proc/net/arp. All real hardware data.",
                 ha='center', color='#445566', fontsize=7.0)

    def _draw_remote(self, fig, p, snap):
        """v104: REMOTE SENSOR NODES — every real device that POSTed its OWN real receiver data
        to the ingest endpoint, shown live. Honest distributed sensing: each node is a real
        receiver; their carriers sum into a planet-scale real-data pool. No fabricated nodes."""
        import time as _t
        nodes = getattr(self.fuser, "remote_nodes", {}) or {}
        fig.suptitle(f"REMOTE SENSOR NODES — {len(nodes)} real devices sending live data",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        if not nodes:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.58, "No remote nodes connected yet.", ha='center', va='center',
                    color='#88ccff', fontsize=15, transform=ax.transAxes)
            ax.text(0.5, 0.40, "Start N.E.P.A. with  --ingest-port 8770 , then on any phone/laptop/Pi open\n"
                    "http://<this-host>:8770/  and run the sender snippet shown there. Each device sends\n"
                    "its OWN real WiFi scan — they fuse here as real distributed sensors (mass correlation).",
                    ha='center', va='center', color='#aaa', fontsize=10, transform=ax.transAxes)
            return
        now = _t.time()
        ax1 = fig.add_subplot(1, 2, 1); ax1.axis('off')
        ax1.text(0.02, 0.97, f"{'NODE':18s} {'kind':6s} {'emit':>5s} {'age':>5s} {'rpts':>6s}",
                 color='#88ccaa', fontsize=9, family='monospace', transform=ax1.transAxes)
        for i, (nid, rec) in enumerate(list(nodes.items())[:20]):
            age = now - rec.get("last_seen", now)
            col = '#00ffcc' if age < 15 else '#778899'
            ax1.text(0.02, 0.92 - i * 0.044,
                     f"{nid[:18]:18s} {str(rec.get('kind','?'))[:6]:6s} "
                     f"{int(rec.get('emitter_count',0)):5d} {age:4.0f}s {int(rec.get('count',0)):6d}",
                     color=col, fontsize=8, family='monospace', transform=ax1.transAxes)
        total = sum(int(v.get('emitter_count', 0)) for v in nodes.values())
        _netmov = int(p.get("network_movers", 0)) if p else 0
        _nodemov = p.get("node_movers", {}) if p else {}
        ax1.text(0.02, 0.08, f"TOTAL real carriers across all nodes: {total}",
                 color='#22ff88', fontsize=11, weight='bold', transform=ax1.transAxes)
        ax1.text(0.02, 0.02, f"NETWORK device-free movers (subspace, MP-gated): {_netmov}"
                 + (f"  ·  per-node {dict(list(_nodemov.items())[:4])}" if _nodemov else ""),
                 color=('#ff8866' if _netmov else '#5aa'), fontsize=9, weight='bold',
                 transform=ax1.transAxes)
        ax2 = fig.add_subplot(1, 2, 2)
        pm = getattr(self.fuser, "planet_map", None)
        located = [(r.get("lat"), r.get("lon"), nid) for nid, r in nodes.items()
                   if r.get("lat") and r.get("lon")]
        if pm is not None and getattr(pm, "map_img", None) is not None and located:
            with pm._lock:
                img = np.array(pm.map_img)
            ax2.imshow(img, origin='upper')
            for la, lo, nid in located:
                px = pm.latlon_to_px(la, lo)
                if px:
                    ax2.plot(px[0], px[1], 'o', color='#ff3355', ms=8)
                    ax2.text(px[0] + 5, px[1], str(nid)[:8], color='#ff88aa', fontsize=7)
            ax2.set_title("node locations on real map", color='#88ccaa', fontsize=9); ax2.axis('off')
        else:
            ax2.axis('off')
            ax2.text(0.5, 0.5, "node geolocations appear here\nwhen nodes send lat/lon",
                     ha='center', va='center', color='#778899', fontsize=10, transform=ax2.transAxes)
        fig.text(0.5, 0.02, "Each node is a REAL remote receiver POSTing its own measurements, fused live. "
                 "No fabricated nodes — a node appears only when a real device sends.",
                 ha='center', color='#6a8', fontsize=8)

    def _draw_geo3d(self, fig, p, snap):
        """v100: UNIFIED 3D GEO-WORLD — the 'total vision construct': real DEM terrain (draped
        with real satellite imagery) + real OSM buildings extruded ONTO that terrain at their
        true ground elevation + the node pin, in one navigable auto-orbiting scene. Every height
        is a real measurement; buildings sit at their real terrain elevation. No fabricated geometry."""
        from mpl_toolkits.mplot3d.art3d import Poly3DCollection
        import math
        pm = getattr(self.fuser, "planet_map", None)
        fig.suptitle("UNIFIED 3D GEO-WORLD — real terrain + real buildings + node (auto-orbit)",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        if pm is None:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "PlanetMapEngine not initialised.", ha='center', va='center',
                    color='#ff8866', fontsize=12, transform=ax.transAxes)
            return
        with pm._lock:
            grid = None if pm.elev_grid is None else np.array(pm.elev_grid)
            emeta = dict(pm.elev_meta)
            mimg = None if pm.map_img is None else np.array(pm.map_img)
            blds = None if pm.buildings is None else list(pm.buildings)
            ef = pm._elev_fetching; bf = pm._bld_fetching
        if grid is None:
            if not ef:
                pm.fetch_elevation_grid_async(24)
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "Building unified world — fetching real DEM terrain…",
                    ha='center', va='center', color='#88ccff', fontsize=12, transform=ax.transAxes)
            return
        if blds is None and not bf:
            pm.fetch_buildings_async(300)
        n = grid.shape[0]
        lat_n, lat_s, lon_w, lon_e = emeta["bounds"]
        lat0 = emeta["lat"]; lon0 = emeta["lon"]
        mx = 111320.0 * math.cos(math.radians(lat0))
        xs = (np.linspace(lon_w, lon_e, n) - lon0) * mx
        ys = (np.linspace(lat_n, lat_s, n) - lat0) * 110540.0
        X, Y = np.meshgrid(xs, ys)
        Z = np.nan_to_num(grid, nan=float(emeta.get("min", 0.0)))
        ve = 3.0  # uniform vertical exaggeration applied to BOTH terrain and buildings (consistent)
        ax = fig.add_subplot(111, projection='3d'); ax.set_facecolor('#05080d')
        fac = None
        if mimg is not None and mimg.ndim == 3:
            H, W = mimg.shape[:2]
            yi = np.clip(np.linspace(0, H - 1, n).astype(int), 0, H - 1)
            xi = np.clip(np.linspace(0, W - 1, n).astype(int), 0, W - 1)
            fac = np.clip(mimg[np.ix_(yi, xi)][..., :3], 0, 1)
        try:
            if fac is not None:
                ax.plot_surface(X, Y, Z * ve, facecolors=fac, rstride=1, cstride=1,
                                linewidth=0, antialiased=True, shade=False)
            else:
                ax.plot_surface(X, Y, Z * ve, cmap='terrain', rstride=1, cstride=1, linewidth=0)
        except Exception as _e:
            ax.text2D(0.5, 0.5, f"terrain error: {_e}", transform=ax.transAxes, ha='center', color='#f55')
        nb = 0
        if blds:
            faces = []; colors = []
            hmax = max((b["h"] for b in blds), default=10.0)
            cmap = plt.get_cmap('plasma')
            for b in blds[:300]:
                xy = b["xy"]; h = b["h"]
                cx = sum(x for x, _ in xy) / len(xy); cy = sum(y for _, y in xy) / len(xy)
                ix = int(np.clip(np.searchsorted(xs, cx), 0, n - 1))
                iy = int(np.clip(np.argmin(np.abs(ys - cy)), 0, n - 1))
                z0 = float(Z[iy, ix])                       # real ground elevation at this building
                col = cmap(min(1.0, h / (hmax + 1e-6)))
                faces.append([(x, y, (z0 + h) * ve) for (x, y) in xy]); colors.append(col)
                for i in range(len(xy) - 1):
                    x0, y0 = xy[i]; x1, y1 = xy[i + 1]
                    faces.append([(x0, y0, z0 * ve), (x1, y1, z0 * ve),
                                  (x1, y1, (z0 + h) * ve), (x0, y0, (z0 + h) * ve)])
                    colors.append(col)
            try:
                ax.add_collection3d(Poly3DCollection(faces, facecolors=colors,
                                                     edgecolors=(0, 0, 0, 0.12), linewidths=0.15))
                nb = min(len(blds), 300)
            except Exception:
                pass
        # node pin at its real position (grid centre) sitting on the terrain
        zc = float(Z[n // 2, n // 2])
        ax.scatter([0], [0], [(zc + 8) * ve], c='#ff2255', s=70, marker='v',
                   edgecolors='white', zorder=20)
        ax.set_xlim(xs.min(), xs.max()); ax.set_ylim(ys.min(), ys.max())
        ax.set_zlim(float(np.min(Z)) * ve, (float(np.max(Z)) + 40) * ve)
        try:
            ax.view_init(elev=28, azim=(time.time() * 5.0) % 360.0)
        except Exception:
            pass
        ax.set_xlabel("E–W (m)", color='#789', fontsize=7)
        ax.set_ylabel("N–S (m)", color='#789', fontsize=7)
        ax.tick_params(colors='#445', labelsize=6)
        ax.set_title(f"REAL DEM {n}×{n} (relief {emeta.get('relief',0):.0f} m) + {nb} REAL buildings "
                     f"on terrain + node · vert ×{ve:.0f}", color='#88ccaa', fontsize=8.5)
        fig.text(0.5, 0.02, "UNIFIED real-data world: measured DEM terrain (open-meteo/SRTM) + satellite drape "
                 "(ESRI) + surveyed OSM buildings at their real ground elevation + node at real location.  "
                 "All vertical dims ×%.0f (consistent), horizontal = true metres.  Nothing fabricated." % ve,
                 ha='center', color='#6a8', fontsize=7.0)

    def _draw_city3d(self, fig, p, snap):
        """v99: 3D CITY — REAL OpenStreetMap building footprints extruded to their real heights
        (OSM height/levels tags; default-extruded where untagged, flagged). Thousands of real
        surveyed structures, navigable (auto-orbit). The honest 'map buildings to extreme
        detail / multitudes of thousands' — real geometry, no invented buildings."""
        from mpl_toolkits.mplot3d.art3d import Poly3DCollection
        pm = getattr(self.fuser, "planet_map", None)
        fig.suptitle("3D CITY — REAL OpenStreetMap buildings, extruded to real heights",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        if pm is None:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "PlanetMapEngine not initialised.", ha='center', va='center',
                    color='#ff8866', fontsize=12, transform=ax.transAxes)
            return
        with pm._lock:
            blds = None if pm.buildings is None else list(pm.buildings)
            bmeta = dict(pm.buildings_meta)
            fetching = pm._bld_fetching
        if blds is None:
            if not fetching:
                pm.fetch_buildings_async(n_max=400)
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "Fetching REAL OSM building footprints (Overpass)…\n"
                    "(hundreds–thousands of real surveyed structures)", ha='center', va='center',
                    color='#88ccff', fontsize=12, transform=ax.transAxes)
            return
        ax = fig.add_subplot(111, projection='3d'); ax.set_facecolor('#05080d')
        faces = []; colors = []
        hmax = max((b["h"] for b in blds), default=10.0)
        cmap = plt.get_cmap('plasma')
        for b in blds:
            xy = b["xy"]; h = b["h"]; col = cmap(min(1.0, h / (hmax + 1e-6)))
            roof = [(x, y, h) for (x, y) in xy]
            faces.append(roof); colors.append(col)
            for i in range(len(xy) - 1):
                x0, y0 = xy[i]; x1, y1 = xy[i + 1]
                faces.append([(x0, y0, 0.0), (x1, y1, 0.0), (x1, y1, h), (x0, y0, h)])
                colors.append(col)
        try:
            pc = Poly3DCollection(faces, facecolors=colors, edgecolors=(0, 0, 0, 0.15), linewidths=0.2)
            ax.add_collection3d(pc)
        except Exception as _e:
            ax.text2D(0.5, 0.5, f"city render error: {_e}", transform=ax.transAxes,
                      ha='center', color='#ff5555')
        allx = [x for b in blds for x, _ in b["xy"]]
        ally = [y for b in blds for _, y in b["xy"]]
        if allx and ally:
            ax.set_xlim(min(allx), max(allx)); ax.set_ylim(min(ally), max(ally))
            ax.set_zlim(0, hmax * 1.3)
        try:
            ax.view_init(elev=34, azim=(time.time() * 6.0) % 360.0)
        except Exception:
            pass
        ax.set_xlabel("E–W (m)", color='#789', fontsize=7)
        ax.set_ylabel("N–S (m)", color='#789', fontsize=7)
        ax.set_zlabel("height (m)", color='#789', fontsize=7)
        ax.tick_params(colors='#445', labelsize=6)
        ax.set_title(f"{bmeta.get('n',0)} REAL buildings · {bmeta.get('tagged',0)} with OSM "
                     f"height/levels tags · tallest {hmax:.0f} m", color='#88ccaa', fontsize=8.5)
        fig.text(0.5, 0.02, "REAL surveyed building footprints © OpenStreetMap contributors.  Heights from "
                 "OSM height/levels tags where present; untagged buildings default-extruded to ~6 m (2 storeys) "
                 "— flagged, not measured.  Horizontal geometry is true metres.", ha='center',
                 color='#6a8', fontsize=7.0)

    def _draw_terrain3d(self, fig, p, snap):
        """v98: 3D TERRAIN RECONSTRUCTION — a real Digital Elevation Model (measured DEM)
        rendered as a navigable 3D surface and draped with the real satellite imagery. The
        honest 'reconstructed representation at extreme detail': every vertex height is a real
        elevation measurement, every texel a real satellite pixel. Auto-rotates; nothing faked."""
        import math
        pm = getattr(self.fuser, "planet_map", None)
        fig.suptitle("3D TERRAIN — REAL elevation (DEM) draped with REAL satellite imagery",
                     color='#00ffcc', fontsize=13, fontweight='bold')
        if pm is None:
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "PlanetMapEngine not initialised.", ha='center', va='center',
                    color='#ff8866', fontsize=12, transform=ax.transAxes)
            return
        with pm._lock:
            grid = None if pm.elev_grid is None else np.array(pm.elev_grid)
            emeta = dict(pm.elev_meta)
            mimg = None if pm.map_img is None else np.array(pm.map_img)
            fetching = pm._elev_fetching
        if grid is None:
            if not fetching:
                pm.fetch_elevation_grid_async(n=24)
            ax = fig.add_subplot(111); ax.axis('off')
            ax.text(0.5, 0.5, "Fetching real elevation (DEM) grid + satellite drape…\n"
                    "(24×24 real topography samples)", ha='center', va='center',
                    color='#88ccff', fontsize=12, transform=ax.transAxes)
            return
        n = grid.shape[0]
        lat_n, lat_s, lon_w, lon_e = emeta["bounds"]
        lat0 = emeta["lat"]; lon0 = emeta["lon"]
        mx = 111320.0 * math.cos(math.radians(lat0))
        xs = (np.linspace(lon_w, lon_e, n) - lon0) * mx
        ys = (np.linspace(lat_n, lat_s, n) - lat0) * 110540.0
        X, Y = np.meshgrid(xs, ys)
        Z = np.nan_to_num(grid, nan=float(emeta.get("min", 0.0)))
        # drape: resample the real satellite image to the DEM grid as per-vertex colours
        fac = None
        if mimg is not None and mimg.ndim == 3:
            H, W = mimg.shape[:2]
            yi = np.clip(np.linspace(0, H - 1, n).astype(int), 0, H - 1)
            xi = np.clip(np.linspace(0, W - 1, n).astype(int), 0, W - 1)
            fac = np.clip(mimg[np.ix_(yi, xi)][..., :3], 0, 1)
        ve = 4.0  # vertical exaggeration (terrain relief is small vs map span) — labelled below
        ax = fig.add_subplot(111, projection='3d'); ax.set_facecolor('#04121a')
        try:
            if fac is not None:
                ax.plot_surface(X, Y, Z * ve, facecolors=fac, rstride=1, cstride=1,
                                linewidth=0, antialiased=True, shade=False)
            else:
                ax.plot_surface(X, Y, Z * ve, cmap='terrain', rstride=1, cstride=1,
                                linewidth=0, antialiased=True)
        except Exception as _e:
            ax.text2D(0.5, 0.5, f"surface render error: {_e}", transform=ax.transAxes,
                      ha='center', color='#ff5555')
        # slow auto-orbit so the reconstruction reads as 3D
        try:
            az = (time.time() * 8.0) % 360.0
            ax.view_init(elev=38, azim=az)
        except Exception:
            pass
        ax.set_xlabel("E–W (m)", color='#789', fontsize=7)
        ax.set_ylabel("N–S (m)", color='#789', fontsize=7)
        ax.set_zlabel("elev ×%.0f (m)" % ve, color='#789', fontsize=7)
        ax.tick_params(colors='#445', labelsize=6)
        ax.set_title(f"REAL DEM {n}×{n} · relief {emeta.get('relief',0):.0f} m "
                     f"({emeta.get('min',0):.0f}–{emeta.get('max',0):.0f} m) · "
                     f"satellite-draped · vert ×{ve:.0f}", color='#88ccaa', fontsize=8.5)
        fig.text(0.5, 0.02, "REAL measured topography (open-meteo / SRTM DEM) draped with REAL satellite "
                 "imagery (ESRI).  Vertical scale exaggerated ×%.0f for visibility — horizontal scale is "
                 "true metres.  No fabricated geometry." % ve, ha='center', color='#6a8', fontsize=7.2)

