# v104: copy-paste sender any phone(Termux)/laptop/SBC runs to contribute its OWN real WiFi
# scan to a N.E.P.A. host — turning every device into a real data sender (no fabricated nodes).
_REMOTE_SENDER_SNIPPET = (
    "<!DOCTYPE html><html><head><meta charset='utf-8'><title>N.E.P.A. Sensor Node</title>"
    "<style>body{background:#050505;color:#00ffcc;font-family:monospace;padding:14px}"
    "pre{background:#0a1014;border:1px solid #0aa5;padding:10px;white-space:pre-wrap}</style></head><body>"
    "<h2>N.E.P.A. multi-node REAL-DATA ingest</h2>"
    "<p>Run this on ANY device (phone/Termux, laptop, Raspberry Pi, router) to become a real sensor node.</p>"
    "<p><b>Option A (ingest server, port 8770):</b> POST /ingest with JSON emitters list</p>"
    "<p><b>Option B (web server, port 8765):</b> POST /api/scan — same format, also GET /api/state + /api/world for phone apps</p>"
    "<pre>"
    "import urllib.request, json, subprocess, socket, time\n"
    "HOST = 'http://HOST_IP:8765/api/scan'  # web viewer port (or :8770/ingest)\n"
    "def scan():\n"
    "    try:\n"
    "        out = subprocess.run(['nmcli','-t','-f','BSSID,SSID,FREQ,SIGNAL','dev','wifi','list'],\n"
    "                             capture_output=True, text=True, timeout=8).stdout\n"
    "    except Exception:\n"
    "        return []\n"
    "    ems = []\n"
    "    for ln in out.splitlines():\n"
    "        f = ln.replace('\\\\:','%').split(':')\n"
    "        if len(f) < 4: continue\n"
    "        try:\n"
    "            ems.append({'bssid':f[0].replace('%',':'),'ssid':f[1],\n"
    "                        'freq_mhz':float(f[2].split()[0]) if f[2] else 0.0,\n"
    "                        'rssi_dbm':-100.0+float(f[3])*0.5 if f[3] else -100.0})\n"
    "        except Exception: pass\n"
    "    return ems\n"
    "while True:\n"
    "    # /api/scan uses 'ssids' key; /ingest uses 'emitters' — both accepted\n"
    "    scans = scan()\n"
    "    rep = {'node_id':socket.gethostname(),'kind':'phone',\n"
    "           'ssids':scans,'emitters':scans,'ts':time.time()}\n"
    "    try:\n"
    "        urllib.request.urlopen(urllib.request.Request(HOST, data=json.dumps(rep).encode(),\n"
    "            headers={'Content-Type':'application/json'}), timeout=5)\n"
    "        print('sent', len(scans), 'APs')\n"
    "    except Exception as e: print('send failed', e)\n"
    "    time.sleep(5)\n"
    "</pre>"
    "<p>Phone/app GET endpoints: "
    "<a href='/api/state' style='color:#0fc'>/api/state</a> · "
    "<a href='/api/world' style='color:#0fc'>/api/world</a></p>"
    "<p>Connected nodes: <a href='/nodes' style='color:#0fc'>/nodes (ingest server)</a></p>"
    "</body></html>"
)


class RemoteSensorIngestServer:
    """v104: MULTI-NODE REAL-DATA INGEST — the honest 'millions of routers/devices connected as
    data senders'. Any remote device that can HTTP POST becomes a real sensor node: it sends its
    OWN real receiver readings (WiFi scan RSSI, GNSS, etc.) to /ingest and N.E.P.A. fuses them
    into the live multi-instrument world. Every node contributes ONLY its own real measurements;
    a node registers only when it actually sends. No fabricated nodes, no synthetic data.
    GET / serves a copy-paste sender; GET /nodes lists every connected real node."""

    def __init__(self, fuser, port: int = 8770):
        self.fuser = fuser
        self.port = port
        self._server = None; self._thread = None; self._running = False
        if not hasattr(fuser, "remote_nodes"):
            fuser.remote_nodes = {}

    def _ingest(self, report: dict) -> dict:
        import time as _t
        nid = str(report.get("node_id", "anon"))[:48]
        nodes = self.fuser.remote_nodes
        rec = nodes.get(nid, {"first_seen": _t.time(), "count": 0, "chist": {}})
        ems = report.get("emitters", []) or []
        # v106: accumulate per-carrier RSSI HISTORY across this node's repeated reports, so each
        # remote device becomes a real device-free SENSOR (its carriers' RSSI variance → motion),
        # not just a snapshot list. Real time-series only — capped, no fabricated samples.
        chist = rec.get("chist", {})
        for e in ems:
            b = str(e.get("bssid", "?"))
            h = chist.setdefault(b, [])
            try:
                h.append(float(e.get("rssi_dbm", -100.0)))
            except Exception:
                continue
            if len(h) > 120:
                del h[:-120]
        # forget carriers a node stops reporting (bounded memory for many nodes)
        if len(chist) > 256:
            for b in list(chist.keys())[:-256]:
                del chist[b]
        rec["chist"] = chist
        rec.update({"last_seen": _t.time(), "count": rec.get("count", 0) + 1,
                    "lat": report.get("lat"), "lon": report.get("lon"),
                    "kind": str(report.get("kind", "generic"))[:24],
                    "emitter_count": len(ems), "emitters": ems[:128],
                    "rssi_dbm": report.get("rssi_dbm")})
        nodes[nid] = rec
        return {"ok": True, "node_id": nid, "nodes_connected": len(nodes),
                "total_emitters": sum(int(v.get("emitter_count", 0)) for v in nodes.values())}

    def _make_handler(self):
        srv = self

        class _H(_http_server.BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def do_POST(self):
                if self.path.split("?")[0] != "/ingest":
                    self._send(404, "text/plain", b"not found"); return
                try:
                    import json as _j
                    n = int(self.headers.get("Content-Length", 0) or 0)
                    body = self.rfile.read(n) if n > 0 else b"{}"
                    out = srv._ingest(_j.loads(body.decode("utf-8", "ignore")))
                    self._send(200, "application/json", _j.dumps(out).encode())
                except Exception as e:
                    self._send(400, "application/json",
                               ('{"ok":false,"err":"%s"}' % type(e).__name__).encode())

            def do_GET(self):
                import json as _j
                p = self.path.split("?")[0]
                if p in ("/", "/index.html"):
                    self._send(200, "text/html; charset=utf-8", _REMOTE_SENDER_SNIPPET.encode())
                elif p == "/nodes":
                    nodes = srv.fuser.remote_nodes
                    out = {"count": len(nodes),
                           "nodes": {k: {kk: vv for kk, vv in v.items() if kk != "emitters"}
                                     for k, v in nodes.items()}}
                    self._send(200, "application/json", _j.dumps(out).encode())
                else:
                    self._send(404, "text/plain", b"not found")

            def _send(self, code, ctype, body):
                self.send_response(code); self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Access-Control-Allow-Origin", "*"); self.end_headers()
                self.wfile.write(body)

        return _H

    def start(self):
        if self._running:
            return
        try:
            self._server = _http_server.HTTPServer(("", self.port), self._make_handler())
            self._running = True
            self._thread = threading.Thread(target=self._server.serve_forever,
                                            daemon=True, name="IngestServer")
            self._thread.start()
            log.info(f"[Ingest] Multi-node REAL-DATA ingest at http://0.0.0.0:{self.port}/  "
                     f"(POST /ingest · sender snippet at GET /  · nodes at /nodes)")
        except Exception as e:
            log.warning(f"[Ingest] start failed: {e}")

    def stop(self):
        self._running = False
        try:
            self._server.shutdown()
        except Exception:
            pass


class WebViewerServer:
    """Pass 34: Serve the live Gaussian-splat world render as an MJPEG stream.

    Endpoints:
      GET /          — minimal HTML viewer shell (auto-refreshes splat every 200 ms)
      GET /stream    — MJPEG multipart stream (~10 fps)
      GET /frame.jpg — single JPEG snapshot of latest splat frame
      GET /status    — JSON status blob
      GET /semantic  — JSON semantic state summary

    Usage:
      server = WebViewerServer(fuser, port=8765)
      server.start()   # non-blocking daemon thread
      server.stop()
    """

    def __init__(self, fuser, port: int = 8765, width: int = 320, height: int = 240,
                 fov: float = 65.0):
        self.fuser    = fuser
        self.port     = port
        self.width    = width
        self.height   = height
        self.fov      = fov
        self._thread  = None
        self._server  = None
        self._running = False
        self._tab_lock = threading.Lock()   # v103: serialise headless tab renders (mpl not thread-safe)

    # ── frame rendering ───────────────────────────────────────────────────────
    # v103: render ANY DetailTabWindow tab headlessly to PNG so the full real UI is browsable
    # without a matplotlib display backend (the NixOS 'I don't see it' fix, completed).
    _WEB_TABS = ("geo3d", "terrain3d", "city3d", "planetmap", "entities", "carrier",
                 "instrbus", "rfmap", "medical", "bci", "remote", "netspectrum", "raw",
                 "globalview", "multispec", "tomoview", "rfsplat", "scanner",
                 "rangedoppler", "worldfeed", "acoustic", "bleview",
                 "radar", "scene3d", "tomography", "planetview",
                 "liveworld", "sigint", "pointcloud3d", "multispectral")

    def _render_tab_png(self, kind: str) -> bytes:
        import io as _io2
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_agg import FigureCanvasAgg
        if kind not in self._WEB_TABS:
            kind = "geo3d"
        try:
            with self._tab_lock:
                fig = Figure(figsize=(11, 8)); fig.patch.set_facecolor('#050505')
                FigureCanvasAgg(fig)
                tab = DetailTabWindow(self.fuser, kind=kind)
                p = getattr(self.fuser, "psych_profile", {})
                snap = getattr(self.fuser, "_world_snapshot", {}) or {}
                getattr(tab, f"_draw_{kind}")(fig, p, snap)
                buf = _io2.BytesIO()
                fig.savefig(buf, format="png", facecolor=fig.get_facecolor(), dpi=88)
                return buf.getvalue()
        except Exception as e:
            log.debug(f"[WebViewer] tab render {kind}: {e}")
            return b""
    def _render_frame_jpeg(self) -> bytes:
        wr = getattr(self.fuser, "world_recon", None)
        if wr is None:
            return self._placeholder_jpeg()
        try:
            import time as _t
            t   = (_t.time() * 0.15) % (2 * 3.14159)
            res = float(getattr(wr, "voxel_res", 24))
            ctr = np.array([res / 2, res / 2, res / 2])
            cam = ctr + np.array([np.cos(t) * res * 1.2,
                                  np.sin(t) * res * 1.2,
                                  res * 0.35])
            img  = wr.render_splats(cam, ctr, width=self.width,
                                    height=self.height, fov=self.fov)
            img8 = (np.clip(img, 0.0, 1.0) * 255).astype(np.uint8)
            if _PIL_Image is not None:
                pil = _PIL_Image.fromarray(img8)
                buf = _io.BytesIO()
                pil.save(buf, format="JPEG", quality=75)
                return buf.getvalue()
            # Pillow absent: serve a PPM stream (browsers won't render it, but /stream works)
            h, w = img8.shape[:2]
            return (f"P6\n{w} {h}\n255\n").encode() + img8.tobytes()
        except Exception as e:
            log.debug(f"[WebViewer] render error: {e}")
            return self._placeholder_jpeg()

    @staticmethod
    def _placeholder_jpeg() -> bytes:
        if _PIL_Image is not None:
            buf = _io.BytesIO()
            _PIL_Image.new("RGB", (4, 4), (5, 5, 5)).save(buf, format="JPEG")
            return buf.getvalue()
        return b""

    def _render_planet_png(self) -> bytes:
        """v102: serve the REAL satellite/OSM map of the node's location as a browser image —
        so the user can SEE real data even when no matplotlib display backend is available.
        Node marker drawn at the real location; pixels are real cartography. Encoded with
        matplotlib (PNG) so no Pillow dependency is required."""
        pm = getattr(self.fuser, "planet_map", None)
        if pm is None:
            return b""
        with pm._lock:
            img = None if pm.map_img is None else np.array(pm.map_img)
            meta = dict(pm.map_meta)
        if img is None:
            try:
                pm.build_map_async()
            except Exception:
                pass
            img = np.zeros((180, 320, 3), np.float32)     # dark placeholder while fetching
        else:
            try:
                h, w = img.shape[:2]
                px = pm.latlon_to_px(meta.get("lat", 0), meta.get("lon", 0)) or (w / 2, h / 2)
                ix, iy = int(np.clip(px[0], 0, w - 1)), int(np.clip(px[1], 0, h - 1))
                img = img.copy()
                rr = 7
                img[max(0, iy - rr):iy + rr, max(0, ix - 1):ix + 2] = [1.0, 0.1, 0.25]
                img[max(0, iy - 1):iy + 2, max(0, ix - rr):ix + rr] = [1.0, 0.1, 0.25]
            except Exception:
                pass
        try:
            import matplotlib.image as mpimg
            buf = _io.BytesIO()
            mpimg.imsave(buf, np.clip(img, 0, 1), format="png")
            return buf.getvalue()
        except Exception:
            return b""

    # ── HTTP handler factory ──────────────────────────────────────────────────
    def _make_handler(self):
        srv = self

        class _H(_http_server.BaseHTTPRequestHandler):
            def log_message(self, fmt, *args):
                pass

            def do_GET(self):
                p = self.path.split("?")[0]
                if p in ("/", "/index.html"):
                    body = _WEB_HTML.encode()
                    self._send(200, "text/html; charset=utf-8", body)
                elif p == "/frame.jpg":
                    self._send(200, "image/jpeg", srv._render_frame_jpeg())
                elif p == "/planet.png":
                    self._send(200, "image/png", srv._render_planet_png())
                elif p == "/tab.png":
                    from urllib.parse import parse_qs, urlparse
                    kind = parse_qs(urlparse(self.path).query).get("kind", ["geo3d"])[0]
                    self._send(200, "image/png", srv._render_tab_png(kind))
                elif p == "/stream":
                    self._mjpeg(srv)
                elif p == "/status":
                    import json as _j
                    pp = getattr(srv.fuser, "psych_profile", {})
                    pm = getattr(srv.fuser, "planet_map", None)
                    _pmst = pm.status() if pm is not None else {}
                    d = {
                        "person_count":   int(pp.get("person_count", 0)),
                        "threat":         float(pp.get("threat_score", 0.0)),
                        "overseer_state": str(pp.get("overseer_state", "DORMANT")),
                        "splat_count":    int(pp.get("recon_splat_count", 0)),
                        "bci_intent":     str(pp.get("bci_motor_intent", "REST")),
                        "semantic_state": str(pp.get("semantic_state", "ROOM_EMPTY")),
                        # v102: real node location + live device-free sensing for the browser view
                        "city":     str(_pmst.get("city", "?")),
                        "lat":      round(float(_pmst.get("lat") or 0.0), 4),
                        "lon":      round(float(_pmst.get("lon") or 0.0), 4),
                        "carriers": int(pp.get("combined_carrier_count",
                                               len(pp.get("rf_link_entities", []) or []))),
                        "local_carriers":  int(pp.get("local_carrier_count", 0)),
                        "remote_carriers": int(pp.get("remote_carrier_count", 0)),
                        "remote_nodes":    int(pp.get("remote_node_count", 0)),
                        "network_movers":  int(pp.get("network_movers", 0)),
                        "presence": ("Y" if pp.get("rssi_presence") else "n"),
                        "motion":   float(pp.get("rssi_motion", 0.0)),
                    }
                    self._send(200, "application/json", _j.dumps(d).encode())
                elif p == "/semantic":
                    import json as _j
                    sem = getattr(srv.fuser, "semantic_engine", None)
                    d = ({"state": sem.state,
                          "frames_in_state": sem.frames_in_state(),
                          "all_rooms":  sem.all_rooms,
                          "history":    sem.state_history(10)}
                         if sem else {"state": "N/A", "frames_in_state": 0})
                    self._send(200, "application/json", _j.dumps(d).encode())
                elif p == "/api/state":
                    # v118 T-PHONE: lightweight JSON state for mobile companion apps
                    import json as _j
                    pp = getattr(srv.fuser, "psych_profile", {})
                    pm = getattr(srv.fuser, "planet_map", None)
                    _pmst = pm.status() if pm is not None else {}
                    self._send(200, "application/json", _j.dumps({
                        "presence":        bool(pp.get("rssi_presence", False)),
                        "motion":          round(float(pp.get("rssi_motion", 0.0)), 3),
                        "person_count":    int(pp.get("person_count", 0)),
                        "semantic_state":  str(pp.get("semantic_state", "ROOM_EMPTY")),
                        "carriers":        int(pp.get("combined_carrier_count", 0)),
                        "remote_nodes":    int(pp.get("remote_node_count", 0)),
                        "movers":          int(pp.get("network_movers", 0)),
                        "cog_occupied":    int(pp.get("cog_spec_occupied", 0)),
                        "cog_bands":       int(pp.get("cog_spec_bands", 0)),
                        "lan_pkt_s":       round(float(pp.get("lan_total_pkt_s", 0.0)), 1),
                        "lat":             round(float(_pmst.get("lat") or 0.0), 5),
                        "lon":             round(float(_pmst.get("lon") or 0.0), 5),
                        "city":            str(_pmst.get("city", "?")),
                    }).encode())
                elif p == "/api/world":
                    # v118 T-PHONE: full carrier list for planet-map phone overlay
                    import json as _j
                    pp = getattr(srv.fuser, "psych_profile", {})
                    ents = pp.get("rf_link_entities", []) or []
                    self._send(200, "application/json", _j.dumps({
                        "carriers": [
                            {"id": e.get("id","?"), "bssid": e.get("bssid","?"),
                             "rssi_dbm": e.get("rssi_dbm",-100.0),
                             "range_m": e.get("range_m", None),
                             "freq_mhz": e.get("freq_mhz", 0.0),
                             "band": e.get("band","?"),
                             "motion": e.get("link_motion", 0.0),
                             "source": e.get("source","wifi"),
                             "kind": e.get("kind","AP")}
                            for e in ents[:128]
                        ],
                        "movers":       int(pp.get("network_movers", 0)),
                        "remote_nodes": int(pp.get("remote_node_count", 0)),
                        "cog_occupied": int(pp.get("cog_spec_occupied", 0)),
                    }).encode())
                else:
                    self._send(404, "text/plain", b"not found")

            def do_POST(self):
                # v118 T-PHONE: POST /api/scan — phones/computers POST real WiFi + BLE scans
                # and join the distributed sensor mesh, contributing real RF data exactly like
                # RemoteSensorIngestServer nodes. No fabricated data — device registers only when
                # it actually sends a real scan.
                p = self.path.split("?")[0]
                if p != "/api/scan":
                    self._send(404, "text/plain", b"not found"); return
                try:
                    import json as _j, time as _pt
                    n = int(self.headers.get("Content-Length", 0) or 0)
                    body = self.rfile.read(n) if n > 0 else b"{}"
                    data = _j.loads(body.decode("utf-8", "ignore"))
                    node_id = str(data.get("node_id", "phone"))[:48]
                    kind = str(data.get("kind", "phone"))[:24]
                    ssids = data.get("ssids", []) or []
                    ble   = data.get("ble",   []) or []
                    rn = getattr(srv.fuser, "remote_nodes", None)
                    if rn is None:
                        srv.fuser.remote_nodes = {}; rn = srv.fuser.remote_nodes
                    rec = rn.get(node_id, {"first_seen": _pt.time(), "count": 0,
                                           "chist": {}, "kind": kind, "emitters": []})
                    # Build unified emitter list (WiFi APs + BLE devices)
                    emitters = [
                        {"ssid": s.get("ssid","?"), "bssid": s.get("bssid","?"),
                         "rssi_dbm": float(s.get("rssi_dbm",-100.0)),
                         "freq_mhz": float(s.get("freq_mhz", 2437.0)),
                         "signal": float(s.get("rssi_dbm",-100.0))}
                        for s in ssids
                    ] + [
                        {"ssid": b.get("name", b.get("mac","BLE")),
                         "bssid": b.get("mac","?"),
                         "rssi_dbm": float(b.get("rssi_dbm",-90.0)),
                         "freq_mhz": 2441.0,
                         "signal": float(b.get("rssi_dbm",-90.0))}
                        for b in ble
                    ]
                    # Accumulate RSSI history per carrier for device-free correlation
                    chist = rec.get("chist", {})
                    for em in emitters:
                        bid = em.get("bssid","?")
                        ch = chist.setdefault(bid, [])
                        ch.append(em["rssi_dbm"])
                        if len(ch) > 120: del ch[:-120]
                    if len(chist) > 256:
                        for b in list(chist.keys())[:-256]: del chist[b]
                    rec.update({"last_seen": _pt.time(), "kind": kind,
                                "count": rec.get("count",0) + 1,
                                "emitter_count": len(emitters),
                                "emitters": emitters[:128],
                                "chist": chist,
                                "lat": data.get("lat"), "lon": data.get("lon")})
                    rn[node_id] = rec
                    self._send(200, "application/json", _j.dumps({
                        "ok": True, "node_id": node_id,
                        "nodes": len(rn),
                        "emitters_accepted": len(emitters),
                    }).encode())
                except Exception as e:
                    self._send(400, "application/json",
                               f'{{"ok":false,"error":"{type(e).__name__}"}}'.encode())

            def _send(self, code, ctype, body):
                self.send_response(code)
                self.send_header("Content-Type", ctype)
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Access-Control-Allow-Origin", "*")
                self.end_headers()
                self.wfile.write(body)

            def _mjpeg(self, srv):
                import time as _t
                self.send_response(200)
                self.send_header("Content-Type",
                                 "multipart/x-mixed-replace; boundary=nepaframe")
                self.end_headers()
                try:
                    while srv._running:
                        data = srv._render_frame_jpeg()
                        hdr  = (b"--nepaframe\r\nContent-Type: image/jpeg\r\n"
                                b"Content-Length: " + str(len(data)).encode()
                                + b"\r\n\r\n")
                        self.wfile.write(hdr + data + b"\r\n")
                        self.wfile.flush()
                        _t.sleep(0.10)
                except Exception:
                    pass

        return _H

    # ── lifecycle ─────────────────────────────────────────────────────────────
    def start(self):
        if self._running:
            return
        try:
            self._server  = _http_server.HTTPServer(("", self.port),
                                                     self._make_handler())
            self._running = True
            self._thread  = threading.Thread(target=self._server.serve_forever,
                                             daemon=True, name="WebViewerServer")
            self._thread.start()
            log.info(f"[WebViewer] Serving at http://0.0.0.0:{self.port}/  "
                     f"(stream: /stream  snap: /frame.jpg)")
        except OSError as e:
            log.warning(f"[WebViewer] Could not start HTTP server on port {self.port}: {e}")
            self._running = False

    def stop(self):
        self._running = False
        if self._server:
            self._server.shutdown()


# ════════════════════════════════════════════════════════════════════════════════
# Pass 35 (T-MVS): EspectreMVSDetector — Moving-Variance Segmentation motion detector
# Studies Examplecode2/espectre micro-espectre/src/mvs_detector.py + filters.py + segmentation.py
# Reimplemented inline: Hampel outlier filter + LPF + circular-buffer turbulence variance.
# ════════════════════════════════════════════════════════════════════════════════

class _HampelFilter:
    """Sliding-window Hampel outlier filter (from espectre filters.py, reimplemented inline).
    Replaces outliers >threshold*MAD with the window median — preserves signal shape."""
    def __init__(self, window_size: int = 7, threshold: float = 5.0):
        self._ws  = window_size
        self._thr = threshold * 1.4826   # pre-scale for MAD→σ
        self._buf = [0.0] * window_size
        self._cnt = 0
        self._idx = 0

    def filter(self, value: float) -> float:
        self._buf[self._idx] = value
        self._idx = (self._idx + 1) % self._ws
        self._cnt = min(self._cnt + 1, self._ws)
        n = self._cnt
        if n < 3:
            return value
        # sorted copy for median + MAD
        s = sorted(self._buf[:n])
        mid = n >> 1
        median = s[mid]
        devs = sorted(abs(v - median) for v in self._buf[:n])
        mad   = devs[mid]
        if mad > 1e-6:
            if abs(value - median) / mad > self._thr:
                return median
        return value

    def reset(self):
        self._cnt = self._idx = 0


class _LowPassFilter:
    """1st-order IIR Butterworth LPF (from espectre filters.py, reimplemented inline)."""
    def __init__(self, cutoff_hz: float = 11.0, sample_rate_hz: float = 100.0):
        import math as _m
        wc = _m.tan(_m.pi * cutoff_hz / sample_rate_hz)
        k  = 1.0 + wc
        self._b0 = wc / k
        self._a1 = (wc - 1.0) / k
        self._xp = self._yp = 0.0
        self._init = False

    def filter(self, v: float) -> float:
        if not self._init:
            self._xp = self._yp = v
            self._init = True
            return v
        y = self._b0 * v + self._b0 * self._xp - self._a1 * self._yp
        self._xp, self._yp = v, y
        return y

    def reset(self):
        self._xp = self._yp = 0.0
        self._init = False


class EspectreMVSDetector:
    """Pass 35: Moving-Variance Segmentation (MVS) motion detector.
    Reimplemented from Examplecode2/espectre micro-espectre/src/segmentation.py + mvs_detector.py.

    Algorithm (matches C++ DETECTOR_DEFAULT_WINDOW_SIZE semantics):
      1. Per-packet: compute spatial turbulence = std(abs(CSI subcarriers)).
      2. Optionally apply Hampel outlier filter + 1st-order IIR LPF.
      3. Store turbulence values in a circular buffer (window_size samples).
      4. Compute moving variance of the buffer (two-pass Welford for stability).
      5. Compare to threshold → MOTION / IDLE state.

    Returns real motion confidence in [0, 1] from the normalised variance.
    """

    MOTION = "MOTION"
    IDLE   = "IDLE"

    def __init__(self, window_size: int = 100, threshold: float = 1.0,
                 enable_hampel: bool = True, enable_lpf: bool = False,
                 lpf_cutoff_hz: float = 11.0):
        self._ws        = window_size
        self.threshold  = threshold
        self._buf       = [0.0] * window_size
        self._bidx      = 0
        self._bcnt      = 0
        self._state     = self.IDLE
        self.moving_var = 0.0
        self.last_turb  = 0.0
        self._hampel    = _HampelFilter(window_size=7, threshold=5.0) if enable_hampel else None
        self._lpf       = _LowPassFilter(cutoff_hz=lpf_cutoff_hz) if enable_lpf else None
        self._pkt_count = 0
        self._motion_count = 0
        log.info(f"[MVS] EspectreMVSDetector init — window={window_size} thr={threshold:.2f} "
                 f"hampel={enable_hampel} lpf={enable_lpf}")

    # ── turbulence from a raw CSI vector ─────────────────────────────────────
    @staticmethod
    def _spatial_turbulence(csi: np.ndarray) -> float:
        """std of subcarrier amplitudes = spatial turbulence proxy."""
        amps = np.abs(csi).astype(np.float32)
        if len(amps) == 0:
            return 0.0
        return float(np.std(amps))

    # ── two-pass variance (numerically stable, from espectre segmentation.py) ─
    @staticmethod
    def _two_pass_variance(buf: list, n: int) -> float:
        if n < 2:
            return 0.0
        mean = sum(buf[:n]) / n
        return sum((x - mean) ** 2 for x in buf[:n]) / n

    # ── process one CSI frame ─────────────────────────────────────────────────
    def process(self, csi: np.ndarray) -> dict:
        """Process one CSI frame.  Returns a dict with state/confidence/variance."""
        self._pkt_count += 1
        turb = self._spatial_turbulence(csi)
        if self._hampel:
            turb = self._hampel.filter(turb)
        if self._lpf:
            turb = self._lpf.filter(turb)
        self.last_turb = turb

        # Add to circular buffer
        self._buf[self._bidx] = turb
        self._bidx = (self._bidx + 1) % self._ws
        self._bcnt = min(self._bcnt + 1, self._ws)

        # Compute moving variance
        self.moving_var = self._two_pass_variance(self._buf, self._bcnt)

        # State decision
        prev = self._state
        if self._bcnt >= self._ws:
            self._state = self.MOTION if self.moving_var >= self.threshold else self.IDLE
        if self._state == self.MOTION and prev != self.MOTION:
            self._motion_count += 1

        # Normalised confidence: 0–1 relative to threshold
        conf = float(np.clip(self.moving_var / (self.threshold + 1e-9), 0.0, 2.0) / 2.0)
        return {
            "state":      self._state,
            "confidence": conf,
            "variance":   self.moving_var,
            "turbulence": turb,
            "ready":      self._bcnt >= self._ws,
        }

    def reset(self):
        self._buf    = [0.0] * self._ws
        self._bidx   = self._bcnt = 0
        self.moving_var = self.last_turb = 0.0
        self._state  = self.IDLE
        if self._hampel:  self._hampel.reset()
        if self._lpf:     self._lpf.reset()

    @property
    def is_motion(self) -> bool:
        return self._state == self.MOTION

    def summary_line(self) -> str:
        return (f"MVS state={self._state:<6}  var={self.moving_var:.4f}  "
                f"thr={self.threshold:.2f}  pkts={self._pkt_count}  "
                f"events={self._motion_count}")


# ════════════════════════════════════════════════════════════════════════════════
# Pass 35 (T-SPEC): CyclostationaryDetector + EnergyDetector (cognitive radio sensing)
# Studies Crucialcode4/Spectrum-Sensing-for-Cognitive-Radio (reimplemented inline)
# Real-time per-band signal occupancy via chi²-thresholded energy + cyclostationary test.
# ════════════════════════════════════════════════════════════════════════════════

class CognitiveSpectrumSensor:
    """Pass 35: Cognitive radio spectrum sensing — two detection algorithms inline.

    1. **EnergyDetector**: Neyman-Pearson energy test (from Crucialcode4 energy_detector.py).
       T_y = Σ|y[k]|²  — compare to chi²-derived threshold γ at target P_FA.
       Decision:  T_y >= γ  →  H1 (signal present)

    2. **CyclostationaryDetector**: OFDM cyclostationary test (from Crucialcode4
       cyclostationary_detector.py). For OFDM with cyclic prefix of length N_c:
       T_y = (1/K) Σ_{n=0}^{N_c-1} Σ_{k=0}^{K-1}  y[n+k(N_c+N_d)] · y*[n+k(N_c+N_d)+N_d]
       Non-zero expectation under H1 (cyclostationarity of OFDM) → complex T_y has
       |real(T_y)| >> 0 when signal present.

    Both run on each spectrum band's IQ or subcarrier data directly.
    Output: per-band detection probability + occupancy decision.
    """

    def __init__(self, p_fa: float = 0.01,
                 ofdm_n_c: int = 16, ofdm_n_d: int = 48, ofdm_k: int = 4,
                 noise_sigma: float = 1.0):
        """
        p_fa        : target false-alarm probability for energy threshold
        ofdm_n_c    : cyclic-prefix length (default 16 samples)
        ofdm_n_d    : OFDM data symbol length (default 48)
        ofdm_k      : number of OFDM symbols per window (default 4)
        noise_sigma : estimated noise std (updated adaptively from quiet bands)
        """
        from scipy.stats import chi2 as _chi2  # always available
        self._chi2      = _chi2
        self.p_fa       = p_fa
        self.N_c        = ofdm_n_c
        self.N_d        = ofdm_n_d
        self.K          = ofdm_k
        self.sigma_n    = noise_sigma
        self._snr_hist: dict = {}   # band_name → EMA SNR
        self._decision_hist: dict = {}   # band_name → deque of bools
        log.info(f"[CogSpectrum] CognitiveSpectrumSensor init — "
                 f"P_FA={p_fa:.3f} OFDM N_c={ofdm_n_c} N_d={ofdm_n_d}")

    # ── energy detector ───────────────────────────────────────────────────────
    def energy_detect(self, iq_or_csi: np.ndarray, band_name: str = "") -> dict:
        """Apply Neyman-Pearson energy detector to a vector of samples.
        Returns h1 (bool), T_y (float), threshold (float), p_d_est (float)."""
        y  = np.asarray(iq_or_csi, dtype=np.complex128).ravel()
        N  = len(y)
        if N == 0:
            return {"h1": False, "T_y": 0.0, "threshold": 0.0, "p_d": 0.0}

        T_y   = float(np.sum(np.abs(y) ** 2))           # energy test statistic
        gamma = self._chi2.isf(q=self.p_fa, df=N) * (self.sigma_n ** 2)
        h1    = T_y >= gamma

        # Theoretical P_D estimate (signal power = T_y - N*σ² clipped)
        sig_pwr  = max(T_y - N * self.sigma_n ** 2, 0.0) / N
        if gamma > 0 and (sig_pwr + self.sigma_n ** 2) > 0:
            p_d = float(self._chi2.sf(
                gamma / (sig_pwr + self.sigma_n ** 2), df=N))
        else:
            p_d = 0.0

        # Adaptive noise floor: update sigma_n when band appears empty
        if not h1 and band_name:
            noise_est = float(np.sqrt(T_y / max(N, 1)))
            self.sigma_n = 0.95 * self.sigma_n + 0.05 * noise_est

        # Record decision history
        if band_name:
            if band_name not in self._decision_hist:
                self._decision_hist[band_name] = deque(maxlen=20)
            self._decision_hist[band_name].append(h1)

        return {"h1": h1, "T_y": T_y, "threshold": gamma, "p_d": p_d,
                "snr_db": float(10 * np.log10(T_y / max(gamma, 1e-12)))}

    # ── cyclostationary detector ──────────────────────────────────────────────
    def cyclo_detect(self, iq: np.ndarray, band_name: str = "") -> dict:
        """OFDM cyclostationary test — exploits cyclic prefix correlation.
        Returns h1, T_y (complex), |T_y| (float), snr_approx (float)."""
        y   = np.asarray(iq, dtype=np.complex128).ravel()
        N   = (self.K + 1) * (self.N_c + self.N_d)
        if len(y) < N:
            y = np.pad(y, (0, N - len(y)))
        else:
            y = y[:N]

        # Cyclostationary test statistic (Crucialcode4 formula)
        T = 0j
        for n in range(self.N_c):
            for k in range(self.K):
                idx_a = n + k * (self.N_c + self.N_d)
                idx_b = idx_a + self.N_d
                if idx_a < len(y) and idx_b < len(y):
                    T += y[idx_a] * np.conj(y[idx_b])
        T /= max(self.K, 1)

        T_abs = float(abs(T))
        # Pass 41: chi²-based threshold (from Crucialuseexamplecode4 cyclostationary_detector_b.py)
        # Under H0: |T_y|² ~ chi²(2) · σ_w⁴ · N_c / K  (complex circular Gaussian)
        # gamma = chi2.isf(P_FA, df=2) * N_c/K * σ_w^4
        _df   = 2
        _sq4  = self.sigma_n ** 4
        gamma = float(self._chi2.isf(q=self.p_fa, df=_df)) * self.N_c / max(self.K, 1) * _sq4
        threshold = float(np.sqrt(max(gamma, 1e-24)))  # work in |T_y| domain
        h1 = (T_abs * T_abs) >= gamma

        return {"h1": h1, "T_y": T, "T_abs": T_abs,
                "threshold": threshold, "snr_approx": T_abs / max(threshold, 1e-9)}

    # ── combined sensing per band ─────────────────────────────────────────────
    def sense_band(self, iq: np.ndarray, band_name: str = "") -> dict:
        """Run both detectors on the IQ buffer. Returns combined decision + metrics."""
        ed = self.energy_detect(iq, band_name)
        cd = self.cyclo_detect(iq, band_name)
        # Fuse: H1 if EITHER detector fires (OR fusion for high sensitivity)
        h1_combined = ed["h1"] or cd["h1"]
        # Occupancy probability: average of p_d and cyclo SNR normalised
        cyclo_conf = float(np.clip(cd["snr_approx"] / 3.0, 0.0, 1.0))
        occ_prob   = float(np.clip((ed["p_d"] + cyclo_conf) / 2.0, 0.0, 1.0))
        return {
            "band":         band_name,
            "occupied":     h1_combined,
            "occupancy_prob": occ_prob,
            "energy_h1":    ed["h1"],
            "cyclo_h1":     cd["h1"],
            "energy_T_y":   ed["T_y"],
            "energy_snr_db": ed["snr_db"],
            "cyclo_T_abs":  cd["T_abs"],
            "noise_sigma":  self.sigma_n,
        }

    # ── batch across all bands from spectrum survey ───────────────────────────
    def sense_all_bands(self, spectrum_survey: dict) -> dict:
        """Run sense_band on each band's IQ data (or CSI proxy) from the survey dict.
        Returns band_name → sense result dict."""
        results = {}
        for band_name, bdata in spectrum_survey.items():
            if not isinstance(bdata, dict):
                continue
            iq = bdata.get("_iq_raw")    # set by HighGHzSpectrumAnalyzer if SDR real
            if iq is None:
                # Use subcarrier CSI as a proxy for the 2.4 GHz band
                continue
            results[band_name] = self.sense_band(np.asarray(iq), band_name)
        return results

    def occupancy_summary(self, sense_results: dict) -> str:
        if not sense_results:
            return "COGSPEC  no-bands-sensed"
        occ = [b for b, r in sense_results.items() if r.get("occupied")]
        return (f"COGSPEC  {len(occ)}/{len(sense_results)} bands occupied  "
                f"bands={occ[:4]}")


