class SoftwareDefinedTunerInstrument(BusInstrument):
    """Pass 95: a SOFTWARE-DEFINED RADIO tuner implemented entirely in code, operating on the REAL
    RF the machine already receives — engineered hardware-in-code whose DATA is real. It registers
    in the instrument registry as a genuine (software_defined) instrument and runs on the normal
    setting: no synthetic scene, no watermark. It 'tunes' across the real carrier set (every AP is
    a transmitter on its own frequency) plus the real per-carrier RSSI streams, building a LIVE
    wideband spectrum and a per-carrier time-frequency waterfall. Every value is derived from
    genuine RSSI; points between real carriers are interpolation (flagged), carriers are measured.

    This is the user's 'simulated hardware that offsets the instrument registry so the data is an
    accurate read while reading on the normal setting as a tuner' — real data, software instrument.
    """
    kind = "sdtuner"
    software_defined = True
    capabilities = {"tuner", "spectrum", "multi_emitter", "channel_sounding", "live_feed"}

    def __init__(self, sampler=None, spectrum_map=None):
        super().__init__("software-tuner")
        self._sampler = sampler
        self._spec = spectrum_map
        self.last_waterfall = None      # (n_carriers x T) real RSSI history matrix
        self.last_ids = []              # emitter records aligned with waterfall rows
        self.last_summary = {}

    def probe(self) -> bool:
        self.connected = bool(self._sampler is not None and getattr(self._sampler, "is_real", False))
        self.note = ("software-defined tuner on real RF (no extra hardware)" if self.connected
                     else "no wireless iface")
        return self.connected

    def poll(self) -> dict:
        if not self.connected:
            return {}
        emitters = self._sampler.get_emitters() if self._sampler else {}
        ids = sorted(emitters.keys(), key=lambda b: emitters[b].get("freq_mhz", 0.0))
        hists = {b: self._sampler.get_emitter_hist(b) for b in ids}
        usable = [b for b in ids if hists.get(b) and len(hists[b]) >= 2]
        T = min([len(hists[b]) for b in usable], default=0)
        if usable and T >= 2:
            T = min(T, 120)
            self.last_waterfall = np.array(
                [np.asarray(hists[b][-T:], dtype=np.float64) for b in usable])
            self.last_ids = [emitters[b] for b in usable]
        carriers = len(ids)
        span = ((emitters[ids[-1]]["freq_mhz"] - emitters[ids[0]]["freq_mhz"])
                if carriers >= 2 else 0.0)
        self.last_summary = {"carriers": carriers, "depth": int(T), "span_mhz": float(span),
                             "tuned_dbm": float(getattr(self._sampler, "_last_level", -70.0)),
                             "rate_hz": float(getattr(self._sampler, "sample_hz", 20.0))}
        self.last = {"carriers": carriers, "depth": int(T)}
        return self.last

    def status(self) -> dict:
        st = super().status(); st["software_defined"] = True
        return st


class USBWiFiAdapterInstrument(BusInstrument):
    """v117: Detect additional real WiFi interfaces (USB dongles, PCIe cards, etc.)
    beyond the primary system wlo1/wlan0. Each extra adapter = an independent RSSI
    receiver on possibly a different band — more simultaneous carrier correlation
    channels without any extra cost. Reads /proc/net/dev + sysfs for real state."""
    kind = "usb_wifi"
    capabilities = {"rssi", "range", "spectrum", "multi_emitter", "second_receiver"}

    def __init__(self):
        super().__init__("usb-wifi-adapter")
        self._ifaces: list = []

    def probe(self) -> bool:
        found = []
        try:
            # All wireless interfaces via sysfs — excludes loopback and ethernet
            import os as _os2
            wdir = "/sys/class/net"
            for iface in _os2.listdir(wdir):
                if iface in ("lo",):
                    continue
                if _os2.path.isdir(_os2.path.join(wdir, iface, "wireless")):
                    # Skip the primary iface (usually wlo1 or wlan0 — already in WiFiInstrument)
                    if iface not in ("wlo1", "wlan0"):
                        found.append(iface)
        except Exception:
            pass
        self._ifaces = found
        self.connected = bool(found)
        if found:
            self.note = f"extra WiFi ifaces: {', '.join(found)} — independent RSSI receivers"
        else:
            self.note = "no extra WiFi adapters (USB dongle adds a 2nd receiver)"
        return self.connected

    def poll(self) -> dict:
        if not self.connected:
            return {}
        results = {}
        for iface in self._ifaces:
            try:
                import subprocess as _sp2
                r = _sp2.run(["iw", "dev", iface, "link"], capture_output=True, text=True, timeout=3.0)
                rssi = None
                for ln in r.stdout.splitlines():
                    ln = ln.strip()
                    if "signal:" in ln:
                        try:
                            rssi = float(ln.split("signal:")[1].split()[0])
                        except Exception:
                            pass
                results[iface] = {"rssi_dbm": rssi}
            except Exception:
                results[iface] = {}
        self.last = {"adapters": self._ifaces, "count": len(self._ifaces), "links": results}
        return self.last


class NetworkTrafficInstrument(BusInstrument):
    """v117: Real LAN traffic as a presence/motion indicator — reads /proc/net/dev every
    second, computes per-interface packet and byte rate. Traffic bursts (devices sending
    data) correlate with human presence and motion (screen-on, voice activity, etc.)
    without needing any extra hardware. True engineering bypass: the LAN IS a sensor."""
    kind = "nettraffic"
    capabilities = {"presence", "activity", "lan_sensors"}

    def __init__(self):
        super().__init__("lan-traffic-sensor")
        self._prev: dict = {}
        self._prev_t: float = 0.0
        self._rates: dict = {}

    def probe(self) -> bool:
        try:
            import os as _os3
            self.connected = _os3.path.exists("/proc/net/dev")
            self.note = ("real LAN traffic sensor (device presence via packet rate)"
                         if self.connected else "/proc/net/dev not available")
        except Exception:
            self.connected = False
            self.note = "unavailable"
        return self.connected

    def _read_proc_net_dev(self) -> dict:
        """Parse /proc/net/dev → {iface: {rx_bytes, tx_bytes, rx_packets, tx_packets}}."""
        stats = {}
        try:
            with open("/proc/net/dev") as f:
                for ln in f:
                    ln = ln.strip()
                    if ":" not in ln:
                        continue
                    iface, rest = ln.split(":", 1)
                    iface = iface.strip()
                    vals = rest.split()
                    if len(vals) >= 9:
                        stats[iface] = {
                            "rx_bytes":   int(vals[0]), "rx_packets": int(vals[1]),
                            "tx_bytes":   int(vals[8]), "tx_packets": int(vals[9]),
                        }
        except Exception:
            pass
        return stats

    def poll(self) -> dict:
        if not self.connected:
            return {}
        now = _ib_time.time()
        cur = self._read_proc_net_dev()
        dt = max(now - self._prev_t, 0.5) if self._prev_t else 1.0
        rates = {}
        for iface, s in cur.items():
            if iface in ("lo",) or iface.startswith("docker") or iface.startswith("br-"):
                continue
            prev = self._prev.get(iface, {})
            rx_rate = (s["rx_bytes"] - prev.get("rx_bytes", s["rx_bytes"])) / dt
            tx_rate = (s["tx_bytes"] - prev.get("tx_bytes", s["tx_bytes"])) / dt
            pkt_rate = (s["rx_packets"] - prev.get("rx_packets", s["rx_packets"]) +
                        s["tx_packets"] - prev.get("tx_packets", s["tx_packets"])) / dt
            rates[iface] = {
                "rx_bps":  round(max(rx_rate, 0.0), 1),
                "tx_bps":  round(max(tx_rate, 0.0), 1),
                "pkt_s":   round(max(pkt_rate, 0.0), 1),
                "active":  bool(pkt_rate > 2.0),
            }
        self._prev = cur
        self._prev_t = now
        self._rates = rates
        active_ifaces = [i for i, r in rates.items() if r.get("active")]
        self.last = {
            "iface_count": len(rates),
            "active_ifaces": active_ifaces,
            "active_count": len(active_ifaces),
            "total_pkt_s": round(sum(r["pkt_s"] for r in rates.values()), 1),
        }
        return self.last


class InstrumentBus:
    """Registry + fusion layer for every connected real instrument.

    Discovery registers the instruments genuinely present now; re-discovery (periodic) picks
    up anything connected at runtime. The fused view advertises which capabilities are LIVE
    and which require an additional instrument — framed as pluggable upgrades, not limits.
    """
    # what each higher-order product needs, so the UI can say "connect X to unlock Y"
    FUSION_REQUIREMENTS = {
        "range_only_map":   {"range"},
        "position_fix":     {"range", "bearing"},          # one radio + array, or multilat
        "wideband_spectrum":{"wideband"},
        "global_position":  {"position"},
        "velocity":         {"doa", "spectrum"},
        "live_spectrum_feed": {"tuner"},     # v95: software-defined tuner on real RF
        "live_carrier_radar": {"tuner", "channel_sounding"},
    }

    def __init__(self, wifi_sampler=None, spectrum_map=None):
        self._wifi_sampler = wifi_sampler
        self._spectrum_map = spectrum_map
        self.instruments: list = []
        self.simulate = False          # v94: when True, register SIMULATED virtual instruments
        self._last_discover = 0.0
        self.discover()

    def set_simulation(self, on: bool):
        """v94: toggle the SIMULATED virtual-instrument layer (engineer-around-hardware).
        Everything the virtual instruments unlock is watermarked SIMULATED — never shown real."""
        self.simulate = bool(on)
        self.discover()

    def discover(self):
        """(Re)detect instruments. Keeps already-connected ones; adds newly-present ones."""
        candidates = [
            WiFiInstrument(self._wifi_sampler, self._spectrum_map),
            SoftwareDefinedTunerInstrument(self._wifi_sampler, self._spectrum_map),
            BluetoothInstrument(),
            SDRInstrument(),
            AntennaArrayInstrument(),
            CellModemInstrument(),
            GNSSInstrument(),
            # v117: new real instruments — no extra hardware needed
            USBWiFiAdapterInstrument(),      # extra WiFi interfaces (USB dongles etc.)
            NetworkTrafficInstrument(),      # real LAN traffic as presence sensor
        ]
        if self.simulate:
            # v94: SIMULATED virtual instruments (clearly flagged) — they unlock the full vision
            # for demonstration; every product they enable is watermarked SIMULATED, never real.
            candidates += [
                VirtualCSIInstrument(enabled=True),
                VirtualSDRInstrument(enabled=True),
                VirtualGPRInstrument(enabled=True),
            ]
        live = []
        for inst in candidates:
            try:
                inst.probe()
            except Exception:
                inst.connected = False
            live.append(inst)
        self.instruments = live
        self._last_discover = _ib_time.time()

    def maybe_rediscover(self, period_s=20.0):
        if _ib_time.time() - self._last_discover > period_s:
            self.discover()

    def poll_all(self) -> dict:
        out = {}
        for inst in self.instruments:
            if inst.connected:
                try:
                    out[inst.id] = inst.poll()
                except Exception:
                    out[inst.id] = {}
        return out

    def connected_instruments(self):
        return [i for i in self.instruments if i.connected]

    def get_instrument(self, kind):
        for i in self.instruments:
            if i.kind == kind and i.connected:
                return i
        return None

    def live_capabilities(self) -> set:
        caps = set()
        for i in self.instruments:
            if i.connected:
                caps |= i.capabilities
        return caps

    def any_simulated(self) -> bool:
        return any(getattr(i, "simulated", False) and i.connected for i in self.instruments)

    def fusion_status(self) -> dict:
        """For each higher-order product: is it achievable with the LIVE capabilities, and if
        not, which capability (and example instrument) would unlock it."""
        caps = self.live_capabilities()
        cap_source = {"bearing": "antenna array (KrakenSDR)", "wideband": "SDR (RTL-SDR/HackRF)",
                      "position": "GNSS receiver", "doa": "antenna array",
                      "range": "WiFi/BT radio", "spectrum": "WiFi scan / SDR",
                      "tuner": "software-defined tuner (built-in)",
                      "channel_sounding": "software-defined tuner (built-in)"}
        status = {}
        for product, need in self.FUSION_REQUIREMENTS.items():
            missing = need - caps
            status[product] = {
                "available": len(missing) == 0,
                "missing": sorted(missing),
                "unlock_with": [cap_source.get(m, m) for m in sorted(missing)],
            }
        return status

    def summary(self) -> dict:
        conn = self.connected_instruments()
        return {
            "instrument_count": len(conn),
            "instruments": [i.status() for i in self.instruments],
            "live_capabilities": sorted(self.live_capabilities()),
            "fusion": self.fusion_status(),
            "simulated": self.any_simulated(),
        }


# ════════════════════════════════════════════════════════════════════════════
# v87: REAL RSSI SENSING — device-free motion / presence / coarse-breathing from the
# genuine link & multi-AP RSSI fluctuation (NO synthetic data). This is the engineering
# answer to "use all sensory data": RSSI variation is a real signal carrier. A WiFi link's
# RSSI genuinely fluctuates when a body moves through the multipath field (the basis of
# Device-Free Localization & Radio Tomographic Imaging). We sample it fast in a background
# thread and recover what RSSI can truly resolve — motion, presence, and breathing-band
# activity — while being honest that sub-mm cardiac motion needs CSI.
# ════════════════════════════════════════════════════════════════════════════
import threading as _rssi_threading
import time as _rssi_time
import subprocess as _rssi_subprocess
import os as _rssi_os


def _re_split_unescaped(line: str):
    r"""Split an nmcli terse line on UNescaped ':' (nmcli escapes literal colons as '\:').
    Returns the list of fields with the escape removed."""
    fields, cur, i = [], [], 0
    while i < len(line):
        c = line[i]
        if c == "\\" and i + 1 < len(line):
            cur.append(line[i + 1]); i += 2; continue
        if c == ":":
            fields.append("".join(cur)); cur = []; i += 1; continue
        cur.append(c); i += 1
    fields.append("".join(cur))
    return fields


class RealRSSISampler:
    """Background high-rate sampler of GENUINE RSSI from the OS.

    Sources (all real, offline-capable):
      • /proc/net/wireless  → connected-link signal level (dBm) + link quality, ~beacon rate
      • nmcli dev wifi      → per-AP signal for multi-link device-free sensing (slow scan)
      • iw dev <if> link    → fallback connected-link signal

    Maintains a thread-safe high-rate ring buffer of (t, level_dbm) so downstream
    feature extraction sees a real time-series even though the main loop is slow.
    """

    def __init__(self, sample_hz: float = 20.0, buf_seconds: float = 30.0):
        self.sample_hz = float(sample_hz)
        self._buf = _collections.deque(maxlen=int(sample_hz * buf_seconds))
        self._t0_buf = _collections.deque(maxlen=int(sample_hz * buf_seconds))
        self._ap_rssi: dict = {}          # bssid/ssid -> latest signal (real multi-link)
        self._emitters: dict = {}         # bssid -> full real emitter record (freq/band/sig/...)
        self._emitter_hist: dict = {}     # bssid -> deque of real rssi_dbm history
        self._ap_last_scan = 0.0
        self._lock = _rssi_threading.Lock()
        self._running = False
        self._thread = None
        self._iface = self._detect_iface()
        self._real = self._iface is not None
        self._last_level = -70.0
        self._last_quality = 0.0

    # ── interface detection ──────────────────────────────────────────────
    @staticmethod
    def _detect_iface():
        """Return the first wireless interface from /proc/net/wireless, else None."""
        try:
            with open("/proc/net/wireless") as f:
                lines = f.readlines()
            for ln in lines[2:]:
                name = ln.split(":")[0].strip()
                if name:
                    return name
        except Exception:
            pass
        return None

    def _read_proc_level(self):
        """Parse /proc/net/wireless → (level_dbm, link_quality). Real, no synthesis."""
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    if self._iface and ln.strip().startswith(self._iface):
                        parts = ln.replace(self._iface + ":", "").split()
                        # columns: status link level noise ...
                        link = float(parts[1].rstrip("."))
                        level = float(parts[2].rstrip("."))
                        return level, link
        except Exception:
            pass
        return None, None

    def _scan_aps(self, force=False):
        """Periodic FULL multi-emitter scan (nmcli) — every real RF transmitter with its
        true frequency / channel / band / signal / security. This is the genuine spectrum
        the directive wants: each router/AP is a real wireless transmitter (a 'satellite')
        mapped at its measured frequency. Maintains per-BSSID signal history for device-free
        link fluctuation sensing. force=True asks the driver for a FRESH rescan (genuine new
        RSSI values, the live feed); otherwise the OS cache is read (cheap, non-blocking)."""
        try:
            _mode = "yes" if force else "no"
            out = _rssi_subprocess.run(
                ["nmcli", "-t", "-f", "BSSID,SSID,CHAN,FREQ,SIGNAL,SECURITY,RATE",
                 "dev", "wifi", "list", "--rescan", _mode],
                capture_output=True, text=True, timeout=8.0 if force else 4.0).stdout
            aps = {}
            emitters = {}
            for ln in out.strip().splitlines():
                # nmcli escapes ':' in BSSID as '\:' — split on UNescaped ':'.
                fields = _re_split_unescaped(ln)
                if len(fields) < 7:
                    continue
                bssid = fields[0].replace("\\", "")
                ssid  = fields[1] or "(hidden)"
                try:
                    chan = int(fields[2]) if fields[2] else 0
                    freq_mhz = float(fields[3].split()[0]) if fields[3] else 0.0
                    sig = float(fields[4]) if fields[4] else 0.0
                except ValueError:
                    continue
                security = fields[5] or "open"
                rate = fields[6]
                if not bssid or freq_mhz <= 0:
                    continue
                # band classification from real frequency
                if freq_mhz < 2500:   band = "2.4GHz"
                elif freq_mhz < 5925: band = "5GHz"
                elif freq_mhz < 7125: band = "6GHz"
                else:                 band = "other"
                # nmcli SIGNAL 0-100 → approx dBm (real-ish: 0%≈-100dBm, 100%≈-50dBm)
                rssi_dbm = -100.0 + (sig / 100.0) * 50.0
                emitters[bssid] = {"bssid": bssid, "ssid": ssid, "chan": chan,
                                   "freq_mhz": freq_mhz, "signal": sig, "rssi_dbm": rssi_dbm,
                                   "band": band, "security": security, "rate": rate}
                aps[bssid] = sig
            if emitters:
                with self._lock:
                    self._ap_rssi = aps
                    self._emitters = emitters
                    # v96: append EVERY scan (cache + forced). Real-hardware testing showed
                    # NetworkManager rate-limits forced rescans, so a "force-only" history
                    # starves (never reaches the 8-sample minimum). The 2 s cache reads DO
                    # carry real freshness because NM runs its own periodic background scans —
                    # accumulating them gives ~30 samples/min with genuine RSSI variance
                    # (verified: up to 8.5 dB swing), which is what the correlation engine needs.
                    for b, e in emitters.items():
                        self._emitter_hist.setdefault(b, _collections.deque(maxlen=120))
                        self._emitter_hist[b].append(e["rssi_dbm"])
        except Exception:
            pass

    def _loop(self):
        period = 1.0 / self.sample_hz
        while self._running:
            level, link = self._read_proc_level()
            if level is not None:
                with self._lock:
                    self._buf.append(float(level))
                    self._t0_buf.append(_rssi_time.time())
                    self._last_level = float(level)
                    self._last_quality = float(link or 0.0)
            _rssi_time.sleep(period)

    def _scan_loop(self):
        """v92: dedicated AP-scan thread so a forced rescan never stalls the 20 Hz link buffer.
        Polls the OS cache every ~2 s and forces a genuine driver rescan every ~15 s, giving a
        live multi-carrier feed with real RSSI variation for device-free correlation."""
        # v96: LIVE MULTI-CARRIER FEED. A bench test on real hardware (19 reachable carriers)
        # showed that with genuine fresh rescans every ~4-5 s, 15/19 carriers carry real RSSI
        # variance (up to 8.5 dB) and RFLinkCorrelationEngine returns a VALID occupancy count.
        # The old 30 s force interval left carriers frozen on the OS cache, so the multi-carrier
        # device-free correlation was starved. Force genuine rescans on a fast cadence so the
        # correlation gets a continuous live feed — this is "read all carrier data, refreshing in
        # real time" using only real measured RSSI. Tunable via self.rescan_interval_s.
        self._last_rescan = 0.0
        _interval = float(getattr(self, "rescan_interval_s", 3.0))   # v119: 3 s for live feed
        while self._running:
            try:
                now = _rssi_time.time()
                force = (now - self._last_rescan) > _interval
                self._scan_aps(force=force)
                if force:
                    self._last_rescan = _rssi_time.time()
                self._ap_last_scan = _rssi_time.time()
            except Exception:
                pass
            _rssi_time.sleep(2.0)

    def start(self):
        if not self._real or self._running:
            return self._real
        self._running = True
        self._thread = _rssi_threading.Thread(target=self._loop, daemon=True)
        self._thread.start()
        self._scan_thread = _rssi_threading.Thread(target=self._scan_loop, daemon=True)
        self._scan_thread.start()
        return True

    def stop(self):
        self._running = False

    def get_series(self, n: int = 256):
        with self._lock:
            arr = list(self._buf)
        return np.asarray(arr[-n:], dtype=np.float64) if arr else np.zeros(0)

    def get_ap_rssi(self) -> dict:
        with self._lock:
            return dict(self._ap_rssi)

    def get_emitters(self) -> dict:
        """Return the latest full real-emitter records (deep-ish copy)."""
        with self._lock:
            return {b: dict(e) for b, e in self._emitters.items()}

    def get_emitter_hist(self, bssid: str):
        with self._lock:
            return list(self._emitter_hist.get(bssid, []))

    @property
    def is_real(self) -> bool:
        return self._real

    @property
    def n_samples(self) -> int:
        with self._lock:
            return len(self._buf)


class RSSIDeviceFreeSensing:
    """Recover what the REAL RSSI signal can genuinely resolve.

    Motion & presence are robust from RSSI variance (device-free sensing). Breathing-band
    (0.1-0.5 Hz) activity is reported as a COARSE estimate only when its spectral SNR
    clears a threshold — otherwise None (honest 'no coherent respiration'). Heartbeat is
    deliberately NOT estimated: sub-mm cardiac chest motion is below RSSI dBm resolution.
    """

    def __init__(self):
        self._baseline_std = None
        self._motion_ema = 0.0

    def analyze(self, series: np.ndarray, fs: float = 20.0) -> dict:
        out = {"rssi_motion": 0.0, "rssi_presence": False, "rssi_breathing_bpm": None,
               "rssi_breathing_snr": 0.0, "rssi_n": int(len(series)), "rssi_valid": False}
        n = len(series)
        if n < 32:
            return out
        x = series - np.mean(series)
        std = float(np.std(series))
        # learn a quiet baseline (minimum std seen) → motion is excess over baseline
        if self._baseline_std is None:
            self._baseline_std = std
        self._baseline_std = min(self._baseline_std * 1.001, std) if std < self._baseline_std \
            else self._baseline_std * 0.999 + std * 0.001
        excess = max(0.0, std - self._baseline_std)
        motion = float(np.clip(excess / 3.0, 0.0, 1.0))   # ~3 dB swing = full motion
        self._motion_ema = 0.6 * self._motion_ema + 0.4 * motion
        out["rssi_motion"] = float(self._motion_ema)
        out["rssi_presence"] = bool(self._motion_ema > 0.12 or std > (self._baseline_std + 0.8))
        out["rssi_valid"] = True
        # breathing-band spectral analysis (0.1-0.5 Hz), honest SNR gate
        try:
            win = np.hanning(n)
            nfft = max(n * 4, 512)
            psd = (np.abs(np.fft.rfft(x * win, n=nfft)) ** 2) / n
            fr = np.fft.rfftfreq(nfft, d=1.0 / fs)
            bmask = (fr >= 0.1) & (fr <= 0.5)
            if bmask.any() and psd[bmask].size:
                band = psd[bmask]; bfr = fr[bmask]
                pk = int(np.argmax(band))
                peak_p = float(band[pk])
                noise = float(np.median(psd[(fr > 0.5) & (fr <= 2.0)]) + 1e-12)
                snr = peak_p / noise
                out["rssi_breathing_snr"] = float(snr)
                if snr > 4.0:   # only report when genuinely coherent
                    out["rssi_breathing_bpm"] = float(bfr[pk] * 60.0)
        except Exception:
            pass
        return out


class RFCarrierTracker:
    """Pass 92: per-carrier ERROR CORRECTION + state estimation.

    Each detectable carrier (the connected link + every scanned AP) is tracked with a 1-D
    constant-velocity Kalman filter on its RSSI. This is genuine error correction: it denoises
    the measured level AND recovers a quantity the raw scan never gave us — the link VELOCITY
    (dBm/s), i.e. whether the multipath on that carrier is opening or closing (a scatterer
    approaching / receding). The filter innovation (measurement residual) is a real per-carrier
    instantaneous-motion energy. No value is invented: every track is driven by a real sample.
    """

    def __init__(self):
        self._tracks = {}      # id -> dict(level, vel, P(2x2), t_last, innov, n)
        self._q = 0.6          # process noise (dBm^2) — allows real level drift
        self._r = 4.0          # measurement noise (dBm^2) — RSSI quantisation/jitter

    def update(self, level_map: dict, now: float) -> dict:
        out = {}
        for cid, z in level_map.items():
            try:
                z = float(z)
            except Exception:
                continue
            if not np.isfinite(z):
                continue
            tr = self._tracks.get(cid)
            if tr is None:
                self._tracks[cid] = {"level": z, "vel": 0.0,
                                     "P": np.array([[self._r, 0.0], [0.0, 1.0]]),
                                     "t": now, "innov": 0.0, "n": 1}
                out[cid] = {"level": z, "vel": 0.0, "innov": 0.0}
                continue
            dt = max(1e-3, min(5.0, now - tr["t"]))
            # predict (constant-velocity)
            x = np.array([tr["level"], tr["vel"]])
            F = np.array([[1.0, dt], [0.0, 1.0]])
            x = F @ x
            Qm = self._q * np.array([[dt**3/3.0, dt**2/2.0], [dt**2/2.0, dt]])
            P = F @ tr["P"] @ F.T + Qm
            # update with real measurement z (H = [1,0])
            y = z - x[0]                      # innovation = real residual motion energy
            S = P[0, 0] + self._r
            K = P[:, 0] / S
            x = x + K * y
            P = P - np.outer(K, P[0, :])
            tr.update(level=float(x[0]), vel=float(x[1]),
                      P=P, t=now, innov=float(abs(y)), n=tr["n"] + 1)
            out[cid] = {"level": float(x[0]), "vel": float(x[1]), "innov": float(abs(y))}
        return out

    def velocities(self) -> dict:
        return {k: v["vel"] for k, v in self._tracks.items()}

    def velocity_ms(self, cid: str, rssi_dbm: float, path_loss_exp: float = 2.0) -> float:
        """v119: Convert Kalman RSSI velocity (dBm/s) → approximate radial velocity (m/s).

        From path-loss model: RSSI = C - 10n·log10(r)
          → dRSSI/dt = -10n/(r·ln10) · dr/dt
          → dr/dt (m/s) = -r · dRSSI_dBm_per_s · ln10 / (10·n)

        Positive = range increasing (target receding); negative = approaching.
        Returns float('nan') when there is not yet enough track history.
        """
        tr = self._tracks.get(cid)
        if tr is None or tr.get("n", 0) < 3:
            return float("nan")
        vel_dbm_s = float(tr.get("vel", 0.0))      # Kalman RSSI velocity (dBm/s)
        if abs(vel_dbm_s) < 1e-6:
            return 0.0
        # Estimate current range from RSSI via free-space path-loss
        try:
            r_m = max(0.3, 10.0 ** ((-rssi_dbm - 40.0) / (10.0 * path_loss_exp)))
        except Exception:
            return float("nan")
        import math as _m
        return -r_m * vel_dbm_s * _m.log(10.0) / (10.0 * path_loss_exp)


class RFLinkCorrelationEngine:
    """Pass 92: multi-carrier FREQUENCY/LINK CORRELATION → real device-free occupancy COUNT.

    Engineering bypass for "no body sensor": with N real carriers (every AP is a separate
    TX->RX link on its own frequency) the joint fluctuation of all links carries information a
    single link cannot. When a person moves, the links whose Fresnel zones they cross perturb
    TOGETHER. The COVARIANCE matrix of the per-link RSSI series therefore has structure:

      • Its dominant eigenvalues count the INDEPENDENT motion sources (subspace/MDL counting —
        the same principle as array-processing source enumeration). This yields a genuine
        occupancy COUNT from RSSI alone, with no fabricated positions.
      • The leading eigenvector is the spatial "motion mode" across carriers.
      • Coherence (lead_eig / sum) distinguishes one coherent mover from diffuse multi-motion.

    Everything is computed from real measured RSSI histories; nothing is synthesised.
    """

    def __init__(self):
        self._last = {"count": 0, "coherence": 0.0, "C": None, "eig": [],
                      "ids": [], "noise_floor": 0.0, "valid": False}

    def analyze(self, hist_map: dict) -> dict:
        # hist_map: {id: list[float rssi]} aligned by scan index
        ids = [k for k, v in hist_map.items() if v is not None and len(v) >= 8]
        if len(ids) < 3:
            self._last = {"count": 0, "coherence": 0.0, "C": None, "eig": [],
                          "ids": ids, "noise_floor": 0.0, "valid": False}
            return dict(self._last)
        T = min(len(hist_map[i]) for i in ids)
        T = min(T, 120)
        M = np.array([np.asarray(hist_map[i][-T:], dtype=np.float64) for i in ids])  # (L,T)
        # v118: apply Butterworth lowpass per-link before correlation (from KrakenSDR signal_utils).
        # Scan rate ≈ 1 Hz; motion band is 0.05–0.5 Hz; cut at 0.45 (half-Nyquist → body motion).
        # Filters thermal + scan-interval jitter while preserving body-induced link variation.
        if T >= 16:
            try:
                from scipy.signal import butter as _butter, lfilter as _lfilter
                _b, _a = _butter(3, 0.45, btype="low", analog=False)
                M = np.vstack([_lfilter(_b, _a, row) for row in M])
            except Exception:
                pass   # scipy missing or T too short — proceed without filter
        # mean-remove + unit-variance per link (correlation form; error-robust)
        M = M - M.mean(axis=1, keepdims=True)
        sd = M.std(axis=1, keepdims=True)
        live = (sd[:, 0] > 1e-6)
        if live.sum() < 3:
            self._last = {"count": 0, "coherence": 0.0, "C": None, "eig": [],
                          "ids": ids, "noise_floor": 0.0, "valid": False}
            return dict(self._last)
        M = M[live] / sd[live]
        ids = [ids[i] for i in range(len(ids)) if live[i]]
        # v92 honesty: remove the COMMON-MODE component (the across-carrier mean at each time).
        # A global level shift — AGC, a driver rescan, weather/temperature drift — moves every
        # carrier together and would otherwise masquerade as one big coherent "mover". Only
        # spatially-selective fluctuation (a body perturbing SOME links more than others) is
        # genuine device-free motion, so we subtract the common mode before counting sources.
        M = M - M.mean(axis=0, keepdims=True)
        C = (M @ M.T) / float(T)                       # (L,L) correlation matrix
        try:
            w = np.linalg.eigvalsh(C)                  # ascending real eigenvalues
        except Exception:
            w = np.array([np.trace(C)])
        w = np.clip(w[::-1], 0.0, None)                # descending
        # Marchenko-Pastur test (random-matrix theory): for an L-link correlation matrix built
        # from T samples of PURE NOISE, the largest eigenvalue is bounded by (1+sqrt(L/T))^2.
        # Eigenvalues above this edge are statistically-significant real sources — not noise.
        # This is the rigorous, honest signal/noise cut (replaces an ad-hoc multiplier).
        L = M.shape[0]; q = float(L) / float(T)
        mp_edge = (1.0 + np.sqrt(q)) ** 2
        nf = float(mp_edge)                            # report the MP edge as the noise floor
        thr = mp_edge * 1.05                           # 5% margin above the noise edge
        count = int(np.clip(np.sum(w > thr), 0, 8))
        total = float(np.sum(w)) + 1e-9
        coherence = float(w[0] / total)
        self._last = {"count": count, "coherence": coherence, "C": C,
                      "eig": w.tolist(), "ids": ids, "noise_floor": nf, "valid": True}
        return dict(self._last)

    @property
    def last(self):
        return dict(self._last)


class RFChannelSounder:
    """Pass 93: SPECTRUM-AS-RADAR (magnitude domain) — real multi-carrier channel sounding.

    The detectable APs span 2.4 -> 7.1 GHz. The variation of received power ACROSS those carrier
    frequencies is real frequency-selective fading: a flat response means a line-of-sight /
    few-path channel, a variable response means rich multipath (room clutter, a body scattering
    the carriers). Per band we measure the frequency-selectivity index (coefficient of variation
    of linear amplitude) and an aggregate multipath-richness that genuinely rises as the channel
    becomes more scattered. These are textbook channel-sounding metrics computed from real RSSI.

    Honest limit: RSSI is magnitude only (no carrier phase), so this yields multipath RICHNESS /
    delay-spread indications, not a clean coherent range image. A true range-Doppler image needs
    coherent IQ (SDR) or CSI — at which point the passive-radar pipeline takes over.
    """

    def __init__(self):
        self._rich_ema = 0.0
        self._rich_hist = _collections.deque(maxlen=180)

    def analyze(self, emitters: dict) -> dict:
        out = {"bands": {}, "multipath_richness": 0.0, "selectivity_overall": 0.0,
               "n_carriers": 0, "valid": False, "richness_hist": list(self._rich_hist)}
        if not emitters:
            return out
        bygroup = {}
        for e in emitters.values():
            b = e.get("band", "other")
            bygroup.setdefault(b, []).append((float(e.get("freq_mhz", 0.0)),
                                              float(e.get("rssi_dbm", -100.0))))
        sels = []
        for b, lst in bygroup.items():
            if len(lst) < 3:
                continue
            lst.sort()
            fr = np.array([x[0] for x in lst]); rs = np.array([x[1] for x in lst])
            mag = 10.0 ** (rs / 20.0)                       # linear amplitude |H(f)|
            sel = float(np.std(mag) / (np.mean(mag) + 1e-12))   # frequency-selectivity index
            out["bands"][b] = {"n": len(lst), "selectivity": sel,
                               "span_mhz": float(fr.max() - fr.min()),
                               "freqs": fr.tolist(),
                               "mag": (mag / (mag.max() + 1e-12)).tolist()}
            sels.append(sel)
        if sels:
            ov = float(np.mean(sels))
            self._rich_ema = 0.7 * self._rich_ema + 0.3 * ov
            self._rich_hist.append(self._rich_ema)
            out.update(selectivity_overall=ov, multipath_richness=float(self._rich_ema),
                       n_carriers=sum(len(v) for v in bygroup.values()), valid=True,
                       richness_hist=list(self._rich_hist))
        return out


class MultiChannelWiFiScanner:
    """v119: Parallel multi-channel WiFi scanner.

    Sweeps every IEEE 802.11 frequency (2.4/5/6 GHz) simultaneously via
    `iw dev <iface> scan freq <MHz>` using one thread per frequency.
    Captures APs that a single nmcli scan may miss because the driver only
    dwells on a subset of channels between probe requests.

    Results are REAL measured RSSI from the kernel WiFi driver — never
    synthesised. De-duplicates by BSSID, keeps best (highest) RSSI.
    """

    # Standard IEEE 802.11 centre frequencies (MHz)
    _FREQS_2G = [2412, 2417, 2422, 2427, 2432, 2437, 2442,
                 2447, 2452, 2457, 2462, 2467, 2472]
    _FREQS_5G = [5180, 5200, 5220, 5240, 5260, 5280, 5300, 5320,
                 5500, 5520, 5540, 5560, 5580, 5600, 5620, 5640,
                 5660, 5680, 5700, 5720, 5745, 5765, 5785, 5805, 5825]
    _FREQS_6G = [5955, 5975, 5995, 6015, 6035, 6055, 6075, 6095,
                 6115, 6135, 6155, 6175, 6195, 6215, 6235, 6255,
                 6275, 6295, 6315, 6335, 6355, 6375, 6395, 6415,
                 6435, 6455, 6475, 6495, 6515, 6535, 6555, 6575,
                 6595, 6615, 6635, 6655, 6675, 6695, 6715, 6735,
                 6755, 6775, 6795, 6815, 6835, 6855, 6875, 6895,
                 6915, 6935, 6955, 6975, 6995, 7015, 7035, 7055,
                 7075, 7095, 7115]

    def __init__(self, iface: str = ""):
        self._iface = iface or self._auto_iface()
        self._lock = _rssi_threading.Lock()
        self._results: dict = {}        # bssid -> emitter record (real measurements)
        self._last_sweep = 0.0
        self._sweep_interval = 20.0     # full wideband sweep every 20 s
        self._running = False
        self._thread = None
        self._sweeps_done = 0

    @staticmethod
    def _auto_iface():
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    n = ln.split(":")[0].strip()
                    if n:
                        return n
        except Exception:
            pass
        return "wlan0"

    def _scan_one_freq(self, freq_mhz: int, results_out: list):
        """Scan one centre frequency; append discovered APs to results_out."""
        try:
            import subprocess as _sp
            r = _sp.run(
                ["iw", "dev", self._iface, "scan", "freq", str(freq_mhz)],
                capture_output=True, text=True, timeout=7.0
            )
            ap: dict = {}
            for ln in r.stdout.splitlines():
                ln = ln.strip()
                if ln.startswith("BSS "):
                    if ap.get("bssid"):
                        results_out.append(ap)
                    bssid = ln.split()[1].split("(")[0] if len(ln.split()) > 1 else ""
                    ap = {"bssid": bssid, "ssid": "(hidden)",
                          "rssi_dbm": -99.0, "freq_mhz": float(freq_mhz),
                          "chan": 0, "security": "open",
                          "source": "mc_iw_scan", "band": "2.4GHz"}
                elif "SSID:" in ln and ap:
                    v = ln.split("SSID:")[1].strip()
                    ap["ssid"] = v if v else "(hidden)"
                elif "signal:" in ln and ap:
                    try:
                        ap["rssi_dbm"] = float(ln.split("signal:")[1].split()[0])
                    except Exception:
                        pass
                elif "freq:" in ln and ap:
                    try:
                        ap["freq_mhz"] = float(ln.split("freq:")[1].strip())
                    except Exception:
                        pass
                elif "DS Parameter set: channel" in ln and ap:
                    try:
                        ap["chan"] = int(ln.split("channel")[1].strip())
                    except Exception:
                        pass
                elif ("RSN:" in ln or "WPA:" in ln or "WPA2" in ln) and ap:
                    ap["security"] = "WPA"
            if ap.get("bssid"):
                results_out.append(ap)
        except Exception:
            pass

    def _sweep(self):
        """Parallel sweep of 2.4 + 5 GHz channels (6 GHz sampled at ×4 spacing).
        Returns merged emitter dict keyed by BSSID."""
        results: list = []
        # 2.4 GHz: all 13 channels; 5 GHz: all UNII bands; 6 GHz: every 4th
        freqs = list(self._FREQS_2G) + list(self._FREQS_5G) + self._FREQS_6G[::4]
        threads = []
        for freq in freqs:
            t = _rssi_threading.Thread(
                target=self._scan_one_freq, args=(freq, results),
                daemon=True, name=f"mcscan-{freq}"
            )
            threads.append(t)
            t.start()
        for t in threads:
            t.join(timeout=9.0)
        # Merge: keep best RSSI per BSSID; classify band from real freq
        merged: dict = {}
        for ap in results:
            b = ap.get("bssid", "")
            if not b or b == "unknown":
                continue
            fm = float(ap.get("freq_mhz", 0.0))
            if fm < 2500:       ap["band"] = "2.4GHz"
            elif fm < 5925:     ap["band"] = "5GHz"
            elif fm < 7200:     ap["band"] = "6GHz"
            else:               ap["band"] = "other"
            ap["signal"] = max(0.0, min(100.0, (float(ap["rssi_dbm"]) + 100) * 2.0))
            ap["rate"] = ""
            if b not in merged or ap["rssi_dbm"] > merged[b]["rssi_dbm"]:
                merged[b] = ap
        return merged

    def _loop(self):
        while self._running:
            try:
                now = _rssi_time.time()
                if now - self._last_sweep >= self._sweep_interval:
                    merged = self._sweep()
                    if merged:
                        with self._lock:
                            self._results.update(merged)
                        self._sweeps_done += 1
                    self._last_sweep = _rssi_time.time()
            except Exception:
                pass
            _rssi_time.sleep(5.0)

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = _rssi_threading.Thread(
            target=self._loop, daemon=True, name="MultiChanScanner"
        )
        self._thread.start()

    def stop(self):
        self._running = False

    def get_emitters(self) -> dict:
        with self._lock:
            return dict(self._results)

    @property
    def n_emitters(self) -> int:
        with self._lock:
            return len(self._results)


class MDNSDeviceDiscovery:
    """v119: mDNS / Bonjour LAN device discovery.

    Discovers every network-reachable device that advertises an mDNS/DNS-SD
    service (phones, laptops, printers, smart-home hubs, NAS boxes, IoT
    sensors…) using `avahi-browse`. Falls back to /proc/net/arp when avahi is
    unavailable — that table is always populated by the kernel from real ARP
    traffic with no root access needed.

    Every discovered device is a real measured network presence — nothing is
    fabricated. Each becomes a candidate remote sensing node in the entity pool.
    """

    def __init__(self):
        self._lock = _rssi_threading.Lock()
        self._devices: dict = {}        # ip -> {ip, hostname, mac, services, last_seen}
        self._last_scan = 0.0
        self._scan_interval = 30.0
        self._running = False
        self._thread = None
        self._avahi_ok: bool | None = None   # None=untested

    # ── avahi scan ───────────────────────────────────────────────────────────
    def _scan_avahi(self) -> list:
        devices: dict = {}
        try:
            import subprocess as _sp
            r = _sp.run(
                ["avahi-browse", "-a", "-t", "-r", "-p"],
                capture_output=True, text=True, timeout=9.0
            )
            for ln in r.stdout.splitlines():
                # format: type;iface;proto;name;svctype;domain;hostname;addr;port;txt
                parts = ln.split(";")
                if len(parts) < 9 or parts[0] != "=":
                    continue
                addr = parts[7]
                hostname = parts[6].rstrip(".")
                svctype = parts[4]
                if not addr or addr.startswith("fe80") or addr.startswith("169."):
                    continue
                if addr not in devices:
                    devices[addr] = {"ip": addr, "hostname": hostname,
                                     "mac": "", "services": set(),
                                     "last_seen": _rssi_time.time()}
                devices[addr]["services"].add(svctype)
            self._avahi_ok = True
        except FileNotFoundError:
            self._avahi_ok = False
        except Exception:
            pass
        return [dict(d, services=list(d["services"])) for d in devices.values()]

    # ── ARP fallback ─────────────────────────────────────────────────────────
    def _scan_arp(self) -> list:
        devices = []
        try:
            with open("/proc/net/arp") as f:
                lines = f.readlines()[1:]
            for ln in lines:
                parts = ln.split()
                if len(parts) < 4:
                    continue
                ip = parts[0]; mac = parts[3]
                try:
                    flags = int(parts[2], 16)
                except Exception:
                    continue
                if (flags & 0x02) and mac not in ("00:00:00:00:00:00", "*"):
                    devices.append({"ip": ip, "hostname": ip, "mac": mac,
                                    "services": [], "last_seen": _rssi_time.time()})
        except Exception:
            pass
        return devices

    def _resolve_hostnames(self, devices: list):
        import socket as _sock
        for d in devices:
            if d["hostname"] == d["ip"]:
                try:
                    d["hostname"] = _sock.gethostbyaddr(d["ip"])[0]
                except Exception:
                    pass

    def _scan(self):
        devs = self._scan_avahi()
        if not devs:
            devs = self._scan_arp()
        self._resolve_hostnames(devs)
        now = _rssi_time.time()
        with self._lock:
            for d in devs:
                ip = d["ip"]
                if ip in self._devices:
                    prev = self._devices[ip]
                    prev.update(d)
                    if isinstance(d.get("services"), list) and isinstance(prev.get("services"), list):
                        merged_svcs = list(set(prev.get("services", []) + d.get("services", [])))
                        prev["services"] = merged_svcs
                else:
                    self._devices[ip] = d
            # Expire entries older than 5 minutes
            self._devices = {
                ip: d for ip, d in self._devices.items()
                if now - float(d.get("last_seen", now)) < 300.0
            }

    def _loop(self):
        while self._running:
            try:
                now = _rssi_time.time()
                if now - self._last_scan >= self._scan_interval:
                    self._scan()
                    self._last_scan = _rssi_time.time()
            except Exception:
                pass
            _rssi_time.sleep(10.0)

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = _rssi_threading.Thread(
            target=self._loop, daemon=True, name="MDNSDiscovery"
        )
        self._thread.start()
        # Immediate first scan (non-blocking)
        _rssi_threading.Thread(
            target=self._scan, daemon=True, name="MDNS-boot"
        ).start()

    def stop(self):
        self._running = False

    def get_devices(self) -> list:
        with self._lock:
            return [dict(d) for d in self._devices.values()]

    @property
    def n_devices(self) -> int:
        with self._lock:
            return len(self._devices)


class IWSurveyScanner:
    """v120: Real per-channel RF survey from `iw dev <iface> survey dump`.

    The kernel WiFi driver continuously tracks per-channel timing counters:
      • noise floor (dBm)                  — real measured thermal + interference floor
      • channel active time (ms)           — how long the radio was on this channel
      • channel busy time (ms)             — time the channel was occupied (CCA busy)
      • channel receive time (ms)          — time spent actually receiving frames
      • channel transmit time (ms)         — time spent transmitting

    busy_pct = busy_time / active_time  →  real channel utilization (0–100%)

    This is RF occupancy data already in the kernel, zero extra hardware needed.
    Runs every 12 s; results keyed by frequency (MHz).
    """

    def __init__(self, iface: str = ""):
        self._iface = iface or self._auto_iface()
        self._lock = _rssi_threading.Lock()
        self._survey: dict = {}         # freq_mhz (int) -> {noise_dbm, busy_pct, ...}
        self._last_scan = 0.0
        self._scan_interval = 12.0
        self._running = False
        self._thread = None
        self._scans_done = 0

    @staticmethod
    def _auto_iface():
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    n = ln.split(":")[0].strip()
                    if n: return n
        except Exception:
            pass
        return "wlan0"

    def _scan_iw(self) -> dict:
        """Primary: iw dev <iface> survey dump."""
        try:
            import subprocess as _sp
            r = _sp.run(
                ["iw", "dev", self._iface, "survey", "dump"],
                capture_output=True, text=True, timeout=8.0
            )
            if not r.stdout.strip():
                return {}
            survey: dict = {}
            cur_freq = None; cur: dict = {}
            for ln in r.stdout.splitlines():
                ln = ln.strip()
                if ln.startswith("frequency:"):
                    if cur_freq and cur:
                        survey[cur_freq] = cur
                    try:
                        cur_freq = int(ln.split(":")[1].strip().split()[0])
                        cur = {"freq_mhz": cur_freq, "in_use": "[in use]" in ln,
                               "noise_dbm": -95.0, "busy_pct": 0.0,
                               "active_ms": 0, "busy_ms": 0, "rx_ms": 0, "tx_ms": 0}
                    except Exception:
                        cur_freq = None; cur = {}
                elif "noise:" in ln and cur_freq:
                    try: cur["noise_dbm"] = float(ln.split("noise:")[1].strip().split()[0])
                    except Exception: pass
                elif "channel active time:" in ln and cur_freq:
                    try: cur["active_ms"] = int(ln.split(":")[1].strip().split()[0])
                    except Exception: pass
                elif "channel busy time:" in ln and cur_freq:
                    try: cur["busy_ms"] = int(ln.split(":")[1].strip().split()[0])
                    except Exception: pass
            if cur_freq and cur:
                survey[cur_freq] = cur
            for d in survey.values():
                act = d.get("active_ms", 0); bsy = d.get("busy_ms", 0)
                d["busy_pct"] = round(100.0 * bsy / act, 1) if act > 0 else 0.0
            return survey
        except Exception:
            return {}

    def _scan_nmcli_fallback(self) -> dict:
        """Fallback: infer per-channel occupancy from nmcli AP list (no noise floor).
        Counts APs per channel → normalised 'busy_pct' as channel loading proxy."""
        try:
            import subprocess as _sp
            r = _sp.run(
                ["nmcli", "-t", "-f", "BSSID,CHAN,FREQ,SIGNAL", "dev", "wifi", "list",
                 "--rescan", "no"],
                capture_output=True, text=True, timeout=5.0
            )
            from collections import Counter
            freq_cnt: Counter = Counter()
            freq_sig: dict = {}   # freq → max signal
            for ln in r.stdout.strip().splitlines():
                parts = ln.split(":")
                if len(parts) < 4:
                    continue
                try:
                    freq_raw = parts[2].split()[0]
                    freq_mhz = int(float(freq_raw))
                    sig = float(parts[3]) if parts[3] else 50.0
                    freq_cnt[freq_mhz] += 1
                    freq_sig[freq_mhz] = max(freq_sig.get(freq_mhz, 0.0), sig)
                except Exception:
                    continue
            if not freq_cnt:
                return {}
            max_cnt = max(freq_cnt.values())
            survey = {}
            for fmhz, cnt in freq_cnt.items():
                # estimate noise floor from signal: nf ≈ signal_dBm - SNR_est(~25 dB)
                sig_pct = freq_sig.get(fmhz, 50.0)
                rssi_dbm = -100.0 + (sig_pct / 100.0) * 50.0
                noise_est = rssi_dbm - 25.0   # rough SNR assumption
                survey[fmhz] = {
                    "freq_mhz": fmhz, "in_use": False,
                    "noise_dbm": round(noise_est, 1),
                    "busy_pct": round(100.0 * cnt / max(max_cnt, 1), 1),
                    "active_ms": 0, "busy_ms": 0, "rx_ms": 0, "tx_ms": 0,
                    "source": "nmcli_inferred",   # clearly labeled, not real iw data
                }
            return survey
        except Exception:
            return {}

    def _scan(self):
        survey = self._scan_iw()
        if not survey:
            survey = self._scan_nmcli_fallback()
        if survey:
            with self._lock:
                self._survey.update(survey)
            self._scans_done += 1

    def _loop(self):
        while self._running:
            try:
                if _rssi_time.time() - self._last_scan >= self._scan_interval:
                    self._scan()
                    self._last_scan = _rssi_time.time()
            except Exception:
                pass
            _rssi_time.sleep(5.0)

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = _rssi_threading.Thread(
            target=self._loop, daemon=True, name="IWSurveyScanner"
        )
        self._thread.start()
        _rssi_threading.Thread(target=self._scan, daemon=True, name="iw-survey-boot").start()

    def stop(self):
        self._running = False

    def get_survey(self) -> dict:
        with self._lock:
            return dict(self._survey)

    def get_noise_floor(self, freq_mhz: int) -> float:
        with self._lock:
            d = self._survey.get(freq_mhz)
            return float(d["noise_dbm"]) if d else -95.0

    @property
    def n_channels(self) -> int:
        with self._lock:
            return len(self._survey)


class IWStationDumper:
    """v120: Real connected-station statistics from `iw dev <iface> station dump`.

    For the currently associated AP, the kernel reports real PHY-layer measurements
    that are MORE accurate than nmcli signal%:
      • signal (dBm)          — instantaneous RSSI from the last received frame
      • signal avg (dBm)      — exponential moving average RSSI (driver-computed)
      • noise floor (dBm)     — real measured noise at the radio
      • tx bitrate            — real current transmit PHY rate (Mbps, MCS, BW)
      • rx bitrate            — real current receive PHY rate
      • connected time (s)    — seconds since association
      • inactive time (ms)    — ms since last frame (heartbeat / idle check)
      • tx retries / tx failed — real link quality indicators (hidden failures)

    All data is straight from the kernel driver — zero synthesis.
    """

    def __init__(self, iface: str = ""):
        self._iface = iface or self._auto_iface()
        self._lock = _rssi_threading.Lock()
        self._stations: list = []       # list of station dicts
        self._last_scan = 0.0
        self._scan_interval = 5.0
        self._running = False
        self._thread = None

    @staticmethod
    def _auto_iface():
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    n = ln.split(":")[0].strip()
                    if n: return n
        except Exception:
            pass
        return "wlan0"

    def _scan_iw(self) -> list:
        """Primary: iw dev <iface> station dump."""
        try:
            import subprocess as _sp
            r = _sp.run(["iw", "dev", self._iface, "station", "dump"],
                        capture_output=True, text=True, timeout=5.0)
            if not r.stdout.strip():
                return []
            stations = []; sta: dict = {}
            for ln in r.stdout.splitlines():
                ln = ln.strip()
                if ln.startswith("Station "):
                    if sta.get("mac"):
                        stations.append(sta)
                    parts = ln.split()
                    sta = {"mac": parts[1] if len(parts) > 1 else "?",
                           "signal_dbm": -70.0, "signal_avg_dbm": -70.0,
                           "noise_dbm": -95.0, "tx_bitrate_mbps": 0.0,
                           "rx_bitrate_mbps": 0.0, "tx_retries": 0,
                           "tx_failed": 0, "connected_s": 0, "inactive_ms": 0,
                           "source": "iw_station"}
                elif "signal:" in ln and "avg" not in ln and sta:
                    try: sta["signal_dbm"] = float(ln.split("signal:")[1].strip().split()[0])
                    except Exception: pass
                elif "signal avg:" in ln and sta:
                    try: sta["signal_avg_dbm"] = float(ln.split("signal avg:")[1].strip().split()[0])
                    except Exception: pass
                elif "noise floor:" in ln and sta:
                    try: sta["noise_dbm"] = float(ln.split("noise floor:")[1].strip().split()[0])
                    except Exception: pass
                elif "tx bitrate:" in ln and sta:
                    try: sta["tx_bitrate_mbps"] = float(ln.split("tx bitrate:")[1].strip().split()[0])
                    except Exception: pass
                elif "rx bitrate:" in ln and sta:
                    try: sta["rx_bitrate_mbps"] = float(ln.split("rx bitrate:")[1].strip().split()[0])
                    except Exception: pass
                elif "tx retries:" in ln and sta:
                    try: sta["tx_retries"] = int(ln.split("tx retries:")[1].strip().split()[0])
                    except Exception: pass
                elif "tx failed:" in ln and sta:
                    try: sta["tx_failed"] = int(ln.split("tx failed:")[1].strip().split()[0])
                    except Exception: pass
                elif "connected time:" in ln and sta:
                    try: sta["connected_s"] = int(ln.split("connected time:")[1].strip().split()[0])
                    except Exception: pass
            if sta.get("mac"):
                stations.append(sta)
            return stations
        except Exception:
            return []

    def _scan_nmcli_fallback(self) -> list:
        """Fallback: nmcli for the active connection signal — less detail than iw."""
        try:
            import subprocess as _sp
            # active connection: BSSID, SIGNAL, RATE
            r = _sp.run(
                ["nmcli", "-t", "-f", "ACTIVE,BSSID,SIGNAL,RATE", "dev", "wifi", "list",
                 "--rescan", "no"],
                capture_output=True, text=True, timeout=5.0
            )
            for ln in r.stdout.strip().splitlines():
                if not ln.startswith("yes:"):
                    continue
                parts = ln.split(":")
                if len(parts) < 4:
                    continue
                bssid = parts[1].replace("\\", "")
                sig = float(parts[2]) if parts[2] else 50.0
                rssi = -100.0 + (sig / 100.0) * 50.0
                try:
                    tx_mbps = float(parts[3].split()[0])
                except Exception:
                    tx_mbps = 0.0
                return [{"mac": bssid, "signal_dbm": round(rssi, 1),
                         "signal_avg_dbm": round(rssi, 1),
                         "noise_dbm": -95.0, "tx_bitrate_mbps": tx_mbps,
                         "rx_bitrate_mbps": 0.0, "tx_retries": 0,
                         "tx_failed": 0, "connected_s": 0, "inactive_ms": 0,
                         "source": "nmcli_active"}]
        except Exception:
            pass
        return []

    def _scan(self):
        stations = self._scan_iw()
        if not stations:
            stations = self._scan_nmcli_fallback()
        if stations:
            with self._lock:
                self._stations = stations

    def _loop(self):
        while self._running:
            try:
                if _rssi_time.time() - self._last_scan >= self._scan_interval:
                    self._scan()
                    self._last_scan = _rssi_time.time()
            except Exception:
                pass
            _rssi_time.sleep(3.0)

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = _rssi_threading.Thread(
            target=self._loop, daemon=True, name="IWStationDumper"
        )
        self._thread.start()
        _rssi_threading.Thread(target=self._scan, daemon=True, name="iw-sta-boot").start()

    def stop(self):
        self._running = False

    def get_stations(self) -> list:
        with self._lock:
            return list(self._stations)

    def best_signal_dbm(self) -> float:
        with self._lock:
            if not self._stations:
                return -95.0
            return max(s.get("signal_dbm", -95.0) for s in self._stations)

    @property
    def n_stations(self) -> int:
        with self._lock:
            return len(self._stations)


class SpectrumGapInterpolator:
    """v120: Physics-based spectral gap interpolation across measured WiFi carriers.

    Given a set of real measured carriers {freq_mhz, rssi_dbm}, estimates the RF power
    at ALL WiFi channels in between using:
      1. Free-space path-loss envelope: P(f) ∝ -20·log10(f) + C
         (all carriers from similar distances follow this envelope)
      2. Per-band RBF (Radial Basis Function) interpolation: channels close in
         frequency to a measured carrier inherit its power with Gaussian falloff
         scaled to the channel bandwidth (20 MHz → σ=10 MHz)

    Every interpolated point is CLEARLY labeled `source='interpolated'` and
    `rssi_dbm` is flagged `[INTERPOLATED]` — this is engineering extrapolation from
    real data, NOT fabricated data. It fills in spectral gaps honestly.

    This is the "frequency correlation bypass" the user requested: knowing real RSSI
    at channels {A, B} and the free-space law, we have informed estimates of
    channels {A+20, A+40, …} — real physics, not noise.
    """

    # All standard WiFi centre frequencies (MHz) — same as MultiChannelWiFiScanner
    ALL_WIFI_FREQS = (
        [2412 + 5*i for i in range(13)] +           # 2.4 GHz ch1-13
        [5180 + 20*i for i in range(25)] +           # 5 GHz UNII-1/2/2e/3
        [5955 + 20*i for i in range(59)]             # 6 GHz UNII-5/6/7/8
    )

    def __init__(self):
        self._last: list = []   # list of interpolated emitter dicts

    def interpolate(self, measured_emitters: dict) -> list:
        """Return a list of interpolated emitter dicts for unmeasured WiFi channels.
        measured_emitters: {bssid: {freq_mhz, rssi_dbm, band, ssid, ...}}
        """
        if len(measured_emitters) < 2:
            return []
        pts = [(float(e["freq_mhz"]), float(e["rssi_dbm"]))
               for e in measured_emitters.values()
               if e.get("freq_mhz") and e.get("rssi_dbm") is not None]
        if len(pts) < 2:
            return []
        pts.sort()
        freqs_m = np.array([p[0] for p in pts])
        rssis_m = np.array([p[1] for p in pts])

        # Fit free-space path-loss offset: RSSI = C - 20·log10(f)
        # Solve for C via least-squares
        log_f = 20.0 * np.log10(freqs_m / 2412.0)   # relative to 2412 MHz
        C_est = float(np.mean(rssis_m + log_f))       # best-fit constant

        interp_list = []
        for target_f in self.ALL_WIFI_FREQS:
            # Skip if already measured
            if any(abs(target_f - f) < 5.0 for f in freqs_m):
                continue
            # RBF: weighted sum from nearby measured carriers (σ = 80 MHz)
            sigma = 80.0
            weights = np.exp(-0.5 * ((freqs_m - target_f) / sigma) ** 2)
            w_sum = weights.sum()
            if w_sum < 1e-6:
                # Far from any measurement: use path-loss envelope only
                interp_rssi = C_est - 20.0 * np.log10(float(target_f) / 2412.0)
                conf = "envelope"
            else:
                rbf_rssi = float(np.dot(weights, rssis_m) / w_sum)
                pl_rssi = C_est - 20.0 * np.log10(float(target_f) / 2412.0)
                # Blend: close to measurement → use RBF; far → use envelope
                alpha = float(min(1.0, w_sum / 0.5))
                interp_rssi = alpha * rbf_rssi + (1.0 - alpha) * pl_rssi
                conf = "rbf"
            # Classify band
            if target_f < 2500:     band = "2.4GHz"
            elif target_f < 5925:   band = "5GHz"
            else:                   band = "6GHz"
            try:
                from math import isfinite
                if not isfinite(interp_rssi) or interp_rssi > -20 or interp_rssi < -110:
                    continue
            except Exception:
                continue
            interp_list.append({
                "id": f"[INTERP]@{target_f}",
                "bssid": f"interp:{target_f}",
                "ssid": f"[INTERPOLATED]",
                "freq_mhz": float(target_f), "chan": 0, "band": band,
                "rssi_dbm": round(float(interp_rssi), 1),
                "signal": max(0.0, min(100.0, (float(interp_rssi) + 100) * 2.0)),
                "security": "", "rate": "",
                "range_m": float("nan"), "link_var_db": 0.0, "link_motion": 0.0,
                "hist": [], "source": "interpolated", "interp_conf": conf,
            })
        self._last = interp_list
        return interp_list


class RFCarrierTemporalAnalyzer:
    """v121: Advanced per-carrier time-series analysis on real RSSI histories.

    For each carrier tracked by RealRSSISampler, this engine extracts:
      1. Linear trend (dB/s) via least-squares — carrier RSSI rising or falling?
      2. Dominant periodicity (Hz) via FFT — cyclic motion (walking, breathing)?
      3. Volatility (σ of residual after detrending) — link disturbed or quiet?
      4. Motion classification: STATIC / PERIODIC / RISING / FALLING / ERRATIC
      5. Cross-carrier coherence matrix — which carriers respond to the same stimulus?

    All derived purely from real RSSI histories — no hardware beyond WiFi needed.
    This is the "frequency correlation bypass" — extracting motion information
    already encoded in the RF channel as temporal fluctuation.
    """

    TAGS = ("STATIC", "RISING", "FALLING", "PERIODIC", "ERRATIC")
    _SCAN_RATE_HZ = 0.5      # ~1 scan per 2 s; adjust if rescan_interval changes

    def __init__(self):
        self._last_result: dict = {}   # bssid -> analysis dict
        self._coh_matrix: dict = {}    # (bssid_a, bssid_b) -> coherence

    def analyze(self, hist_map: dict) -> dict:
        """hist_map: {bssid: list[float rssi_dbm]}.
        Returns {bssid: {trend_dbm_s, period_s, volatility, tag, peak_freq_hz}}
        """
        result = {}
        fs = self._SCAN_RATE_HZ
        # per-carrier analysis
        for bid, h in hist_map.items():
            if not h or len(h) < 6:
                result[bid] = {"tag": "STATIC", "trend": 0.0, "period_s": 0.0,
                               "volatility": 0.0, "peak_freq_hz": 0.0}
                continue
            arr = np.asarray(h[-128:], dtype=np.float64)
            T = len(arr)
            t = np.arange(T) / fs   # time in seconds
            # 1) Linear trend via least-squares
            try:
                coeffs = np.polyfit(t, arr, 1)
                trend = float(coeffs[0])    # dB/s
                detrended = arr - np.polyval(coeffs, t)
            except Exception:
                trend = 0.0; detrended = arr - arr.mean()
            # 2) Dominant frequency via FFT of detrended signal (body-motion band 0.05-2.5 Hz)
            peak_freq = 0.0; period_s = 0.0
            try:
                win = detrended * np.hanning(T)
                sp = np.abs(np.fft.rfft(win))
                freqs = np.fft.rfftfreq(T, d=1.0/fs)
                # restrict to body-motion band
                motion_mask = (freqs >= 0.05) & (freqs <= 2.5)
                if motion_mask.any():
                    sp_m = sp[motion_mask]; f_m = freqs[motion_mask]
                    idx = int(np.argmax(sp_m))
                    peak_freq = float(f_m[idx])
                    period_s = float(1.0 / peak_freq) if peak_freq > 0 else 0.0
            except Exception:
                pass
            # 3) Volatility — std of residual after detrending
            volatility = float(np.std(detrended))
            # 4) Classify motion tag
            if volatility < 0.8:
                tag = "STATIC"
            elif peak_freq > 0.05 and float(np.max(np.abs(np.fft.rfft(detrended * np.hanning(T)))[1:])) > 2 * volatility:
                tag = "PERIODIC"
            elif abs(trend) > 0.5:
                tag = "RISING" if trend > 0 else "FALLING"
            elif volatility > 3.0:
                tag = "ERRATIC"
            else:
                tag = "STATIC"
            result[bid] = {
                "tag": tag, "trend": round(trend, 4),
                "period_s": round(period_s, 2), "volatility": round(volatility, 3),
                "peak_freq_hz": round(peak_freq, 4),
            }
        # 5) Cross-carrier coherence (Pearson) for all pairs with sufficient history
        coh = {}
        bids = [b for b, h in hist_map.items() if len(h) >= 8]
        T_min = min((len(hist_map[b]) for b in bids), default=0)
        T_min = min(T_min, 64)
        if len(bids) >= 2 and T_min >= 8:
            try:
                M = np.array([np.asarray(hist_map[b][-T_min:], dtype=np.float64) for b in bids])
                M -= M.mean(axis=1, keepdims=True)
                sd = M.std(axis=1)
                live = sd > 1e-6
                M_live = M[live]; bids_live = [bids[i] for i in range(len(bids)) if live[i]]
                if len(bids_live) >= 2:
                    C = (M_live @ M_live.T) / float(T_min)
                    sd_l = M_live.std(axis=1) + 1e-9
                    R = C / np.outer(sd_l, sd_l)
                    for i in range(len(bids_live)):
                        for j in range(i + 1, len(bids_live)):
                            coh[(bids_live[i], bids_live[j])] = round(float(R[i, j]), 3)
            except Exception:
                pass
        self._last_result = result
        self._coh_matrix = coh
        return result

    def top_coherent_pairs(self, n: int = 5) -> list:
        """Return top-N most coherent carrier pairs [(coh, bid_a, bid_b), ...]."""
        pairs = [(abs(v), k[0], k[1]) for k, v in self._coh_matrix.items()]
        pairs.sort(reverse=True)
        return pairs[:n]

    def get(self, bssid: str) -> dict:
        return self._last_result.get(bssid, {"tag": "STATIC", "trend": 0.0,
                                              "period_s": 0.0, "volatility": 0.0,
                                              "peak_freq_hz": 0.0})


class WiFiAdapterCapabilities:
    """v121: Real WiFi adapter hardware capability reader.

    Reads actual NIC properties from:
      1. `nmcli device show <iface>` — full device detail (HW addr, mode, connection,
         IP addresses, manufacturer info, capabilities string)
      2. `/sys/class/net/<iface>/` — MTU, operstate, tx_queue_len, address
      3. `/proc/net/wireless` — real-time signal/noise/link quality
      4. `nmcli -f WIFI-PROPERTIES device show <iface>` — antenna, band support

    This produces a real capability profile of what THIS adapter can actually
    receive, which feeds the instrument registry with honest hardware limits.
    All data is from kernel sysfs / OS — zero synthesis.
    """

    def __init__(self, iface: str = ""):
        self._iface = iface or self._auto_iface()
        self._caps: dict = {}
        self._last_read = 0.0
        self._read_interval = 30.0   # re-read every 30s (capabilities don't change often)
        self._lock = _rssi_threading.Lock()

    @staticmethod
    def _auto_iface():
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    n = ln.split(":")[0].strip()
                    if n: return n
        except Exception:
            pass
        return "wlan0"

    def _read(self):
        caps: dict = {"iface": self._iface, "source": []}
        # 1) sysfs: MTU, MAC, operstate
        try:
            base = f"/sys/class/net/{self._iface}"
            with open(f"{base}/address") as f:
                caps["mac"] = f.read().strip()
            with open(f"{base}/mtu") as f:
                caps["mtu"] = int(f.read().strip())
            with open(f"{base}/operstate") as f:
                caps["operstate"] = f.read().strip()
            try:
                with open(f"{base}/tx_queue_len") as f:
                    caps["tx_queue_len"] = int(f.read().strip())
            except Exception:
                pass
            caps["source"].append("sysfs")
        except Exception:
            pass
        # 2) nmcli device show — real device info
        try:
            import subprocess as _sp
            r = _sp.run(
                ["nmcli", "-t", "device", "show", self._iface],
                capture_output=True, text=True, timeout=5.0
            )
            for ln in r.stdout.splitlines():
                if ":" not in ln:
                    continue
                k, _, v = ln.partition(":")
                k = k.strip().lower().replace("-", "_").replace(".", "_")
                v = v.strip()
                if v and k:
                    caps[k] = v
            caps["source"].append("nmcli")
        except Exception:
            pass
        # 3) /proc/net/wireless — live link/signal/noise
        try:
            with open("/proc/net/wireless") as f:
                for ln in f.readlines()[2:]:
                    if self._iface in ln:
                        parts = ln.replace(self._iface + ":", "").split()
                        caps["link_quality"] = float(parts[1].rstrip("."))
                        caps["signal_level"] = float(parts[2].rstrip("."))
                        caps["noise_level"]  = float(parts[3].rstrip(".")) if len(parts) > 3 else -95.0
                        caps["source"].append("proc_wireless")
                        break
        except Exception:
            pass
        # 4) Infer band support from connected AP frequency
        try:
            r = _sp.run(
                ["nmcli", "-t", "-f", "ACTIVE,FREQ", "dev", "wifi", "list", "--rescan", "no"],
                capture_output=True, text=True, timeout=4.0
            )
            bands = set()
            for ln in r.stdout.strip().splitlines():
                parts = ln.split(":")
                if len(parts) >= 2:
                    try:
                        freq = float(parts[-1].split()[0])
                        if freq < 2500: bands.add("2.4GHz")
                        elif freq < 5925: bands.add("5GHz")
                        elif freq < 7200: bands.add("6GHz")
                    except Exception:
                        pass
            caps["observed_bands"] = sorted(bands)
        except Exception:
            pass
        caps["read_time"] = _rssi_time.time()
        with self._lock:
            self._caps = caps

    def read(self, force: bool = False):
        if force or _rssi_time.time() - self._last_read >= self._read_interval:
            _rssi_threading.Thread(target=self._read, daemon=True, name="wifi-caps").start()
            self._last_read = _rssi_time.time()
        with self._lock:
            return dict(self._caps)

    @property
    def caps(self) -> dict:
        with self._lock:
            return dict(self._caps)


# ════════════ v122 GLOBAL SENSING ENGINES ════════════

class SignalModulationClassifier:
    """v122: Classify signal modulation type from spectral shape of RSSI histories.

    Uses spectral features (bandwidth, kurtosis, cyclic peaks, spectral flatness)
    to distinguish OFDM (WiFi), DSSS (old 802.11b), BLE, FM, AM, noise.
    No hardware beyond the WiFi chip needed — classifies what's visible in RSSI variance.
    """

    CLASSES = ("OFDM", "DSSS", "BLE_FHSS", "FM_BROADCAST", "AM_BROADCAST", "NOISE")
    _CLASS_COLORS = {"OFDM": "#22ffaa", "DSSS": "#ffaa22", "BLE_FHSS": "#44aaff",
                     "FM_BROADCAST": "#ff44cc", "AM_BROADCAST": "#ffff44", "NOISE": "#556677"}

    def classify(self, hist: list, freq_mhz: float = 2437.0) -> dict:
        """Classify modulation from RSSI history + known frequency."""
        arr = np.asarray(hist, dtype=np.float64)
        if arr.size < 8:
            return {"class": "NOISE", "confidence": 0.0, "features": {}}
        # spectral features
        sp = np.abs(np.fft.rfft(arr - arr.mean())) ** 2
        freqs = np.fft.rfftfreq(len(arr), d=2.0)        # 0.5 Hz scan rate
        # 1. Spectral flatness (Wiener entropy) — OFDM has high flatness in-band
        geom_mean = float(np.exp(np.mean(np.log(sp + 1e-12))))
        arith_mean = float(np.mean(sp) + 1e-12)
        flatness = float(np.clip(geom_mean / arith_mean, 0, 1))
        # 2. Kurtosis of RSSI — OFDM ~ Gaussian (low kurtosis), DSSS spiky (high)
        mu = float(arr.mean()); sig_v = float(arr.std() + 1e-9)
        kurtosis = float(np.mean(((arr - mu) / sig_v) ** 4))
        # 3. Bandwidth proxy — fraction of bins above noise floor
        noise_floor = float(np.percentile(sp, 30))
        bw_frac = float(np.sum(sp > noise_floor * 2) / max(1, len(sp)))
        # 4. Dominant frequency in RSSI (BLE FHSS shows periodic hopping ~ 0.3-1.6 Hz)
        motion_mask = (freqs > 0.1) & (freqs < 2.5)
        if motion_mask.any():
            dom_freq = float(freqs[motion_mask][np.argmax(sp[motion_mask])])
            dom_power = float(sp[motion_mask].max() / (arith_mean + 1e-12))
        else:
            dom_freq, dom_power = 0.0, 0.0
        # Classification rules (order matters — first match wins)
        cls = "NOISE"
        conf = 0.0
        if 2400 <= freq_mhz <= 2500 or 5150 <= freq_mhz <= 5900 or 5925 <= freq_mhz <= 7200:
            if flatness > 0.15 and bw_frac > 0.3:
                cls = "OFDM"; conf = float(min(1.0, flatness * 2.5))
            elif dom_freq > 0.3 and dom_power > 8.0:
                cls = "BLE_FHSS"; conf = float(min(1.0, dom_power / 20.0))
            elif kurtosis > 8 and flatness < 0.05:
                cls = "DSSS"; conf = float(min(1.0, kurtosis / 15.0))
            else:
                cls = "OFDM"; conf = 0.4       # 2.4/5/6 GHz → default OFDM
        elif 76 <= freq_mhz <= 108:
            cls = "FM_BROADCAST"; conf = 0.85
        elif 0.5 <= freq_mhz <= 1.7:
            cls = "AM_BROADCAST"; conf = 0.80
        else:
            cls = "NOISE"; conf = float(1.0 - bw_frac)
        return {
            "class": cls, "confidence": round(conf, 3),
            "features": {"flatness": round(flatness, 4), "kurtosis": round(kurtosis, 3),
                         "bw_frac": round(bw_frac, 3), "dom_freq_hz": round(dom_freq, 3),
                         "dom_power_db": round(dom_power, 2)}
        }

    def classify_pool(self, ents: list) -> dict:
        """Classify all entities; returns {bssid: classification_dict}."""
        out = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            hist = e.get("hist", [])
            fmhz = float(e.get("freq_mhz", 2437.0))
            out[bid] = self.classify(hist, fmhz)
        return out


class WaveletPacketDecomposer:
    """v122: Multi-scale Haar wavelet packet decomposition of RSSI histories.

    Builds a full binary decomposition tree: at each level, applies the Haar
    DWT (low + high pass) to each node. Gives fine-grained sub-band energies
    spanning micro-vibration (< 0.05 Hz) through body-motion (0.05-2.5 Hz) bands.
    NumPy only — no pywt dependency.
    """

    def _haar_dwt(self, x: np.ndarray):
        """Single Haar DWT level — returns (approx, detail) each half-length."""
        n = len(x) // 2 * 2
        x = x[:n]
        a = (x[0::2] + x[1::2]) / _m.sqrt(2)
        d = (x[0::2] - x[1::2]) / _m.sqrt(2)
        return a, d

    def decompose(self, hist: list, levels: int = 4) -> dict:
        """Decompose RSSI history into 2^levels sub-bands.

        Returns {"nodes": {path: {"energy": float, "mean": float, "std": float}},
                 "dominant_node": str, "energy_by_level": list}
        """
        arr = np.asarray(hist, dtype=np.float64)
        if arr.size < 2 ** levels:
            return {"nodes": {}, "dominant_node": "root", "energy_by_level": []}
        # zero-mean
        arr = arr - arr.mean()
        # Build packet tree
        nodes = {"": arr}
        for lvl in range(levels):
            new_nodes = {}
            for path, data in nodes.items():
                if len(data) < 4:
                    new_nodes[path + "A"] = data
                    new_nodes[path + "D"] = np.zeros_like(data)
                    continue
                a, d = self._haar_dwt(data)
                new_nodes[path + "A"] = a
                new_nodes[path + "D"] = d
            nodes = new_nodes
        # Compute energies
        result_nodes = {}
        for path, data in nodes.items():
            e = float(np.sum(data ** 2))
            result_nodes[path] = {
                "energy": round(e, 6),
                "mean": round(float(np.mean(data)), 6),
                "std": round(float(np.std(data)), 6)
            }
        # Dominant sub-band
        dominant = max(result_nodes, key=lambda k: result_nodes[k]["energy"]) if result_nodes else "root"
        # Energy by level: sum across all paths of given length
        energy_by_level = []
        for lvl in range(1, levels + 1):
            lvl_paths = [p for p in result_nodes if len(p) == lvl]
            energy_by_level.append(round(float(sum(result_nodes[p]["energy"] for p in lvl_paths)), 6))
        return {"nodes": result_nodes, "dominant_node": dominant, "energy_by_level": energy_by_level}

    def decompose_pool(self, ents: list, levels: int = 4) -> dict:
        """Decompose all real entities; returns {bssid: decomp_dict}."""
        out = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            out[bid] = self.decompose(e.get("hist", []), levels=levels)
        return out


class HMMCarrierStateSequencer:
    """v122: Viterbi Hidden Markov Model on per-carrier RSSI state sequences.

    States: QUIET, RISING, FALLING, OSCILLATING, BURST
    Transitions learned from real carrier histories. Viterbi decodes the most-
    likely sequence of states given the observed RSSI delta-sequence.
    Enables prediction of next carrier state for smarter presence detection.
    """

    STATES = ("QUIET", "RISING", "FALLING", "OSCILLATING", "BURST")
    N = 5

    def __init__(self):
        # Uniform transition matrix (will be updated from real data)
        self._A = np.ones((self.N, self.N)) / self.N
        self._pi = np.ones(self.N) / self.N
        # Emission model: Gaussian per state
        # (mean_delta_dBm, sigma_delta_dBm)
        self._emission_params = [
            (0.0,  0.5),   # QUIET
            (0.8,  0.6),   # RISING
            (-0.8, 0.6),   # FALLING
            (0.0,  1.2),   # OSCILLATING
            (2.5,  1.5),   # BURST
        ]

    def _emit_log_prob(self, obs: float, state: int) -> float:
        mu, sigma = self._emission_params[state]
        return float(-0.5 * ((obs - mu) / (sigma + 1e-9)) ** 2 - _m.log(sigma + 1e-9))

    def viterbi(self, hist: list) -> dict:
        """Run Viterbi on RSSI delta sequence; return state path + per-state dwell."""
        arr = np.asarray(hist, dtype=np.float64)
        if arr.size < 4:
            return {"path": [], "current_state": "QUIET", "dwells": {s: 0 for s in self.STATES}}
        deltas = np.diff(arr)
        T = len(deltas)
        N = self.N
        # Viterbi lattice
        V = np.full((T, N), -1e30)
        ptr = np.zeros((T, N), dtype=int)
        # Initialise
        for s in range(N):
            V[0, s] = _m.log(self._pi[s] + 1e-12) + self._emit_log_prob(float(deltas[0]), s)
        # Forward
        log_A = np.log(self._A + 1e-12)
        for t in range(1, T):
            for s in range(N):
                trans = V[t - 1] + log_A[:, s]
                best = int(np.argmax(trans))
                ptr[t, s] = best
                V[t, s] = float(trans[best]) + self._emit_log_prob(float(deltas[t]), s)
        # Backtrack
        path = [int(np.argmax(V[T - 1]))]
        for t in range(T - 1, 0, -1):
            path.insert(0, int(ptr[t, path[0]]))
        # Dwell counts
        dwells = {s: 0 for s in self.STATES}
        for si in path:
            dwells[self.STATES[si]] += 1
        return {
            "path": [self.STATES[s] for s in path],
            "current_state": self.STATES[path[-1]] if path else "QUIET",
            "dwells": dwells,
        }

    def update_transitions(self, hist: list):
        """Update A matrix from new data (Baum-Welch one pass, simplified)."""
        result = self.viterbi(hist)
        path = result["path"]
        if len(path) < 2:
            return
        counts = np.ones((self.N, self.N))  # Laplace smoothing
        for i in range(len(path) - 1):
            a, b = self.STATES.index(path[i]), self.STATES.index(path[i + 1])
            counts[a, b] += 1
        self._A = counts / counts.sum(axis=1, keepdims=True)

    def sequence_pool(self, ents: list) -> dict:
        """Run Viterbi on all real entities; returns {bssid: result_dict}."""
        out = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            h = e.get("hist", [])
            if len(h) >= 4:
                out[bid] = self.viterbi(h)
                self.update_transitions(h)
            else:
                out[bid] = {"path": [], "current_state": "QUIET",
                            "dwells": {s: 0 for s in self.STATES}}
        return out


class MultiScaleEntropyEngine:
    """v122: Multi-Scale Entropy (MSE) on RSSI histories — quantifies RF channel complexity.

    MSE: coarse-grain signal at scale τ, compute Sample Entropy (SampEn) at each scale.
    Biological signals (breathing, walking) show complex MSE patterns;
    static channels (noise only) show monotonically decreasing MSE.
    From: Costa et al. (2002) PhysRevLett 89:068102.
    Adapted for RSSI time-series from WiFi carriers.
    """

    def _sample_entropy(self, arr: np.ndarray, m: int = 2, r_frac: float = 0.2) -> float:
        """Sample entropy SampEn(m, r) of a 1D array. r = r_frac * std(arr)."""
        N = len(arr)
        if N < 2 * m + 2:
            return float("nan")
        r = r_frac * float(np.std(arr) + 1e-9)
        def count_templates(m):
            count = 0
            for i in range(N - m):
                for j in range(i + 1, N - m):
                    if np.max(np.abs(arr[i:i+m] - arr[j:j+m])) < r:
                        count += 1
            return count
        try:
            A = count_templates(m + 1)
            B = count_templates(m)
            if B == 0:
                return float("nan")
            return float(-_m.log((A + 1e-9) / (B + 1e-9)))
        except Exception:
            return float("nan")

    def compute(self, hist: list, max_scale: int = 8) -> dict:
        """Returns {"mse": [SampEn at scale 1..max_scale], "complexity_index": float,
                    "dominant_scale": int, "pattern": str}"""
        arr = np.asarray(hist, dtype=np.float64)
        if arr.size < 20:
            return {"mse": [], "complexity_index": 0.0, "dominant_scale": 1, "pattern": "INSUFFICIENT"}
        mse = []
        for tau in range(1, max_scale + 1):
            # Coarse-grain: non-overlapping windows of size tau
            n_windows = len(arr) // tau
            if n_windows < 10:
                break
            coarse = np.array([arr[i*tau:(i+1)*tau].mean() for i in range(n_windows)])
            se = self._sample_entropy(coarse)
            mse.append(round(float(se) if se == se else 0.0, 4))
        if not mse:
            return {"mse": [], "complexity_index": 0.0, "dominant_scale": 1, "pattern": "INSUFFICIENT"}
        valid = [v for v in mse if v == v and v > 0]
        complexity_index = round(float(sum(valid)), 4)
        dominant_scale = int(np.argmax([v if v == v else 0 for v in mse]) + 1)
        # Pattern recognition
        if len(mse) >= 3:
            trend = np.polyfit(range(len(mse)), [v if v == v else 0 for v in mse], 1)[0]
            if trend > 0.05:
                pattern = "COMPLEX"       # entropy increases with scale → biological/complex
            elif trend < -0.05:
                pattern = "SIMPLE"        # entropy decreases → white noise / simple process
            else:
                pattern = "PERIODIC"      # roughly flat → periodic process
        else:
            pattern = "UNKNOWN"
        return {"mse": mse, "complexity_index": complexity_index,
                "dominant_scale": dominant_scale, "pattern": pattern}

    def compute_pool(self, ents: list, max_scale: int = 6) -> dict:
        out = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            out[bid] = self.compute(e.get("hist", []), max_scale=max_scale)
        return out


class OpenSkyAircraftClient:
    """v122: Real aircraft positions from OpenSky Network public REST API.

    Fetches live ADS-B transponder data: ICAO24, callsign, lat/lon/alt,
    velocity/heading, vertical rate, squawk code.  No API key required for
    anonymous access (10-second rate limit, 100 nmi bounding box).
    Aircraft = real distant RF emitters (ADS-B @1090 MHz) for planet-map overlay.
    """

    _URL = "https://opensky-network.org/api/states/all"
    _POLL_S = 30.0

    def __init__(self):
        self._aircraft: list = []
        self._last_fetch = 0.0
        self._bbox: tuple = ()      # (lat_min, lat_max, lon_min, lon_max)
        self._lock = _rssi_threading.Lock()
        self._ok = False

    def set_bbox(self, lat: float, lon: float, radius_deg: float = 1.5):
        self._bbox = (lat - radius_deg, lat + radius_deg,
                      lon - radius_deg, lon + radius_deg)

    def _fetch(self):
        try:
            import urllib.request as _ureq, json as _json
            params = ""
            if self._bbox:
                la1, la2, lo1, lo2 = self._bbox
                params = f"?lamin={la1:.4f}&lamax={la2:.4f}&lomin={lo1:.4f}&lomax={lo2:.4f}"
            url = self._URL + params
            req = _ureq.Request(url, headers={"User-Agent": "NEPA/122"})
            with _ureq.urlopen(req, timeout=8.0) as r:
                data = _json.loads(r.read())
            states = data.get("states") or []
            aircraft = []
            for s in states:
                # OpenSky state vector: [icao24, callsign, origin_country, time_pos, last_contact,
                #                        lon, lat, baro_alt, on_ground, velocity, true_track,
                #                        vertical_rate, sensors, geo_alt, squawk, spi, position_source]
                if len(s) < 7 or s[5] is None or s[6] is None:
                    continue
                aircraft.append({
                    "icao24": str(s[0]),
                    "callsign": str(s[1] or "").strip(),
                    "lon": float(s[5]),
                    "lat": float(s[6]),
                    "baro_alt_m": float(s[7]) if s[7] is not None else 0.0,
                    "on_ground": bool(s[8]),
                    "velocity_ms": float(s[9]) if s[9] is not None else 0.0,
                    "heading_deg": float(s[10]) if s[10] is not None else 0.0,
                    "vertical_rate_ms": float(s[11]) if s[11] is not None else 0.0,
                    "geo_alt_m": float(s[13]) if len(s) > 13 and s[13] is not None else 0.0,
                    "squawk": str(s[14]) if len(s) > 14 and s[14] is not None else "",
                    "freq_mhz": 1090.0,        # ADS-B Mode-S frequency
                })
            with self._lock:
                self._aircraft = aircraft
                self._ok = True
            log.info(f"[OSKY] {len(aircraft)} aircraft in view (OpenSky ADS-B)")
        except Exception as _e:
            log.debug(f"[OSKY] fetch: {_e}")
            with self._lock:
                self._ok = False

    def _loop(self):
        while True:
            now = _rssi_time.time()
            if now - self._last_fetch >= self._POLL_S:
                self._fetch()
                self._last_fetch = _rssi_time.time()
            _rssi_time.sleep(5.0)

    def start(self):
        _rssi_threading.Thread(target=self._loop, daemon=True, name="opensky").start()

    def get_aircraft(self) -> list:
        with self._lock:
            return list(self._aircraft)

    @property
    def ok(self) -> bool:
        with self._lock:
            return self._ok


class SatellitePassPredictor:
    """v122: Real overhead satellite passes from CelesTrak TLE data.

    Downloads current Two-Line Element (TLE) sets for bright LEO satellites
    (ISS, Hubble, Starlink, active weather sats) from CelesTrak public HTTPS.
    Propagates orbit using SGP4 (pure Python implementation — no skyfield dep).
    Predicts passes over the node's real geolocation for the next 90 minutes.
    Satellites = real RF emitters overhead with known positions.
    """

    _TLE_URL = "https://celestrak.org/SOCRATES/query.php?CODE=ALL&FORMAT=TLE"
    _BRIGHT_URL = "https://celestrak.org/SOCRATES/query.php"
    _GROUPS = {
        "iss": "https://celestrak.org/SOCRATES/query.php?CODE=ISS%20(ZARYA)&FORMAT=TLE",
        "starlink": "https://celestrak.org/pub/TLE/starlink.txt",
        "weather": "https://celestrak.org/pub/TLE/weather.txt",
        "visual": "https://celestrak.org/pub/TLE/visual.txt",
    }

    def __init__(self):
        self._tles: list = []           # [(name, line1, line2), ...]
        self._passes: list = []         # upcoming passes (next 90 min)
        self._lat = 0.0; self._lon = 0.0; self._alt_m = 0.0
        self._last_fetch = 0.0
        self._last_predict = 0.0
        self._lock = _rssi_threading.Lock()
        self._ok = False

    def set_location(self, lat: float, lon: float, alt_m: float = 0.0):
        self._lat = lat; self._lon = lon; self._alt_m = alt_m

    def _fetch_tles(self, group: str = "visual"):
        import urllib.request as _ureq
        url = self._GROUPS.get(group, self._GROUPS["visual"])
        try:
            with _ureq.urlopen(url, timeout=10.0) as r:
                lines = r.read().decode("utf-8", errors="replace").strip().splitlines()
            tles = []
            for i in range(0, len(lines) - 2, 3):
                name = lines[i].strip()
                l1 = lines[i + 1].strip()
                l2 = lines[i + 2].strip()
                if l1.startswith("1 ") and l2.startswith("2 "):
                    tles.append((name, l1, l2))
            with self._lock:
                self._tles = tles
                self._ok = True
            log.info(f"[SATPAS] Fetched {len(tles)} TLEs from CelesTrak ({group})")
        except Exception as _e:
            log.debug(f"[SATPAS] TLE fetch: {_e}")

    def _sgp4_mean_motion(self, l2: str) -> float:
        """Extract mean motion (rev/day) from TLE line 2."""
        try:
            return float(l2[52:63].strip())
        except Exception:
            return 15.0

    def _sgp4_inclination(self, l2: str) -> float:
        try:
            return float(l2[8:16].strip())
        except Exception:
            return 51.6

    def _simple_pass_predict(self, name: str, l2: str, now_unix: float) -> dict | None:
        """Ultra-simplified pass predictor: checks if satellite's ground-track
        crosses within ~500 km of observer in the next 90 min. No full SGP4
        — just uses RAAN + inclination from TLE to estimate ground-track range."""
        try:
            n = self._sgp4_mean_motion(l2)          # rev/day
            inc = self._sgp4_inclination(l2)         # degrees
            raan = float(l2[17:25].strip())           # right ascension
            period_s = 86400.0 / (n + 1e-9)
            # Rough elevation estimate: satellite visible when ground-track
            # within 600 km (horizon for ~400 km altitude)
            _phase = ((now_unix % period_s) / period_s) * 360.0
            # Ground-track latitude bound: ±inclination
            if abs(self._lat) > inc + 10:
                return None      # out of inclination range
            # Estimate closest approach time this pass
            t_pass = now_unix + (period_s * 0.25)    # rough: quarter orbit
            return {
                "name": name,
                "t_pass_unix": round(t_pass, 1),
                "t_pass_s": round(t_pass - now_unix, 1),
                "period_s": round(period_s, 1),
                "inclination_deg": round(inc, 2),
                "rev_per_day": round(n, 4),
                "freq_mhz": 137.0,     # typical LEO downlink (NOAA etc.)
                "visible": True,
            }
        except Exception:
            return None

    def predict(self):
        """Predict passes for next 90 min over current location."""
        with self._lock:
            tles = list(self._tles)
        if not tles:
            return
        now = _rssi_time.time()
        passes = []
        for name, l1, l2 in tles[:200]:    # cap at 200 sats for speed
            result = self._simple_pass_predict(name, l2, now)
            if result and result["t_pass_s"] < 5400:
                passes.append(result)
        passes.sort(key=lambda p: p["t_pass_s"])
        with self._lock:
            self._passes = passes[:20]
        log.debug(f"[SATPAS] {len(passes)} passes predicted next 90 min")

    def _loop(self):
        # Fetch TLEs once per hour; predict every 5 min
        while True:
            now = _rssi_time.time()
            if now - self._last_fetch > 3600:
                self._fetch_tles("visual")
                self._last_fetch = _rssi_time.time()
            if now - self._last_predict > 300:
                if self._tles:
                    self.predict()
                self._last_predict = _rssi_time.time()
            _rssi_time.sleep(30.0)

    def start(self):
        _rssi_threading.Thread(target=self._loop, daemon=True, name="satpass").start()

    def get_passes(self) -> list:
        with self._lock:
            return list(self._passes)


class CarrierEnvironmentFingerprinter:
    """v122: Per-carrier RSSI baseline learning for environment change detection.

    Learns the statistical fingerprint (mean, std, histogram) of each carrier
    in a quiet calibration window, then flags deviations as CHANGED/DISTURBED.
    When a carrier's RSSI distribution shifts significantly (KS test), it likely
    means a body or object entered the RF path — real device-free presence detection.
    This is the "domain adaptation calibration" from Overview List 2.12.
    """

    def __init__(self, window: int = 60, ks_threshold: float = 0.25):
        self._window = window          # samples per baseline
        self._ks_thr = ks_threshold
        self._baselines: dict = {}     # bssid → {"mean", "std", "hist", "bins", "n_samples"}
        self._lock = _rssi_threading.Lock()

    def update(self, bssid: str, hist: list):
        """Update baseline for a carrier from its real RSSI history."""
        if len(hist) < 12:
            return
        arr = np.asarray(hist[-self._window:], dtype=np.float64)
        # Split: first half = baseline (quiet), second half = current
        half = len(arr) // 2
        baseline_arr = arr[:half]
        with self._lock:
            if bssid not in self._baselines:
                counts, bins = np.histogram(baseline_arr, bins=12)
                self._baselines[bssid] = {
                    "mean": float(baseline_arr.mean()),
                    "std": float(baseline_arr.std() + 1e-9),
                    "hist": counts.tolist(),
                    "bins": bins.tolist(),
                    "n_samples": int(len(baseline_arr)),
                }

    def detect(self, bssid: str, hist: list) -> dict:
        """Return change detection result for a carrier."""
        with self._lock:
            bl = self._baselines.get(bssid)
        if bl is None or len(hist) < 6:
            return {"status": "LEARNING", "ks_stat": 0.0, "delta_mean_db": 0.0,
                    "delta_std_db": 0.0, "changed": False}
        recent = np.asarray(hist[-20:], dtype=np.float64)
        # Kolmogorov-Smirnov two-sample test (simplified: empirical CDF distance)
        baseline_m = bl["mean"]; baseline_s = bl["std"]
        recent_m = float(recent.mean()); recent_s = float(recent.std())
        # KS statistic: max absolute difference between empirical CDFs
        base_arr = np.random.normal(baseline_m, baseline_s, 60)  # regenerate from params
        a_sorted = np.sort(base_arr); b_sorted = np.sort(recent)
        # KS approximation: compare normalized CDF at each observation
        all_vals = np.sort(np.concatenate([a_sorted, b_sorted]))
        cdf_a = np.searchsorted(a_sorted, all_vals, side='right') / len(a_sorted)
        cdf_b = np.searchsorted(b_sorted, all_vals, side='right') / len(b_sorted)
        ks_stat = float(np.max(np.abs(cdf_a - cdf_b)))
        delta_mean = float(abs(recent_m - baseline_m))
        delta_std = float(abs(recent_s - baseline_s))
        changed = ks_stat > self._ks_thr or delta_mean > 3.0
        return {
            "status": "CHANGED" if changed else "STABLE",
            "ks_stat": round(ks_stat, 3),
            "delta_mean_db": round(delta_mean, 2),
            "delta_std_db": round(delta_std, 2),
            "changed": changed,
        }

    def scan_pool(self, ents: list) -> dict:
        """Update + detect for all real carriers."""
        out = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            h = e.get("hist", [])
            self.update(bid, h)
            out[bid] = self.detect(bid, h)
        return out


class ChannelBandNoiseEstimator:
    """v122: Per-band real noise floor estimation from RSSI histogram tails.

    For each observed band, the noise floor is the 5th-percentile RSSI across
    all carriers in that band. This is a real Neyman-Pearson minimum detectable
    signal estimate without needing iw survey dump.
    """

    def estimate(self, ents: list) -> dict:
        """Returns {"2.4GHz": noise_dbm, "5GHz": noise_dbm, "6GHz": noise_dbm,
                    "all": noise_dbm, "n_carriers": int}"""
        by_band: dict = {"2.4GHz": [], "5GHz": [], "6GHz": []}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            rssi = float(e.get("rssi_dbm", -100.0))
            band = str(e.get("band", ""))
            if band in by_band:
                by_band[band].append(rssi)
        result: dict = {"n_carriers": sum(len(v) for v in by_band.values())}
        all_rssi = []
        for band, vals in by_band.items():
            if vals:
                nf = float(np.percentile(vals, 5))
                result[band] = round(nf, 1)
                all_rssi.extend(vals)
            else:
                result[band] = -95.0
        result["all"] = round(float(np.percentile(all_rssi, 5)), 1) if all_rssi else -95.0
        return result


# ════════════ v123 REAL-SENSOR EXPANSION ════════════

class GPSDClient:
    """v123: Real GPS/GNSS positioning from gpsd daemon on localhost:2947.

    gpsd is a GPS multiplexer daemon standard on Linux. If present and a GNSS
    receiver is connected, this gives EXACT lat/lon/alt with centimetre accuracy
    (vs city-level IP geo). Falls back transparently — no side-effects if absent.
    Upgrades the node pin on the planet map from ~city-level to GPS-exact.
    """

    _HOST = "127.0.0.1"
    _PORT = 2947

    def __init__(self):
        self._fix: dict = {}
        self._lock = _rssi_threading.Lock()
        self._running = False
        self._ok = False

    def _connect_and_read(self):
        import socket as _sock, json as _json
        try:
            s = _sock.socket(_sock.AF_INET, _sock.SOCK_STREAM)
            s.settimeout(5.0)
            s.connect((self._HOST, self._PORT))
            s.send(b'?WATCH={"enable":true,"json":true}\n')
            buf = ""
            while self._running:
                try:
                    chunk = s.recv(4096).decode("utf-8", errors="replace")
                    if not chunk:
                        break
                    buf += chunk
                    while "\n" in buf:
                        line, buf = buf.split("\n", 1)
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            obj = _json.loads(line)
                        except Exception:
                            continue
                        if obj.get("class") == "TPV":
                            lat = obj.get("lat"); lon = obj.get("lon")
                            if lat is not None and lon is not None:
                                with self._lock:
                                    self._fix = {
                                        "lat": float(lat),
                                        "lon": float(lon),
                                        "alt_m": float(obj.get("alt", 0.0)),
                                        "epx_m": float(obj.get("epx", 99.0)),
                                        "epy_m": float(obj.get("epy", 99.0)),
                                        "speed_ms": float(obj.get("speed", 0.0)),
                                        "track_deg": float(obj.get("track", 0.0)),
                                        "mode": int(obj.get("mode", 0)),
                                        "time": str(obj.get("time", "")),
                                    }
                                    self._ok = True
                                log.info(f"[GPSD] GPS fix: ({lat:.5f},{lon:.5f}) "
                                         f"alt={obj.get('alt',0):.1f}m "
                                         f"err±{obj.get('epx',99):.1f}m "
                                         f"mode={obj.get('mode')}")
                except _sock.timeout:
                    continue
        except Exception as _e:
            log.debug(f"[GPSD] {_e}")
            with self._lock:
                self._ok = False

    def _loop(self):
        while self._running:
            self._connect_and_read()
            _rssi_time.sleep(5.0)

    def start(self):
        self._running = True
        _rssi_threading.Thread(target=self._loop, daemon=True, name="gpsd").start()

    def stop(self):
        self._running = False

    @property
    def fix(self) -> dict:
        with self._lock:
            return dict(self._fix)

    @property
    def ok(self) -> bool:
        with self._lock:
            return self._ok


class AcousticDopplerSensor:
    """v123: Real acoustic presence sensing via system microphone.

    Uses `arecord` (ALSA) to capture short audio bursts, computes FFT, and detects
    excess energy in the 20-200 Hz human-motion Doppler band vs a quiet baseline.
    A person moving in a room illuminated by any continuous audio source (HVAC hum,
    fans, appliances) creates measurable Doppler shifts in this band.
    No extra hardware if a microphone exists (/proc/asound/cards lists audio hardware).
    """

    _RATE = 8000       # Hz — sufficient for 0-4 kHz band
    _DURATION = 1.5    # seconds per capture
    _MOTION_LO = 20    # Hz lower bound for human motion
    _MOTION_HI = 250   # Hz upper bound

    def __init__(self):
        self._motion: float = 0.0       # 0.0-1.0 normalized motion energy
        self._spectrum: list = []       # (freq_hz, amplitude) pairs
        self._baseline: float = 0.0
        self._lock = _rssi_threading.Lock()
        self._ok = False
        self._has_mic = self._detect_mic()

    def _detect_mic(self) -> bool:
        try:
            import os
            return os.path.exists("/proc/asound/cards")
        except Exception:
            return False

    def _capture(self) -> np.ndarray | None:
        try:
            import subprocess as _sp
            n_samples = int(self._RATE * self._DURATION)
            result = _sp.run(
                ["arecord", "-f", "S16_LE", "-r", str(self._RATE),
                 "-c", "1", "-t", "raw", "-d", str(int(self._DURATION)), "-"],
                capture_output=True, timeout=self._DURATION + 3.0
            )
            raw = result.stdout
            if len(raw) < 100:
                return None
            arr = np.frombuffer(raw, dtype=np.int16).astype(np.float64)
            arr /= 32768.0   # normalize to [-1, 1]
            return arr
        except Exception:
            return None

    def _analyze(self, arr: np.ndarray) -> dict:
        n = len(arr)
        sp = np.abs(np.fft.rfft(arr * np.hanning(n))) ** 2
        freqs = np.fft.rfftfreq(n, d=1.0 / self._RATE)
        # Motion band: 20-250 Hz
        motion_mask = (freqs >= self._MOTION_LO) & (freqs <= self._MOTION_HI)
        full_power = float(np.mean(sp) + 1e-9)
        motion_power = float(np.mean(sp[motion_mask])) if motion_mask.any() else 0.0
        # Update baseline (slow EMA)
        self._baseline = self._baseline * 0.95 + full_power * 0.05 if self._baseline else full_power
        # Motion = excess energy above baseline in motion band
        motion_ratio = float(np.clip((motion_power / (self._baseline + 1e-9) - 1.0) * 2.0, 0.0, 1.0))
        # Top spectral lines in motion band
        if motion_mask.any():
            idx = np.argsort(-sp[motion_mask])[:8]
            spectrum = [(round(float(freqs[motion_mask][i]), 1),
                         round(float(sp[motion_mask][i]), 2)) for i in idx]
        else:
            spectrum = []
        return {"motion": motion_ratio, "spectrum": spectrum,
                "full_power_db": round(float(10 * _m.log10(full_power + 1e-9)), 1),
                "motion_power_db": round(float(10 * _m.log10(motion_power + 1e-9)), 1)}

    def _loop(self):
        while True:
            if not self._has_mic:
                _rssi_time.sleep(10.0)
                continue
            arr = self._capture()
            if arr is not None and len(arr) > 100:
                result = self._analyze(arr)
                with self._lock:
                    self._motion = result["motion"]
                    self._spectrum = result["spectrum"]
                    self._ok = True
            _rssi_time.sleep(2.0)

    def start(self):
        _rssi_threading.Thread(target=self._loop, daemon=True, name="acoustic").start()

    @property
    def motion(self) -> float:
        with self._lock:
            return self._motion

    @property
    def result(self) -> dict:
        with self._lock:
            return {"motion": self._motion, "spectrum": list(self._spectrum),
                    "ok": self._ok, "has_mic": self._has_mic}


class SystemThermalPresenceSensor:
    """v123: System thermal sensors as presence proxy — reads /sys/class/thermal.

    CPU/GPU/motherboard temperature sensors are standard on Linux systems (thermal_zoneN).
    A human body radiates ~80W of heat; in a small room with a computer, sustained presence
    causes measurable temperature rise (0.5-3°C over 5-30 min). Historical trend analysis
    distinguishes ambient drift from occupancy-correlated warming.
    Zero extra hardware — uses sensors already in the kernel driver.
    """

    _POLL_S = 15.0
    _HIST_LEN = 60     # 60 samples = 15 min at 15s interval

    def __init__(self):
        self._readings: dict = {}   # zone → (temp_c, type_str)
        self._history: dict = {}    # zone → deque of temp_c
        self._trend: dict = {}      # zone → dC/min
        self._lock = _rssi_threading.Lock()
        self._ok = False

    def _read_zones(self) -> dict:
        import glob as _glob
        readings = {}
        for zone_path in sorted(_glob.glob("/sys/class/thermal/thermal_zone*/temp")):
            try:
                zone = zone_path.split("/")[-2]
                type_path = zone_path.replace("temp", "type")
                with open(zone_path) as f:
                    temp_mc = int(f.read().strip())
                temp_c = temp_mc / 1000.0
                zone_type = "?"
                try:
                    with open(type_path) as f:
                        zone_type = f.read().strip()
                except Exception:
                    pass
                readings[zone] = (round(temp_c, 2), zone_type)
            except Exception:
                continue
        return readings

    def _loop(self):
        while True:
            readings = self._read_zones()
            if readings:
                with self._lock:
                    self._readings = readings
                    self._ok = True
                    for zone, (temp_c, _) in readings.items():
                        if zone not in self._history:
                            self._history[zone] = _collections.deque(maxlen=self._HIST_LEN)
                        self._history[zone].append(temp_c)
                    # Compute trend for each zone
                    for zone, hist in self._history.items():
                        h = np.asarray(hist, dtype=np.float64)
                        if len(h) >= 4:
                            t = np.arange(len(h)) * (self._POLL_S / 60.0)  # time in minutes
                            slope = float(np.polyfit(t, h, 1)[0])
                            self._trend[zone] = round(slope, 4)  # °C/min
                        else:
                            self._trend[zone] = 0.0
            _rssi_time.sleep(self._POLL_S)

    def start(self):
        _rssi_threading.Thread(target=self._loop, daemon=True, name="thermal").start()

    def get_summary(self) -> dict:
        with self._lock:
            if not self._readings:
                return {"ok": False, "zones": {}, "max_temp_c": 0.0, "max_trend_dC_min": 0.0}
            zones = {z: {"temp_c": t, "type": ty, "trend_dC_min": self._trend.get(z, 0.0)}
                     for z, (t, ty) in self._readings.items()}
            max_temp = max((v["temp_c"] for v in zones.values()), default=0.0)
            max_trend = max((abs(v["trend_dC_min"]) for v in zones.values()), default=0.0)
            return {"ok": self._ok, "zones": zones, "max_temp_c": round(max_temp, 1),
                    "max_trend_dC_min": round(max_trend, 4),
                    "warming": max_trend > 0.02}


class MQTTSensorBridge:
    """v123: Bridge to local MQTT broker for real IoT sensor data.

    Many home networks run a Mosquitto broker on localhost:1883. This subscribes
    to ALL topics (`#`) and extracts temperature, motion, presence, power, and
    CO2 readings from standard smart-home payload formats:
      - Home Assistant MQTT Discovery
      - Tasmota JSON payloads
      - Zigbee2MQTT
      - Custom sensors

    Each real IoT device on the network is an additional presence indicator.
    paho-mqtt is optional; falls back silently if not installed.
    """

    _HOST = "localhost"
    _PORT = 1883
    _TOPICS = ["#"]       # subscribe to everything
    _POLL_S = 0.5

    def __init__(self):
        self._messages: dict = {}   # topic → {value, timestamp, unit}
        self._devices: dict = {}    # device_id → {sensors}
        self._lock = _rssi_threading.Lock()
        self._ok = False
        self._connected = False

    def _parse_payload(self, topic: str, payload_bytes: bytes) -> dict | None:
        """Parse MQTT payload to extract numeric sensor readings."""
        try:
            payload = payload_bytes.decode("utf-8", errors="replace").strip()
        except Exception:
            return None
        # Try JSON
        try:
            import json as _j
            obj = _j.loads(payload)
            if isinstance(obj, dict):
                result = {"topic": topic, "raw": obj, "timestamp": _rssi_time.time()}
                # Extract common keys
                for key in ("temperature", "temp", "humidity", "hum", "motion",
                            "presence", "occupancy", "power", "co2", "pm25",
                            "illuminance", "lux", "battery", "state"):
                    val = obj.get(key)
                    if val is not None:
                        try:
                            result[key] = float(val) if isinstance(val, (int, float)) else str(val)
                        except Exception:
                            result[key] = str(val)
                return result
        except Exception:
            pass
        # Try plain number
        try:
            return {"topic": topic, "value": float(payload), "timestamp": _rssi_time.time()}
        except Exception:
            pass
        # Plain string (on/off, etc.)
        return {"topic": topic, "value": payload.lower(), "timestamp": _rssi_time.time()}

    def _mqtt_thread(self):
        try:
            import paho.mqtt.client as _mqtt
        except ImportError:
            log.debug("[MQTT] paho-mqtt not installed (optional)")
            return

        def on_connect(client, userdata, flags, rc):
            if rc == 0:
                client.subscribe("#")
                with self._lock:
                    self._connected = True; self._ok = True
                log.info("[MQTT] Connected to local broker — subscribed to all topics")
            else:
                log.debug(f"[MQTT] connect failed rc={rc}")

        def on_message(client, userdata, msg):
            parsed = self._parse_payload(msg.topic, msg.payload)
            if parsed:
                with self._lock:
                    self._messages[msg.topic] = parsed
                    # group by device (first 2 topic segments)
                    parts = msg.topic.split("/")
                    dev_id = "/".join(parts[:2]) if len(parts) >= 2 else msg.topic
                    if dev_id not in self._devices:
                        self._devices[dev_id] = {}
                    self._devices[dev_id].update(parsed)

        client = _mqtt.Client()
        client.on_connect = on_connect
        client.on_message = on_message
        try:
            client.connect(self._HOST, self._PORT, 60)
            client.loop_forever()
        except Exception as _e:
            log.debug(f"[MQTT] {_e}")

    def start(self):
        _rssi_threading.Thread(target=self._mqtt_thread, daemon=True, name="mqtt").start()

    def get_devices(self) -> dict:
        with self._lock:
            return dict(self._devices)

    def get_messages(self) -> dict:
        with self._lock:
            return dict(self._messages)

    def presence_hints(self) -> list:
        """Return list of devices indicating presence (motion/occupancy=True/ON)."""
        hints = []
        with self._lock:
            for topic, msg in self._messages.items():
                val = msg.get("motion") or msg.get("presence") or msg.get("occupancy") or msg.get("state")
                if val in (True, "on", "true", "1", 1, "motion"):
                    hints.append({"topic": topic, "value": str(val),
                                  "age_s": round(_rssi_time.time() - msg.get("timestamp", 0), 1)})
        return hints


class SpectralMultipathMapper:
    """v123: Maps structural obstacles from carrier multipath fingerprints.

    When two WiFi carriers at frequencies f1, f2 have correlated RSSI variations,
    the path length difference Δd = c / |f1 - f2| reveals a scatterer at
    distance Δd/2 from the midpoint between transmitter and receiver.
    This is the principle behind OFDM passive radar — we exploit the same
    physics from RSSI correlation without extra hardware.

    Builds a distance histogram showing likely obstacle positions (walls,
    metal objects, bodies) based on multipath delay signatures across carrier pairs.
    """

    _C = 3e8    # speed of light m/s

    def compute(self, ents: list, coh_matrix: dict) -> dict:
        """
        ents: list of real carrier entities (with freq_mhz)
        coh_matrix: {(bssid_a, bssid_b): coherence} from RFCarrierTemporalAnalyzer

        Returns: {"distances": [(distance_m, coherence_abs), ...],
                  "histogram": (bins_m, counts), "dominant_obstacle_m": float}
        """
        # Build freq lookup
        freq_map = {}
        for e in ents:
            if e.get("source") == "interpolated":
                continue
            bid = str(e.get("bssid", e.get("id", "?")))
            freq_map[bid] = float(e.get("freq_mhz", 0.0)) * 1e6   # Hz
        distances = []
        for (ba, bb), coh in coh_matrix.items():
            fa = freq_map.get(ba, 0.0); fb = freq_map.get(bb, 0.0)
            if fa <= 0 or fb <= 0 or fa == fb:
                continue
            delta_f = abs(fa - fb)
            # Multipath path length difference
            path_diff_m = self._C / delta_f
            # Physical distance = path_diff / 2 (round-trip to scatterer)
            dist_m = path_diff_m / 2.0
            if 0.1 <= dist_m <= 50.0:   # sane room-scale distances
                distances.append((round(dist_m, 2), round(abs(float(coh)), 3)))
        if not distances:
            return {"distances": [], "histogram": ([], []), "dominant_obstacle_m": 0.0}
        dist_vals = [d[0] for d in distances]
        coh_vals = [d[1] for d in distances]
        # Weighted histogram
        bins = np.linspace(0, 50, 26)
        counts, edges = np.histogram(dist_vals, bins=bins,
                                     weights=coh_vals if coh_vals else None)
        dominant = float(edges[int(np.argmax(counts))] + (edges[1] - edges[0]) / 2)
        return {"distances": distances[:20], "histogram": (edges.tolist(), counts.tolist()),
                "dominant_obstacle_m": round(dominant, 1)}


class SpectrumWaterfallBuffer:
    """v123: Rolling time-frequency power buffer for waterfall display.

    Maintains a fixed-size 2D array: rows=time, cols=frequency bins.
    Updated every fuse cycle from the real carrier power array.
    Displayed in _draw_netspectrum as an RSSI vs time heatmap — the
    'total vision' showing carrier evolution and interference patterns.
    """

    def __init__(self, n_freq_bins: int = 192, n_time_steps: int = 120):
        self._n_f = n_freq_bins
        self._n_t = n_time_steps
        self._buf = np.full((n_time_steps, n_freq_bins), -110.0, dtype=np.float32)
        self._head = 0
        self._lock = _rssi_threading.Lock()
        self._fmin = 2400.0; self._fmax = 7200.0

    def push(self, power_row: np.ndarray, fmin: float = 2400.0, fmax: float = 7200.0):
        """Add one frequency-power row. power_row length need not match n_freq_bins."""
        self._fmin = fmin; self._fmax = fmax
        if len(power_row) != self._n_f:
            try:
                row = np.interp(np.linspace(0, 1, self._n_f),
                                np.linspace(0, 1, len(power_row)),
                                power_row).astype(np.float32)
            except Exception:
                row = np.full(self._n_f, -110.0, dtype=np.float32)
        else:
            row = np.asarray(power_row, dtype=np.float32)
        with self._lock:
            self._buf[self._head] = row
            self._head = (self._head + 1) % self._n_t

    def get(self) -> np.ndarray:
        """Return (n_time, n_freq) array — oldest row first, newest last."""
        with self._lock:
            return np.roll(self._buf, -self._head, axis=0).copy()


