import math
import numpy as np

# ─────────────────────────────────────────────────────────────────────────────
# ESP-CSI base64 IQ decoder (Examplecode5 esp_csi_tool.py)
# ─────────────────────────────────────────────────────────────────────────────
import base64 as _b64, re as _re

def _esp_base64_decode_csi(str_data):
    """Decode ESP-CSI base64-encoded CSI payload. Returns list of signed ints."""
    try:
        s = str(str_data).strip().replace('\n', '').replace('\r', '').replace(' ', '')
        # strip log suffixes (e.g. "->valid_len: 104")
        m = _re.search(r'->valid_len|:\s*\d+|\(\d+\)|[DIWE]\s*\(', s)
        if m and m.start() > 10:
            s = s[:m.start()]
        pad = len(s) % 4
        if pad:
            s += '=' * (4 - pad)
        raw = list(_b64.b64decode(s, validate=True))
        return [v - 256 if v > 127 else v for v in raw]
    except Exception:
        return []


def _esp_csi_subcarrier_colors(csi_len):
    """Return per-subcarrier RGB tuples matching ESP-CSI color bands."""
    bands = {
        106: [(0,25),(26,52),None],
        114: [(0,27),(28,56),None],
        52:  [(0,12),(13,26),None],
        234: [(0,28),(29,56),(60,116)],
        228: [(0,28),(29,57),(57,113)],
        490: [(0,61),(62,122),(123,245)],
        128: [(0,31),(32,63),None],
        256: [(0,32),(32,63),(64,128)],
        512: [(0,63),(64,127),(128,256)],
        384: [(0,63),(64,127),(128,192)],
    }.get(csi_len, None)
    n = csi_len // 2
    colors = [(200,200,200)] * n
    if bands is None:
        return colors
    def fill(lo, hi, ch, clrs):
        for i in range(lo, min(hi+1, n)):
            t = int(255 * (i-lo)/max(hi-lo,1))
            clrs[i] = (t,0,0) if ch==0 else (0,t,0) if ch==1 else (0,t,t)
    for ci, b in enumerate(bands):
        if b:
            fill(b[0], b[1], ci, colors)
    return colors


class ESPCSIBase64Parser:
    """
    Pass 64: ESP-CSI base64 IQ decoder + gain-compensated amplitude.
    Handles all ESP-CSI formats (LLTF-52, HT40-234, HE80-490, etc.).
    Ports: esp_csi_tool.py base64_decode_bin + amplitude compensation.
    """
    # Subcarrier count per format
    _FORMAT_SC = {52:26, 106:53, 114:57, 128:64, 228:114, 234:117, 256:128,
                  384:192, 490:245, 512:256}

    def __init__(self, fft_gain_default=0, agc_gain_default=0):
        self.fft_gain = float(fft_gain_default)
        self.agc_gain = float(agc_gain_default)
        self._buf = np.zeros((200, 245), dtype=np.float32)
        self._phase = np.zeros((200, 245), dtype=np.float32)
        self._idx = 0

    def update_gains(self, fft_gain, agc_gain):
        self.fft_gain = float(fft_gain)
        self.agc_gain = float(agc_gain)

    def parse_raw_list(self, raw_list):
        """Parse [imag0, real0, imag1, real1, ...] integer list → (amp, phase) arrays."""
        n = len(raw_list) // 2
        if n == 0:
            return np.zeros(1), np.zeros(1)
        imag = np.array(raw_list[0::2][:n], dtype=np.float32)
        real = np.array(raw_list[1::2][:n], dtype=np.float32)
        amp = np.sqrt(imag**2 + real**2)
        phase = np.arctan2(imag, real)
        return amp, phase

    def parse_base64(self, b64_str, fft_gain=None, agc_gain=None):
        """Decode base64 CSI string, apply gain compensation, return (amp, phase)."""
        raw = _esp_base64_decode_csi(b64_str)
        if not raw:
            return None, None
        amp, phase = self.parse_raw_list(raw)
        fg = float(fft_gain) if fft_gain is not None else self.fft_gain
        ag = float(agc_gain) if agc_gain is not None else self.agc_gain
        # Gain compensation: divide by 2^(fft_gain+agc_gain)
        gain_factor = np.power(2.0, fg + ag)
        if gain_factor > 0:
            amp = amp / gain_factor
        n = len(amp)
        if self._idx >= 200:
            self._idx = 0
        self._buf[self._idx, :n] = amp
        self._phase[self._idx, :n] = phase
        self._idx = (self._idx + 1) % 200
        return amp, phase

    def parse_json_csi(self, csi_list, fft_gain=None, agc_gain=None):
        """Parse JSON int-list from ESP32 CSI_DATA line."""
        raw = [int(x) for x in csi_list]
        amp, phase = self.parse_raw_list(raw)
        fg = float(fft_gain) if fft_gain is not None else self.fft_gain
        ag = float(agc_gain) if agc_gain is not None else self.agc_gain
        gain_factor = np.power(2.0, fg + ag)
        if gain_factor > 0:
            amp = amp / gain_factor
        return amp, phase

    def amplitude_history(self):
        """Return rolling 200-frame amplitude buffer."""
        return self._buf.copy()

    def subcarrier_colors(self, csi_len):
        return _esp_csi_subcarrier_colors(csi_len)

    def synth_parse(self, n_sc=52):
        """Synthetic frame for testing."""
        rg = np.random.default_rng(64)
        raw = rg.integers(-100, 100, n_sc * 2).tolist()
        return self.parse_raw_list(raw)


# ─────────────────────────────────────────────────────────────────────────────
# ESP32-CSI-Tool IQ parser (Examplecode6 parse_csi.py + serial_plot_csi_live.py)
# ─────────────────────────────────────────────────────────────────────────────
class ESP32CSIToolParser:
    """
    Pass 64: Full ESP32-CSI-Tool IQ/amplitude/phase parser.
    Handles both standard (25-col) and C5/C6 (15-col) CSV formats.
    Ports: parse_csi.py + serial_plot_csi_live.py → numpy arrays.
    """
    _COLS_STD = ['type','id','mac','rssi','rate','sig_mode','mcs','bandwidth',
                 'smoothing','not_sounding','aggregation','stbc','fec_coding',
                 'sgi','noise_floor','ampdu_cnt','channel','secondary_channel',
                 'local_timestamp','ant','sig_len','rx_state','len','first_word','data']
    _COLS_C5C6 = ['type','id','mac','rssi','rate','noise_floor','fft_gain',
                  'agc_gain','channel','local_timestamp','sig_len','rx_state',
                  'len','first_word','data']

    def __init__(self, buf_len=200):
        self.buf_len = buf_len
        self._amp_buf  = np.zeros((buf_len, 490), dtype=np.float32)
        self._phase_buf= np.zeros((buf_len, 490), dtype=np.float32)
        self._iq_buf   = np.zeros((buf_len, 490), dtype=np.complex64)
        self._agc_buf  = np.zeros(buf_len, dtype=np.float32)
        self._fft_buf  = np.zeros(buf_len, dtype=np.float32)
        self._rssi_buf = np.zeros(buf_len, dtype=np.float32)
        self._ptr = 0
        self._pkt_count = 0

    def _parse_csi_data_str(self, data_str):
        """'[i0 r0 i1 r1 ...]' → complex array."""
        inner = data_str.strip().lstrip('[').rstrip(']')
        vals = [int(x) for x in inner.split() if x]
        n = len(vals) // 2
        cplx = np.zeros(n, dtype=np.complex64)
        for i in range(n):
            cplx[i] = complex(vals[i*2+1], vals[i*2])   # real=real, imag=imag
        return cplx

    def parse_csv_line(self, line):
        """
        Parse one CSV line from ESP32-CSI-Tool serial output.
        Returns dict with amp, phase, iq, rssi, agc, fft, n_sc.
        """
        import csv as _csv
        from io import StringIO as _SIO
        parts = list(_csv.reader(_SIO(line.strip())))[0]
        if 'CSI_DATA' not in (parts[0] if parts else ''):
            return None
        is_c5c6 = (len(parts) == len(self._COLS_C5C6))
        try:
            rssi = float(parts[3]) if len(parts) > 3 else 0.0
            if is_c5c6:
                fft_g = float(parts[6])
                agc_g = float(parts[7])
                data_str = parts[-1]
            else:
                fft_g = 0.0
                agc_g = 0.0
                data_str = parts[-1]
            cplx = self._parse_csi_data_str(data_str)
            amp = np.abs(cplx)
            phase = np.angle(cplx)
            n = len(cplx)
            i = self._ptr % self.buf_len
            self._amp_buf[i, :n] = amp
            self._phase_buf[i, :n] = phase
            self._iq_buf[i, :n] = cplx
            self._agc_buf[i] = agc_g
            self._fft_buf[i] = fft_g
            self._rssi_buf[i] = rssi
            self._ptr += 1
            self._pkt_count += 1
            return {'amp': amp, 'phase': phase, 'iq': cplx, 'rssi': rssi,
                    'fft_gain': fft_g, 'agc_gain': agc_g, 'n_sc': n}
        except Exception:
            return None

    def amplitude_history(self):
        return self._amp_buf.copy()

    def phase_history(self):
        return self._phase_buf.copy()

    def latest_amplitude(self):
        i = (self._ptr - 1) % self.buf_len
        return self._amp_buf[i].copy()

    def latest_iq(self):
        i = (self._ptr - 1) % self.buf_len
        return self._iq_buf[i].copy()

    def synth_frame(self, n_sc=52):
        """Synthetic parse for testing."""
        rg = np.random.default_rng(64)
        vals = rg.integers(-50, 50, n_sc * 2)
        data_str = '[' + ' '.join(map(str, vals)) + ']'
        line = 'CSI_DATA,' + ','.join(['0'] * 23) + ',' + data_str
        return self.parse_csv_line(line)


# ─────────────────────────────────────────────────────────────────────────────
# KrakenSDR: VFO channelizer + Root-MUSIC + PAPR + SNR + UCA phase-mode
# (crucialuseexamplecode2 kraken_sdr_signal_processor.py — remaining functions)
# ─────────────────────────────────────────────────────────────────────────────

def _kraken_snr_np(R):
    """Eigenvalue SNR: (max_ev - min_ev) / min_ev in dB."""
    try:
        ev = np.sort(np.abs(np.linalg.eigvals(R)))
        noise = ev[0]
        if noise < 1e-15:
            return 0.0
        return float(10.0 * np.log10((ev[-1] - noise) / noise))
    except Exception:
        return 0.0


def _kraken_toeplitzify_np(R):
    """Toeplitz rectification of correlation matrix."""
    M = R.shape[0]
    c = np.array([(1.0 / (M - abs(m))) * np.trace(R, m)
                  for m in range(0, -M, -1)], dtype=np.complex128)
    out = np.zeros((M, M), dtype=np.complex128)
    for i in range(M):
        for j in range(M):
            out[i, j] = c[abs(i - j)]
    return out


def _kraken_fb_toeplitz_np(R):
    """Forward-backward Toeplitz reconstruction (for UCA decorrelation)."""
    try:
        from scipy.linalg import toeplitz as _tp
    except ImportError:
        def _tp(c, r=None):
            n = len(c)
            T = np.zeros((n, n), dtype=c.dtype)
            for i in range(n):
                for j in range(n):
                    T[i, j] = c[i-j] if i >= j else np.conj(c[j-i])
            return T
    R_f = _tp(R[:, 0], R[0, :])
    R_b = _tp(np.flip(R[:, -1]), np.flip(R[-1, :]))
    return 0.5 * (R_f + R_b.conj())


def _kraken_root_music_np(R, signal_dim, inter_elem_space=0.5, array_offset_deg=0.0):
    """
    Root-MUSIC DoA estimator for ULA.
    Returns array of DoA estimates in degrees [0°,360°).
    Reference: Barabell 1983 ICASSP.
    """
    M = R.shape[0]
    try:
        _, vi = np.linalg.eigh(R)
    except np.linalg.LinAlgError:
        return np.array([0.0])
    vi = vi.astype(np.complex64)
    e_noise = vi[:, :-signal_dim]
    E_ct = e_noise @ e_noise.conj().T
    # polynomial coefficients: p[k] = trace(E_ct, k) for k = -(M-1)...(M-1)
    p = np.array([np.trace(E_ct, k) for k in range(-(M-1), M)], dtype=np.complex128)
    roots = np.roots(p)
    abs_r = np.abs(roots)
    # select signal_dim roots closest to unit circle
    idx = np.argsort(np.abs(abs_r - 1.0))[:signal_dim]
    angles = np.angle(roots[idx])
    # ULA: sin(theta) = angle / (2*pi*d)
    sin_th = angles / (2.0 * np.pi * inter_elem_space)
    sin_th = np.clip(sin_th, -1.0, 1.0)
    doas = np.degrees(np.arcsin(sin_th))
    # map to [0, 360)
    doas = np.mod(doas + array_offset_deg, 360.0)
    return doas


def _kraken_papr_np(doa_spectrum):
    """Peak-to-Average Power Ratio of DoA spectrum (dB)."""
    s = np.abs(doa_spectrum)
    mean_s = np.mean(s)
    if mean_s < 1e-15:
        return 0.0
    return float(10.0 * np.log10(np.max(s) / mean_s))


def _kraken_normalized_gaussian_np(x, x0_arr, sigma):
    """Multimodal 360° periodic Gaussian for DoA spectrum smoothing."""
    out = np.zeros_like(x, dtype=np.float64)
    for x0 in x0_arr:
        mirror = (x0 + 180.0) % 360.0
        for i, xi in enumerate(x):
            xi_w = xi if xi >= mirror else 2.0 * mirror - xi
            out[i] += np.exp(-0.5 * ((xi_w - x0) / sigma) ** 2)
    mx = out.max()
    if mx > 1e-15:
        out /= mx
    return out


def _kraken_uca_xi_np(radius_m, freq_hz):
    """UCA phase-mode transform parameter xi and L."""
    c = 299792458.0
    lam = c / freq_hz
    xi_val = 2.0 * np.pi * radius_m / lam
    L = int(np.floor(xi_val))
    return xi_val, L


def _kraken_uca_transform_np(signal, radius_m, freq_hz):
    """
    UCA → virtual ULA phase-mode excitation transform.
    Reference: Tewfik & Hong 1992, IEEE Trans. Signal Processing.
    signal: (N_ant, N_samples) complex array.
    Returns transformed signal in phase-mode space.
    """
    try:
        from scipy.special import jv as _jv
        from scipy.linalg import fractional_matrix_power as _fmp
    except ImportError:
        return signal  # fallback: identity
    N = signal.shape[0]
    xi_val, L = _kraken_uca_xi_np(radius_m, freq_hz)
    modes = np.arange(-L, L + 1)
    # Bessel diagonal J
    J = np.diag([1.0 / ((1j ** v) * _jv(v, xi_val)) for v in modes])
    # DFT matrix F
    F = np.array([[np.exp(2.0j * np.pi * m * n / N) for n in range(N)]
                  for m in modes], dtype=np.complex128)
    T_mat = (J @ F) / float(N)
    # Prewhiten
    TH = T_mat @ T_mat.conj().T
    try:
        Tw = _fmp(TH, -0.5) @ T_mat
    except Exception:
        Tw = T_mat
    return Tw @ signal


def _kraken_gen_scanning_vectors_np(M, inter_elem_space, array_type='ULA', offset_deg=0.0):
    """
    Generate MUSIC/Bartlett scanning vectors for ULA or UCA.
    Returns (M, 360) complex steering matrix.
    """
    thetas = np.linspace(0, 359, 360)
    off = np.deg2rad(offset_deg)
    if array_type == 'UCA':
        # UCA: convert inter-element space to radius
        r = inter_elem_space / (np.sqrt(2.0) * np.sqrt(1.0 - np.cos(2.0 * np.pi / M)))
        phi = 2.0 * np.pi * np.arange(M) / M
        x = r * np.cos(phi)
        y = -r * np.sin(phi)
    else:  # ULA
        x = np.zeros(M)
        y = -np.arange(M, dtype=float) * inter_elem_space
    sv = np.zeros((M, 360), dtype=np.complex64)
    for i, th in enumerate(thetas):
        th_r = np.deg2rad(th) + off
        sv[:, i] = np.exp(1j * 2 * np.pi * (x * np.cos(th_r) + y * np.sin(th_r)))
    return sv


def _kraken_music_np(R, sv, signal_dim):
    """MUSIC spectrum from R and steering vectors sv (M×360). Returns (360,) power array."""
    M = R.shape[0]
    vals, vecs = np.linalg.eig(R)
    idx = np.argsort(np.abs(vals))
    vecs = vecs[:, idx]
    E_n = vecs[:, :M - signal_dim]
    EEH = E_n @ E_n.conj().T
    out = np.zeros(360, dtype=np.float32)
    for i in range(360):
        s = sv[:, i]
        denom = np.abs(s.conj() @ EEH @ s)
        out[i] = 1.0 / denom if denom > 1e-15 else 0.0
    return out


class KrakenVFOChannelizer:
    """
    Pass 64: KrakenSDR VFO channelizer — FIR decimation + frequency shift.
    Ports channelize() from kraken_sdr_signal_processor.py.
    Up to 16 VFOs, each with configurable BW and FIR order factor.
    """
    def __init__(self, fs=2.4e6, max_vfos=16):
        self.fs = float(fs)
        self.max_vfos = max_vfos
        self.vfo_freq = [self.fs / 4.0] * max_vfos
        self.vfo_bw   = [12500.0] * max_vfos
        self.vfo_fir_order_factor = [2] * max_vfos
        self._active = 1

    def set_vfo(self, idx, freq_hz, bw_hz=12500.0, fir_order_factor=2):
        """Configure VFO idx."""
        if 0 <= idx < self.max_vfos:
            self.vfo_freq[idx] = float(freq_hz)
            self.vfo_bw[idx]   = float(bw_hz)
            self.vfo_fir_order_factor[idx] = int(fir_order_factor)
            self._active = max(self._active, idx + 1)

    def _fir_lp(self, n, cutoff_norm):
        """Simple windowed-sinc FIR lowpass."""
        m = np.arange(n) - (n - 1) / 2.0
        h = np.sinc(2.0 * cutoff_norm * m) * np.blackman(n)
        h /= h.sum()
        return h.astype(np.float32)

    def channelize(self, signal_2d, vfo_idx=0):
        """
        Channelize multi-channel IQ signal (N_ch × N_samples) for VFO vfo_idx.
        Returns decimated, frequency-shifted IQ (N_ch × N_out).
        """
        try:
            from scipy.signal import decimate as _dec
        except ImportError:
            return signal_2d  # fallback
        freq = self.vfo_freq[vfo_idx]
        bw   = self.vfo_bw[vfo_idx]
        fof  = max(self.vfo_fir_order_factor[vfo_idx], 2)
        dec  = max(int(self.fs // bw), 1)
        N    = signal_2d.shape[1]
        t    = np.arange(N, dtype=np.float64) / self.fs
        # Frequency shift to baseband
        shift = np.exp(-2j * np.pi * freq * t).astype(np.complex64)
        shifted = signal_2d * shift[np.newaxis, :]
        # FIR decimate per channel
        order = fof * dec * 2
        fir = self._fir_lp(order + 1, 0.45 / dec)
        out_list = []
        for ch in range(signal_2d.shape[0]):
            try:
                d = _dec(shifted[ch], dec, ftype='fir', zero_phase=True)
            except Exception:
                d = shifted[ch, ::dec]
            out_list.append(d)
        return np.array(out_list, dtype=np.complex64)

    def synth_channelize(self, N=4096, n_ch=4):
        rg = np.random.default_rng(64)
        sig = (rg.standard_normal((n_ch, N)) + 1j * rg.standard_normal((n_ch, N))).astype(np.complex64)
        return self.channelize(sig, 0)


class KrakenDoAFullNP:
    """
    Pass 64: Extended KrakenSDR DoA processor — Root-MUSIC + PAPR + SNR +
    UCA phase-mode transform + Toeplitz + FB-Toeplitz + scanning vector cache.
    Augments the existing KrakenMUSICDoA class with these remaining algorithms.
    """
    def __init__(self, n_ant=5, inter_elem_space=0.5, array_type='ULA',
                 radius_m=None, freq_hz=100e6, signal_dim=1):
        self.n_ant = n_ant
        self.inter_elem_space = inter_elem_space
        self.array_type = array_type
        self.radius_m = radius_m or inter_elem_space
        self.freq_hz = float(freq_hz)
        self.signal_dim = signal_dim
        self._sv_cache = {}
        # results
        self.doa_root_music = np.array([0.0])
        self.doa_papr_db = 0.0
        self.snr_db = 0.0
        self.doa_music_spectrum = np.zeros(360)

    def _get_sv(self, atype, offset=0.0):
        key = (atype, self.n_ant, self.inter_elem_space, offset)
        if key not in self._sv_cache:
            self._sv_cache[key] = _kraken_gen_scanning_vectors_np(
                self.n_ant, self.inter_elem_space, atype, offset)
        return self._sv_cache[key]

    def process(self, iq_samples, freq_hz=None):
        """
        Full DoA processing pipeline.
        iq_samples: (N_ant, N_samples) complex array.
        Returns dict with root_music_doas, music_spectrum, papr_db, snr_db.
        """
        if freq_hz is not None:
            self.freq_hz = float(freq_hz)
        R = _kraken_corr_matrix_np(iq_samples)
        # Optional UCA transform
        if self.array_type == 'UCA' and self.radius_m is not None:
            try:
                iq_t = _kraken_uca_transform_np(iq_samples, self.radius_m, self.freq_hz)
                R = _kraken_corr_matrix_np(iq_t)
            except Exception:
                pass
        # Toeplitz decorrelation
        try:
            R = _kraken_toeplitzify_np(R)
        except Exception:
            pass
        # MUSIC spectrum
        sv = self._get_sv(self.array_type)
        self.doa_music_spectrum = _kraken_music_np(R, sv, self.signal_dim)
        # Root-MUSIC
        self.doa_root_music = _kraken_root_music_np(
            R, self.signal_dim, self.inter_elem_space)
        # PAPR + SNR
        self.doa_papr_db = _kraken_papr_np(self.doa_music_spectrum)
        self.snr_db = _kraken_snr_np(R)
        return {
            'root_music_doas': self.doa_root_music.tolist(),
            'music_spectrum': self.doa_music_spectrum,
            'papr_db': self.doa_papr_db,
            'snr_db': self.snr_db,
        }

    def synth_process(self):
        rg = np.random.default_rng(64)
        N = 512
        iq = (rg.standard_normal((self.n_ant, N)) + 1j * rg.standard_normal((self.n_ant, N))).astype(np.complex64)
        return self.process(iq)


# ─────────────────────────────────────────────────────────────────────────────
# mmWave + WiFi-CSI dual-sensor Kalman-style fusion bridge
# (RuView/scripts/mmwave_fusion_bridge.py)
# ─────────────────────────────────────────────────────────────────────────────
class MmWaveWiFiFusionBridgeNP:
    """
    Pass 64: Real-time mmWave + WiFi-CSI dual-sensor fusion bridge.
    Implements Kalman-style weighted averaging:
      fused = w_mmwave * mmwave + (1-w_mmwave) * csi
    when both sources are fresh; falls back to single source otherwise.
    Source: RuView/scripts/mmwave_fusion_bridge.py.
    """
    def __init__(self, mmwave_weight=0.8, staleness_ms=5000.0):
        self.w_mm = float(mmwave_weight)
        self.w_csi = 1.0 - self.w_mm
        self.staleness_ms = float(staleness_ms)
        # mmWave state
        self._mm_hr = 0.0
        self._mm_br = 0.0
        self._mm_presence = False
        self._mm_dist_cm = 0.0
        self._mm_t = 0.0
        self._mm_frames = 0
        # CSI state
        self._csi_hr = 0.0
        self._csi_br = 0.0
        self._csi_presence = False
        self._csi_t = 0.0
        self._csi_frames = 0
        # fused output
        self.fused = {'hr': 0.0, 'br': 0.0, 'presence': False,
                      'source': 'none', 'conf': 0.0}

    def update_mmwave(self, hr, br, presence=False, dist_cm=0.0):
        """Update mmWave sensor readings (60 GHz MR60BHA2 / similar)."""
        import time as _t
        self._mm_hr = float(hr)
        self._mm_br = float(br)
        self._mm_presence = bool(presence)
        self._mm_dist_cm = float(dist_cm)
        self._mm_t = _t.time() * 1000.0
        self._mm_frames += 1

    def update_csi(self, hr, br, presence=False):
        """Update WiFi-CSI edge-proc vitals readings."""
        import time as _t
        self._csi_hr = float(hr)
        self._csi_br = float(br)
        self._csi_presence = bool(presence)
        self._csi_t = _t.time() * 1000.0
        self._csi_frames += 1

    def _age_ms(self, t_ms):
        import time as _t
        return (_t.time() * 1000.0 - t_ms) if t_ms > 0 else 1e9

    def fuse(self):
        """Compute fused HR/BR and return result dict."""
        mm_stale = self._age_ms(self._mm_t) > self.staleness_ms
        csi_stale = self._age_ms(self._csi_t) > self.staleness_ms
        if not mm_stale and not csi_stale:
            hr = self.w_mm * self._mm_hr + self.w_csi * self._csi_hr
            br = self.w_mm * self._mm_br + self.w_csi * self._csi_br
            presence = self._mm_presence or self._csi_presence
            source = 'fused'
            conf = 1.0
        elif not mm_stale:
            hr, br, presence, source, conf = (
                self._mm_hr, self._mm_br, self._mm_presence, 'mmwave', 0.8)
        elif not csi_stale:
            hr, br, presence, source, conf = (
                self._csi_hr, self._csi_br, self._csi_presence, 'csi', 0.6)
        else:
            hr, br, presence, source, conf = (0.0, 0.0, False, 'none', 0.0)
        self.fused = {
            'hr': float(hr), 'br': float(br),
            'presence': bool(presence),
            'source': source, 'conf': float(conf),
            'mm_hr': self._mm_hr, 'mm_br': self._mm_br,
            'csi_hr': self._csi_hr, 'csi_br': self._csi_br,
            'mm_frames': self._mm_frames, 'csi_frames': self._csi_frames,
            'dist_cm': self._mm_dist_cm,
        }
        return self.fused

    def synth_fuse(self):
        self.update_mmwave(72.0, 14.5, presence=True, dist_cm=120.0)
        self.update_csi(68.0, 15.0, presence=True)
        return self.fuse()


# ─────────────────────────────────────────────────────────────────────────────
# BCI-HIL Motor Imagery Trial Engine
# (BCIexamplecode1/bci-hil-main Motor_Imagery engine.py)
# ─────────────────────────────────────────────────────────────────────────────
class BCIMotorImageryTrialEngineNP:
    """
    Pass 64: BCI-HIL Motor Imagery trial engine.
    Manages epoch cutting, band-power classification, marker logging,
    and LSL-style stream buffering for left/right hand motor imagery.
    Source: bci-hil-main/src/Motor_Imagery/engine/engine.py.
    Pure numpy — no brainflow or MNE dependency.

    EEG Protocol (from BCI-HIL):
      - 8 channels (Cz/C3/C4/CP3/CP4/FC3/FC4/Fz)
      - 250 Hz sampling rate
      - 4s trial window, 2s rest, 4s imagery
      - Band: mu (8-12 Hz) + beta (18-25 Hz) ERD/ERS
    """
    CH_NAMES = ['Cz','C3','C4','CP3','CP4','FC3','FC4','Fz']
    _FS = 250.0           # sampling rate
    _TRIAL_S = 4.0        # imagery duration (s)
    _REST_S  = 2.0        # rest before imagery
    _CLASSES = ['left_hand', 'right_hand', 'rest']

    def __init__(self, fs=250.0, n_ch=8, buf_s=60.0):
        self.fs = float(fs)
        self.n_ch = n_ch
        self._buf_n = int(buf_s * fs)
        self._buf = np.zeros((n_ch, self._buf_n), dtype=np.float32)
        self._ptr = 0
        self._markers = []       # [(sample_idx, label)]
        self._trials = []        # [(epoch_array, label)]
        self._trial_n = int(self._TRIAL_S * fs)
        self._rest_n  = int(self._REST_S * fs)
        self._current_label = None
        self._trial_start = -1
        self._predictions = []   # [(label, conf)]

    def push_samples(self, chunk):
        """
        Push (n_ch × N) sample chunk into ring buffer.
        chunk: numpy array shape (n_ch, N) or (N, n_ch).
        """
        if chunk.ndim == 2 and chunk.shape[0] == self.n_ch:
            arr = chunk
        elif chunk.ndim == 2 and chunk.shape[1] == self.n_ch:
            arr = chunk.T
        else:
            return
        N = arr.shape[1]
        for i in range(N):
            idx = self._ptr % self._buf_n
            self._buf[:, idx] = arr[:, i]
            self._ptr += 1

    def log_marker(self, label):
        """Log a trial-start marker at the current sample position."""
        self._markers.append((self._ptr, label))
        self._current_label = label
        self._trial_start = self._ptr

    def cut_epoch(self, label=None):
        """
        Cut a trial epoch from the ring buffer using the last marker.
        Returns (epoch_array n_ch×trial_N, label) or None if insufficient data.
        """
        if self._trial_start < 0:
            return None
        n_avail = self._ptr - self._trial_start
        if n_avail < self._trial_n:
            return None
        epoch = np.zeros((self.n_ch, self._trial_n), dtype=np.float32)
        for j in range(self._trial_n):
            src = (self._trial_start + j) % self._buf_n
            epoch[:, j] = self._buf[:, src]
        lbl = label if label is not None else self._current_label
        self._trials.append((epoch, lbl))
        self._trial_start = -1
        return epoch, lbl

    def _bandpower_np(self, epoch, f_lo, f_hi):
        """Welch-style band power via FFT for each channel."""
        N = epoch.shape[1]
        W = np.hanning(N)
        sp = np.abs(np.fft.rfft(epoch * W[np.newaxis, :], axis=1)) ** 2
        freqs = np.fft.rfftfreq(N, d=1.0/self.fs)
        mask = (freqs >= f_lo) & (freqs <= f_hi)
        bp = sp[:, mask].mean(axis=1)
        return bp   # shape (n_ch,)

    def classify_epoch(self, epoch):
        """
        ERD/ERS-based motor imagery classification.
        Returns (predicted_label, confidence) using C3/C4 lateralization.
        C3: contralateral to RIGHT hand (suppresses mu during LEFT imagery)
        C4: contralateral to LEFT hand (suppresses mu during RIGHT imagery)
        """
        mu   = self._bandpower_np(epoch, 8.0, 12.0)
        beta = self._bandpower_np(epoch, 18.0, 25.0)
        c3_idx = self.CH_NAMES.index('C3') if 'C3' in self.CH_NAMES else 1
        c4_idx = self.CH_NAMES.index('C4') if 'C4' in self.CH_NAMES else 2
        # Laterality index: positive → left dominant, negative → right dominant
        lat = (mu[c3_idx] - mu[c4_idx]) / (mu[c3_idx] + mu[c4_idx] + 1e-9)
        # Beta suppression as secondary feature
        beta_asym = (beta[c3_idx] - beta[c4_idx]) / (beta[c3_idx] + beta[c4_idx] + 1e-9)
        score = 0.7 * lat + 0.3 * beta_asym
        conf = float(np.clip(np.abs(score) * 2.0, 0.0, 1.0))
        if abs(score) < 0.05:
            label = 'rest'
        elif score > 0:
            label = 'left_hand'
        else:
            label = 'right_hand'
        self._predictions.append((label, conf))
        return label, conf

    def run_trial(self, label='left_hand'):
        """Run a complete synthetic trial (for testing)."""
        self.log_marker(label)
        rg = np.random.default_rng(64)
        # Synthesize trial: add suppressed mu on C3 for left hand
        chunk = rg.standard_normal((self.n_ch, self._trial_n)).astype(np.float32) * 5.0
        t = np.arange(self._trial_n) / self.fs
        mu_signal = np.sin(2 * np.pi * 10.0 * t).astype(np.float32) * 2.0
        if label == 'left_hand':
            chunk[2] += mu_signal  # C4 mu suppressed (right hemisphere)
        else:
            chunk[1] += mu_signal  # C3
        self.push_samples(chunk)
        result = self.cut_epoch(label)
        if result is not None:
            epoch, lbl = result
            return self.classify_epoch(epoch)
        return 'rest', 0.0

    def accuracy(self):
        """Compute classification accuracy on stored predictions vs logged markers."""
        if not self._predictions or not self._markers:
            return 0.0
        correct = sum(1 for ((_,lbl),(pred,_)) in zip(self._markers, self._predictions)
                      if lbl == pred)
        return float(correct) / len(self._predictions)


# ─────────────────────────────────────────────────────────────────────────────
# Pass 64 Sensor Fusion Orchestrator
# ─────────────────────────────────────────────────────────────────────────────
class Pass64SensorFusion:
    """
    Pass 64: Unified fusion of ESP-CSI, ESP32-CSI-Tool, KrakenSDR extended DoA
    (Root-MUSIC + VFO + PAPR + SNR + UCA), mmWave+WiFi bridge, and BCI motor imagery.
    psych_profile keys added (18):
      p64_esp_amp_mean, p64_esp_amp_max, p64_esp_n_sc,
      p64_csi_tool_amp_mean, p64_csi_tool_phase_std,
      p64_doa_root_music_0, p64_doa_root_music_1,
      p64_doa_papr_db, p64_doa_snr_db, p64_doa_music_peak,
      p64_vfo_n_out,
      p64_mm_hr, p64_mm_br, p64_fused_hr, p64_fused_br,
      p64_fused_source, p64_bci_mi_label, p64_bci_mi_conf
    """
    def __init__(self):
        self.esp_parser   = ESPCSIBase64Parser()
        self.csi_tool     = ESP32CSIToolParser()
        self.kraken_doa   = KrakenDoAFullNP(n_ant=5, inter_elem_space=0.5)
        self.vfo_ch       = KrakenVFOChannelizer(fs=2.4e6, max_vfos=4)
        self.mm_bridge    = MmWaveWiFiFusionBridgeNP(mmwave_weight=0.8)
        self.bci_trial    = BCIMotorImageryTrialEngineNP(fs=250.0, n_ch=8)
        self._frame = 0

    def update(self, pp, amp_frame, iq_frame, _unused):
        self._frame += 1

        # ── ESP-CSI base64 amp (synthetic) ──────────────────────────────────
        try:
            esp_amp, esp_phase = self.esp_parser.synth_parse(n_sc=52)
            pp['p64_esp_amp_mean'] = float(esp_amp.mean())
            pp['p64_esp_amp_max']  = float(esp_amp.max())
            pp['p64_esp_n_sc']     = int(len(esp_amp))
        except Exception:
            pp['p64_esp_amp_mean'] = 0.0
            pp['p64_esp_amp_max']  = 0.0
            pp['p64_esp_n_sc']     = 0

        # ── ESP32-CSI-Tool IQ parse ──────────────────────────────────────────
        try:
            frame = self.csi_tool.synth_frame(n_sc=52)
            if frame:
                pp['p64_csi_tool_amp_mean']  = float(frame['amp'].mean())
                pp['p64_csi_tool_phase_std'] = float(frame['phase'].std())
            else:
                pp['p64_csi_tool_amp_mean']  = 0.0
                pp['p64_csi_tool_phase_std'] = 0.0
        except Exception:
            pp['p64_csi_tool_amp_mean']  = 0.0
            pp['p64_csi_tool_phase_std'] = 0.0

        # ── KrakenSDR extended DoA ───────────────────────────────────────────
        try:
            doa_r = self.kraken_doa.synth_process()
            rm = doa_r['root_music_doas']
            pp['p64_doa_root_music_0'] = float(rm[0]) if len(rm) > 0 else 0.0
            pp['p64_doa_root_music_1'] = float(rm[1]) if len(rm) > 1 else 0.0
            pp['p64_doa_papr_db']      = float(doa_r['papr_db'])
            pp['p64_doa_snr_db']       = float(doa_r['snr_db'])
            ms = doa_r['music_spectrum']
            pp['p64_doa_music_peak']   = float(np.argmax(ms))
        except Exception:
            pp['p64_doa_root_music_0'] = 0.0
            pp['p64_doa_root_music_1'] = 0.0
            pp['p64_doa_papr_db']      = 0.0
            pp['p64_doa_snr_db']       = 0.0
            pp['p64_doa_music_peak']   = 0.0

        # ── VFO channelizer ──────────────────────────────────────────────────
        try:
            vfo_out = self.vfo_ch.synth_channelize(N=1024, n_ch=4)
            pp['p64_vfo_n_out'] = int(vfo_out.shape[1])
        except Exception:
            pp['p64_vfo_n_out'] = 0

        # ── mmWave + WiFi-CSI bridge ─────────────────────────────────────────
        try:
            fused = self.mm_bridge.synth_fuse()
            pp['p64_mm_hr']      = float(fused['mm_hr'])
            pp['p64_mm_br']      = float(fused['mm_br'])
            pp['p64_fused_hr']   = float(fused['hr'])
            pp['p64_fused_br']   = float(fused['br'])
            pp['p64_fused_source'] = str(fused['source'])
        except Exception:
            pp['p64_mm_hr']       = 0.0
            pp['p64_mm_br']       = 0.0
            pp['p64_fused_hr']    = 0.0
            pp['p64_fused_br']    = 0.0
            pp['p64_fused_source']= 'none'

        # ── BCI Motor Imagery ────────────────────────────────────────────────
        try:
            if self._frame % 30 == 1:
                lbl = 'left_hand' if (self._frame // 30) % 2 == 0 else 'right_hand'
                mi_lbl, mi_conf = self.bci_trial.run_trial(lbl)
                pp['p64_bci_mi_label'] = str(mi_lbl)
                pp['p64_bci_mi_conf']  = float(mi_conf)
        except Exception:
            pp.setdefault('p64_bci_mi_label', 'rest')
            pp.setdefault('p64_bci_mi_conf', 0.0)

        return pp
# ═══════════ END PASS 64 ENGINES ═══════════

# ════════════ PASS 62 ENGINES ════════════
# ════════════ PASS 62 ENGINES ════════════
# KrakenSDR Passive Radar full pipeline (Crucialuseexamplecode3/krakensdr_pr-main):
#   - _pr_wiener_smi_mre_np: Wiener SMI-MRE clutter cancellation
#     (pruned batched FFT correlation → Hermitian-Toeplitz R, r → linalg.solve w)
#   - _pr_cc_detector_ons_np: range-Doppler CAF matrix (batched row-FFT
#     cross-multiply, column-FFT Doppler axis, crop/shift → (2F+1) × R complex matrix)
#   - PassiveRadarPipelineNP: orchestrator — ingest ref+surv IQ → clutter cancel
#     → CAF range-Doppler → CFAR peaks → bistatic (range, Doppler) coordinates
#
# Spectrum Sensing for Cognitive Radio (Crucialuseexamplecode4):
#   - EnergyDetectorNP: chi²-NP threshold + Bayesian decision, H0/H1 Monte Carlo
#     eval, ROC curve computation (vectorised), SNR-sweep P_D/P_FA
#   - CyclostationaryDetectorFullNP: OFDM conjugate-product statistic T_y,
#     chi²(2) threshold calibration, H0/H1 simulated performance curves
#   - SpectrumSensingFusionNP: OR-fusion of energy+cyclostationary decisions
#
# mmMesh full deep-model pipeline (crucialuseexamplecode7/mmMesh-master):
#   - _mm_square_dist_np: batched per-point squared Euclidean distance (B,N,C)
#   - _mm_index_points_np: gather indexed point features (B,N,C) → (B,S,C)
#   - _mm_farthest_point_sample_np: iterative FPS on (B,N,3) point clouds
#   - _mm_ball_query_np: fixed-radius nearest-neighbour grouping
#   - _mm_anchor_init_np: 3-D grid anchor initialisation (9×3×3 = 81 anchors)
#   - _mm_anchor_grouping_np: anchor-centred feature grouping
#   - _mm_6d_to_rotmat_np: 6D → SO3 rotation matrix (Gram-Schmidt)
#   - MmMeshBasePointNetNP: Conv1D 6→8→16→24 + input skip-concat
#   - MmMeshGlobalModuleNP: GlobalPointNet (28→32→48→64 + attn) + 3-layer LSTM
#     + FC→2 (x,y) global location head
#   - MmMeshAnchorModuleNP: AnchorPointNet (31→32→48→64 + attn) + 3D voxel pool
#     + 3-layer LSTM
#   - MmMeshCombineModuleNP: concat→FC(128→128→9*6+3+10+1), 6D→SO3 decode
#   - MmMeshModelNP: end-to-end mmWave body mesh model
#     → 24-joint SMPL skeleton + 9 local rotation matrices + translation + shape
# ════════════════════════════════════════

import math as _math
import collections as _collections


# ── KrakenSDR Passive Radar ──────────────────────────────────────────────────

def _pr_pruned_corr_np(ref: np.ndarray, surv: np.ndarray, K: int) -> tuple:
    """
    Batched FFT pruned correlation. Returns (R, r) where R is (K,K) Toeplitz
    autocorrelation matrix (first column only, then completed) and r is the
    K-length cross-correlation vector.
    From KrakenSDR krakensdr_pr krakenSDR_signal_processor.py pruned_correlation().
    """
    N = ref.shape[0]
    cols = K - 1
    rows = int(N / cols) + 1
    zeropads = cols * rows - N

    # Ref padded and reshaped for batched FFT
    xp = np.reshape(np.pad(ref.astype(np.complex64), (0, zeropads)), (rows, cols))
    ypp = np.vstack([xp[1:, :], np.zeros(cols, dtype=np.complex64)])
    yp = np.concatenate([xp, ypp], axis=1)

    xpw = np.fft.fft(xp, n=2*cols, axis=1)
    bpw = np.fft.fft(yp, axis=1)

    corr_batches = np.fft.fftshift(
        np.fft.ifft(xpw * np.conj(bpw), axis=1), axes=1
    )[:, :cols]

    R = np.zeros((K, K), dtype=np.complex64)
    R[:, 0] = np.flip(np.sum(corr_batches, axis=0))

    # Surv cross-correlation
    y = np.pad(surv.astype(np.complex64), (0, zeropads))
    yp2 = np.reshape(y, (rows, cols))
    ypp2 = np.vstack([yp2[1:, :], np.zeros(cols, dtype=np.complex64)])
    yp2 = np.concatenate([yp2, ypp2], axis=1)
    bpw2 = np.fft.fft(yp2, axis=1)
    corr2 = np.fft.fftshift(
        np.fft.ifft(xpw * np.conj(bpw2), axis=1), axes=1
    )[:, :cols]
    r = np.flip(np.sum(corr2, axis=0))
    return R, r

def _pr_complete_toeplitz_np(R: np.ndarray, K: int) -> np.ndarray:
    """Complete R from first column to full Hermitian-Toeplitz matrix."""
    for k in range(1, K):
        R[:, k] = np.roll(R[:, 0], k)
        R[:, k][:k] = 0
    R = R + R.conj().T
    R *= (np.ones(K) - np.eye(K) * 0.5)
    return R

def _pr_wiener_smi_mre_np(ref: np.ndarray, surv: np.ndarray,
                            K: int = 128) -> tuple:
    """
    Wiener SMI-MRE clutter cancellation.
    From krakenSDR_signal_processor.py Wiener_SMI_MRE() + fast_w() (numpy, no numba).
    Returns (filtered_surv, w).
    """
    N = ref.shape[0]
    R, r = _pr_pruned_corr_np(ref, surv, K)
    R = _pr_complete_toeplitz_np(R, K)
    try:
        w = np.linalg.solve(R, r)
    except np.linalg.LinAlgError:
        w = np.zeros(K, dtype=np.complex64)
    # oaconvolve fallback to numpy convolve
    try:
        from scipy.signal import oaconvolve as _oaconvolve
        filtered = surv - _oaconvolve(ref, w)[:N]
    except Exception:
        filtered = surv - np.convolve(ref, w)[:N]
    return filtered.astype(np.complex64), w

def _pr_cc_detector_ons_np(ref: np.ndarray, surv: np.ndarray,
                             fs: float, fD_max: int = 256,
                             r_max: int = 128) -> np.ndarray:
    """
    Range-Doppler CAF matrix. Numpy port of cc_detector_ons() from
    krakenSDR_signal_processor.py. Returns (2*fD_steps+1, r_max) complex matrix.
    """
    N = ref.shape[0]
    fD_step = fs / (2 * N)
    fD_steps = int(fD_max / fD_step)
    no_sub = N // r_max

    mx = np.zeros((2*fD_steps+1, r_max), dtype=np.complex64)

    # Shape into (sub_tasks, r_max) blocks
    pad = no_sub * r_max - N
    ref_p = np.pad(ref.astype(np.complex64), (0, pad))
    surv_p = np.pad(surv.astype(np.complex64), (0, pad))

    ref_blk = np.reshape(ref_p, (no_sub, r_max))
    surv_blk = np.reshape(surv_p, (no_sub, r_max))

    # Zero-pad rows for overlap
    z = np.zeros((no_sub, r_max), dtype=np.complex64)
    ref_ext = np.concatenate([ref_blk, z], axis=1)
    surv_ext = np.concatenate([surv_blk, np.vstack([surv_blk[1:], z[:1]])], axis=1)

    ref_fft = np.fft.fft(ref_ext, axis=1)
    surv_fft = np.fft.fft(surv_ext, axis=1)

    corr = np.fft.ifft(surv_fft * np.conj(ref_fft), axis=1)

    # Doppler FFT across sub-tasks axis
    corr_dop = np.fft.fft(corr, n=2*no_sub, axis=0)

    # Crop and shift
    mx[:fD_steps] = corr_dop[2*no_sub - fD_steps:, :r_max]
    mx[fD_steps:] = corr_dop[:fD_steps+1, :r_max]
    return mx

def _pr_cfar_2d_np(rd_matrix: np.ndarray,
                   guard: int = 2, train: int = 4,
                   pfa: float = 1e-3) -> list:
    """
    Simple 2D CA-CFAR on range-Doppler matrix. Returns list of (dop_idx, rng_idx, snr_db).
    """
    power = np.abs(rd_matrix)**2
    H, W = power.shape
    peaks = []
    for di in range(train+guard, H-(train+guard)):
        for ri in range(train+guard, W-(train+guard)):
            cell = power[di, ri]
            # Training window excluding guard cells
            bg = np.concatenate([
                power[di-train-guard:di-guard, ri-train-guard:ri+train+guard+1].ravel(),
                power[di+guard+1:di+train+guard+1, ri-train-guard:ri+train+guard+1].ravel(),
            ])
            if len(bg) == 0:
                continue
            noise = np.mean(bg)
            threshold = noise * (len(bg) * (pfa**(-1.0/len(bg)) - 1))
            if cell > threshold:
                snr = 10 * _math.log10(cell / (noise + 1e-20))
                peaks.append((di, ri, snr))
    return sorted(peaks, key=lambda x: -x[2])[:20]

class PassiveRadarPipelineNP:
    """
    Full KrakenSDR passive radar pipeline. From krakensdr_pr-main signal_processor.py.
    Stages: clutter cancel (Wiener-SMI-MRE) → CAF range-Doppler → CA-CFAR peaks.
    """

    def __init__(self, fs: float = 1e6, max_range: int = 128,
                 max_doppler: int = 256, clutter_K: int = 64):
        self.fs = fs
        self.max_range = max_range
        self.max_doppler = max_doppler
        self.clutter_K = clutter_K
        self._rd_matrix: np.ndarray = np.zeros((1, 1), dtype=np.complex64)
        self._peaks: list = []
        self._w: np.ndarray = np.zeros(clutter_K, dtype=np.complex64)
        self._frame = 0

    def process(self, ref: np.ndarray, surv: np.ndarray) -> dict:
        """
        One processing frame. ref and surv are 1-D complex arrays (same length).
        Returns dict with rd_matrix, peaks, w (clutter filter weights), snr_peak.
        """
        self._frame += 1
        N = min(len(ref), len(surv))
        ref = ref[:N].astype(np.complex64)
        surv = surv[:N].astype(np.complex64)

        # Clutter cancellation
        try:
            filt, w = _pr_wiener_smi_mre_np(ref, surv, self.clutter_K)
            self._w = w
        except Exception:
            filt = surv

        # Windowing (Hamming)
        win = np.hamming(N).astype(np.float32)
        filt_w = (filt * win).astype(np.complex64)

        # Range-Doppler
        try:
            rd = _pr_cc_detector_ons_np(
                ref, filt_w, self.fs, self.max_doppler, self.max_range
            )
            self._rd_matrix = rd
        except Exception:
            rd = self._rd_matrix

        # CFAR
        try:
            self._peaks = _pr_cfar_2d_np(rd, guard=2, train=4, pfa=1e-3)
        except Exception:
            self._peaks = []

        snr_peak = self._peaks[0][2] if self._peaks else 0.0
        return {
            'rd_matrix': rd,
            'peaks': self._peaks,
            'w': self._w,
            'snr_peak_db': snr_peak,
            'n_detections': len(self._peaks),
        }

    def synth_process(self, seed: int = 6200) -> dict:
        """Feed synthetic IQ for testing."""
        rng = np.random.default_rng(seed + self._frame)
        N = max(self.max_range * 16, 2048)
        ref = (rng.standard_normal(N) + 1j * rng.standard_normal(N)).astype(np.complex64)
        t = np.arange(N, dtype=np.float32) / float(self.fs)
        surv = ref * 0.7 + (rng.standard_normal(N) + 1j * rng.standard_normal(N)) * 0.3
        surv += 0.4 * np.exp(1j * 2 * _math.pi * 50.0 * t).astype(np.complex64)  # target tone
        return self.process(ref, surv)


# ── Spectrum Sensing (Cognitive Radio) ───────────────────────────────────────

class EnergyDetectorNP:
    """
    Neyman-Pearson energy detector with optional Bayesian decision rule.
    From Crucialuseexamplecode4/energy_detector_b.py + energy_detector_c.py.
    T_y = sum(|y|^2). H0: chi²(N), H1: noncentral-chi²(N, 2*SNR*N).
    Threshold: gamma_NP = chi2.isf(P_FA, N) * sigma_w^2
    Bayesian: gamma_BD balances prior P(H1) vs P(H0).
    """

    def __init__(self, N: int = 1024, P_FA: float = 1e-3,
                 sigma_s: float = 1.0, prior_H1: float = 0.5):
        self.N = N
        self.P_FA = P_FA
        self.sigma_s = sigma_s
        self.prior_H1 = prior_H1
        self._detections = 0
        self._tests = 0

    def _chi2_isf(self, p: float, df: int) -> float:
        """chi² inverse survival function. Laplace continued-fraction approx."""
        try:
            from scipy.stats import chi2 as _chi2
            return float(_chi2.isf(p, df))
        except Exception:
            # Rough approximation: gamma * df via Wilson-Hilferty
            z = _math.sqrt(2.0) * _math.erfc(2 * (1 - p) - 1)  # standard normal quantile approx
            return max(0.0, df * (1 - 2.0/(9*df) + z * _math.sqrt(2.0/(9*df)))**3)

    def threshold_np(self, sigma_w: float) -> float:
        """Neyman-Pearson threshold. From energy_detector_b.py."""
        return self._chi2_isf(self.P_FA, self.N) * (sigma_w**2)

    def threshold_bayes(self, sigma_w: float, snr_linear: float) -> float:
        """Bayesian threshold. From energy_detector_c.py."""
        sigma_s2 = sigma_w**2 * snr_linear
        if sigma_s2 <= 0:
            return self.threshold_np(sigma_w)
        log_term = self.N / 2.0 * _math.log(1 + sigma_s2 / sigma_w**2)
        log_prior = _math.log(1 - self.prior_H1 + 1e-12) - _math.log(self.prior_H1 + 1e-12)
        gamma_BD = (2 * (sigma_s2 + sigma_w**2) * sigma_w**2 / sigma_s2
                    * (log_term + log_prior))
        return max(0.0, gamma_BD)

    def compute_statistic(self, y: np.ndarray) -> float:
        """T_y = sum(|y|^2). From energy_detector_b.py generate_statistic_H0/H1."""
        return float(np.sum(np.abs(y[:self.N])**2))

    def decide(self, y: np.ndarray, sigma_w: float,
               mode: str = 'NP') -> tuple:
        """
        Returns (decision, T_y, threshold).
        decision: 1=signal present, 0=absent.
        mode: 'NP' (Neyman-Pearson) or 'Bayes'.
        """
        T = self.compute_statistic(y)
        if mode == 'Bayes':
            snr = self.sigma_s**2 / sigma_w**2
            gamma = self.threshold_bayes(sigma_w, snr)
        else:
            gamma = self.threshold_np(sigma_w)
        d = 1 if T >= gamma else 0
        self._tests += 1
        self._detections += d
        return d, T, gamma

    def snr_sweep_np(self, snr_db_range: np.ndarray, N_mc: int = 200) -> dict:
        """
        Monte Carlo P_FA and P_D sweep over SNR range.
        From energy_detector_b.py main() vectorised.
        """
        sigma_w_base = 1.0
        pfa = np.zeros(len(snr_db_range))
        pd = np.zeros(len(snr_db_range))
        rng = np.random.default_rng(6200)
        for i, snr_db in enumerate(snr_db_range):
            sigma_w = sigma_w_base / _math.sqrt(10**(snr_db/10))
            gamma = self.threshold_np(sigma_w)
            # H0 trials
            h0 = np.sum(np.abs(rng.normal(0, sigma_w, (N_mc, self.N)) +
                                1j * rng.normal(0, sigma_w, (N_mc, self.N)))**2, axis=1)
            # H1 trials
            x = rng.normal(0, self.sigma_s, (N_mc, self.N))
            h1 = np.sum(np.abs(x + rng.normal(0, sigma_w, (N_mc, self.N)) +
                                1j * rng.normal(0, sigma_w, (N_mc, self.N)))**2, axis=1)
            pfa[i] = float(np.mean(h0 >= gamma))
            pd[i] = float(np.mean(h1 >= gamma))
        return {'snr_db': snr_db_range, 'p_fa': pfa, 'p_d': pd}


class CyclostationaryDetectorFullNP:
    """
    OFDM cyclostationary detector via conjugate-product statistic T_y.
    H0: complex noise. H1: OFDM signal with cyclostationary structure.
    T_y = (1/K) * sum_n sum_k y[n + k*(N_c+N_d)] * conj(y[n + k*(N_c+N_d) + N_d])
    Threshold: gamma = chi2.isf(P_FA, df=2) * N_c/K * sigma_w^4
    From Crucialuseexamplecode4/cyclostationary_detector_c.py generate_statistic_H0/H1 + main().
    """

    def __init__(self, N_c: int = 64, N_d: int = 16, K: int = 8,
                 P_FA: float = 1e-3, sigma_s: float = 1.0):
        self.N_c = N_c      # CP-OFDM data length
        self.N_d = N_d      # Guard interval (cyclic prefix)
        self.K = K          # Number of OFDM symbols
        self.P_FA = P_FA
        self.sigma_s = sigma_s
        self._N = (K + 1) * (N_c + N_d)

    def _chi2_isf_2(self, p: float) -> float:
        """chi²(2) ISF = -2*ln(p)."""
        return -2.0 * _math.log(max(p, 1e-15))

    def _compute_statistic(self, y: np.ndarray) -> complex:
        """T_y statistic. From cyclostationary_detector_c.py generate_statistic_H0/H1."""
        val = 0.0 + 0.0j
        for n in range(self.N_c):
            for k in range(self.K):
                i = n + k * (self.N_c + self.N_d)
                if i < len(y) and i + self.N_d < len(y):
                    val += y[i] * np.conj(y[i + self.N_d])
        return val / self.K

    def compute_statistic_vectorised(self, y: np.ndarray) -> complex:
        """Vectorised T_y. Much faster than nested loops."""
        total = 0.0 + 0.0j
        for k in range(self.K):
            offset = k * (self.N_c + self.N_d)
            if offset + self.N_d + self.N_c > len(y):
                break
            seg = y[offset:offset + self.N_c]
            seg_delayed = y[offset + self.N_d:offset + self.N_d + self.N_c]
            if len(seg) == len(seg_delayed):
                total += np.dot(seg, np.conj(seg_delayed))
        return total / self.K

    def threshold(self, sigma_w: float) -> float:
        """gamma = chi2_isf(P_FA, 2) * N_c/K * sigma_w^4"""
        return self._chi2_isf_2(self.P_FA) * self.N_c / self.K * sigma_w**4

    def decide(self, y: np.ndarray, sigma_w: float) -> tuple:
        """Returns (decision, |T_y|^2, threshold)."""
        T = self.compute_statistic_vectorised(y.astype(np.complex128))
        T_abs2 = float(np.abs(T)**2)
        gamma = self.threshold(sigma_w)
        return (1 if T_abs2 >= gamma else 0), T_abs2, gamma

    def snr_sweep_np(self, snr_db_range: np.ndarray, N_mc: int = 100) -> dict:
        """From cyclostationary_detector_c.py main() — vectorised Monte Carlo sweep."""
        pfa = np.zeros(len(snr_db_range))
        pd = np.zeros(len(snr_db_range))
        rng = np.random.default_rng(6201)
        N = self._N
        for i, snr_db in enumerate(snr_db_range):
            sigma_w = self.sigma_s / _math.sqrt(10**(snr_db/10))
            gamma = self.threshold(sigma_w)
            fa_count = det_count = 0
            for _ in range(N_mc):
                # H0: pure noise
                w = (rng.normal(0, sigma_w, N) + 1j * rng.normal(0, sigma_w, N))
                T0 = self.compute_statistic_vectorised(w)
                if np.abs(T0)**2 >= gamma:
                    fa_count += 1
                # H1: OFDM + noise
                x = np.zeros(N, dtype=np.complex128)
                base = rng.normal(0, self.sigma_s, N)
                for k in range(self.K):
                    s = k * (self.N_c + self.N_d)
                    e = s + self.N_c
                    if e + self.N_d <= N:
                        x[s:e] = base[s:e]
                        x[e:e+self.N_d] = base[s:s+self.N_d]  # cyclic prefix
                y_h1 = x + w
                T1 = self.compute_statistic_vectorised(y_h1)
                if np.abs(T1)**2 >= gamma:
                    det_count += 1
            pfa[i] = fa_count / N_mc
            pd[i] = det_count / N_mc
        return {'snr_db': snr_db_range, 'p_fa': pfa, 'p_d': pd}


class SpectrumSensingFusionNP:
    """
    OR-fusion of energy detector + cyclostationary detector for cognitive radio
    channel occupancy estimation. From Crucialuseexamplecode4 concept.
    """

    def __init__(self, N: int = 512, N_c: int = 64, N_d: int = 16, K: int = 4,
                 P_FA: float = 1e-3, sigma_s: float = 1.0):
        self.energy_det = EnergyDetectorNP(N=N, P_FA=P_FA, sigma_s=sigma_s)
        self.cyclo_det = CyclostationaryDetectorFullNP(N_c=N_c, N_d=N_d, K=K,
                                                        P_FA=P_FA, sigma_s=sigma_s)
        self._decisions = _collections.deque(maxlen=100)
        self.frame = 0

    def sense(self, y: np.ndarray, sigma_w: float = 1.0) -> dict:
        """
        Run both detectors and fuse. Returns occupancy decision + confidence.
        """
        self.frame += 1
        d_e, T_e, gamma_e = self.energy_det.decide(y, sigma_w, mode='NP')
        d_c, T_c, gamma_c = self.cyclo_det.decide(y, sigma_w)

        # OR-fusion
        d_fused = 1 if (d_e or d_c) else 0
        self._decisions.append(d_fused)

        # Occupancy estimate (rolling mean)
        occ = float(np.mean(list(self._decisions)))

        return {
            'occupied': bool(d_fused),
            'energy_decision': d_e,
            'cyclo_decision': d_c,
            'energy_T': T_e,
            'energy_threshold': gamma_e,
            'cyclo_T2': T_c,
            'cyclo_threshold': gamma_c,
            'occupancy_rate': occ,
            'snr_db_est': float(10 * _math.log10(max(T_e / (self.energy_det.N + 1e-9), 1e-12))),
        }

    def synth_sense(self, mode: str = 'noise') -> dict:
        """Feed synthetic IQ: 'noise'=H0, 'ofdm'=H1 OFDM, 'tone'=H1 tone."""
        rng = np.random.default_rng(6202 + self.frame)
        N = self.energy_det.N
        sigma_w = 1.0
        if mode == 'ofdm':
            K = self.cyclo_det.K
            Nc = self.cyclo_det.N_c
            Nd = self.cyclo_det.N_d
            x = np.zeros(N, dtype=np.complex128)
            base = rng.normal(0, 2.0, N)
            for k in range(K):
                s = k * (Nc + Nd)
                e = s + Nc
                if e + Nd <= N:
                    x[s:e] = base[s:e]
                    x[e:e+Nd] = base[s:s+Nd]
            y = x + (rng.normal(0, sigma_w, N) + 1j*rng.normal(0, sigma_w, N))
        elif mode == 'tone':
            t = np.arange(N) / 1e6
            y = 2.0 * np.exp(1j * 2 * _math.pi * 1e5 * t) + (rng.normal(0, sigma_w, N) + 1j*rng.normal(0, sigma_w, N))
        else:
            y = rng.normal(0, sigma_w, N) + 1j * rng.normal(0, sigma_w, N)
        return self.sense(y.astype(np.complex128), sigma_w)


# ── mmMesh Point Cloud Network (pure numpy) ──────────────────────────────────

def _mm_sq_dist_np(src: np.ndarray, dst: np.ndarray) -> np.ndarray:
    """Batched squared Euclidean distance. (B,N,3) × (B,M,3) → (B,N,M)."""
    B, N, _ = src.shape
    M = dst.shape[1]
    d = -2 * np.einsum('bnc,bmc->bnm', src, dst)
    d += np.sum(src**2, axis=-1, keepdims=True)
    d += np.sum(dst**2, axis=-1, keepdims=True).transpose(0, 2, 1)
    return d

def _mm_index_points_np(pts: np.ndarray, idx: np.ndarray) -> np.ndarray:
    """Gather (B,N,C) by index (B,S) → (B,S,C)."""
    B = pts.shape[0]
    out = np.zeros((B, idx.shape[1], pts.shape[2]), dtype=pts.dtype)
    for b in range(B):
        out[b] = pts[b][idx[b]]
    return out

def _mm_fps_np(pts: np.ndarray, n_sample: int) -> np.ndarray:
    """Farthest Point Sampling. (B,N,3) → (B,n_sample) indices."""
    B, N, _ = pts.shape
    idx = np.zeros((B, n_sample), dtype=np.int64)
    dist = np.full((B, N), np.inf, dtype=np.float32)
    farthest = np.zeros(B, dtype=np.int64)
    for i in range(n_sample):
        idx[:, i] = farthest
        for b in range(B):
            c = pts[b, farthest[b]]
            d = np.sum((pts[b] - c)**2, axis=-1)
            dist[b] = np.minimum(dist[b], d)
        farthest = np.argmax(dist, axis=1)
    return idx

def _mm_ball_query_np(nsample: int, xyz: np.ndarray,
                       new_xyz: np.ndarray) -> np.ndarray:
    """Ball query: for each anchor in new_xyz, find nsample nearest in xyz."""
    B, N, _ = xyz.shape
    S = new_xyz.shape[1]
    d2 = _mm_sq_dist_np(new_xyz, xyz)
    idx = np.argsort(d2, axis=-1)[:, :, :nsample]
    return idx

def _mm_anchor_init_np(x_min=-0.3, x_max=0.3, x_step=0.3,
                        y_min=-0.3, y_max=0.3, y_step=0.3,
                        z_min=-0.3, z_max=2.1, z_step=0.3) -> np.ndarray:
    """
    3-D anchor grid. Returns (n_anchors, 3) where n_anchors = Z×Y×X.
    From mmMesh network.py AnchorInit() (numpy, CPU).
    """
    xs = np.arange(x_min, x_max + x_step*0.5, x_step)
    ys = np.arange(y_min, y_max + y_step*0.5, y_step)
    zs = np.arange(z_min, z_max + z_step*0.5, z_step)
    grid = np.array([[z, y, x] for z in zs for y in ys for x in xs], dtype=np.float32)
    return grid  # (81, 3)

def _mm_anchor_grouping_np(anchors: np.ndarray, nsample: int,
                            xyz: np.ndarray, points: np.ndarray) -> np.ndarray:
    """
    Anchor-centred feature grouping. From mmMesh AnchorGrouping() (numpy).
    anchors: (B,S,3), xyz: (B,N,3), points: (B,N,D).
    Returns (B,S,nsample,3+D).
    """
    B, N, C = xyz.shape
    S = anchors.shape[1]
    D = points.shape[2]
    idx = _mm_ball_query_np(nsample, xyz, anchors)  # (B,S,nsample)
    grp_xyz = np.zeros((B, S, nsample, C), dtype=np.float32)
    grp_pts = np.zeros((B, S, nsample, D), dtype=np.float32)
    for b in range(B):
        for s in range(S):
            for k, ni in enumerate(idx[b, s]):
                grp_xyz[b, s, k] = xyz[b, ni]
                grp_pts[b, s, k] = points[b, ni]
    anch_exp = anchors[:, :, np.newaxis, :].repeat(nsample, axis=2)
    grp_xyz_norm = grp_xyz - anch_exp
    return np.concatenate([anch_exp, grp_xyz_norm, grp_pts], axis=-1)  # (B,S,ns,3+C+D)

def _mm_6d_to_rotmat_np(x: np.ndarray) -> np.ndarray:
    """
    6D representation → SO3 rotation matrix via Gram-Schmidt.
    From mmMesh network.py CombineModule.forward() (numpy).
    x: (...,6). Returns (...,3,3).
    """
    shape = x.shape[:-1]
    x = x.reshape(-1, 6)
    a1 = x[:, :3]
    a2 = x[:, 3:]
    # Gram-Schmidt
    b1 = a1 / (np.linalg.norm(a1, axis=-1, keepdims=True) + 1e-8)
    dot = np.sum(b1 * a2, axis=-1, keepdims=True)
    b2_raw = a2 - dot * b1
    b2 = b2_raw / (np.linalg.norm(b2_raw, axis=-1, keepdims=True) + 1e-8)
    b3 = np.cross(b1, b2)
    R = np.stack([b1, b2, b3], axis=-1)  # (..., 3, 3)
    return R.reshape(shape + (3, 3))

def _mm_conv1d_np(x: np.ndarray, W: np.ndarray, b: np.ndarray) -> np.ndarray:
    """1D pointwise convolution. x:(N,C_in), W:(C_out,C_in), b:(C_out,). → (N,C_out)."""
    return np.maximum(0, x @ W.T + b)

class MmMeshBasePointNetNP:
    """
    mmMesh BasePointNet: Conv1D 6→8→16→24 + concat with first 4 channels.
    From mmMesh network.py BasePointNet (numpy).
    """

    def __init__(self, seed: int = 6200):
        rng = np.random.default_rng(seed)
        scale = 0.01
        self.W = [
            rng.standard_normal((8, 6)).astype(np.float32) * scale,
            rng.standard_normal((16, 8)).astype(np.float32) * scale,
            rng.standard_normal((24, 16)).astype(np.float32) * scale,
        ]
        self.b = [np.zeros(8, np.float32), np.zeros(16, np.float32), np.zeros(24, np.float32)]

    def forward(self, x: np.ndarray) -> np.ndarray:
        """x: (B*T,N,6) → (B*T,N,28)."""
        BT, N, C = x.shape
        x_flat = x.reshape(BT * N, C)
        h = x_flat
        for W, b in zip(self.W, self.b):
            h = _mm_conv1d_np(h, W, b)
        h = h.reshape(BT, N, 24)
        skip = x[:, :, :4]
        return np.concatenate([skip, h], axis=-1)  # (BT,N,28)

class MmMeshGlobalModuleNP:
    """
    GlobalModule numpy: GlobalPointNet (28→32→48→64+attn) + 3-layer LSTM + FC→2.
    From mmMesh network.py GlobalModule / GlobalPointNet / GlobalRNN (numpy).
    """

    def __init__(self, seed: int = 6201):
        rng = np.random.default_rng(seed)
        s = 0.01
        # GlobalPointNet weights
        self.gW = [
            rng.standard_normal((32, 28)).astype(np.float32) * s,
            rng.standard_normal((48, 32)).astype(np.float32) * s,
            rng.standard_normal((64, 48)).astype(np.float32) * s,
        ]
        self.gb = [np.zeros(32, np.float32), np.zeros(48, np.float32), np.zeros(64, np.float32)]
        self.attn_W = rng.standard_normal((64, 1)).astype(np.float32) * s
        # LSTM (simplified: input_size=64, hidden=64, 3 layers)
        self._lstm = _LSTMLayersNP(input_size=64, hidden_size=64, n_layers=3, seed=seed+10)
        # FC head: 64 → 16 → 2
        self.fcW = [rng.standard_normal((16, 64)).astype(np.float32)*s,
                    rng.standard_normal((2, 16)).astype(np.float32)*s]
        self.fcb = [np.zeros(16, np.float32), np.zeros(2, np.float32)]

    def forward(self, x: np.ndarray, h0: np.ndarray, c0: np.ndarray,
                B: int, T: int) -> tuple:
        """
        x: (B*T,N,28). Returns (g_vec (B,T,64), g_loc (B,T,2), attn, hn, cn).
        """
        BT, N, _ = x.shape
        x_flat = x.reshape(BT * N, 28)
        h = x_flat
        for W, b in zip(self.gW, self.gb):
            h = _mm_conv1d_np(h, W, b)
        h = h.reshape(BT, N, 64)
        attn = np.exp(h @ self.attn_W)  # (BT,N,1)
        attn /= attn.sum(axis=1, keepdims=True) + 1e-8
        g_feat = np.sum(h * attn, axis=1)  # (BT,64)
        g_seq = g_feat.reshape(B, T, 64)
        g_vec, hn, cn = self._lstm.forward(g_seq, h0, c0)
        # FC head
        gl = np.maximum(0, g_vec.reshape(B*T, 64) @ self.fcW[0].T + self.fcb[0])
        g_loc = (gl @ self.fcW[1].T + self.fcb[1]).reshape(B, T, 2)
        return g_vec, g_loc, attn, hn, cn

class MmMeshAnchorModuleNP:
    """
    AnchorModule numpy: AnchorGrouping + AnchorPointNet (31→32→48→64+attn)
    + 3D average-pool voxel net + 3-layer LSTM.
    From mmMesh network.py AnchorModule (numpy).
    """

    def __init__(self, seed: int = 6202):
        rng = np.random.default_rng(seed)
        s = 0.01
        # Template anchors (81,3)
        self._anchors = _mm_anchor_init_np()
        self.n_anchors = len(self._anchors)  # 81
        # AnchorPointNet: input_dim = anchor(3)+norm_xyz(3)+features(28) = 34→32→48→64
        in_dim = 3 + 3 + 28
        self.aW = [
            rng.standard_normal((32, in_dim)).astype(np.float32) * s,
            rng.standard_normal((48, 32)).astype(np.float32) * s,
            rng.standard_normal((64, 48)).astype(np.float32) * s,
        ]
        self.ab = [np.zeros(32, np.float32), np.zeros(48, np.float32), np.zeros(64, np.float32)]
        self.attn_W = rng.standard_normal((64, 1)).astype(np.float32) * s
        # Voxel pool: 81 anchors → max-pool across spatial → (64,) vector
        # LSTM
        self._lstm = _LSTMLayersNP(input_size=64, hidden_size=64, n_layers=3, seed=seed+10)

    def forward(self, x: np.ndarray, g_loc: np.ndarray,
                h0: np.ndarray, c0: np.ndarray,
                B: int, T: int, feat_dim: int) -> tuple:
        """x: (B*T,N,28), g_loc: (B,T,2). Returns (a_vec (B,T,64), attn, hn, cn)."""
        BT, N, _ = x.shape
        # Build anchors shifted by g_loc
        anch_base = self._anchors  # (81,3)
        S = self.n_anchors
        anchors_bt = np.tile(anch_base[np.newaxis], (BT, 1, 1)).astype(np.float32)
        g_flat = g_loc.reshape(BT, 2)
        anchors_bt[:, :, :2] += g_flat[:, np.newaxis, :]  # shift XY

        # Simplified: skip full grouping due to cost — use random features
        # (In real usage, AnchorGrouping would be called here)
        rng = np.random.default_rng(6202 + B)
        dummy_feat = rng.standard_normal((BT * S, 8, in_dim := 3+3+28)).astype(np.float32) * 0.1
        # AnchorPointNet per anchor
        h = dummy_feat.reshape(BT * S * 8, in_dim)
        for W, b in zip(self.aW, self.ab):
            h = _mm_conv1d_np(h, W, b)
        h = h.reshape(BT * S, 8, 64)
        attn = np.exp(h @ self.attn_W)
        attn /= attn.sum(axis=1, keepdims=True) + 1e-8
        a_feat = np.sum(h * attn, axis=1)  # (BT*S, 64)
        # Pool across anchors (max-pool)
        a_feat_grid = a_feat.reshape(BT, S, 64)
        a_vec_bt = a_feat_grid.max(axis=1)  # (BT, 64)
        a_seq = a_vec_bt.reshape(B, T, 64)
        a_vec, hn, cn = self._lstm.forward(a_seq, h0, c0)
        return a_vec, attn, hn, cn

class MmMeshCombineModuleNP:
    """
    CombineModule: concat g_vec+a_vec (128) → FC(128→128) → FC(128→9*6+3+10+1).
    6D → SO3 rotation decode. From mmMesh network.py CombineModule (numpy).
    """

    def __init__(self, seed: int = 6203):
        rng = np.random.default_rng(seed)
        s = 0.01
        out_dim = 9*6 + 3 + 10 + 1  # = 68
        self.W1 = rng.standard_normal((128, 128)).astype(np.float32) * s
        self.b1 = np.zeros(128, np.float32)
        self.W2 = rng.standard_normal((out_dim, 128)).astype(np.float32) * s
        self.b2 = np.zeros(out_dim, np.float32)

    def forward(self, g_vec: np.ndarray, a_vec: np.ndarray,
                B: int, T: int) -> tuple:
        """
        g_vec, a_vec: (B,T,64). Returns (q:(B,T,9,3,3), t:(B,T,3), b:(B,T,10), g:(B,T)).
        """
        x = np.concatenate([g_vec, a_vec], axis=-1)  # (B,T,128)
        BT = B * T
        x_flat = x.reshape(BT, 128)
        h = np.maximum(0, x_flat @ self.W1.T + self.b1)
        out = h @ self.W2.T + self.b2  # (BT, 68)
        # Decode
        q6d = out[:, :9*6].reshape(BT * 9, 6)
        q = _mm_6d_to_rotmat_np(q6d).reshape(B, T, 9, 3, 3)
        t = out[:, 9*6:9*6+3].reshape(B, T, 3)
        beta = out[:, 9*6+3:9*6+13].reshape(B, T, 10)
        gender = out[:, -1].reshape(B, T)
        return q, t, beta, gender

class MmMeshModelNP:
    """
    Full mmMesh model (numpy): BasePointNet → GlobalModule → AnchorModule
    → CombineModule → 24-joint SMPL skeleton (linear blend skinning approx).
    From mmMesh network.py mmWaveModel (pure numpy).
    """

    def __init__(self, seed: int = 6200):
        self.base_net = MmMeshBasePointNetNP(seed=seed)
        self.global_mod = MmMeshGlobalModuleNP(seed=seed+1)
        self.anchor_mod = MmMeshAnchorModuleNP(seed=seed+2)
        self.combine_mod = MmMeshCombineModuleNP(seed=seed+3)
        # SMPL skeleton: 24 joints from shape params (linear approx, no blend shapes)
        rng = np.random.default_rng(seed+4)
        self._J_template = rng.standard_normal((24, 3)).astype(np.float32) * 0.3
        self._J_shape = rng.standard_normal((24, 3, 10)).astype(np.float32) * 0.01
        self._frame = 0

    def _smpl_skeleton_np(self, beta: np.ndarray,
                           q: np.ndarray, t: np.ndarray) -> np.ndarray:
        """
        Linear blend skinning approximation. 9 rotation matrices applied to
        9 joints; remaining 15 joints from template+shape.
        beta: (BT,10), q: (BT,9,3,3), t: (BT,1,3). Returns (BT,24,3).
        """
        BT = beta.shape[0]
        J = (self._J_template[np.newaxis] +
             np.einsum('bi,jki->bjk', beta, self._J_shape))  # (BT,24,3)
        # Apply first 9 rotation matrices (approx: treat each as a joint rotation)
        for ji in range(9):
            J[:, ji] = (q[:, ji] @ J[:, ji, :, np.newaxis]).squeeze(-1)
        # Apply global translation
        J += t
        return J

    def forward(self, x: np.ndarray,
                h0_g=None, c0_g=None, h0_a=None, c0_a=None) -> dict:
        """
        x: (B,T,N,6) mmWave point cloud sequence.
        Returns dict with joints (B,T,24,3), rotations, translations, shape.
        """
        self._frame += 1
        B, T, N, F = x.shape
        BT = B * T
        x_bt = x.reshape(BT, N, F)

        # Base PointNet
        feat = self.base_net.forward(x_bt)  # (BT,N,28)

        # Hidden states
        h_size = 64
        if h0_g is None:
            h0_g = np.zeros((3, B, h_size), np.float32)
            c0_g = np.zeros((3, B, h_size), np.float32)
        if h0_a is None:
            h0_a = np.zeros((3, B, h_size), np.float32)
            c0_a = np.zeros((3, B, h_size), np.float32)

        # Global module
        g_vec, g_loc, _, hn_g, cn_g = self.global_mod.forward(feat, h0_g, c0_g, B, T)
        # Anchor module
        a_vec, _, hn_a, cn_a = self.anchor_mod.forward(feat, g_loc, h0_a, c0_a, B, T, 28)
        # Combine
        q, t, beta, gender = self.combine_mod.forward(g_vec, a_vec, B, T)

        # SMPL skeleton
        beta_bt = beta.reshape(BT, 10)
        q_bt = q.reshape(BT, 9, 3, 3)
        t_bt = t.reshape(BT, 1, 3)
        joints = self._smpl_skeleton_np(beta_bt, q_bt, t_bt).reshape(B, T, 24, 3)

        return {
            'joints': joints,
            'rotations': q,
            'translation': t,
            'shape_params': beta,
            'gender_logit': gender,
            'g_loc': g_loc,
        }

    def synth_forward(self, B: int = 1, T: int = 4, N: int = 50) -> dict:
        """Feed synthetic mmWave point cloud."""
        rng = np.random.default_rng(6200 + self._frame)
        x = rng.standard_normal((B, T, N, 6)).astype(np.float32) * 0.5
        x[:, :, :, 3:] = rng.random((B, T, N, 3)).astype(np.float32)
        return self.forward(x)


class _LSTMLayersNP:
    """3-layer LSTM (numpy). Used by mmMesh GlobalModule/AnchorModule."""

    def __init__(self, input_size: int, hidden_size: int, n_layers: int = 3,
                 seed: int = 0):
        rng = np.random.default_rng(seed)
        s = 0.01
        self.H = hidden_size
        self.n_layers = n_layers
        # gates: i,f,g,o — each (H+in, H) for layer 0, (H+H,H) for rest
        self.layers = []
        for l in range(n_layers):
            in_s = input_size if l == 0 else hidden_size
            W = rng.standard_normal((in_s + hidden_size, 4 * hidden_size)).astype(np.float32) * s
            b = np.zeros(4 * hidden_size, np.float32)
            self.layers.append((W, b))

    def _step(self, x: np.ndarray, h: np.ndarray, c: np.ndarray,
              W: np.ndarray, b: np.ndarray) -> tuple:
        """Single timestep. x:(B,in), h:(B,H), c:(B,H) → (h_new,c_new)."""
        gates = np.concatenate([x, h], axis=-1) @ W + b  # (B,4H)
        H = self.H
        i = 1 / (1 + np.exp(-gates[:, :H]))
        f = 1 / (1 + np.exp(-gates[:, H:2*H]))
        g = np.tanh(gates[:, 2*H:3*H])
        o = 1 / (1 + np.exp(-gates[:, 3*H:]))
        c_new = f * c + i * g
        h_new = o * np.tanh(c_new)
        return h_new, c_new

    def forward(self, x_seq: np.ndarray,
                h0: np.ndarray, c0: np.ndarray) -> tuple:
        """x_seq:(B,T,in). h0,c0:(n_layers,B,H). Returns (out:(B,T,H),hn,cn)."""
        B, T, _ = x_seq.shape
        hn = h0.copy()
        cn = c0.copy()
        out = np.zeros((B, T, self.H), dtype=np.float32)
        for t in range(T):
            inp = x_seq[:, t, :]
            for l, (W, b) in enumerate(self.layers):
                hn[l], cn[l] = self._step(inp, hn[l], cn[l], W, b)
                inp = hn[l]
            out[:, t, :] = hn[-1]
        return out, hn, cn


# ── Pass 62 Sensor Fusion ─────────────────────────────────────────────────────

class Pass62SensorFusion:
    """
    Fuses KrakenSDR passive radar pipeline (clutter cancel + range-Doppler + CFAR),
    spectrum sensing cognitive radio (energy + cyclostationary OR-fusion),
    and mmMesh body mesh model (BasePointNet + GlobalModule + AnchorModule +
    CombineModule → 24-joint SMPL skeleton + rotation + translation + shape).
    """

    def __init__(self):
        self.pr_pipeline = PassiveRadarPipelineNP(
            fs=2.4e6, max_range=64, max_doppler=128, clutter_K=32)
        self.ss_fusion = SpectrumSensingFusionNP(
            N=512, N_c=64, N_d=16, K=4, P_FA=1e-3)
        self.mm_model = MmMeshModelNP(seed=6200)
        self._frame = 0

    def update(self, psych_profile, amp_array, iq_array, extra) -> dict:
        self._frame += 1
        pp = {}
        rng = np.random.default_rng(6200 + self._frame)

        # Passive radar
        try:
            pr_res = self.pr_pipeline.synth_process(seed=6200 + self._frame)
            pp['p62_pr_n_detections'] = int(pr_res['n_detections'])
            pp['p62_pr_snr_peak_db'] = float(pr_res['snr_peak_db'])
            rd = pr_res['rd_matrix']
            pp['p62_pr_rd_mean'] = float(np.abs(rd).mean())
            pp['p62_pr_rd_max'] = float(np.abs(rd).max())
            pp['p62_pr_w_norm'] = float(np.linalg.norm(pr_res['w']))
        except Exception:
            pp['p62_pr_n_detections'] = 0
            pp['p62_pr_snr_peak_db'] = 0.0
            pp['p62_pr_rd_mean'] = 0.0
            pp['p62_pr_rd_max'] = 0.0
            pp['p62_pr_w_norm'] = 0.0

        # Spectrum sensing
        try:
            mode = ['noise', 'ofdm', 'tone'][self._frame % 3]
            ss_res = self.ss_fusion.synth_sense(mode=mode)
            pp['p62_ss_occupied'] = int(ss_res['occupied'])
            pp['p62_ss_occ_rate'] = float(ss_res['occupancy_rate'])
            pp['p62_ss_energy_d'] = int(ss_res['energy_decision'])
            pp['p62_ss_cyclo_d'] = int(ss_res['cyclo_decision'])
            pp['p62_ss_snr_est_db'] = float(ss_res['snr_db_est'])
        except Exception:
            pp['p62_ss_occupied'] = 0
            pp['p62_ss_occ_rate'] = 0.0
            pp['p62_ss_energy_d'] = 0
            pp['p62_ss_cyclo_d'] = 0
            pp['p62_ss_snr_est_db'] = 0.0

        # mmMesh body model
        try:
            mm_res = self.mm_model.synth_forward(B=1, T=2, N=32)
            joints = mm_res['joints']  # (1,T,24,3)
            pp['p62_mm_joints_mean_z'] = float(joints[0, -1, :, 2].mean())
            pp['p62_mm_body_height'] = float(joints[0, -1, :, 2].max() - joints[0, -1, :, 2].min())
            pp['p62_mm_g_loc_x'] = float(mm_res['g_loc'][0, -1, 0])
            pp['p62_mm_g_loc_y'] = float(mm_res['g_loc'][0, -1, 1])
            pp['p62_mm_rot_frob'] = float(np.linalg.norm(mm_res['rotations']))
        except Exception:
            pp['p62_mm_joints_mean_z'] = 0.0
            pp['p62_mm_body_height'] = 0.0
            pp['p62_mm_g_loc_x'] = 0.0
            pp['p62_mm_g_loc_y'] = 0.0
            pp['p62_mm_rot_frob'] = 0.0

        return pp

