    H = np.atleast_2d(np.abs(csi_history))
    try:
        fractal_dim = float(np.log(H.shape[1]) / np.log(2)) if H.shape[1] > 1 else 1.0
        upscaled_resolution = H.shape[1] ** 3 if H.ndim > 1 else 0
    except Exception:
        fractal_dim = 1.0
        upscaled_resolution = 0
