    parser = argparse.ArgumentParser(
        description="N.E.P.A. v83 — WiFi CSI + DoA + WienerMRE-PR + mmWave + Cyclostationary + World/Planet Mapper + P81:PointCloud + P82:MVS+SAR3D+ReID + P83:FMCW+PoseNet+HashGrid+P4D+SatSpec")
    parser.add_argument('--mode', choices=['sim', 'udp'], default='sim')
    parser.add_argument('--port', type=int, default=UDP_PORT)
    parser.add_argument('--demo-only', action='store_true',
                        help='List 1.12: force simulation, disable real RF capture')
    parser.add_argument('--record', action='store_true',
                        help='List 1.9: record CSI + features to nepa_record.npz')
    parser.add_argument('--record-path', default='nepa_record.npz')
    parser.add_argument('--train', action='store_true',
                        help='List 1.9: offline fine-tune internal MLP from a recording, then exit')
    parser.add_argument('--epochs', type=int, default=10)
    parser.add_argument('--no-world', action='store_true',
                        help='Pass 25: do not open the walkable 3D world window')
    parser.add_argument('--sim-validate', action='store_true',
                        help='Pass 26: OFFLINE TEST — drive CSI from the synthetic '
                             'GroundTruthScene and show the accuracy gauge. Default mode '
                             'shows ONLY real measured data from the connected router.')
    parser.add_argument('--simulate-hardware', action='store_true',
                        help='v94: ENGINEER-AROUND-HARDWARE — register SIMULATED virtual '
                             'instruments (CSI/SDR/GPR) so the full vision (walking bodies, '
                             'vitals, coherent radar, subsurface imaging) renders for '
                             'demonstration. Every product is watermarked SIMULATED and is '
                             'NEVER shown as real. Toggle live with the [V] key.')
    parser.add_argument('--fps', type=int, default=20,
                        help='Pass 26: target display refresh rate (frames/sec)')
    parser.add_argument('--record-splat', metavar='DIR', default=None,
                        help='Pass 44 (T-RECORD): record render frames as PNG/NPZ to DIR.')
    parser.add_argument('--passive-sniff', action='store_true',
                        help='Pass 30 (T0-5): passive CSI capture from all passing WiFi '
                             'packets (UDP-forwarded ESP32/Nexmon sniffer, or scapy monitor).')
    parser.add_argument('--monitor-iface', default=None,
                        help='Pass 30 (T0-5): monitor-mode interface for scapy passive sniff.')
    parser.add_argument('--web-viewer', action='store_true',
                        help='Pass 34: Start HTTP MJPEG server streaming the live Gaussian-splat '
                             'world. Open http://localhost:<--web-port>/ in any browser.')
    parser.add_argument('--web-port', type=int, default=8765,
                        help='Pass 34: Port for the --web-viewer HTTP server (default 8765).')
    parser.add_argument('--ingest-port', type=int, default=0,
                        help='v104: start the multi-node REAL-DATA ingest server on this port '
                             '(e.g. 8770). Remote devices (phones/laptops/routers) POST their own '
                             'real WiFi scans to http://<host>:<port>/ingest; they fuse as real '
                             'distributed sensors. 0 = disabled.')
    parser.add_argument('--csi-port', type=int, default=0,
                        help='v118: start the ESP32 CSI ingest server on this UDP port '
                             '(e.g. 5001). Any ESP32 running esp-csi firmware can send real '
                             'per-subcarrier CSI frames here; they feed the passive radar pipeline '
                             'as real channel-sounding data. 0 = disabled.')
    parser.add_argument('--lsl', action='store_true',
                        help='Pass 34 (T-LSL): Open a Lab Streaming Layer outlet named NEPA_BCI '
                             'broadcasting 10-channel BCI band powers at target_fps Hz. '
                             'Requires pylsl (pip install pylsl).')
    parser.add_argument('--mqtt-host', default=None,
                        help='Pass 34 (T-SEM): MQTT broker host for SemanticStateEngine '
                             'room-state publishing (e.g. 192.168.1.1 or homeassistant.local).')
    parser.add_argument('--mqtt-port', type=int, default=1883,
                        help='Pass 34: MQTT broker port (default 1883).')
    parser.add_argument('--ha-discovery', action='store_true',
                        help='Pass 34: Publish Home Assistant MQTT discovery messages on start.')
    args = parser.parse_args()
    # Pass 44: T-RECORD frame recorder init
    _splat_recorder_global = None
    if getattr(args, 'record_splat', None):
        _splat_recorder_global = SplatFrameRecorder(record_dir=args.record_splat, fmt='auto')
        log.info(f"[RECORD] Frame recorder active → {args.record_splat}")

    # List 1.9: offline training mode (no UI)
    if args.train:
        mlp = TinyMLP()
        mlp = offline_train(args.record_path, mlp, epochs=args.epochs)
        with open('nepa_mlp.pkl', 'wb') as fh:
            pickle.dump({'W1': mlp.W1, 'b1': mlp.b1, 'W2': mlp.W2, 'b2': mlp.b2}, fh)
        log.info("[TRAIN] Saved fine-tuned MLP to nepa_mlp.pkl")
        sys.exit(0)

    mode = 'sim' if args.demo_only else args.mode
    fuser = MultiAgentWirelessBCIFuser(mode=mode, udp_port=args.port,
                                       demo_only=args.demo_only,
                                       record=args.record, record_path=args.record_path,
                                       sim_validate=args.sim_validate)
    fuser.enable_world = not args.no_world   # Pass 25: walkable 3D world toggle
    fuser.target_fps = max(5, min(60, args.fps))  # Pass 26: live refresh rate
    # v116 BUGFIX: --record-splat created a SplatFrameRecorder + dir but was never wired to the
    # fuser and save_frame() was never called → it recorded ZERO frames (non-implemented feature).
    # Wire it so the main loop actually saves rendered splat frames.
    fuser.splat_recorder = _splat_recorder_global
    # v94: simulate-hardware (virtual instruments). Watermarked SIMULATED everywhere.
    if getattr(args, "simulate_hardware", False):
        fuser.sim_hardware = True
        try:
            fuser.instrument_bus.set_simulation(True)
        except Exception:
            pass
        log.info("[MAIN] SIMULATE-HARDWARE ON — virtual CSI/SDR/GPR instruments registered "
                 "(all outputs watermarked SIMULATED, never shown as real).")
    # Pass 30 (T0-5): enable passive-sniff CSI capture path.
    if args.passive_sniff and hasattr(fuser, "router_csi"):
        fuser.router_csi.enable_passive_sniff(monitor_iface=args.monitor_iface)
        log.info("[MAIN] Passive-sniff capture path enabled.")

    # Pass 34 (T-WEB): --web-viewer HTTP MJPEG stream of the Gaussian-splat world
    if args.web_viewer:
        fuser.web_viewer = WebViewerServer(fuser, port=args.web_port)
        fuser.web_viewer.start()

    # v104: --ingest-port multi-node REAL-DATA ingest server (distributed real sensors)
    if getattr(args, "ingest_port", 0):
        fuser.ingest_server = RemoteSensorIngestServer(fuser, port=args.ingest_port)
        fuser.ingest_server.start()

    # v118: --csi-port ESP32 real per-subcarrier CSI ingest (any ESP32 + esp-csi firmware)
    if getattr(args, "csi_port", 0):
        fuser.esp32_csi_server = ESP32CSIIngestServer(fuser, port=args.csi_port)
        fuser.esp32_csi_server.start()

    # Pass 34 (T-LSL): --lsl BCI band-power LSL outlet
    if args.lsl:
        fuser.lsl_broadcaster = BCILSLBroadcaster(
            srate=float(max(5, min(60, args.fps))))

    # Pass 34 (T-SEM): --mqtt-host for SemanticStateEngine MQTT publishing
    if args.mqtt_host:
        fuser.semantic_engine = SemanticStateEngine(
            room_id="room_0",
            mqtt_host=args.mqtt_host,
            mqtt_port=args.mqtt_port,
            ha_discovery=args.ha_discovery,
        )
        log.info(f"[MAIN] SemanticStateEngine MQTT → {args.mqtt_host}:{args.mqtt_port}")

    try:
        fuser.start()
    except KeyboardInterrupt:
        # start()'s finally block already sets running=False and saves recorder/profiles
        log.info("N.E.P.A. v23 shutdown complete. Humanitarian life-saving system delivered.")